xfs_ioc_getbmap(
struct file *file,
unsigned int cmd,
void __user *arg)
{
struct getbmapx bmx = { 0 };
struct kgetbmap *buf;
size_t recsize;
int error, i;
switch (cmd) {
case XFS_IOC_GETBMAPA:
bmx.bmv_iflags = BMV_IF_ATTRFORK;
fallthrough;
case XFS_IOC_GETBMAP:
recsize = sizeof(struct getbmap);
break;
case XFS_IOC_GETBMAPX:
recsize = sizeof(struct getbmapx);
break;
default:
return -EINVAL;
}
if (copy_from_user(&bmx, arg, recsize))
return -EFAULT;
if (bmx.bmv_count < 2)
return -EINVAL;
if (bmx.bmv_count > ULONG_MAX / recsize)
return -ENOMEM;
buf = kvcalloc(bmx.bmv_count, sizeof(*buf), GFP_KERNEL);
if (!buf)
return -ENOMEM;
error = xfs_getbmap(XFS_I(file_inode(file)), &bmx, buf);
if (error)
goto out_free_buf;
error = -EFAULT;
if (copy_to_user(arg, &bmx, recsize))
goto out_free_buf;
arg += recsize;
for (i = 0; i < bmx.bmv_entries; i++) {
if (!xfs_getbmap_format(buf + i, arg, recsize))
goto out_free_buf;
arg += recsize;
}
error = 0;
out_free_buf:
kmem_free(buf);
return error;
},0

hfs_read_zlib_block_table(const TSK_FS_ATTR *rAttr, CMP_OFFSET_ENTRY** offsetTableOut, uint32_t* tableSizeOut, uint32_t* tableOffsetOut) {
int attrReadResult;
hfs_resource_fork_header rfHeader;
uint32_t dataOffset;
uint32_t offsetTableOffset;
char fourBytes[4];
uint32_t tableSize;
char *offsetTableData = NULL;
CMP_OFFSET_ENTRY *offsetTable = NULL;
size_t indx;
attrReadResult = tsk_fs_attr_read(rAttr, 0, (char *) &rfHeader,
sizeof(hfs_resource_fork_header), TSK_FS_FILE_READ_FLAG_NONE);
if (attrReadResult != sizeof(hfs_resource_fork_header)) {
error_returned
(" %s: trying to read the resource fork header", __func__);
return 0;
}
dataOffset = tsk_getu32(TSK_BIG_ENDIAN, rfHeader.dataOffset);
offsetTableOffset = dataOffset + 4;
attrReadResult =
tsk_fs_attr_read(rAttr, offsetTableOffset, fourBytes, 4,
TSK_FS_FILE_READ_FLAG_NONE);
if (attrReadResult != 4) {
error_returned
(" %s: trying to read the offset table size, "
"return value of %u should have been 4", __func__, attrReadResult);
return 0;
}
tableSize = tsk_getu32(TSK_LIT_ENDIAN, fourBytes);
offsetTableData = tsk_malloc(tableSize * 8);
if (offsetTableData == NULL) {
error_returned
(" %s: space for the offset table raw data", __func__);
return 0;
}
offsetTable =
(CMP_OFFSET_ENTRY *) tsk_malloc(tableSize *
sizeof(CMP_OFFSET_ENTRY));
if (offsetTable == NULL) {
error_returned
(" %s: space for the offset table", __func__);
goto on_error;
}
attrReadResult = tsk_fs_attr_read(rAttr, offsetTableOffset + 4,
offsetTableData, tableSize * 8, TSK_FS_FILE_READ_FLAG_NONE);
if (attrReadResult != tableSize * 8) {
error_returned
(" %s: reading in the compression offset table, "
"return value %u should have been %u", __func__, attrReadResult,
tableSize * 8);
goto on_error;
}
for (indx = 0; indx < tableSize; ++indx) {
offsetTable[indx].offset =
tsk_getu32(TSK_LIT_ENDIAN, offsetTableData + indx * 8);
offsetTable[indx].length =
tsk_getu32(TSK_LIT_ENDIAN, offsetTableData + indx * 8 + 4);
}
free(offsetTableData);
*offsetTableOut = offsetTable;
*tableSizeOut = tableSize;
*tableOffsetOut = offsetTableOffset;
return 1;
on_error:
free(offsetTable);
free(offsetTableData);
return 0;
},0

gerbv_gdk_draw_prim4(GdkPixmap *pixmap, GdkGC *gc, double *p,
double scale, gint x, gint y)
{
const int exposure_idx = 0;
const int nuf_points_idx = 1;
const int first_x_idx = 2;
const int first_y_idx = 3;
const int rotext_idx = 4;
GdkGC *local_gc = gdk_gc_new(pixmap);
int nuf_points, point;
double rotation;
GdkPoint *points;
GdkColor color;
nuf_points = (int)p[nuf_points_idx] + 1;
points = g_new(GdkPoint, nuf_points);
if (!points) {
g_free(points);
return;
}
rotation = p[(nuf_points - 1) * 2 + rotext_idx];
for (point = 0; point < nuf_points; point++) {
points[point].x = (int)round(scale * p[point * 2 + first_x_idx]);
points[point].y = -(int)round(scale * p[point * 2 + first_y_idx]);
if (rotation != 0.0)
points[point] = rotate_point(points[point], rotation);
points[point].x += x;
points[point].y += y;
}
gdk_gc_copy(local_gc, gc);
if (p[exposure_idx] == 0.0) {
color.pixel = 0;
gdk_gc_set_foreground(local_gc, &color);
}
gdk_gc_set_line_attributes(local_gc,
1,
GDK_LINE_SOLID,
GDK_CAP_BUTT,
GDK_JOIN_MITER);
gdk_draw_polygon(pixmap, local_gc, 1, points, nuf_points);
g_free(points);
gdk_gc_unref(local_gc);
return;
},1

pci_emul_add_capability(struct pci_vdev *dev, u_char *capdata, int caplen)
{
int i, capoff, reallen;
uint16_t sts;
assert(caplen > 0);
reallen = roundup2(caplen, 4);
sts = pci_get_cfgdata16(dev, PCIR_STATUS);
if ((sts & PCIM_STATUS_CAPPRESENT) == 0)
capoff = CAP_START_OFFSET;
else
capoff = dev->capend + 1;
if (capoff + reallen > PCI_REGMAX + 1)
return -1;
if ((sts & PCIM_STATUS_CAPPRESENT) == 0) {
pci_set_cfgdata8(dev, PCIR_CAP_PTR, capoff);
pci_set_cfgdata16(dev, PCIR_STATUS, sts|PCIM_STATUS_CAPPRESENT);
} else
pci_set_cfgdata8(dev, dev->prevcap + 1, capoff);
for (i = 0; i < caplen; i++)
pci_set_cfgdata8(dev, capoff + i, capdata[i]);
pci_set_cfgdata8(dev, capoff + 1, 0);
dev->prevcap = capoff;
dev->capend = capoff + reallen - 1;
return 0;
},1

int pgx_validate(jas_stream_t *in)
{
uchar buf[PGX_MAGICLEN];
uint_fast32_t magic;
int i;
int n;
assert(JAS_STREAM_MAXPUTBACK >= PGX_MAGICLEN);
if ((n = jas_stream_read(in, buf, PGX_MAGICLEN)) < 0) {
return -1;
}
for (i = n - 1; i >= 0; --i) {
if (jas_stream_ungetc(in, buf[i]) == EOF) {
return -1;
}
}
if (n < PGX_MAGICLEN) {
return -1;
}
magic = (buf[0] << 8) | buf[1];
if (magic != PGX_MAGIC) {
return -1;
}
return 0;
},1

static int init_ssl_connection(SSL *con)
{
