R_API RBinJavaAttrInfo *r_bin_java_local_variable_table_attr_new(ut8 *buffer, ut64 sz, ut64 buf_offset) {
RBinJavaLocalVariableAttribute *lvattr;
ut64 curpos = 0, offset = 6;
RBinJavaAttrInfo *attr;
ut32 i = 0;
if (!buffer || sz < 1) {
return NULL;
}
attr = r_bin_java_default_attr_new (buffer, sz, buf_offset);
if (!attr) {
return NULL;
}
attr->type = R_BIN_JAVA_ATTR_TYPE_LOCAL_VARIABLE_TABLE_ATTR;
attr->info.local_variable_table_attr.table_length = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
attr->info.local_variable_table_attr.local_variable_table =\
r_list_newf (r_bin_java_local_variable_table_attr_entry_free);
for (i = 0; i < attr->info.local_variable_table_attr.table_length; i++) {
if (offset + 10 > sz) {
break;
}
curpos = buf_offset + offset;
lvattr = R_NEW0 (RBinJavaLocalVariableAttribute);
lvattr->start_pc = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lvattr->length = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lvattr->name_idx = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lvattr->descriptor_idx = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lvattr->index = R_BIN_JAVA_USHORT (buffer, offset);
offset += 2;
lvattr->file_offset = curpos;
lvattr->name = r_bin_java_get_utf8_from_bin_cp_list (R_BIN_JAVA_GLOBAL_BIN, lvattr->name_idx);
lvattr->size = 10;
if (!lvattr->name) {
lvattr->name = strdup ("NULL");
eprintf ("r_bin_java_local_variable_table_attr_new: Unable to find the name for %d index.\n", lvattr->name_idx);
}
lvattr->descriptor = r_bin_java_get_utf8_from_bin_cp_list (R_BIN_JAVA_GLOBAL_BIN, lvattr->descriptor_idx);
if (!lvattr->descriptor) {
lvattr->descriptor = strdup ("NULL");
eprintf ("r_bin_java_local_variable_table_attr_new: Unable to find the descriptor for %d index.\n", lvattr->descriptor_idx);
}
r_list_append (attr->info.local_variable_table_attr.local_variable_table, lvattr);
}
attr->size = offset;
return attr;
},0

match_mb_charset (struct dfa *d, int s, position pos, int idx)
{
int i;
int match;
int match_len;
int op_len;
char buffer[128];
wchar_t wcbuf[6];
struct mb_char_classes *work_mbc;
int context;
wchar_t wc;
wc = inputwcs[idx];
if (wc == (wchar_t)eolbyte)
{
if (!(syntax_bits & RE_DOT_NEWLINE))
return 0;
}
else if (wc == (wchar_t)'\0')
{
if (syntax_bits & RE_DOT_NOT_NULL)
return 0;
}
context = wchar_context(wc);
if (!SUCCEEDS_IN_CONTEXT(pos.constraint, d->states[s].context, context))
return 0;
work_mbc = &(d->mbcsets[(d->multibyte_prop[pos.index]) >> 2]);
match = !work_mbc->invert;
match_len = (mblen_buf[idx] == 0)? 1 : mblen_buf[idx];
if (wc < NOTCHAR && work_mbc->cset != -1
&& tstbit((unsigned char)wc, d->charclasses[work_mbc->cset]))
goto charset_matched;
for (i = 0; i<work_mbc->nch_classes; i++)
{
if (iswctype((wint_t)wc, work_mbc->ch_classes[i]))
goto charset_matched;
}
strncpy(buffer, (char const *) buf_begin + idx, match_len);
buffer[match_len] = '\0';
for (i = 0; i<work_mbc->nequivs; i++)
{
op_len = strlen(work_mbc->equivs[i]);
strncpy(buffer, (char const *) buf_begin + idx, op_len);
buffer[op_len] = '\0';
if (strcoll(work_mbc->equivs[i], buffer) == 0)
{
match_len = op_len;
goto charset_matched;
}
}
for (i = 0; i<work_mbc->ncoll_elems; i++)
{
op_len = strlen(work_mbc->coll_elems[i]);
strncpy(buffer, (char const *) buf_begin + idx, op_len);
buffer[op_len] = '\0';
if (strcoll(work_mbc->coll_elems[i], buffer) == 0)
{
match_len = op_len;
goto charset_matched;
}
}
wcbuf[0] = wc;
wcbuf[1] = wcbuf[3] = wcbuf[5] = '\0';
for (i = 0; i<work_mbc->nranges; i++)
{
wcbuf[2] = work_mbc->range_sts[i];
wcbuf[4] = work_mbc->range_ends[i];
if (wcscoll(wcbuf, wcbuf+2) >= 0 &&
wcscoll(wcbuf+4, wcbuf) >= 0)
goto charset_matched;
}
for (i = 0; i<work_mbc->nchars; i++)
{
if (wc == work_mbc->chars[i])
goto charset_matched;
}
match = !match;
charset_matched:
return match ? match_len : 0;
},1

Http::Response AbstractWebApplication::processRequest(const Http::Request &request, const Http::Environment &env)
{
session_ = 0;
request_ = request;
env_ = env;
clear();
sessionInitialize();
if (!sessionActive() && !isAuthNeeded())
sessionStart();
if (isBanned()) {
status(403, "Forbidden");
print(QObject::tr("Your IP address has been banned after too many failed authentication attempts."), Http::CONTENT_TYPE_TXT);
}
else {
processRequest();
}
return response();
},1

