static const char *parse_value( cJSON *item, const char *value )
{
if ( ! value )
return 0;
if ( ! strncmp( value, "null", 4 ) ) {
item->type = cJSON_NULL;
return value + 4;
}
if ( ! strncmp( value, "false", 5 ) ) {
item->type = cJSON_False;
return value + 5;
}
if ( ! strncmp( value, "true", 4 ) ) {
item->type = cJSON_True;
item->valueint = 1;
return value + 4;
}
if ( *value == '\"' )
return parse_string( item, value );
if ( *value == '-' || ( *value >= '0' && *value <= '9' ) )
return parse_number( item, value );
if ( *value == '[' )
return parse_array( item, value );
if ( *value == '{' )
return parse_object( item, value );
ep = value;
return 0;
},1

archive_read_format_zip_cleanup(struct archive_read *a)
{
struct zip *zip;
struct zip_entry *zip_entry, *next_zip_entry;
zip = (struct zip *)(a->format->data);
#ifdef HAVE_ZLIB_H
if (zip->stream_valid)
inflateEnd(&zip->stream);
#endif
#if HAVA_LZMA_H && HAVE_LIBLZMA
if (zip->zipx_lzma_valid) {
lzma_end(&zip->zipx_lzma_stream);
}
#endif
#ifdef HAVE_BZLIB_H
if (zip->bzstream_valid) {
BZ2_bzDecompressEnd(&zip->bzstream);
}
#endif
free(zip->uncompressed_buffer);
if (zip->ppmd8_valid)
__archive_ppmd8_functions.Ppmd8_Free(&zip->ppmd8);
if (zip->zip_entries) {
zip_entry = zip->zip_entries;
while (zip_entry != NULL) {
next_zip_entry = zip_entry->next;
archive_string_free(&zip_entry->rsrcname);
free(zip_entry);
zip_entry = next_zip_entry;
}
}
free(zip->decrypted_buffer);
if (zip->cctx_valid)
archive_decrypto_aes_ctr_release(&zip->cctx);
if (zip->hctx_valid)
archive_hmac_sha1_cleanup(&zip->hctx);
free(zip->iv);
free(zip->erd);
free(zip->v_data);
archive_string_free(&zip->format_name);
free(zip);
(a->format->data) = NULL;
return (ARCHIVE_OK);
},1

_bson_iter_next_internal (bson_iter_t *iter,
uint32_t next_keylen,
const char **key,
uint32_t *bson_type,
bool *unsupported)
{
const uint8_t *data;
uint32_t o;
unsigned int len;
BSON_ASSERT (iter);
*unsupported = false;
if (!iter->raw) {
*key = NULL;
*bson_type = BSON_TYPE_EOD;
return false;
}
data = iter->raw;
len = iter->len;
iter->off = iter->next_off;
iter->type = iter->off;
iter->key = iter->off + 1;
iter->d1 = 0;
iter->d2 = 0;
iter->d3 = 0;
iter->d4 = 0;
if (next_keylen == 0) {
for (o = iter->key; o < len; o++) {
if (!data[o]) {
iter->d1 = ++o;
goto fill_data_fields;
}
}
} else {
o = iter->key + next_keylen + 1;
iter->d1 = o;
goto fill_data_fields;
}
goto mark_invalid;
fill_data_fields:
*key = bson_iter_key_unsafe (iter);
*bson_type = ITER_TYPE (iter);
switch (*bson_type) {
case BSON_TYPE_DATE_TIME:
case BSON_TYPE_DOUBLE:
case BSON_TYPE_INT64:
case BSON_TYPE_TIMESTAMP:
iter->next_off = o + 8;
break;
case BSON_TYPE_CODE:
case BSON_TYPE_SYMBOL:
case BSON_TYPE_UTF8: {
uint32_t l;
if ((o + 4) >= len) {
iter->err_off = o;
goto mark_invalid;
}
iter->d2 = o + 4;
memcpy (&l, iter->raw + iter->d1, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if (l > (len - (o + 4))) {
iter->err_off = o;
goto mark_invalid;
}
iter->next_off = o + 4 + l;
if (BSON_UNLIKELY ((l == 0) || (iter->next_off >= len))) {
iter->err_off = o;
goto mark_invalid;
}
if (BSON_UNLIKELY ((iter->raw + iter->d2)[l - 1] != '\0')) {
iter->err_off = o + 4 + l - 1;
goto mark_invalid;
}
} break;
case BSON_TYPE_BINARY: {
bson_subtype_t subtype;
uint32_t l;
if (o >= (len - 4)) {
iter->err_off = o;
goto mark_invalid;
}
iter->d2 = o + 4;
iter->d3 = o + 5;
memcpy (&l, iter->raw + iter->d1, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if (l >= (len - o - 4)) {
iter->err_off = o;
goto mark_invalid;
}
subtype = *(iter->raw + iter->d2);
if (subtype == BSON_SUBTYPE_BINARY_DEPRECATED) {
int32_t binary_len;
if (l < 4) {
iter->err_off = o;
goto mark_invalid;
}
memcpy (&binary_len, (iter->raw + iter->d3), sizeof (binary_len));
binary_len = BSON_UINT32_FROM_LE (binary_len);
if (binary_len + 4 != l) {
iter->err_off = iter->d3;
goto mark_invalid;
}
}
iter->next_off = o + 5 + l;
} break;
case BSON_TYPE_ARRAY:
case BSON_TYPE_DOCUMENT: {
uint32_t l;
if (o >= (len - 4)) {
iter->err_off = o;
goto mark_invalid;
}
memcpy (&l, iter->raw + iter->d1, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if ((l > len) || (l > (len - o))) {
iter->err_off = o;
goto mark_invalid;
}
iter->next_off = o + l;
} break;
case BSON_TYPE_OID:
iter->next_off = o + 12;
break;
case BSON_TYPE_BOOL: {
char val;
if (iter->d1 >= len) {
iter->err_off = o;
goto mark_invalid;
}
memcpy (&val, iter->raw + iter->d1, 1);
if (val != 0x00 && val != 0x01) {
iter->err_off = o;
goto mark_invalid;
}
iter->next_off = o + 1;
} break;
case BSON_TYPE_REGEX: {
bool eor = false;
bool eoo = false;
for (; o < len; o++) {
if (!data[o]) {
iter->d2 = ++o;
eor = true;
break;
}
}
if (!eor) {
iter->err_off = iter->next_off;
goto mark_invalid;
}
for (; o < len; o++) {
if (!data[o]) {
eoo = true;
break;
}
}
if (!eoo) {
iter->err_off = iter->next_off;
goto mark_invalid;
}
iter->next_off = o + 1;
} break;
case BSON_TYPE_DBPOINTER: {
uint32_t l;
if (o >= (len - 4)) {
iter->err_off = o;
goto mark_invalid;
}
iter->d2 = o + 4;
memcpy (&l, iter->raw + iter->d1, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if (l == 0 || l > (len - o - 4)) {
iter->err_off = o;
goto mark_invalid;
}
if (*(iter->raw + o + l + 3)) {
iter->err_off = o + l + 3;
goto mark_invalid;
}
iter->d3 = o + 4 + l;
iter->next_off = o + 4 + l + 12;
} break;
case BSON_TYPE_CODEWSCOPE: {
uint32_t l;
uint32_t doclen;
if ((len < 19) || (o >= (len - 14))) {
iter->err_off = o;
goto mark_invalid;
}
iter->d2 = o + 4;
iter->d3 = o + 8;
memcpy (&l, iter->raw + iter->d1, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if ((l < 14) || (l >= (len - o))) {
iter->err_off = o;
goto mark_invalid;
}
iter->next_off = o + l;
if (iter->next_off >= len) {
iter->err_off = o;
goto mark_invalid;
}
memcpy (&l, iter->raw + iter->d2, sizeof (l));
l = BSON_UINT32_FROM_LE (l);
if (l == 0 || l >= (len - o - 4 - 4)) {
iter->err_off = o;
goto mark_invalid;
}
if ((o + 4 + 4 + l + 4) >= iter->next_off) {
iter->err_off = o + 4;
goto mark_invalid;
}
iter->d4 = o + 4 + 4 + l;
memcpy (&doclen, iter->raw + iter->d4, sizeof (doclen));
doclen = BSON_UINT32_FROM_LE (doclen);
if ((o + 4 + 4 + l + doclen) != iter->next_off) {
iter->err_off = o + 4 + 4 + l;
goto mark_invalid;
}
} break;
case BSON_TYPE_INT32:
iter->next_off = o + 4;
break;
case BSON_TYPE_DECIMAL128:
iter->next_off = o + 16;
break;
case BSON_TYPE_MAXKEY:
case BSON_TYPE_MINKEY:
case BSON_TYPE_NULL:
case BSON_TYPE_UNDEFINED:
iter->next_off = o;
break;
default:
*unsupported = true;
case BSON_TYPE_EOD:
iter->err_off = o;
goto mark_invalid;
}
if (iter->next_off >= len) {
iter->err_off = o;
goto mark_invalid;
}
iter->err_off = 0;
return true;
mark_invalid:
iter->raw = NULL;
iter->len = 0;
iter->next_off = 0;
return false;
},0

_forkexec_slurmstepd(uint16_t type, void *req,
slurm_addr_t *cli, slurm_addr_t *self,
const hostset_t step_hset, uint16_t protocol_version)
{
pid_t pid;
int to_stepd[2] = {-1, -1};
int to_slurmd[2] = {-1, -1};
if (pipe(to_stepd) < 0 || pipe(to_slurmd) < 0) {
error("_forkexec_slurmstepd pipe failed: %m");
return SLURM_FAILURE;
}
if (_add_starting_step(type, req)) {
error("_forkexec_slurmstepd failed in _add_starting_step: %m");
return SLURM_FAILURE;
}
if ((pid = fork()) < 0) {
error("_forkexec_slurmstepd: fork: %m");
close(to_stepd[0]);
close(to_stepd[1]);
close(to_slurmd[0]);
close(to_slurmd[1]);
_remove_starting_step(type, req);
return SLURM_FAILURE;
} else if (pid > 0) {
int rc = SLURM_SUCCESS;
#if (SLURMSTEPD_MEMCHECK == 0)
int i;
time_t start_time = time(NULL);
#endif
if (close(to_stepd[0]) < 0)
error("Unable to close read to_stepd in parent: %m");
if (close(to_slurmd[1]) < 0)
error("Unable to close write to_slurmd in parent: %m");
if ((rc = _send_slurmstepd_init(to_stepd[1], type,
req, cli, self,
step_hset,
protocol_version)) != 0) {
error("Unable to init slurmstepd");
goto done;
}
#if (SLURMSTEPD_MEMCHECK == 0)
i = read(to_slurmd[0], &rc, sizeof(int));
if (i < 0) {
error("%s: Can not read return code from slurmstepd "
"got %d: %m", __func__, i);
rc = SLURM_FAILURE;
} else if (i != sizeof(int)) {
error("%s: slurmstepd failed to send return code "
"got %d: %m", __func__, i);
rc = SLURM_FAILURE;
} else {
int delta_time = time(NULL) - start_time;
int cc;
if (delta_time > 5) {
info("Warning: slurmstepd startup took %d sec, "
"possible file system problem or full "
"memory", delta_time);
}
if (rc != SLURM_SUCCESS)
error("slurmstepd return code %d", rc);
cc = SLURM_SUCCESS;
cc = write(to_stepd[1], &cc, sizeof(int));
if (cc != sizeof(int)) {
error("%s: failed to send ack to stepd %d: %m",
__func__, cc);
}
}
#endif
done:
if (_remove_starting_step(type, req))
error("Error cleaning up starting_step list");
if (waitpid(pid, NULL, 0) < 0)
error("Unable to reap slurmd child process");
if (close(to_stepd[1]) < 0)
error("close write to_stepd in parent: %m");
if (close(to_slurmd[0]) < 0)
error("close read to_slurmd in parent: %m");
return rc;
} else {
#if (SLURMSTEPD_MEMCHECK == 1)
char *const argv[3] = {"memcheck",
(char *)conf->stepd_loc, NULL};
#elif (SLURMSTEPD_MEMCHECK == 2)
uint32_t job_id = 0, step_id = 0;
char log_file[256];
char *const argv[13] = {"valgrind", "--tool=memcheck",
"--error-limit=no",
"--leak-check=summary",
"--show-reachable=yes",
"--max-stackframe=16777216",
"--num-callers=20",
"--child-silent-after-fork=yes",
"--track-origins=yes",
log_file, (char *)conf->stepd_loc,
NULL};
if (type == LAUNCH_BATCH_JOB) {
job_id = ((batch_job_launch_msg_t *)req)->job_id;
step_id = ((batch_job_launch_msg_t *)req)->step_id;
} else if (type == LAUNCH_TASKS) {
job_id = ((launch_tasks_request_msg_t *)req)->job_id;
step_id = ((launch_tasks_request_msg_t *)req)->job_step_id;
}
snprintf(log_file, sizeof(log_file),
"--log-file=/tmp/slurmstepd_valgrind_%u.%u",
job_id, step_id);
#elif (SLURMSTEPD_MEMCHECK == 3)
uint32_t job_id = 0, step_id = 0;
char log_file[256];
char *const argv[10] = {"valgrind", "--tool=drd",
"--error-limit=no",
"--max-stackframe=16777216",
"--num-callers=20",
"--child-silent-after-fork=yes",
log_file, (char *)conf->stepd_loc,
NULL};
if (type == LAUNCH_BATCH_JOB) {
job_id = ((batch_job_launch_msg_t *)req)->job_id;
step_id = ((batch_job_launch_msg_t *)req)->step_id;
} else if (type == LAUNCH_TASKS) {
job_id = ((launch_tasks_request_msg_t *)req)->job_id;
step_id = ((launch_tasks_request_msg_t *)req)->job_step_id;
}
snprintf(log_file, sizeof(log_file),
"--log-file=/tmp/slurmstepd_valgrind_%u.%u",
job_id, step_id);
#elif (SLURMSTEPD_MEMCHECK == 4)
uint32_t job_id = 0, step_id = 0;
char log_file[256];
char *const argv[10] = {"valgrind", "--tool=helgrind",
"--error-limit=no",
"--max-stackframe=16777216",
"--num-callers=20",
"--child-silent-after-fork=yes",
log_file, (char *)conf->stepd_loc,
NULL};
if (type == LAUNCH_BATCH_JOB) {
job_id = ((batch_job_launch_msg_t *)req)->job_id;
step_id = ((batch_job_launch_msg_t *)req)->step_id;
} else if (type == LAUNCH_TASKS) {
job_id = ((launch_tasks_request_msg_t *)req)->job_id;
step_id = ((launch_tasks_request_msg_t *)req)->job_step_id;
}
snprintf(log_file, sizeof(log_file),
"--log-file=/tmp/slurmstepd_valgrind_%u.%u",
job_id, step_id);
#else
char *const argv[2] = { (char *)conf->stepd_loc, NULL};
#endif
int i;
int failed = 0;
setenv("SLURM_CONF", conf->conffile, 1);
if (setsid() < 0) {
error("_forkexec_slurmstepd: setsid: %m");
failed = 1;
}
if ((pid = fork()) < 0) {
error("_forkexec_slurmstepd: "
"Unable to fork grandchild: %m");
failed = 2;
} else if (pid > 0) {
exit(0);
}
for (i=3; i<256; i++) {
(void) fcntl(i, F_SETFD, FD_CLOEXEC);
}
if ((to_stepd[0] != conf->lfd)
&& (to_slurmd[1] != conf->lfd))
slurm_shutdown_msg_engine(conf->lfd);
if (close(to_stepd[1]) < 0)
error("close write to_stepd in grandchild: %m");
if (close(to_slurmd[0]) < 0)
error("close read to_slurmd in parent: %m");
(void) close(STDIN_FILENO);
if (dup2(to_stepd[0], STDIN_FILENO) == -1) {
error("dup2 over STDIN_FILENO: %m");
exit(1);
}
fd_set_close_on_exec(to_stepd[0]);
(void) close(STDOUT_FILENO);
if (dup2(to_slurmd[1], STDOUT_FILENO) == -1) {
error("dup2 over STDOUT_FILENO: %m");
exit(1);
}
fd_set_close_on_exec(to_slurmd[1]);
(void) close(STDERR_FILENO);
if (dup2(devnull, STDERR_FILENO) == -1) {
error("dup2 /dev/null to STDERR_FILENO: %m");
exit(1);
}
fd_set_noclose_on_exec(STDERR_FILENO);
log_fini();
if (!failed) {
if (conf->chos_loc && !access(conf->chos_loc, X_OK))
execvp(conf->chos_loc, argv);
else
execvp(argv[0], argv);
error("exec of slurmstepd failed: %m");
}
exit(2);
}
},0

QPDF::dumpHSharedObject()
{
HSharedObject& t = this->m->shared_object_hints;
*this->m->out_stream
<< "first_shared_obj: " << t.first_shared_obj
<< std::endl
<< "first_shared_offset: " << adjusted_offset(t.first_shared_offset)
<< std::endl
<< "nshared_first_page: " << t.nshared_first_page
<< std::endl
<< "nshared_total: " << t.nshared_total
<< std::endl
<< "nbits_nobjects: " << t.nbits_nobjects
<< std::endl
<< "min_group_length: " << t.min_group_length
<< std::endl
<< "nbits_delta_group_length: " << t.nbits_delta_group_length
<< std::endl;
for (int i = 0; i < t.nshared_total; ++i)
{
HSharedObjectEntry& se = t.entries.at(i);
*this->m->out_stream
<< "Shared Object " << i << ":" << std::endl
<< " group length: "
<< se.delta_group_length + t.min_group_length << std::endl;
if (se.signature_present)
{
*this->m->out_stream << " signature present" << std::endl;
}
if (se.nobjects_minus_one != 0)
{
*this->m->out_stream << " nobjects: "
<< se.nobjects_minus_one + 1 << std::endl;
}
}
