int ping_common_sendmsg(int family, struct msghdr *msg, size_t len,
void *user_icmph, size_t icmph_len) {
u8 type, code;
if (len > 0xFFFF)
return -EMSGSIZE;
if (msg->msg_flags & MSG_OOB)
return -EOPNOTSUPP;
if (memcpy_from_msg(user_icmph, msg, icmph_len))
return -EFAULT;
if (family == AF_INET) {
type = ((struct icmphdr *) user_icmph)->type;
code = ((struct icmphdr *) user_icmph)->code;
#if IS_ENABLED(CONFIG_IPV6)
} else if (family == AF_INET6) {
type = ((struct icmp6hdr *) user_icmph)->icmp6_type;
code = ((struct icmp6hdr *) user_icmph)->icmp6_code;
#endif
} else {
BUG();
}
if (!ping_supported(family, type, code))
return -EINVAL;
return 0;
},1

int encode_msg(struct sip_msg *msg,char *payload,int len)
{
int i,j,k,u,request;
unsigned short int h;
struct hdr_field* hf;
struct msg_start* ms;
struct sip_uri miuri;
char *myerror=NULL;
ptrdiff_t diff;
if(len < MAX_ENCODED_MSG + MAX_MESSAGE_LEN)
return -1;
if(parse_headers(msg,HDR_EOH_F,0)<0){
myerror="in parse_headers";
goto error;
}
memset(payload,0,len);
ms=&msg->first_line;
if(ms->type == SIP_REQUEST)
request=1;
else if(ms->type == SIP_REPLY)
request=0;
else{
myerror="message is neither request nor response";
goto error;
}
if(request) {
for(h=0;h<32;j=(0x01<<h),h++)
if(j & ms->u.request.method_value)
break;
} else {
h=(unsigned short)(ms->u.reply.statuscode);
}
if(h==32){
myerror="unknown message type\n";
goto error;
}
h=htons(h);
memcpy(payload,&h,2);
h=htons((unsigned short int)msg->len);
memcpy(&payload[MSG_LEN_IDX],&h,2);
if(0>(diff=(get_body(msg)-(msg->buf)))){
myerror="body starts before the message (uh ?)";
goto error;
}else
h=htons((unsigned short int)diff);
memcpy(payload+CONTENT_IDX,&h,2);
payload[METHOD_CODE_IDX]=(unsigned char)(request?
(ms->u.request.method.s-msg->buf):
(ms->u.reply.status.s-msg->buf));
payload[METHOD_CODE_IDX+1]=(unsigned char)(request?
(ms->u.request.method.len):
(ms->u.reply.status.len));
payload[URI_REASON_IDX]=(unsigned char)(request?
(ms->u.request.uri.s-msg->buf):
(ms->u.reply.reason.s-msg->buf));
payload[URI_REASON_IDX+1]=(unsigned char)(request?
(ms->u.request.uri.len):
(ms->u.reply.reason.len));
payload[VERSION_IDX]=(unsigned char)(request?
(ms->u.request.version.s-msg->buf):
(ms->u.reply.version.s-msg->buf));
if(request){
if (parse_uri(ms->u.request.uri.s,ms->u.request.uri.len, &miuri)<0){
LM_ERR("<%.*s>\n",ms->u.request.uri.len,ms->u.request.uri.s);
myerror="while parsing the R-URI";
goto error;
}
if(0>(j=encode_uri2(msg->buf,
ms->u.request.method.s-msg->buf+ms->len,
ms->u.request.uri,&miuri,
(unsigned char*)&payload[REQUEST_URI_IDX+1])))
{
myerror="ENCODE_MSG: ERROR while encoding the R-URI";
goto error;
}
payload[REQUEST_URI_IDX]=(unsigned char)j;
k=REQUEST_URI_IDX+1+j;
}else
k=REQUEST_URI_IDX;
u=k;
k++;
for(i=0,hf=msg->headers;hf;hf=hf->next,i++);
i++;
j=k+3*i;
for(i=0,hf=msg->headers;hf;hf=hf->next,k+=3){
payload[k]=(unsigned char)(hf->type & 0xFF);
h=htons(j);
memcpy(&payload[k+1],&h,2);
if(0>(i=encode_header(msg,hf,(unsigned char*)(payload+j),MAX_ENCODED_MSG+MAX_MESSAGE_LEN-j))){
LM_ERR("encoding header %.*s\n",hf->name.len,hf->name.s);
goto error;
k-=3;
continue;
}
j+=(unsigned short int)i;
}
payload[u]=(unsigned char)((k-u-1)/3);
j=htons(j);
memcpy(&payload[k+1],&j,2);
k+=3;
j=ntohs(j);
memcpy(&payload[j],msg->buf,msg->len);
LM_DBG("msglen = %d,msg starts at %d\n",msg->len,j);
j=htons(j);
memcpy(&payload[MSG_START_IDX],&j,2);
return GET_PAY_SIZE( payload );
error:
LM_ERR("%s\n",myerror);
return -1;
},1

get_next_reel (int tape_des)
{
static int reel_number = 1;
FILE *tty_in;
FILE *tty_out;
int old_tape_des;
char *next_archive_name;
dynamic_string new_name;
char *str_res;
ds_init (&new_name, 128);
tty_in = fopen (TTY_NAME, "r");
if (tty_in == NULL)
error (PAXEXIT_FAILURE, errno, TTY_NAME);
tty_out = fopen (TTY_NAME, "w");
if (tty_out == NULL)
error (PAXEXIT_FAILURE, errno, TTY_NAME);
old_tape_des = tape_des;
tape_offline (tape_des);
rmtclose (tape_des);
++reel_number;
if (new_media_message)
fprintf (tty_out, "%s", new_media_message);
else if (new_media_message_with_number)
fprintf (tty_out, "%s%d%s", new_media_message_with_number, reel_number,
new_media_message_after_number);
else if (archive_name)
fprintf (tty_out, _("Found end of tape. Load next tape and press RETURN. "));
else
fprintf (tty_out, _("Found end of tape. To continue, type device/file name when ready.\n"));
fflush (tty_out);
if (archive_name)
{
int c;
do
c = getc (tty_in);
while (c != EOF && c != '\n');
tape_des = open_archive (archive_name);
if (tape_des == -1)
open_error (archive_name);
}
else
{
do
{
if (tape_des < 0)
{
fprintf (tty_out,
_("To continue, type device/file name when ready.\n"));
fflush (tty_out);
}
str_res = ds_fgets (tty_in, &new_name);
if (str_res == NULL || str_res[0] == '\0')
exit (PAXEXIT_FAILURE);
next_archive_name = str_res;
tape_des = open_archive (next_archive_name);
if (tape_des == -1)
open_error (next_archive_name);
}
while (tape_des < 0);
}
if (tape_des != old_tape_des)
error (PAXEXIT_FAILURE, 0, _("internal error: tape descriptor changed from %d to %d"),
old_tape_des, tape_des);
free (new_name.ds_string);
fclose (tty_in);
fclose (tty_out);
},1

int main(int argc, char *argv[])
{
char *p, *q, *r;
Clp_Parser *clp =
Clp_NewParser(argc, (const char * const *)argv, sizeof(options) / sizeof(options[0]), options);
program_name = Clp_ProgramName(clp);
while (1) {
int opt = Clp_Next(clp);
switch (opt) {
case BLOCK_LEN_OPT:
blocklen = clp->val.i;
break;
output_file:
case OUTPUT_OPT:
if (ofp)
fatal_error("output file already specified");
if (strcmp(clp->vstr, "-") == 0)
ofp = stdout;
else if (!(ofp = fopen(clp->vstr, "w")))
fatal_error("%s: %s", clp->vstr, strerror(errno));
break;
case PFB_OPT:
pfb = 1;
break;
case PFA_OPT:
pfb = 0;
break;
case HELP_OPT:
usage();
exit(0);
break;
case VERSION_OPT:
printf("t1asm (LCDF t1utils) %s\n", VERSION);
printf("Copyright (C) 1992-2010 I. Lee Hetherington, Eddie Kohler et al.\n\
This is free software; see the source for copying conditions.\n\
There is NO warranty, not even for merchantability or fitness for a\n\
particular purpose.\n");
exit(0);
break;
case Clp_NotOption:
if (ifp && ofp)
fatal_error("too many arguments");
else if (ifp)
goto output_file;
if (strcmp(clp->vstr, "-") == 0)
ifp = stdin;
else if (!(ifp = fopen(clp->vstr, "r")))
fatal_error("%s: %s", clp->vstr, strerror(errno));
break;
case Clp_Done:
goto done;
case Clp_BadOption:
short_usage();
exit(1);
break;
}
}
done:
if (!pfb) {
if (blocklen == -1)
blocklen = 64;
else if (blocklen < 8) {
blocklen = 8;
error("warning: line length raised to %d", blocklen);
} else if (blocklen > 1024) {
blocklen = 1024;
error("warning: line length lowered to %d", blocklen);
}
}
if (!ifp) ifp = stdin;
if (!ofp) ofp = stdout;
if (pfb)
init_pfb_writer(&w, blocklen, ofp);
#if defined(_MSDOS) || defined(_WIN32)
if (pfb)
_setmode(_fileno(ofp), _O_BINARY);
#endif
while (!feof(ifp) && !ferror(ifp)) {
t1utils_getline();
if (!ever_active) {
if (strncmp(line, "currentfile eexec", 17) == 0 && isspace(line[17])) {
for (p = line + 18; isspace(*p); p++)
;
eexec_start(p);
continue;
} else if (strncmp(line, "/lenIV", 6) == 0) {
lenIV = atoi(line + 6);
} else if ((p = strstr(line, "string currentfile"))
&& strstr(line, "readstring")) {
*p = '\0';
q = strrchr(line, '/');
if (q) {
r = cs_start;
++q;
while (!isspace(*q) && *q != '{')
*r++ = *q++;
*r = '\0';
}
*p = 's';
}
}
if (!active) {
if ((p = strstr(line, "/Subrs")) && isdigit(p[7]))
ever_active = active = 1;
else if ((p = strstr(line, "/CharStrings")) && isdigit(p[13]))
ever_active = active = 1;
}
if ((p = strstr(line, "currentfile closefile"))) {
p += sizeof("currentfile closefile") - 1;
for (q = p; isspace(*q) && *q != '\n'; q++)
;
if (q == p && !*q)
error("warning: `currentfile closefile' line too long");
else if (q != p) {
if (*q != '\n')
error("text after `currentfile closefile' ignored");
*p++ = '\n';
*p++ = '\0';
}
eexec_string(line);
break;
}
eexec_string(line);
if (start_charstring) {
if (!cs_start[0])
fatal_error("couldn't find charstring start command");
parse_charstring();
}
}
if (in_eexec)
eexec_end();
while (!feof(ifp) && !ferror(ifp)) {
t1utils_getline();
eexec_string(line);
}
if (pfb)
pfb_writer_end(&w);
if (!ever_active)
error("warning: no charstrings found in input file");
fclose(ifp);
fclose(ofp);
return 0;
},1

