static int v4l2loopback_set_ctrl( struct v4l2_loopback_device *dev,
u32 id,
s64 val)
{
switch (id) {
case CID_KEEP_FORMAT:
if (val < 0 || val > 1)
return -EINVAL;
dev->keep_format = val;
try_free_buffers(dev);
break;
case CID_SUSTAIN_FRAMERATE:
if (val < 0 || val > 1)
return -EINVAL;
spin_lock_bh(&dev->lock);
dev->sustain_framerate = val;
check_timers(dev);
spin_unlock_bh(&dev->lock);
break;
case CID_TIMEOUT:
if (val < 0 || val > MAX_TIMEOUT)
return -EINVAL;
spin_lock_bh(&dev->lock);
dev->timeout_jiffies = msecs_to_jiffies(val);
check_timers(dev);
spin_unlock_bh(&dev->lock);
allocate_timeout_image(dev);
break;
case CID_TIMEOUT_IMAGE_IO:
if (val < 0 || val > 1)
return -EINVAL;
dev->timeout_image_io = val;
break;
default:
return -EINVAL;
}
return 0;
},0

void shut(pid_t pid) {
EUID_ASSERT();
EUID_ROOT();
char *comm = pid_proc_comm(pid);
EUID_USER();
if (comm) {
if (strcmp(comm, "firejail") != 0) {
fprintf(stderr, "Error: this is not a firejail sandbox\n");
exit(1);
}
free(comm);
}
else {
fprintf(stderr, "Error: cannot find process %d\n", pid);
exit(1);
}
uid_t uid = getuid();
if (uid != 0) {
uid_t sandbox_uid = pid_get_uid(pid);
if (uid != sandbox_uid) {
fprintf(stderr, "Error: permission is denied to shutdown a sandbox created by a different user.\n");
exit(1);
}
}
printf("Sending SIGTERM to %u\n", pid);
kill(pid, SIGTERM);
int monsec = 11;
char *monfile;
if (asprintf(&monfile, "/proc/%d/cmdline", pid) == -1)
errExit("asprintf");
int killdone = 0;
while (monsec) {
sleep(1);
monsec--;
EUID_ROOT();
FILE *fp = fopen(monfile, "re");
EUID_USER();
if (!fp) {
killdone = 1;
break;
}
char c;
size_t count = fread(&c, 1, 1, fp);
fclose(fp);
if (count == 0) {
killdone = 1;
break;
}
}
free(monfile);
if (!killdone) {
pid_t child;
if (find_child(pid, &child) == 0) {
printf("Sending SIGKILL to %u\n", child);
kill(child, SIGKILL);
}
printf("Sending SIGKILL to %u\n", pid);
kill(pid, SIGKILL);
}
EUID_ROOT();
delete_run_files(pid);
},1

