ccbaWriteStream(FILE *fp,
CCBORDA *ccba)
{
char strbuf[256];
l_uint8 bval;
l_uint8 *datain, *dataout;
l_int32 i, j, k, bx, by, bw, bh, val, startx, starty;
l_int32 ncc, nb, n;
l_uint32 w, h;
size_t inbytes, outbytes;
L_BBUFFER *bbuf;
CCBORD *ccb;
NUMA *na;
NUMAA *naa;
PTA *pta;
PROCNAME("ccbaWriteStream");
#if !HAVE_LIBZ
return ERROR_INT("no libz: can't write data", procName, 1);
#else
if (!fp)
return ERROR_INT("stream not open", procName, 1);
if (!ccba)
return ERROR_INT("ccba not defined", procName, 1);
if ((bbuf = bbufferCreate(NULL, 1000)) == NULL)
return ERROR_INT("bbuf not made", procName, 1);
ncc = ccbaGetCount(ccba);
snprintf(strbuf, sizeof(strbuf), "ccba: %7d cc\n", ncc);
bbufferRead(bbuf, (l_uint8 *)strbuf, 18);
w = pixGetWidth(ccba->pix);
h = pixGetHeight(ccba->pix);
bbufferRead(bbuf, (l_uint8 *)&w, 4);
bbufferRead(bbuf, (l_uint8 *)&h, 4);
for (i = 0; i < ncc; i++) {
ccb = ccbaGetCcb(ccba, i);
if (boxaGetBoxGeometry(ccb->boxa, 0, &bx, &by, &bw, &bh)) {
bbufferDestroy(&bbuf);
ccbDestroy(&ccb);
return ERROR_INT("bounding box not found", procName, 1);
}
bbufferRead(bbuf, (l_uint8 *)&bx, 4);
bbufferRead(bbuf, (l_uint8 *)&by, 4);
bbufferRead(bbuf, (l_uint8 *)&bw, 4);
bbufferRead(bbuf, (l_uint8 *)&bh, 4);
if ((naa = ccb->step) == NULL) {
ccbaGenerateStepChains(ccba);
naa = ccb->step;
}
nb = numaaGetCount(naa);
bbufferRead(bbuf, (l_uint8 *)&nb, 4);
pta = ccb->start;
for (j = 0; j < nb; j++) {
ptaGetIPt(pta, j, &startx, &starty);
bbufferRead(bbuf, (l_uint8 *)&startx, 4);
bbufferRead(bbuf, (l_uint8 *)&starty, 4);
na = numaaGetNuma(naa, j, L_CLONE);
n = numaGetCount(na);
for (k = 0; k < n; k++) {
numaGetIValue(na, k, &val);
if (k % 2 == 0)
bval = (l_uint8)val << 4;
else
bval |= (l_uint8)val;
if (k % 2 == 1)
bbufferRead(bbuf, (l_uint8 *)&bval, 1);
}
if (n % 2 == 1) {
bval |= 0x8;
bbufferRead(bbuf, (l_uint8 *)&bval, 1);
} else {
bval = 0x88;
bbufferRead(bbuf, (l_uint8 *)&bval, 1);
}
numaDestroy(&na);
}
ccbDestroy(&ccb);
}
datain = bbufferDestroyAndSaveData(&bbuf, &inbytes);
dataout = zlibCompress(datain, inbytes, &outbytes);
fwrite(dataout, 1, outbytes, fp);
LEPT_FREE(datain);
LEPT_FREE(dataout);
return 0;
#endif
},0

PickContigCase(TIFFRGBAImage* img)
{
img->get = TIFFIsTiled(img->tif) ? gtTileContig : gtStripContig;
img->put.contig = NULL;
switch (img->photometric) {
case PHOTOMETRIC_RGB:
switch (img->bitspersample) {
case 8:
if (img->alpha == EXTRASAMPLE_ASSOCALPHA)
img->put.contig = putRGBAAcontig8bittile;
else if (img->alpha == EXTRASAMPLE_UNASSALPHA)
{
if (BuildMapUaToAa(img))
img->put.contig = putRGBUAcontig8bittile;
}
else
img->put.contig = putRGBcontig8bittile;
break;
case 16:
if (img->alpha == EXTRASAMPLE_ASSOCALPHA)
{
if (BuildMapBitdepth16To8(img))
img->put.contig = putRGBAAcontig16bittile;
}
else if (img->alpha == EXTRASAMPLE_UNASSALPHA)
{
if (BuildMapBitdepth16To8(img) &&
BuildMapUaToAa(img))
img->put.contig = putRGBUAcontig16bittile;
}
else
{
if (BuildMapBitdepth16To8(img))
img->put.contig = putRGBcontig16bittile;
}
break;
}
break;
case PHOTOMETRIC_SEPARATED:
if (buildMap(img)) {
if (img->bitspersample == 8) {
if (!img->Map)
img->put.contig = putRGBcontig8bitCMYKtile;
else
img->put.contig = putRGBcontig8bitCMYKMaptile;
}
}
break;
case PHOTOMETRIC_PALETTE:
if (buildMap(img)) {
switch (img->bitspersample) {
case 8:
img->put.contig = put8bitcmaptile;
break;
case 4:
img->put.contig = put4bitcmaptile;
break;
case 2:
img->put.contig = put2bitcmaptile;
break;
case 1:
img->put.contig = put1bitcmaptile;
break;
}
}
break;
case PHOTOMETRIC_MINISWHITE:
case PHOTOMETRIC_MINISBLACK:
if (buildMap(img)) {
switch (img->bitspersample) {
case 16:
img->put.contig = put16bitbwtile;
break;
case 8:
if (img->alpha && img->samplesperpixel == 2)
img->put.contig = putagreytile;
else
img->put.contig = putgreytile;
break;
case 4:
img->put.contig = put4bitbwtile;
break;
case 2:
img->put.contig = put2bitbwtile;
break;
case 1:
img->put.contig = put1bitbwtile;
break;
}
}
break;
case PHOTOMETRIC_YCBCR:
if ((img->bitspersample==8) && (img->samplesperpixel==3))
{
if (initYCbCrConversion(img)!=0)
{
uint16 SubsamplingHor;
uint16 SubsamplingVer;
TIFFGetFieldDefaulted(img->tif, TIFFTAG_YCBCRSUBSAMPLING, &SubsamplingHor, &SubsamplingVer);
switch ((SubsamplingHor<<4)|SubsamplingVer) {
case 0x44:
img->put.contig = putcontig8bitYCbCr44tile;
break;
case 0x42:
img->put.contig = putcontig8bitYCbCr42tile;
break;
case 0x41:
img->put.contig = putcontig8bitYCbCr41tile;
break;
case 0x22:
img->put.contig = putcontig8bitYCbCr22tile;
break;
case 0x21:
img->put.contig = putcontig8bitYCbCr21tile;
break;
case 0x12:
img->put.contig = putcontig8bitYCbCr12tile;
break;
case 0x11:
img->put.contig = putcontig8bitYCbCr11tile;
break;
}
}
}
break;
case PHOTOMETRIC_CIELAB:
if (buildMap(img)) {
if (img->bitspersample == 8)
img->put.contig = initCIELabConversion(img);
break;
}
}
return ((img->get!=NULL) && (img->put.contig!=NULL));
},1

CImg<T>& mirror(const char axis) {
if (is_empty()) return *this;
T *pf, *pb, *buf = 0;
switch (cimg::lowercase(axis)) {
case 'x' : {
pf = _data; pb = data(_width - 1);
const unsigned int width2 = _width/2;
for (unsigned int yzv = 0; yzv<_height*_depth*_spectrum; ++yzv) {
for (unsigned int x = 0; x<width2; ++x) { const T val = *pf; *(pf++) = *pb; *(pb--) = val; }
pf+=_width - width2;
pb+=_width + width2;
}
} break;
case 'y' : {
buf = new T[_width];
pf = _data; pb = data(0,_height - 1);
const unsigned int height2 = _height/2;
for (unsigned int zv = 0; zv<_depth*_spectrum; ++zv) {
for (unsigned int y = 0; y<height2; ++y) {
std::memcpy(buf,pf,_width*sizeof(T));
std::memcpy(pf,pb,_width*sizeof(T));
std::memcpy(pb,buf,_width*sizeof(T));
pf+=_width;
pb-=_width;
}
pf+=(ulongT)_width*(_height - height2);
pb+=(ulongT)_width*(_height + height2);
}
} break;
case 'z' : {
buf = new T[(ulongT)_width*_height];
pf = _data; pb = data(0,0,_depth - 1);
const unsigned int depth2 = _depth/2;
cimg_forC(*this,c) {
for (unsigned int z = 0; z<depth2; ++z) {
std::memcpy(buf,pf,_width*_height*sizeof(T));
std::memcpy(pf,pb,_width*_height*sizeof(T));
std::memcpy(pb,buf,_width*_height*sizeof(T));
pf+=(ulongT)_width*_height;
pb-=(ulongT)_width*_height;
}
pf+=(ulongT)_width*_height*(_depth - depth2);
pb+=(ulongT)_width*_height*(_depth + depth2);
}
} break;
case 'c' : {
buf = new T[(ulongT)_width*_height*_depth];
pf = _data; pb = data(0,0,0,_spectrum - 1);
const unsigned int _spectrum2 = _spectrum/2;
for (unsigned int v = 0; v<_spectrum2; ++v) {
std::memcpy(buf,pf,_width*_height*_depth*sizeof(T));
std::memcpy(pf,pb,_width*_height*_depth*sizeof(T));
std::memcpy(pb,buf,_width*_height*_depth*sizeof(T));
pf+=(ulongT)_width*_height*_depth;
pb-=(ulongT)_width*_height*_depth;
}
} break;
default :
throw CImgArgumentException(_cimg_instance
"mirror(): Invalid specified axis '%c'.",
cimg_instance,
axis);
}
delete[] buf;
return *this;
},0

static irqreturn_t i8042_interrupt(int irq, void *dev_id)
{
struct i8042_port *port;
struct serio *serio;
unsigned long flags;
unsigned char str, data;
unsigned int dfl;
unsigned int port_no;
bool filtered;
int ret = 1;
spin_lock_irqsave(&i8042_lock, flags);
str = i8042_read_status();
if (unlikely(~str & I8042_STR_OBF)) {
spin_unlock_irqrestore(&i8042_lock, flags);
if (irq)
dbg("Interrupt %d, without any data\n", irq);
ret = 0;
goto out;
}
data = i8042_read_data();
if (i8042_mux_present && (str & I8042_STR_AUXDATA)) {
static unsigned long last_transmit;
static unsigned char last_str;
dfl = 0;
if (str & I8042_STR_MUXERR) {
dbg("MUX error, status is %02x, data is %02x\n",
str, data);
switch (data) {
default:
if (time_before(jiffies, last_transmit + HZ/10)) {
str = last_str;
break;
}
case 0xfc:
case 0xfd:
case 0xfe: dfl = SERIO_TIMEOUT; data = 0xfe; break;
case 0xff: dfl = SERIO_PARITY; data = 0xfe; break;
}
}
port_no = I8042_MUX_PORT_NO + ((str >> 6) & 3);
last_str = str;
last_transmit = jiffies;
} else {
dfl = ((str & I8042_STR_PARITY) ? SERIO_PARITY : 0) |
((str & I8042_STR_TIMEOUT && !i8042_notimeout) ? SERIO_TIMEOUT : 0);
port_no = (str & I8042_STR_AUXDATA) ?
I8042_AUX_PORT_NO : I8042_KBD_PORT_NO;
}
port = &i8042_ports[port_no];
serio = port->exists ? port->serio : NULL;
filter_dbg(port->driver_bound, data, "<- i8042 (interrupt, %d, %d%s%s)\n",
port_no, irq,
dfl & SERIO_PARITY ? ", bad parity" : "",
dfl & SERIO_TIMEOUT ? ", timeout" : "");
filtered = i8042_filter(data, str, serio);
spin_unlock_irqrestore(&i8042_lock, flags);
if (likely(port->exists && !filtered))
serio_interrupt(serio, data, dfl);
out:
return IRQ_RETVAL(ret);
},1

e_ews_get_msg_for_url (CamelEwsSettings *settings,
const gchar *url,
xmlOutputBuffer *buf,
GError **error)
{
SoupMessage *msg;
if (url == NULL) {
g_set_error_literal (
error, G_IO_ERROR, G_IO_ERROR_INVALID_ARGUMENT,
_("URL cannot be NULL"));
return NULL;
}
msg = soup_message_new (buf != NULL ? "POST" : "GET", url);
if (!msg) {
g_set_error (
error, G_IO_ERROR, G_IO_ERROR_INVALID_ARGUMENT,
_("URL “%s” is not valid"), url);
return NULL;
}
e_ews_message_attach_chunk_allocator (msg);
e_ews_message_set_user_agent_header (msg, settings);
if (buf != NULL) {
soup_message_set_request (
msg, "text/xml; charset=utf-8", SOUP_MEMORY_COPY,
(gchar *)
#ifdef LIBXML2_NEW_BUFFER
xmlOutputBufferGetContent (buf), xmlOutputBufferGetSize (buf)
#else
buf->buffer->content, buf->buffer->use
#endif
);
g_signal_connect (
msg, "restarted",
G_CALLBACK (post_restarted), buf);
}
e_ews_debug_dump_raw_soup_request (msg);
return msg;
},1

R_API st64 r_buf_fread_at(RBuffer *b, ut64 addr, ut8 *buf, const char *fmt, int n) {
r_return_val_if_fail (b && buf && fmt, -1);
st64 o_addr = r_buf_seek (b, 0, R_BUF_CUR);
st64 r = r_buf_seek (b, addr, R_BUF_SET);
if (r < 0) {
return r;
}
r = r_buf_fread (b, buf, fmt, n);
r_buf_seek (b, o_addr, R_BUF_SET);
return r;
},1

CURLcode Curl_ssl_addsessionid(struct Curl_easy *data,
struct connectdata *conn,
void *ssl_sessionid,
size_t idsize,
int sockindex)
{
size_t i;
struct Curl_ssl_session *store = &data->state.session[0];
long oldest_age = data->state.session[0].age;
char *clone_host;
char *clone_conn_to_host;
int conn_to_port;
long *general_age;
#ifndef CURL_DISABLE_PROXY
const bool isProxy = CONNECT_PROXY_SSL();
struct ssl_primary_config * const ssl_config = isProxy ?
&conn->proxy_ssl_config :
&conn->ssl_config;
const char *hostname = isProxy ? conn->http_proxy.host.name :
conn->host.name;
#else
const bool isProxy = FALSE;
struct ssl_primary_config * const ssl_config = &conn->ssl_config;
const char *hostname = conn->host.name;
(void)sockindex;
#endif
DEBUGASSERT(SSL_SET_OPTION(primary.sessionid));
clone_host = strdup(hostname);
if(!clone_host)
return CURLE_OUT_OF_MEMORY;
if(conn->bits.conn_to_host) {
clone_conn_to_host = strdup(conn->conn_to_host.name);
if(!clone_conn_to_host) {
free(clone_host);
return CURLE_OUT_OF_MEMORY;
}
}
else
clone_conn_to_host = NULL;
if(conn->bits.conn_to_port)
conn_to_port = conn->conn_to_port;
else
conn_to_port = -1;
if(SSLSESSION_SHARED(data)) {
general_age = &data->share->sessionage;
}
else {
general_age = &data->state.sessionage;
}
for(i = 1; (i < data->set.general_ssl.max_ssl_sessions) &&
data->state.session[i].sessionid; i++) {
if(data->state.session[i].age < oldest_age) {
oldest_age = data->state.session[i].age;
store = &data->state.session[i];
}
}
if(i == data->set.general_ssl.max_ssl_sessions)
Curl_ssl_kill_session(store);
else
store = &data->state.session[i];
store->sessionid = ssl_sessionid;
store->idsize = idsize;
store->age = *general_age;
free(store->name);
free(store->conn_to_host);
store->name = clone_host;
store->conn_to_host = clone_conn_to_host;
store->conn_to_port = conn_to_port;
store->remote_port = isProxy ? (int)conn->port : conn->remote_port;
store->scheme = conn->handler->scheme;
if(!Curl_clone_primary_ssl_config(ssl_config, &store->ssl_config)) {
Curl_free_primary_ssl_config(&store->ssl_config);
store->sessionid = NULL;
free(clone_host);
free(clone_conn_to_host);
return CURLE_OUT_OF_MEMORY;
}
return CURLE_OK;
},1

bytes_richcompare(PyBytesObject *a, PyBytesObject *b, int op)
{
int c;
Py_ssize_t len_a, len_b;
Py_ssize_t min_len;
PyObject *result;
int rc;
if (!(PyBytes_Check(a) && PyBytes_Check(b))) {
if (Py_BytesWarningFlag && (op == Py_EQ || op == Py_NE)) {
rc = PyObject_IsInstance((PyObject*)a,
(PyObject*)&PyUnicode_Type);
if (!rc)
rc = PyObject_IsInstance((PyObject*)b,
(PyObject*)&PyUnicode_Type);
if (rc < 0)
return NULL;
if (rc) {
if (PyErr_WarnEx(PyExc_BytesWarning,
"Comparison between bytes and string", 1))
return NULL;
}
else {
rc = PyObject_IsInstance((PyObject*)a,
(PyObject*)&PyLong_Type);
if (!rc)
rc = PyObject_IsInstance((PyObject*)b,
(PyObject*)&PyLong_Type);
if (rc < 0)
return NULL;
if (rc) {
if (PyErr_WarnEx(PyExc_BytesWarning,
"Comparison between bytes and int", 1))
return NULL;
}
}
}
result = Py_NotImplemented;
}
else if (a == b) {
switch (op) {
case Py_EQ:
case Py_LE:
case Py_GE:
result = Py_True;
break;
case Py_NE:
case Py_LT:
case Py_GT:
result = Py_False;
break;
default:
PyErr_BadArgument();
return NULL;
}
}
else if (op == Py_EQ || op == Py_NE) {
int eq = bytes_compare_eq(a, b);
eq ^= (op == Py_NE);
result = eq ? Py_True : Py_False;
}
else {
len_a = Py_SIZE(a);
len_b = Py_SIZE(b);
min_len = Py_MIN(len_a, len_b);
if (min_len > 0) {
c = Py_CHARMASK(*a->ob_sval) - Py_CHARMASK(*b->ob_sval);
if (c == 0)
c = memcmp(a->ob_sval, b->ob_sval, min_len);
}
else
c = 0;
if (c == 0)
c = (len_a < len_b) ? -1 : (len_a > len_b) ? 1 : 0;
switch (op) {
case Py_LT: c = c < 0; break;
case Py_LE: c = c <= 0; break;
case Py_GT: c = c > 0; break;
case Py_GE: c = c >= 0; break;
default:
PyErr_BadArgument();
return NULL;
}
result = c ? Py_True : Py_False;
}
Py_INCREF(result);
return result;
},0

static int crypto_report(struct sk_buff *in_skb, struct nlmsghdr *in_nlh,
struct nlattr **attrs)
{
struct net *net = sock_net(in_skb->sk);
struct crypto_user_alg *p = nlmsg_data(in_nlh);
struct crypto_alg *alg;
struct sk_buff *skb;
struct crypto_dump_info info;
int err;
if (!null_terminated(p->cru_name) || !null_terminated(p->cru_driver_name))
return -EINVAL;
alg = crypto_alg_match(p, 0);
if (!alg)
return -ENOENT;
err = -ENOMEM;
skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
if (!skb)
goto drop_alg;
info.in_skb = in_skb;
info.out_skb = skb;
info.nlmsg_seq = in_nlh->nlmsg_seq;
info.nlmsg_flags = 0;
err = crypto_report_alg(alg, &info);
drop_alg:
crypto_mod_put(alg);
if (err)
return err;
return nlmsg_unicast(net->crypto_nlsk, skb, NETLINK_CB(in_skb).portid);
},1

