OPJ_UINT32 opj_tcd_get_decoded_tile_size(opj_tcd_t *p_tcd)
{
OPJ_UINT32 i;
OPJ_UINT32 l_data_size = 0;
opj_image_comp_t * l_img_comp = 00;
opj_tcd_tilecomp_t * l_tile_comp = 00;
opj_tcd_resolution_t * l_res = 00;
OPJ_UINT32 l_size_comp, l_remaining;
OPJ_UINT32 l_temp;
l_tile_comp = p_tcd->tcd_image->tiles->comps;
l_img_comp = p_tcd->image->comps;
for (i = 0; i < p_tcd->image->numcomps; ++i) {
l_size_comp = l_img_comp->prec >> 3;
l_remaining = l_img_comp->prec & 7;
if (l_remaining) {
++l_size_comp;
}
if (l_size_comp == 3) {
l_size_comp = 4;
}
l_res = l_tile_comp->resolutions + l_tile_comp->minimum_num_resolutions - 1;
l_temp = (OPJ_UINT32)((l_res->x1 - l_res->x0) * (l_res->y1 -
l_res->y0));
if (l_size_comp && UINT_MAX / l_size_comp < l_temp) {
return UINT_MAX;
}
l_temp *= l_size_comp;
if (l_temp > UINT_MAX - l_data_size) {
return UINT_MAX;
}
l_data_size += l_temp;
++l_img_comp;
++l_tile_comp;
}
return l_data_size;
},0

nfa_get_reganch(nfa_state_T *start, int depth)
{
nfa_state_T *p = start;
if (depth > 4)
return 0;
while (p != NULL)
{
switch (p->c)
{
case NFA_BOL:
case NFA_BOF:
return 1;
case NFA_ZSTART:
case NFA_ZEND:
case NFA_CURSOR:
case NFA_VISUAL:
case NFA_MOPEN:
case NFA_MOPEN1:
case NFA_MOPEN2:
case NFA_MOPEN3:
case NFA_MOPEN4:
case NFA_MOPEN5:
case NFA_MOPEN6:
case NFA_MOPEN7:
case NFA_MOPEN8:
case NFA_MOPEN9:
case NFA_NOPEN:
#ifdef FEAT_SYN_HL
case NFA_ZOPEN:
case NFA_ZOPEN1:
case NFA_ZOPEN2:
case NFA_ZOPEN3:
case NFA_ZOPEN4:
case NFA_ZOPEN5:
case NFA_ZOPEN6:
case NFA_ZOPEN7:
case NFA_ZOPEN8:
case NFA_ZOPEN9:
#endif
p = p->out;
break;
case NFA_SPLIT:
return nfa_get_reganch(p->out, depth + 1)
&& nfa_get_reganch(p->out1, depth + 1);
default:
return 0;
}
}
return 0;
},0

scanner_append_argument (parser_context_t *context_p,
scanner_context_t *scanner_context_p)
{
scanner_literal_pool_t *literal_pool_p = scanner_context_p->active_literal_pool_p;
parser_list_iterator_t literal_iterator;
parser_list_iterator_init (&literal_pool_p->literal_pool, &literal_iterator);
lexer_lit_location_t *literal_location_p = &context_p->token.lit_location;
lexer_lit_location_t *literal_p;
const uint8_t *char_p = literal_location_p->char_p;
prop_length_t length = literal_location_p->length;
JERRY_ASSERT (SCANNER_LITERAL_POOL_MAY_HAVE_ARGUMENTS (literal_pool_p->status_flags));
if (JERRY_LIKELY (!context_p->token.lit_location.has_escape))
{
while ((literal_p = (lexer_lit_location_t *) parser_list_iterator_next (&literal_iterator)) != NULL)
{
if (literal_p->length == length)
{
if (JERRY_LIKELY (!literal_p->has_escape))
{
if (memcmp (literal_p->char_p, char_p, length) == 0)
{
break;
}
}
else if (lexer_compare_identifier_to_string (literal_p, char_p, length))
{
break;
}
}
}
}
else
{
while ((literal_p = (lexer_lit_location_t *) parser_list_iterator_next (&literal_iterator)) != NULL)
{
if (lexer_compare_identifiers (context_p, literal_p, literal_location_p))
{
break;
}
}
}
uint8_t literal_type = SCANNER_LITERAL_IS_ARG;
if (literal_p != NULL)
{
literal_p->length = 0;
#if JERRY_ESNEXT
if (literal_p->type & SCANNER_LITERAL_IS_USED)
{
literal_type = SCANNER_LITERAL_IS_ARG | SCANNER_LITERAL_EARLY_CREATE;
}
#endif
}
literal_p = (lexer_lit_location_t *) parser_list_append (context_p, &literal_pool_p->literal_pool);
*literal_p = context_p->token.lit_location;
literal_p->type = literal_type;
return literal_p;
},1

int received_request(rad_listen_t *listener,
RADIUS_PACKET *packet, REQUEST **prequest,
RADCLIENT *client)
{
RADIUS_PACKET **packet_p;
REQUEST *request = NULL;
struct main_config_t *root = &mainconfig;
packet_p = fr_packet_list_find(pl, packet);
if (packet_p) {
request = fr_packet2myptr(REQUEST, packet, packet_p);
rad_assert(request->in_request_hash);
if ((request->packet->data_len == packet->data_len) &&
(memcmp(request->packet->vector, packet->vector,
sizeof(packet->vector)) == 0)) {
received_retransmit(request, client);
return 0;
}
switch (request->child_state) {
struct timeval when;
default:
if ((request->reply->code != 0) &&
request->reply->data) {
radlog(L_INFO, "WARNING: Allowing fast client %s port %d - ID: %d for recent request %u.",
client->shortname,
packet->src_port, packet->id,
request->number);
remove_from_request_hash(request);
request = NULL;
break;
}
gettimeofday(&when, NULL);
when.tv_sec -= 1;
if (timercmp(&when, &request->received, <)) {
radlog(L_ERR, "Discarding conflicting packet from "
"client %s port %d - ID: %d due to recent request %u.",
client->shortname,
packet->src_port, packet->id,
request->number);
return 0;
}
received_conflicting_request(request, client);
request = NULL;
break;
case REQUEST_REJECT_DELAY:
case REQUEST_CLEANUP_DELAY:
request->child_state = REQUEST_DONE;
case REQUEST_DONE:
cleanup_delay(request);
request = NULL;
break;
}
}
if ((listener->type != RAD_LISTEN_DETAIL) &&
!can_handle_new_request(packet, client, root)) {
return 0;
}
request = request_alloc();
if ((request->reply = rad_alloc(0)) == NULL) {
radlog(L_ERR, "No memory");
exit(1);
}
request->listener = listener;
request->client = client;
request->packet = packet;
request->packet->timestamp = request->timestamp;
request->number = request_num_counter++;
request->priority = listener->type;
#ifdef HAVE_PTHREAD_H
request->child_pid = NO_SUCH_CHILD_PID;
#endif
if (request->packet->code == PW_STATUS_SERVER) request->priority = 0;
if (client->server) {
request->server = client->server;
} else if (listener->server) {
request->server = listener->server;
} else {
request->server = NULL;
}
if (!fr_packet_list_insert(pl, &request->packet)) {
radlog(L_ERR, "Failed to insert request %u in the list of live requests: discarding", request->number);
ev_request_free(&request);
return 0;
}
request->in_request_hash = TRUE;
request->root = root;
root->refcount++;
request->reply->sockfd = request->packet->sockfd;
request->reply->dst_ipaddr = request->packet->src_ipaddr;
request->reply->src_ipaddr = request->packet->dst_ipaddr;
request->reply->dst_port = request->packet->src_port;
request->reply->src_port = request->packet->dst_port;
request->reply->id = request->packet->id;
request->reply->code = 0;
memcpy(request->reply->vector, request->packet->vector,
sizeof(request->reply->vector));
request->reply->vps = NULL;
request->reply->data = NULL;
request->reply->data_len = 0;
request->master_state = REQUEST_ACTIVE;
request->child_state = REQUEST_QUEUED;
request->next_callback = NULL;
gettimeofday(&request->received, NULL);
request->timestamp = request->received.tv_sec;
request->when = request->received;
request->delay = USEC;
tv_add(&request->when, request->delay);
INSERT_EVENT(wait_a_bit, request);
*prequest = request;
return 1;
},0

