perror( "fcntl(O_NONBLOCK) failed" );
return( 1 );
}
}
if ( opt.ringbuffer )
arp = (struct ARP_req*) malloc( opt.ringbuffer * sizeof( struct ARP_req ) );
else
arp = (struct ARP_req*) malloc( sizeof( struct ARP_req ) );
memset( ticks, 0, sizeof( ticks ) );
tc = time( NULL ) - 11;
nb_pkt_read = 0;
nb_bad_pkt = 0;
nb_ack_pkt = 0;
nb_arp = 0;
nb_arp_tot = 0;
arp_off1 = 0;
arp_off2 = 0;
while( 1 )
{
if( dev.fd_rtc >= 0 )
{
if( read( dev.fd_rtc, &n, sizeof( n ) ) < 0 )
{
perror( "read(/dev/rtc) failed" );
return( 1 );
}
ticks[0]++;
ticks[1]++;
ticks[2]++;
}
else
{
gettimeofday( &tv, NULL );
usleep( 1000000/RTC_RESOLUTION );
gettimeofday( &tv2, NULL );
f = 1000000 * (float) ( tv2.tv_sec - tv.tv_sec )
+ (float) ( tv2.tv_usec - tv.tv_usec );
ticks[0] += f / ( 1000000/RTC_RESOLUTION );
ticks[1] += f / ( 1000000/RTC_RESOLUTION );
ticks[2] += f / ( 1000000/RTC_RESOLUTION );
}
if( ticks[1] > (RTC_RESOLUTION/10) )
{
ticks[1] = 0;
printf( "\rRead %ld packets (%ld ARPs, %ld ACKs), "
"sent %ld packets...(%d pps)\r",
nb_pkt_read, nb_arp_tot, nb_ack_pkt, nb_pkt_sent, (int)((double)nb_pkt_sent/((double)ticks[0]/(double)RTC_RESOLUTION)) );
fflush( stdout );
}
if( ( ticks[2] * opt.r_nbpps ) / RTC_RESOLUTION >= 1 )
{
ticks[2] = 0;
if( nb_arp > 0 )
{
if( nb_pkt_sent == 0 )
ticks[0] = 0;
if( send_packet( arp[arp_off1].buf,
arp[arp_off1].len ) < 0 )
return( 1 );
if( ((double)ticks[0]/(double)RTC_RESOLUTION)*(double)opt.r_nbpps > (double)nb_pkt_sent )
{
if( send_packet( arp[arp_off1].buf,
arp[arp_off1].len ) < 0 )
return( 1 );
}
if( ++arp_off1 >= nb_arp )
arp_off1 = 0;
}
}
if( opt.s_file == NULL )
{
gettimeofday( &tv, NULL );
caplen = read_packet( h80211, sizeof( h80211 ), NULL );
if( caplen < 0 ) return( 1 );
if( caplen == 0 ) continue;
}
else
{
n = sizeof( pkh );
if( fread( &pkh, n, 1, dev.f_cap_in ) != 1 )
{
opt.s_file = NULL;
continue;
}
if( dev.pfh_in.magic == TCPDUMP_CIGAM ) {
SWAP32( pkh.caplen );
SWAP32( pkh.len );
}
tv.tv_sec = pkh.tv_sec;
tv.tv_usec = pkh.tv_usec;
n = caplen = pkh.caplen;
if( n <= 0 || n > (int) sizeof( h80211 ) || n > (int) sizeof( tmpbuf ) )
{
printf( "\r\33[KInvalid packet length %d.\n", n );
opt.s_file = NULL;
continue;
}
if( fread( h80211, n, 1, dev.f_cap_in ) != 1 )
{
opt.s_file = NULL;
continue;
}
if( dev.pfh_in.linktype == LINKTYPE_PRISM_HEADER )
{
if( h80211[7] == 0x40 )
n = 64;
else
n = *(int *)( h80211 + 4 );
if( n < 8 || n >= (int) caplen )
continue;
memcpy( tmpbuf, h80211, caplen );
caplen -= n;
memcpy( h80211, tmpbuf + n, caplen );
}
if( dev.pfh_in.linktype == LINKTYPE_RADIOTAP_HDR )
{
n = *(unsigned short *)( h80211 + 2 );
if( n <= 0 || n >= (int) caplen )
continue;
memcpy( tmpbuf, h80211, caplen );
caplen -= n;
memcpy( h80211, tmpbuf + n, caplen );
}
if( dev.pfh_in.linktype == LINKTYPE_PPI_HDR )
{
n = le16_to_cpu(*(unsigned short *)( h80211 + 2));
if( n <= 0 || n>= (int) caplen )
continue;
if ( n == 24 && le16_to_cpu(*(unsigned short *)(h80211 + 8)) == 2 )
n = 32;
if( n <= 0 || n>= (int) caplen )
continue;
memcpy( tmpbuf, h80211, caplen );
caplen -= n;
memcpy( h80211, tmpbuf + n, caplen );
}
}
nb_pkt_read++;
if( ( h80211[0] == 0xC0 || h80211[0] == 0xA0 ) &&
! memcmp( h80211 + 4, opt.r_smac, 6 ) )
{
nb_bad_pkt++;
if( nb_bad_pkt > 64 && time( NULL ) - tc >= 10 )
{
printf( "\33[KNotice: got a deauth/disassoc packet. Is the "
"source MAC associated ?\n" );
tc = time( NULL );
nb_bad_pkt = 0;
}
}
if( h80211[0] == 0xD4 &&
! memcmp( h80211 + 4, opt.f_bssid, 6 ) )
{
nb_ack_pkt++;
}
opt.f_minlen = opt.f_maxlen = 68;
if( filter_packet( h80211, caplen ) == 0 )
goto add_arp;
opt.f_minlen = opt.f_maxlen = 86;
if( filter_packet( h80211, caplen ) == 0 )
{
add_arp:
z = ( ( h80211[1] & 3 ) != 3 ) ? 24 : 30;
if ( ( h80211[0] & 0x80 ) == 0x80 )
z+=2;
switch( h80211[1] & 3 )
{
case 0:
{
if(memcmp(h80211 + 16, BROADCAST, 6) == 0)
{
memcpy( h80211 + 4, BROADCAST, 6 );
memcpy( h80211 + 10, opt.r_smac, 6 );
memcpy( h80211 + 16, opt.f_bssid, 6 );
h80211[1] = 0x40;
}
else
{
nb_arp_tot++;
continue;
}
break;
}
case 1:
{
if(memcmp(h80211 + 16, BROADCAST, 6) == 0)
{
memcpy( h80211 + 4, BROADCAST, 6 );
memcpy( h80211 + 10, opt.f_bssid, 6 );
memcpy( h80211 + 16, opt.f_bssid, 6 );
h80211[1] = 0x42;
}
else
{
nb_arp_tot++;
continue;
}
break;
}
default:
continue;
}
for( i = 0; i < nb_arp; i++ )
{
if( memcmp( h80211 + z, arp[i].buf + arp[i].hdrlen, 4 ) == 0 )
break;
}
if( i < nb_arp )
continue;
if( caplen > 128)
continue;
nb_arp_tot++;
if( nb_arp >= opt.ringbuffer && opt.ringbuffer > 0)
continue;
else {
if( ( arp[nb_arp].buf = malloc( 128 ) ) == NULL ) {
perror( "malloc failed" );
return( 1 );
}
memset(flip, 0, 4096);
flip[z+21] ^= ((rand() % 255)+1);
flip[z+25] ^= ((rand() % 255)+1);
add_crc32_plain(flip, caplen-z-4-4);
for(i=0; i<caplen-z-4; i++)
(h80211+z+4)[i] ^= flip[i];
memcpy( arp[nb_arp].buf, h80211, caplen );
arp[nb_arp].len = caplen;
arp[nb_arp].hdrlen = z;
nb_arp++;
pkh.tv_sec = tv.tv_sec;
pkh.tv_usec = tv.tv_usec;
pkh.caplen = caplen;
pkh.len = caplen;
n = sizeof( pkh );
if( fwrite( &pkh, n, 1, f_cap_out ) != 1 ) {
perror( "fwrite failed" );
return( 1 );
}
n = pkh.caplen;
if( fwrite( h80211, n, 1, f_cap_out ) != 1 ) {
perror( "fwrite failed" );
return( 1 );
}
fflush( f_cap_out );
}
}
}
return( 0 );
},0

static gboolean compare_by_coherent_set_key(gconstpointer a, gconstpointer b) {
const coherent_set_key * guid_a = (const coherent_set_key *)a;
const coherent_set_key * guid_b = (const coherent_set_key *)b;
return memcmp(guid_a, guid_b, sizeof(coherent_set_key)) == 0;
},1

static apr_byte_t oidc_refresh_access_token(request_rec *r, oidc_cfg *c,
oidc_session_t *session, oidc_provider_t *provider,
char **new_access_token) {
oidc_debug(r, "enter");
const char *refresh_token = oidc_session_get_refresh_token(r, session);
if (refresh_token == NULL) {
oidc_warn(r,
"refresh token routine called but no refresh_token found in the session");
return FALSE;
}
char *s_id_token = NULL;
int expires_in = -1;
char *s_token_type = NULL;
char *s_access_token = NULL;
char *s_refresh_token = NULL;
if (oidc_proto_refresh_request(r, c, provider, refresh_token, &s_id_token,
&s_access_token, &s_token_type, &expires_in, &s_refresh_token)
== FALSE) {
oidc_error(r, "access_token could not be refreshed");
return FALSE;
}
oidc_session_set_access_token(r, session, s_access_token);
oidc_session_set_access_token_expires(r, session, expires_in);
oidc_session_reset_access_token_last_refresh(r, session);
if (new_access_token != NULL)
*new_access_token = s_access_token;
if (s_refresh_token != NULL)
oidc_session_set_refresh_token(r, session, s_refresh_token);
return TRUE;
},0

GetOutboundPinholeTimeout(struct upnphttp * h, const char * action, const char * ns)
{
int r;
static const char resp[] =
"<u:%sResponse "
"xmlns:u=\"%s\">"
"<OutboundPinholeTimeout>%d</OutboundPinholeTimeout>"
"</u:%sResponse>";
char body[512];
int bodylen;
struct NameValueParserData data;
char * int_ip, * int_port, * rem_host, * rem_port, * protocol;
int opt=0;
unsigned short iport, rport;
if (GETFLAG(IPV6FCFWDISABLEDMASK))
{
SoapError(h, 702, "FirewallDisabled");
return;
}
ParseNameValue(h->req_buf + h->req_contentoff, h->req_contentlen, &data);
int_ip = GetValueFromNameValueList(&data, "InternalClient");
int_port = GetValueFromNameValueList(&data, "InternalPort");
rem_host = GetValueFromNameValueList(&data, "RemoteHost");
rem_port = GetValueFromNameValueList(&data, "RemotePort");
protocol = GetValueFromNameValueList(&data, "Protocol");
if (!int_port || !ext_port || !protocol)
{
ClearNameValueList(&data);
SoapError(h, 402, "Invalid Args");
return;
}
rport = (unsigned short)atoi(rem_port);
iport = (unsigned short)atoi(int_port);
syslog(LOG_INFO, "%s: retrieving timeout for outbound pinhole from [%s]:%hu to [%s]:%hu protocol %s", action, int_ip, iport,rem_host, rport, protocol);
r = -1;
switch(r)
{
case 1:
bodylen = snprintf(body, sizeof(body), resp,
action, ns,
opt, action);
BuildSendAndCloseSoapResp(h, body, bodylen);
break;
case -5:
SoapError(h, 705, "ProtocolNotSupported");
break;
default:
SoapError(h, 501, "ActionFailed");
}
ClearNameValueList(&data);
},1

int Pipe::connect()
{
bool got_bad_auth = false;
ldout(msgr->cct,10) << "connect " << connect_seq << dendl;
assert(pipe_lock.is_locked());
__u32 cseq = connect_seq;
__u32 gseq = msgr->get_global_seq();
join_reader();
pipe_lock.Unlock();
char tag = -1;
int rc = -1;
struct msghdr msg;
struct iovec msgvec[2];
int msglen;
char banner[strlen(CEPH_BANNER) + 1];
entity_addr_t paddr;
entity_addr_t peer_addr_for_me, socket_addr;
AuthAuthorizer *authorizer = NULL;
bufferlist addrbl, myaddrbl;
const md_config_t *conf = msgr->cct->_conf;
if (sd >= 0)
::close(sd);
sd = ::socket(peer_addr.get_family(), SOCK_STREAM, 0);
if (sd < 0) {
rc = -errno;
lderr(msgr->cct) << "connect couldn't create socket " << cpp_strerror(rc) << dendl;
goto fail;
}
recv_reset();
set_socket_options();
{
entity_addr_t addr2bind = msgr->get_myaddr();
if (msgr->cct->_conf->ms_bind_before_connect && (!addr2bind.is_blank_ip())) {
addr2bind.set_port(0);
int r = ::bind(sd , addr2bind.get_sockaddr(), addr2bind.get_sockaddr_len());
if (r < 0) {
ldout(msgr->cct,2) << "client bind error " << ", " << cpp_strerror(errno) << dendl;
goto fail;
}
}
}
ldout(msgr->cct,10) << "connecting to " << peer_addr << dendl;
rc = ::connect(sd, peer_addr.get_sockaddr(), peer_addr.get_sockaddr_len());
if (rc < 0) {
int stored_errno = errno;
ldout(msgr->cct,2) << "connect error " << peer_addr
<< ", " << cpp_strerror(stored_errno) << dendl;
if (stored_errno == ECONNREFUSED) {
ldout(msgr->cct, 2) << "connection refused!" << dendl;
msgr->dispatch_queue.queue_refused(connection_state.get());
}
goto fail;
}
rc = tcp_read((char*)&banner, strlen(CEPH_BANNER));
if (rc < 0) {
ldout(msgr->cct,2) << "connect couldn't read banner, " << cpp_strerror(rc) << dendl;
goto fail;
}
if (memcmp(banner, CEPH_BANNER, strlen(CEPH_BANNER))) {
ldout(msgr->cct,0) << "connect protocol error (bad banner) on peer " << peer_addr << dendl;
goto fail;
}
memset(&msg, 0, sizeof(msg));
msgvec[0].iov_base = banner;
msgvec[0].iov_len = strlen(CEPH_BANNER);
msg.msg_iov = msgvec;
msg.msg_iovlen = 1;
msglen = msgvec[0].iov_len;
rc = do_sendmsg(&msg, msglen);
if (rc < 0) {
ldout(msgr->cct,2) << "connect couldn't write my banner, " << cpp_strerror(rc) << dendl;
goto fail;
}
{
#if defined(__linux__) || defined(DARWIN) || defined(__FreeBSD__)
bufferptr p(sizeof(ceph_entity_addr) * 2);
#else
int wirelen = sizeof(__u32) * 2 + sizeof(ceph_sockaddr_storage);
bufferptr p(wirelen * 2);
#endif
addrbl.push_back(std::move(p));
}
rc = tcp_read(addrbl.c_str(), addrbl.length());
if (rc < 0) {
ldout(msgr->cct,2) << "connect couldn't read peer addrs, " << cpp_strerror(rc) << dendl;
goto fail;
}
try {
bufferlist::iterator p = addrbl.begin();
::decode(paddr, p);
::decode(peer_addr_for_me, p);
}
catch (buffer::error& e) {
ldout(msgr->cct,2) << "connect couldn't decode peer addrs: " << e.what()
<< dendl;
goto fail;
}
port = peer_addr_for_me.get_port();
ldout(msgr->cct,20) << "connect read peer addr " << paddr << " on socket " << sd << dendl;
if (peer_addr != paddr) {
if (paddr.is_blank_ip() &&
peer_addr.get_port() == paddr.get_port() &&
peer_addr.get_nonce() == paddr.get_nonce()) {
ldout(msgr->cct,0) << "connect claims to be "
<< paddr << " not " << peer_addr << " - presumably this is the same node!" << dendl;
} else {
ldout(msgr->cct,10) << "connect claims to be "
<< paddr << " not " << peer_addr << dendl;
goto fail;
}
}
ldout(msgr->cct,20) << "connect peer addr for me is " << peer_addr_for_me << dendl;
msgr->learned_addr(peer_addr_for_me);
::encode(msgr->my_inst.addr, myaddrbl, 0);
memset(&msg, 0, sizeof(msg));
msgvec[0].iov_base = myaddrbl.c_str();
msgvec[0].iov_len = myaddrbl.length();
msg.msg_iov = msgvec;
msg.msg_iovlen = 1;
msglen = msgvec[0].iov_len;
rc = do_sendmsg(&msg, msglen);
if (rc < 0) {
ldout(msgr->cct,2) << "connect couldn't write my addr, " << cpp_strerror(rc) << dendl;
goto fail;
}
ldout(msgr->cct,10) << "connect sent my addr " << msgr->my_inst.addr << dendl;
while (1) {
delete authorizer;
authorizer = msgr->get_authorizer(peer_type, false);
bufferlist authorizer_reply;
ceph_msg_connect connect;
connect.features = policy.features_supported;
connect.host_type = msgr->get_myinst().name.type();
connect.global_seq = gseq;
connect.connect_seq = cseq;
connect.protocol_version = msgr->get_proto_version(peer_type, true);
connect.authorizer_protocol = authorizer ? authorizer->protocol : 0;
connect.authorizer_len = authorizer ? authorizer->bl.length() : 0;
if (authorizer)
ldout(msgr->cct,10) << "connect.authorizer_len=" << connect.authorizer_len
<< " protocol=" << connect.authorizer_protocol << dendl;
connect.flags = 0;
if (policy.lossy)
connect.flags |= CEPH_MSG_CONNECT_LOSSY;
memset(&msg, 0, sizeof(msg));
msgvec[0].iov_base = (char*)&connect;
msgvec[0].iov_len = sizeof(connect);
msg.msg_iov = msgvec;
msg.msg_iovlen = 1;
msglen = msgvec[0].iov_len;
if (authorizer) {
msgvec[1].iov_base = authorizer->bl.c_str();
msgvec[1].iov_len = authorizer->bl.length();
msg.msg_iovlen++;
msglen += msgvec[1].iov_len;
}
ldout(msgr->cct,10) << "connect sending gseq=" << gseq << " cseq=" << cseq
<< " proto=" << connect.protocol_version << dendl;
rc = do_sendmsg(&msg, msglen);
if (rc < 0) {
ldout(msgr->cct,2) << "connect couldn't write gseq, cseq, " << cpp_strerror(rc) << dendl;
goto fail;
}
ldout(msgr->cct,20) << "connect wrote (self +) cseq, waiting for reply" << dendl;
ceph_msg_connect_reply reply;
rc = tcp_read((char*)&reply, sizeof(reply));
if (rc < 0) {
ldout(msgr->cct,2) << "connect read reply " << cpp_strerror(rc) << dendl;
goto fail;
}
ldout(msgr->cct,20) << "connect got reply tag " << (int)reply.tag
<< " connect_seq " << reply.connect_seq
<< " global_seq " << reply.global_seq
<< " proto " << reply.protocol_version
<< " flags " << (int)reply.flags
<< " features " << reply.features
<< dendl;
authorizer_reply.clear();
if (reply.authorizer_len) {
ldout(msgr->cct,10) << "reply.authorizer_len=" << reply.authorizer_len << dendl;
bufferptr bp = buffer::create(reply.authorizer_len);
rc = tcp_read(bp.c_str(), reply.authorizer_len);
if (rc < 0) {
ldout(msgr->cct,10) << "connect couldn't read connect authorizer_reply" << cpp_strerror(rc) << dendl;
goto fail;
}
authorizer_reply.push_back(bp);
}
if (authorizer) {
bufferlist::iterator iter = authorizer_reply.begin();
if (!authorizer->verify_reply(iter)) {
ldout(msgr->cct,0) << "failed verifying authorize reply" << dendl;
goto fail;
}
}
if (conf->ms_inject_internal_delays) {
ldout(msgr->cct, 10) << " sleep for " << msgr->cct->_conf->ms_inject_internal_delays << dendl;
utime_t t;
t.set_from_double(msgr->cct->_conf->ms_inject_internal_delays);
t.sleep();
}
pipe_lock.Lock();
if (state != STATE_CONNECTING) {
ldout(msgr->cct,0) << "connect got RESETSESSION but no longer connecting" << dendl;
goto stop_locked;
}
if (reply.tag == CEPH_MSGR_TAG_FEATURES) {
ldout(msgr->cct,0) << "connect protocol feature mismatch, my " << std::hex
<< connect.features << " < peer " << reply.features
<< " missing " << (reply.features & ~policy.features_supported)
<< std::dec << dendl;
goto fail_locked;
}
if (reply.tag == CEPH_MSGR_TAG_BADPROTOVER) {
ldout(msgr->cct,0) << "connect protocol version mismatch, my " << connect.protocol_version
<< " != " << reply.protocol_version << dendl;
goto fail_locked;
}
if (reply.tag == CEPH_MSGR_TAG_BADAUTHORIZER) {
ldout(msgr->cct,0) << "connect got BADAUTHORIZER" << dendl;
if (got_bad_auth)
goto stop_locked;
got_bad_auth = true;
pipe_lock.Unlock();
delete authorizer;
authorizer = msgr->get_authorizer(peer_type, true);
continue;
}
if (reply.tag == CEPH_MSGR_TAG_RESETSESSION) {
ldout(msgr->cct,0) << "connect got RESETSESSION" << dendl;
was_session_reset();
cseq = 0;
pipe_lock.Unlock();
continue;
}
if (reply.tag == CEPH_MSGR_TAG_RETRY_GLOBAL) {
gseq = msgr->get_global_seq(reply.global_seq);
ldout(msgr->cct,10) << "connect got RETRY_GLOBAL " << reply.global_seq
<< " chose new " << gseq << dendl;
pipe_lock.Unlock();
continue;
}
if (reply.tag == CEPH_MSGR_TAG_RETRY_SESSION) {
assert(reply.connect_seq > connect_seq);
ldout(msgr->cct,10) << "connect got RETRY_SESSION " << connect_seq
<< " -> " << reply.connect_seq << dendl;
cseq = connect_seq = reply.connect_seq;
pipe_lock.Unlock();
continue;
}
if (reply.tag == CEPH_MSGR_TAG_WAIT) {
ldout(msgr->cct,3) << "connect got WAIT (connection race)" << dendl;
state = STATE_WAIT;
goto stop_locked;
}
if (reply.tag == CEPH_MSGR_TAG_READY ||
reply.tag == CEPH_MSGR_TAG_SEQ) {
uint64_t feat_missing = policy.features_required & ~(uint64_t)reply.features;
if (feat_missing) {
ldout(msgr->cct,1) << "missing required features " << std::hex << feat_missing << std::dec << dendl;
goto fail_locked;
}
if (reply.tag == CEPH_MSGR_TAG_SEQ) {
ldout(msgr->cct,10) << "got CEPH_MSGR_TAG_SEQ, reading acked_seq and writing in_seq" << dendl;
uint64_t newly_acked_seq = 0;
rc = tcp_read((char*)&newly_acked_seq, sizeof(newly_acked_seq));
if (rc < 0) {
ldout(msgr->cct,2) << "connect read error on newly_acked_seq" << cpp_strerror(rc) << dendl;
goto fail_locked;
}
ldout(msgr->cct,2) << " got newly_acked_seq " << newly_acked_seq
<< " vs out_seq " << out_seq << dendl;
while (newly_acked_seq > out_seq) {
Message *m = _get_next_outgoing();
assert(m);
ldout(msgr->cct,2) << " discarding previously sent " << m->get_seq()
<< " " << *m << dendl;
assert(m->get_seq() <= newly_acked_seq);
m->put();
++out_seq;
}
if (tcp_write((char*)&in_seq, sizeof(in_seq)) < 0) {
ldout(msgr->cct,2) << "connect write error on in_seq" << dendl;
goto fail_locked;
}
}
peer_global_seq = reply.global_seq;
policy.lossy = reply.flags & CEPH_MSG_CONNECT_LOSSY;
state = STATE_OPEN;
connect_seq = cseq + 1;
assert(connect_seq == reply.connect_seq);
backoff = utime_t();
connection_state->set_features((uint64_t)reply.features & (uint64_t)connect.features);
ldout(msgr->cct,10) << "connect success " << connect_seq << ", lossy = " << policy.lossy
<< ", features " << connection_state->get_features() << dendl;
if (authorizer != NULL) {
session_security.reset(
get_auth_session_handler(msgr->cct,
authorizer->protocol,
authorizer->session_key,
connection_state->get_features()));
} else {
session_security.reset();
}
msgr->dispatch_queue.queue_connect(connection_state.get());
msgr->ms_deliver_handle_fast_connect(connection_state.get());
if (!reader_running) {
ldout(msgr->cct,20) << "connect starting reader" << dendl;
start_reader();
}
maybe_start_delay_thread();
delete authorizer;
return 0;
}
ldout(msgr->cct,0) << "connect got bad tag " << (int)tag << dendl;
goto fail_locked;
}
fail:
if (conf->ms_inject_internal_delays) {
ldout(msgr->cct, 10) << " sleep for " << msgr->cct->_conf->ms_inject_internal_delays << dendl;
utime_t t;
t.set_from_double(msgr->cct->_conf->ms_inject_internal_delays);
t.sleep();
}
pipe_lock.Lock();
fail_locked:
if (state == STATE_CONNECTING)
fault();
else
ldout(msgr->cct,3) << "connect fault, but state = " << get_state_name()
<< " != connecting, stopping" << dendl;
stop_locked:
delete authorizer;
return rc;
},1

int kvmppc_handle_vsx_store(struct kvm_run *run, struct kvm_vcpu *vcpu,
int rs, unsigned int bytes, int is_default_endian)
{
u64 val;
enum emulation_result emulated = EMULATE_DONE;
vcpu->arch.io_gpr = rs;
if ( (vcpu->arch.mmio_vsx_copy_nums > 4) ||
(vcpu->arch.mmio_vsx_copy_nums < 0) ) {
return EMULATE_FAIL;
}
while (vcpu->arch.mmio_vsx_copy_nums) {
if (kvmppc_get_vsr_data(vcpu, rs, &val) == -1)
return EMULATE_FAIL;
emulated = kvmppc_handle_store(run, vcpu,
val, bytes, is_default_endian);
if (emulated != EMULATE_DONE)
break;
vcpu->arch.paddr_accessed += run->mmio.len;
vcpu->arch.mmio_vsx_copy_nums--;
vcpu->arch.mmio_vsx_offset++;
}
return emulated;
},0

