execreg_line_continuation(char_u **lines, long *idx)
{
garray_T ga;
long i = *idx;
char_u *p;
int cmd_start;
int cmd_end = i;
int j;
char_u *str;
ga_init2(&ga, sizeof(char_u), 400);
while (--i > 0)
{
p = skipwhite(lines[i]);
if (*p != '\\' && (p[0] != '"' || p[1] != '\\' || p[2] != ' '))
break;
}
cmd_start = i;
ga_concat(&ga, lines[cmd_start]);
for (j = cmd_start + 1; j <= cmd_end; j++)
{
p = skipwhite(lines[j]);
if (*p == '\\')
{
if (ga.ga_len > 400)
{
if (ga.ga_len > 8000)
ga.ga_growsize = 8000;
else
ga.ga_growsize = ga.ga_len;
}
ga_concat(&ga, p + 1);
}
}
ga_append(&ga, NUL);
str = vim_strsave(ga.ga_data);
ga_clear(&ga);
*idx = i;
return str;
},0

static char *oidc_cache_get_hashed_key(request_rec *r, const char *passphrase,
const char *key) {
