ExecBRUpdateTriggers(EState *estate, EPQState *epqstate,
ResultRelInfo *relinfo,
ItemPointer tupleid, TupleTableSlot *slot)
{
TriggerDesc *trigdesc = relinfo->ri_TrigDesc;
HeapTuple slottuple = ExecMaterializeSlot(slot);
HeapTuple newtuple = slottuple;
TriggerData LocTriggerData;
HeapTuple trigtuple;
HeapTuple oldtuple;
TupleTableSlot *newSlot;
int i;
Bitmapset *modifiedCols;
Bitmapset *keyCols;
LockTupleMode lockmode;
modifiedCols = GetModifiedColumns(relinfo, estate);
keyCols = RelationGetIndexAttrBitmap(relinfo->ri_RelationDesc,
INDEX_ATTR_BITMAP_KEY);
if (bms_overlap(keyCols, modifiedCols))
lockmode = LockTupleExclusive;
else
lockmode = LockTupleNoKeyExclusive;
trigtuple = GetTupleForTrigger(estate, epqstate, relinfo, tupleid,
lockmode, &newSlot);
if (trigtuple == NULL)
return NULL;
if (newSlot != NULL)
{
slot = ExecFilterJunk(relinfo->ri_junkFilter, newSlot);
slottuple = ExecMaterializeSlot(slot);
newtuple = slottuple;
}
LocTriggerData.type = T_TriggerData;
LocTriggerData.tg_event = TRIGGER_EVENT_UPDATE |
TRIGGER_EVENT_ROW |
TRIGGER_EVENT_BEFORE;
LocTriggerData.tg_relation = relinfo->ri_RelationDesc;
for (i = 0; i < trigdesc->numtriggers; i++)
{
Trigger *trigger = &trigdesc->triggers[i];
if (!TRIGGER_TYPE_MATCHES(trigger->tgtype,
TRIGGER_TYPE_ROW,
TRIGGER_TYPE_BEFORE,
TRIGGER_TYPE_UPDATE))
continue;
if (!TriggerEnabled(estate, relinfo, trigger, LocTriggerData.tg_event,
modifiedCols, trigtuple, newtuple))
continue;
LocTriggerData.tg_trigtuple = trigtuple;
LocTriggerData.tg_newtuple = oldtuple = newtuple;
LocTriggerData.tg_trigtuplebuf = InvalidBuffer;
LocTriggerData.tg_newtuplebuf = InvalidBuffer;
LocTriggerData.tg_trigger = trigger;
newtuple = ExecCallTriggerFunc(&LocTriggerData,
i,
relinfo->ri_TrigFunctions,
relinfo->ri_TrigInstrument,
GetPerTupleMemoryContext(estate));
if (oldtuple != newtuple && oldtuple != slottuple)
heap_freetuple(oldtuple);
if (newtuple == NULL)
{
heap_freetuple(trigtuple);
return NULL;
}
}
heap_freetuple(trigtuple);
if (newtuple != slottuple)
{
TupleTableSlot *newslot = estate->es_trig_tuple_slot;
TupleDesc tupdesc = RelationGetDescr(relinfo->ri_RelationDesc);
if (newslot->tts_tupleDescriptor != tupdesc)
ExecSetSlotDescriptor(newslot, tupdesc);
ExecStoreTuple(newtuple, newslot, InvalidBuffer, false);
slot = newslot;
}
return slot;
},0

int main(int argc, char **argv)
{
int c;
char *orgoptions = NULL;
char *mountpoint = NULL;
char *options = NULL;
char *orig_dev = NULL;
char *currentaddress, *nextaddress;
int rc = 0;
int already_uppercased = 0;
size_t options_size = MAX_OPTIONS_LEN;
struct parsed_mount_info *parsed_info = NULL;
pid_t pid;
const char *fstype;
rc = check_setuid();
if (rc)
return rc;
rc = drop_capabilities(1);
if (rc)
return EX_SYSERR;
if (!argc || !argv) {
rc = mount_usage(stderr);
goto mount_exit;
}
thisprogram = basename(argv[0]);
if (thisprogram == NULL)
thisprogram = "mount.cifs";
parsed_info = mmap(0, sizeof(*parsed_info), PROT_READ | PROT_WRITE,
MAP_ANONYMOUS | MAP_SHARED, -1, 0);
if (parsed_info == (struct parsed_mount_info *) -1) {
parsed_info = NULL;
fprintf(stderr, "Unable to allocate memory: %s\n",
strerror(errno));
return EX_SYSERR;
}
while ((c = getopt_long(argc, argv, "?fhno:rvVw",
longopts, NULL)) != -1) {
switch (c) {
case '?':
case 'h':
rc = mount_usage(stdout);
goto mount_exit;
case 'n':
++parsed_info->nomtab;
break;
case 'o':
orgoptions = strndup(optarg, MAX_OPTIONS_LEN);
if (!orgoptions) {
rc = EX_SYSERR;
goto mount_exit;
}
break;
case 'r':
parsed_info->flags |= MS_RDONLY;
break;
case 'v':
++parsed_info->verboseflag;
break;
case 'V':
print_cifs_mount_version();
exit(0);
case 'w':
parsed_info->flags &= ~MS_RDONLY;
break;
case 'f':
++parsed_info->fakemnt;
break;
default:
fprintf(stderr, "unknown command-line option: %c\n", c);
rc = mount_usage(stderr);
goto mount_exit;
}
}
if (argc < 3 || argv[optind] == NULL || argv[optind + 1] == NULL) {
rc = mount_usage(stderr);
goto mount_exit;
}
orig_dev = argv[optind];
mountpoint = argv[optind + 1];
rc = toggle_dac_capability(0, 1);
if (rc)
return rc;
rc = chdir(mountpoint);
if (rc) {
fprintf(stderr, "Couldn't chdir to %s: %s\n", mountpoint,
strerror(errno));
rc = EX_USAGE;
goto mount_exit;
}
mountpoint = realpath(".", NULL);
if (!mountpoint) {
fprintf(stderr, "Unable to resolve %s to canonical path: %s\n",
mountpoint, strerror(errno));
rc = EX_SYSERR;
goto mount_exit;
}
rc = toggle_dac_capability(0, 0);
if (rc)
return rc;
pid = fork();
if (pid == -1) {
fprintf(stderr, "Unable to fork: %s\n", strerror(errno));
rc = EX_SYSERR;
goto mount_exit;
} else if (!pid) {
rc = assemble_mountinfo(parsed_info, thisprogram, mountpoint,
orig_dev, orgoptions);
return rc;
} else {
pid = wait(&rc);
if (!WIFEXITED(rc)) {
fprintf(stderr, "Child process terminated abnormally.\n");
rc = EX_SYSERR;
goto mount_exit;
}
rc = WEXITSTATUS(rc);
if (rc)
goto mount_exit;
}
options = calloc(options_size, 1);
if (!options) {
fprintf(stderr, "Unable to allocate memory.\n");
rc = EX_SYSERR;
goto mount_exit;
}
currentaddress = parsed_info->addrlist;
nextaddress = strchr(currentaddress, ',');
if (nextaddress)
*nextaddress++ = '\0';
mount_retry:
if (!currentaddress) {
fprintf(stderr, "Unable to find suitable address.\n");
rc = EX_SYSERR;
goto mount_exit;
}
strlcpy(options, "ip=", options_size);
strlcat(options, currentaddress, options_size);
strlcat(options, ",unc=\\\\", options_size);
strlcat(options, parsed_info->host, options_size);
strlcat(options, "\\", options_size);
strlcat(options, parsed_info->share, options_size);
if (*parsed_info->options) {
strlcat(options, ",", options_size);
strlcat(options, parsed_info->options, options_size);
}
if (*parsed_info->prefix) {
strlcat(options, ",prefixpath=", options_size);
strlcat(options, parsed_info->prefix, options_size);
}
if (parsed_info->verboseflag)
fprintf(stderr, "%s kernel mount options: %s",
thisprogram, options);
if (parsed_info->got_password) {
strlcat(options, ",pass=", options_size);
strlcat(options, parsed_info->password, options_size);
if (parsed_info->verboseflag)
fprintf(stderr, ",pass=********");
}
if (parsed_info->verboseflag)
fprintf(stderr, "\n");
rc = check_mtab(thisprogram, orig_dev, mountpoint);
if (rc)
goto mount_exit;
if (strcmp(thisprogram, "mount.smb2") == 0)
fstype = smb2_fstype;
else
fstype = cifs_fstype;
if (!parsed_info->fakemnt) {
toggle_dac_capability(0, 1);
rc = mount(orig_dev, ".", fstype, parsed_info->flags, options);
toggle_dac_capability(0, 0);
if (rc == 0)
goto do_mtab;
switch (errno) {
case ECONNREFUSED:
case EHOSTUNREACH:
currentaddress = nextaddress;
if (currentaddress) {
nextaddress = strchr(currentaddress, ',');
if (nextaddress)
*nextaddress++ = '\0';
}
goto mount_retry;
case ENODEV:
fprintf(stderr,
"mount error: %s filesystem not supported by the system\n", fstype);
break;
case ENXIO:
if (!already_uppercased &&
uppercase_string(parsed_info->host) &&
uppercase_string(parsed_info->share) &&
uppercase_string(parsed_info->prefix)) {
fprintf(stderr,
"Retrying with upper case share name\n");
already_uppercased = 1;
goto mount_retry;
}
}
fprintf(stderr, "mount error(%d): %s\n", errno,
strerror(errno));
fprintf(stderr,
"Refer to the %s(8) manual page (e.g. man "
"%s)\n", thisprogram, thisprogram);
rc = EX_FAIL;
goto mount_exit;
}
do_mtab:
if (!parsed_info->nomtab && !mtab_unusable())
rc = add_mtab(orig_dev, mountpoint, parsed_info->flags, fstype);
mount_exit:
if (parsed_info) {
memset(parsed_info->password, 0, sizeof(parsed_info->password));
munmap(parsed_info, sizeof(*parsed_info));
}
SAFE_FREE(options);
SAFE_FREE(orgoptions);
return rc;
},0

handle_subnets_accessed(CMD_Request *rx_message, CMD_Reply *tx_message)
{
int i, j;
unsigned long ns, bits_specd;
IPAddr ip;
CLG_Status result;
ns = ntohl(rx_message->data.subnets_accessed.n_subnets);
tx_message->status = htons(STT_SUCCESS);
tx_message->reply = htons(RPY_SUBNETS_ACCESSED);
tx_message->data.subnets_accessed.n_subnets = htonl(ns);
for (i=0; i<ns; i++) {
UTI_IPNetworkToHost(&rx_message->data.subnets_accessed.subnets[i].ip, &ip);
bits_specd = ntohl(rx_message->data.subnets_accessed.subnets[i].bits_specd);
UTI_IPHostToNetwork(&ip, &tx_message->data.subnets_accessed.subnets[i].ip);
tx_message->data.subnets_accessed.subnets[i].bits_specd = htonl(bits_specd);
result = CLG_GetSubnetBitmap(&ip, bits_specd, tx_message->data.subnets_accessed.subnets[i].bitmap);
switch (result) {
case CLG_SUCCESS:
case CLG_EMPTYSUBNET:
for (j=0; j<8; j++) {
FLIPL(tx_message->data.subnets_accessed.subnets[i].bitmap[j]);
}
break;
case CLG_BADSUBNET:
tx_message->status = htons(STT_BADSUBNET);
return;
case CLG_INACTIVE:
tx_message->status = htons(STT_INACTIVE);
return;
default:
assert(0);
break;
}
}
