eval0_retarg(
char_u *arg,
typval_T *rettv,
exarg_T *eap,
evalarg_T *evalarg,
char_u **retarg)
{
int ret;
char_u *p;
char_u *expr_end;
int did_emsg_before = did_emsg;
int called_emsg_before = called_emsg;
int flags = evalarg == NULL ? 0 : evalarg->eval_flags;
int check_for_end = retarg == NULL;
int end_error = FALSE;
p = skipwhite(arg);
ret = eval1(&p, rettv, evalarg);
expr_end = p;
p = skipwhite(p);
if (in_vim9script() && p > expr_end && retarg == NULL)
while (*p == '#')
{
char_u *nl = vim_strchr(p, NL);
if (nl == NULL)
break;
p = skipwhite(nl + 1);
if (eap != NULL && *p != NUL)
eap->nextcmd = p;
check_for_end = FALSE;
}
if (ret != FAIL && check_for_end)
end_error = !ends_excmd2(arg, p);
if (ret == FAIL || end_error)
{
if (ret != FAIL)
clear_tv(rettv);
if (!aborting()
&& did_emsg == did_emsg_before
&& called_emsg == called_emsg_before
&& (flags & EVAL_CONSTANT) == 0
&& (!in_vim9script() || !vim9_bad_comment(p)))
{
if (end_error)
semsg(_(e_trailing_characters_str), p);
else
semsg(_(e_invalid_expression_str), arg);
}
if (eap != NULL && skipwhite(p)[0] == '|' && skipwhite(p)[1] != '|')
eap->nextcmd = check_nextcmd(p);
return FAIL;
}
if (retarg != NULL)
*retarg = p;
else if (check_for_end && eap != NULL)
set_nextcmd(eap, p);
return ret;
},1

txtwrite_process_cmap_text(gs_text_enum_t *pte)
{
textw_text_enum_t *const penum = (textw_text_enum_t *)pte;
unsigned int rcode = 0;
gs_text_enum_t scan = *(gs_text_enum_t *)pte;
for ( ; ; ) {
gs_glyph glyph;
int font_code, code;
gs_font *subfont;
gs_char chr;
txt_glyph_widths_t widths;
gs_matrix m3;
gs_point wanted;
gs_point dpt = {0,0};
font_code = scan.orig_font->procs.next_char_glyph
(&scan, &chr, &glyph);
subfont = scan.fstack.items[scan.fstack.depth].font;
switch (font_code) {
case 0:
case 1:
code = txt_glyph_widths(subfont, scan.orig_font->WMode, glyph, (gs_font *)subfont, &widths,
penum->cdevproc_callout ? penum->cdevproc_result : NULL);
if (code == TEXT_PROCESS_CDEVPROC) {
penum->cdevproc_callout = true;
pte->returned.current_glyph = glyph;
scan.returned.current_glyph = glyph;
pte->current_font = subfont;
scan.current_font = subfont;
rcode = TEXT_PROCESS_CDEVPROC;
break;
}
else {
penum->cdevproc_callout = false;
pte->index = scan.index;
}
code = gs_matrix_multiply(&subfont->FontMatrix, &pte->orig_font->FontMatrix, &m3);
if (code < 0)
return code;
code = txt_update_text_state(penum->text_state, (textw_text_enum_t *)pte, pte->orig_font, &m3);
if (code < 0)
return code;
txt_char_widths_to_uts(pte->orig_font, &widths);
gs_distance_transform(widths.real_width.xy.x * penum->text_state->size,
widths.real_width.xy.y * penum->text_state->size,
&penum->text_state->matrix, &wanted);
pte->returned.total_width.x += wanted.x;
pte->returned.total_width.y += wanted.y;
penum->Widths[penum->TextBufferIndex] = wanted.x;
if (pte->text.operation & TEXT_ADD_TO_ALL_WIDTHS) {
gs_point tpt;
gs_distance_transform(pte->text.delta_all.x, pte->text.delta_all.y,
&ctm_only(pte->pgs), &tpt);
dpt.x += tpt.x;
dpt.y += tpt.y;
}
if (pte->text.operation & TEXT_ADD_TO_SPACE_WIDTH && chr == pte->text.space.s_char) {
gs_point tpt;
gs_distance_transform(pte->text.delta_space.x, pte->text.delta_space.y,
&ctm_only(pte->pgs), &tpt);
dpt.x += tpt.x;
dpt.y += tpt.y;
}
pte->returned.total_width.x += dpt.x;
pte->returned.total_width.y += dpt.y;
penum->TextBufferIndex += get_unicode(penum, (gs_font *)pte->orig_font, glyph, chr, &penum->TextBuffer[penum->TextBufferIndex]);
penum->Widths[penum->TextBufferIndex] += dpt.x;
break;
case 2:
return 0;
default:
return font_code;
}
if (rcode || pte->index >= pte->text.size)
break;
}
return rcode;
},1

pixGetCCBorders(PIX *pixs,
BOX *box)
{
l_int32 allzero, i, x, xh, w, nh;
l_int32 xs, ys;
l_uint32 val;
BOX *boxt, *boxe;
BOXA *boxa;
CCBORD *ccb;
PIX *pixh;
PIX *pixt;
PIXA *pixa;
PROCNAME("pixGetCCBorders");
if (!pixs)
return (CCBORD *)ERROR_PTR("pixs not defined", procName, NULL);
if (!box)
return (CCBORD *)ERROR_PTR("box not defined", procName, NULL);
if (pixGetDepth(pixs) != 1)
return (CCBORD *)ERROR_PTR("pixs not binary", procName, NULL);
pixZero(pixs, &allzero);
if (allzero)
return (CCBORD *)ERROR_PTR("pixs all 0", procName, NULL);
if ((ccb = ccbCreate(pixs)) == NULL)
return (CCBORD *)ERROR_PTR("ccb not made", procName, NULL);
pixGetOuterBorder(ccb, pixs, box);
if ((pixh = pixHolesByFilling(pixs, 4)) == NULL) {
ccbDestroy(&ccb);
return (CCBORD *)ERROR_PTR("pixh not made", procName, NULL);
}
pixZero(pixh, &allzero);
if (allzero) {
pixDestroy(&pixh);
return ccb;
}
if ((boxa = pixConnComp(pixh, &pixa, 4)) == NULL) {
ccbDestroy(&ccb);
pixDestroy(&pixh);
return (CCBORD *)ERROR_PTR("boxa not made", procName, NULL);
}
nh = boxaGetCount(boxa);
w = pixGetWidth(pixs);
for (i = 0; i < nh; i++) {
boxt = boxaGetBox(boxa, i, L_CLONE);
pixt = pixaGetPix(pixa, i, L_CLONE);
ys = boxt->y;
for (x = 0; x < boxt->w; x++) {
pixGetPixel(pixt, x, 0, &val);
if (val == 1) {
xh = x;
break;
}
}
if (x == boxt->w) {
L_WARNING("no hole pixel found!\n", procName);
continue;
}
for (x = xh + boxt->x; x < w; x++) {
pixGetPixel(pixs, x, ys, &val);
if (val == 1) {
xs = x;
break;
}
}
boxe = boxCreate(boxt->x - 1, boxt->y - 1, boxt->w + 2, boxt->h + 2);
#if DEBUG_PRINT
