int parse_sar_opt(char *argv[], int *opt, struct activity *act[],
uint64_t *flags, int caller)
{
int i, p;
for (i = 1; *(argv[*opt] + i); i++) {
switch (*(argv[*opt] + i)) {
case 'A':
select_all_activities(act);
*flags |= S_F_OPTION_A;
p = get_activity_position(act, A_MEMORY, EXIT_IF_NOT_FOUND);
act[p]->opt_flags |= AO_F_MEMORY + AO_F_SWAP + AO_F_MEM_ALL;
p = get_activity_position(act, A_CPU, EXIT_IF_NOT_FOUND);
act[p]->opt_flags = AO_F_CPU_ALL;
p = get_activity_position(act, A_FS, EXIT_IF_NOT_FOUND);
act[p]->opt_flags = AO_F_FILESYSTEM;
break;
case 'B':
SELECT_ACTIVITY(A_PAGE);
break;
case 'b':
SELECT_ACTIVITY(A_IO);
break;
case 'C':
*flags |= S_F_COMMENT;
break;
case 'd':
SELECT_ACTIVITY(A_DISK);
break;
case 'F':
p = get_activity_position(act, A_FS, EXIT_IF_NOT_FOUND);
act[p]->options |= AO_SELECTED;
if (!*(argv[*opt] + i + 1) && argv[*opt + 1] && !strcmp(argv[*opt + 1], K_MOUNT)) {
(*opt)++;
act[p]->opt_flags |= AO_F_MOUNT;
return 0;
}
else {
act[p]->opt_flags |= AO_F_FILESYSTEM;
}
break;
case 'H':
SELECT_ACTIVITY(A_HUGE);
break;
case 'h':
*flags |= S_F_HUMAN_READ + S_F_UNIT + S_F_DEV_PRETTY;
break;
case 'j':
if (!argv[*opt + 1]) {
return 1;
}
(*opt)++;
if (!strcmp(argv[*opt], K_SID)) {
*flags |= S_F_DEV_SID + S_F_DEV_PRETTY;
return 0;
}
if (strnlen(argv[*opt], MAX_FILE_LEN) >= MAX_FILE_LEN - 1)
return 1;
strncpy(persistent_name_type, argv[*opt], MAX_FILE_LEN - 1);
persistent_name_type[MAX_FILE_LEN - 1] = '\0';
strtolower(persistent_name_type);
if (!get_persistent_type_dir(persistent_name_type)) {
fprintf(stderr, _("Invalid type of persistent device name\n"));
return 2;
}
*flags |= S_F_PERSIST_NAME + S_F_DEV_PRETTY;
return 0;
break;
case 'p':
*flags |= S_F_DEV_PRETTY;
break;
case 'q':
SELECT_ACTIVITY(A_QUEUE);
break;
case 'r':
p = get_activity_position(act, A_MEMORY, EXIT_IF_NOT_FOUND);
act[p]->options |= AO_SELECTED;
act[p]->opt_flags |= AO_F_MEMORY;
if (!*(argv[*opt] + i + 1) && argv[*opt + 1] && !strcmp(argv[*opt + 1], K_ALL)) {
(*opt)++;
act[p]->opt_flags |= AO_F_MEM_ALL;
return 0;
}
break;
case 'S':
p = get_activity_position(act, A_MEMORY, EXIT_IF_NOT_FOUND);
act[p]->options |= AO_SELECTED;
act[p]->opt_flags |= AO_F_SWAP;
break;
case 't':
if (caller != C_SAR) {
return 1;
}
*flags |= S_F_TRUE_TIME;
break;
case 'u':
p = get_activity_position(act, A_CPU, EXIT_IF_NOT_FOUND);
act[p]->options |= AO_SELECTED;
if (!*(argv[*opt] + i + 1) && argv[*opt + 1] && !strcmp(argv[*opt + 1], K_ALL)) {
(*opt)++;
act[p]->opt_flags = AO_F_CPU_ALL;
return 0;
}
else {
act[p]->opt_flags = AO_F_CPU_DEF;
}
break;
case 'v':
SELECT_ACTIVITY(A_KTABLES);
break;
case 'w':
SELECT_ACTIVITY(A_PCSW);
break;
case 'W':
SELECT_ACTIVITY(A_SWAP);
break;
case 'y':
SELECT_ACTIVITY(A_SERIAL);
break;
case 'z':
*flags |= S_F_ZERO_OMIT;
break;
case 'V':
print_version();
break;
default:
return 1;
}
}
return 0;
},0

static char * php_zip_make_relative_path(char *path, size_t path_len)
{
char *path_begin = path;
size_t i;
if (path_len < 1 || path == NULL) {
return NULL;
}
if (IS_SLASH(path[0])) {
return path + 1;
}
i = path_len;
while (1) {
while (i > 0 && !IS_SLASH(path[i])) {
i--;
}
if (!i) {
return path;
}
if (i >= 2 && (path[i -1] == '.' || path[i -1] == ':')) {
path_begin = path + i + 1;
break;
}
i--;
}
return path_begin;
},0

int ath6kl_wmi_add_del_mcast_filter_cmd(struct wmi *wmi, u8 if_idx,
u8 *filter, bool add_filter)
{
struct sk_buff *skb;
struct wmi_mcast_filter_add_del_cmd *cmd;
int ret;
if ((filter[0] != 0x33 || filter[1] != 0x33) &&
(filter[0] != 0x01 || filter[1] != 0x00 ||
filter[2] != 0x5e || filter[3] > 0x7f)) {
ath6kl_warn("invalid multicast filter address\n");
return -EINVAL;
}
skb = ath6kl_wmi_get_new_buf(sizeof(*cmd));
if (!skb)
return -ENOMEM;
cmd = (struct wmi_mcast_filter_add_del_cmd *) skb->data;
memcpy(cmd->mcast_mac, filter, ATH6KL_MCAST_FILTER_MAC_ADDR_SIZE);
ret = ath6kl_wmi_cmd_send(wmi, if_idx, skb,
add_filter ? WMI_SET_MCAST_FILTER_CMDID :
WMI_DEL_MCAST_FILTER_CMDID,
NO_SYNC_WMIFLAG);
return ret;
},0

static int tpm_seal(struct tpm_buf *tb, uint16_t keytype,
uint32_t keyhandle, const unsigned char *keyauth,
const unsigned char *data, uint32_t datalen,
unsigned char *blob, uint32_t *bloblen,
const unsigned char *blobauth,
const unsigned char *pcrinfo, uint32_t pcrinfosize)
{
struct osapsess sess;
struct tpm_digests *td;
unsigned char cont;
uint32_t ordinal;
uint32_t pcrsize;
uint32_t datsize;
int sealinfosize;
int encdatasize;
int storedsize;
int ret;
int i;
td = kmalloc(sizeof *td, GFP_KERNEL);
if (!td)
return -ENOMEM;
ret = osap(tb, &sess, keyauth, keytype, keyhandle);
if (ret < 0)
goto out;
dump_sess(&sess);
memcpy(td->xorwork, sess.secret, SHA1_DIGEST_SIZE);
memcpy(td->xorwork + SHA1_DIGEST_SIZE, sess.enonce, SHA1_DIGEST_SIZE);
ret = TSS_sha1(td->xorwork, SHA1_DIGEST_SIZE * 2, td->xorhash);
if (ret < 0)
goto out;
ret = tpm_get_random(TPM_ANY_NUM, td->nonceodd, TPM_NONCE_SIZE);
if (ret != TPM_NONCE_SIZE)
goto out;
ordinal = htonl(TPM_ORD_SEAL);
datsize = htonl(datalen);
pcrsize = htonl(pcrinfosize);
cont = 0;
for (i = 0; i < SHA1_DIGEST_SIZE; ++i)
td->encauth[i] = td->xorhash[i] ^ blobauth[i];
if (pcrinfosize == 0) {
ret = TSS_authhmac(td->pubauth, sess.secret, SHA1_DIGEST_SIZE,
sess.enonce, td->nonceodd, cont,
sizeof(uint32_t), &ordinal, SHA1_DIGEST_SIZE,
td->encauth, sizeof(uint32_t), &pcrsize,
sizeof(uint32_t), &datsize, datalen, data, 0,
0);
} else {
ret = TSS_authhmac(td->pubauth, sess.secret, SHA1_DIGEST_SIZE,
sess.enonce, td->nonceodd, cont,
sizeof(uint32_t), &ordinal, SHA1_DIGEST_SIZE,
td->encauth, sizeof(uint32_t), &pcrsize,
