static int read_yes_no_answer(void)
{
char answer[1024];
if (fgets(answer, sizeof(answer), stdin)) {
size_t answer_len = strlen(answer);
int got_full_line = 0, c;
if (answer_len >= 2 && answer[answer_len-2] == '\r') {
answer[answer_len-2] = '\0';
got_full_line = 1;
} else if (answer_len >= 1 && answer[answer_len-1] == '\n') {
answer[answer_len-1] = '\0';
got_full_line = 1;
}
if (!got_full_line)
while ((c = getchar()) != EOF && c != '\n')
;
} else
return 0;
if (tolower(answer[0]) == 'y' && !answer[1])
return 1;
if (!strncasecmp(answer, "yes", sizeof(answer)))
return 1;
if (tolower(answer[0]) == 'n' && !answer[1])
return 0;
if (!strncasecmp(answer, "no", sizeof(answer)))
return 0;
return -1;
},0

alloc_strvec_r(char *string)
{
char *cp, *start, *token;
size_t str_len;
vector_t *strvec;
if (!string)
return NULL;
strvec = vector_alloc();
cp = string;
while (true) {
cp += strspn(cp, WHITE_SPACE);
if (!*cp)
break;
start = cp;
if (*start == '"') {
start++;
if (!(cp = strchr(start, '"'))) {
report_config_error(CONFIG_UNMATCHED_QUOTE, "Unmatched quote: '%s'", string);
break;
}
str_len = (size_t)(cp - start);
cp++;
} else {
cp += strcspn(start, WHITE_SPACE_STR "\"");
str_len = (size_t)(cp - start);
}
token = MALLOC(str_len + 1);
memcpy(token, start, str_len);
token[str_len] = '\0';
vector_alloc_slot(strvec);
vector_set_slot(strvec, token);
}
if (!vector_size(strvec)) {
free_strvec(strvec);
return NULL;
}
return strvec;
},0

