static void rtl8xxxu_stop(struct ieee80211_hw *hw)
{
struct rtl8xxxu_priv *priv = hw->priv;
unsigned long flags;
rtl8xxxu_write8(priv, REG_TXPAUSE, 0xff);
rtl8xxxu_write16(priv, REG_RXFLTMAP0, 0x0000);
rtl8xxxu_write16(priv, REG_RXFLTMAP2, 0x0000);
spin_lock_irqsave(&priv->rx_urb_lock, flags);
priv->shutdown = true;
spin_unlock_irqrestore(&priv->rx_urb_lock, flags);
usb_kill_anchored_urbs(&priv->rx_anchor);
usb_kill_anchored_urbs(&priv->tx_anchor);
if (priv->usb_interrupts)
usb_kill_anchored_urbs(&priv->int_anchor);
rtl8xxxu_write8(priv, REG_TXPAUSE, 0xff);
priv->fops->disable_rf(priv);
if (priv->usb_interrupts)
rtl8xxxu_write32(priv, REG_USB_HIMR, 0);
rtl8xxxu_free_rx_resources(priv);
rtl8xxxu_free_tx_resources(priv);
},0

resolveEmphasisResets(EmphasisInfo *buffer, const EmphasisClass class,
const TranslationTableHeader *table, const InString *input,
unsigned int *wordBuffer) {
int in_word = 0, in_pass = 0, word_start = -1, word_reset = 0, orig_reset = -1,
letter_cnt = 0;
int i, j;
for (i = 0; i < input->length; i++) {
if (in_pass)
if (buffer[i].end & class) in_pass = 0;
if (!in_pass) {
if (buffer[i].begin & class)
in_pass = 1;
else {
if (!in_word) {
if (buffer[i].word & class) {
if (wordBuffer[i] & WORD_RESET ||
!checkAttr(input->chars[i], CTC_Letter, 0, table)) {
if (wordBuffer[i + 1] & WORD_CHAR) {
buffer[i + 1].word |= class;
if (wordBuffer[i] & WORD_WHOLE)
wordBuffer[i + 1] |= WORD_WHOLE;
}
buffer[i].word &= ~class;
wordBuffer[i] &= ~WORD_WHOLE;
if (checkAttr(input->chars[i], CTC_Letter, 0, table))
buffer[i].symbol |= class;
continue;
}
in_word = 1;
word_start = i;
letter_cnt = 0;
word_reset = 0;
}
else if (buffer[i].symbol & class) {
if (wordBuffer[i] & WORD_RESET ||
!checkAttr(input->chars[i], CTC_Letter, 0, table))
buffer[i].symbol &= ~class;
}
}
if (in_word) {
if (!(wordBuffer[i] & WORD_CHAR) ||
(buffer[i].word & class && buffer[i].end & class)) {
in_word = 0;
if (letter_cnt == 1) {
buffer[word_start].symbol |= class;
buffer[word_start].word &= ~class;
wordBuffer[word_start] &= ~WORD_WHOLE;
buffer[i].end &= ~class;
buffer[i].word &= ~class;
}
if (word_reset || wordBuffer[i] & WORD_RESET ||
!checkAttr(input->chars[i], CTC_Letter, 0, table)) {
buffer[i].end &= ~class;
buffer[i].word &= ~class;
}
if (i == word_start) {
wordBuffer[word_start] &= ~WORD_WHOLE;
buffer[i].end &= ~class;
buffer[i].word &= ~class;
}
orig_reset = -1;
} else {
if (wordBuffer[i] & WORD_RESET ||
!checkAttr(input->chars[i], CTC_Letter, 0, table)) {
if (!checkAttr(input->chars[i], CTC_Letter, 0, table)) {
if (checkAttr(input->chars[i], CTC_CapsMode, 0, table)) {
orig_reset = i;
continue;
} else if (orig_reset >= 0) {
for (j = orig_reset; j < i; j++)
buffer[j].word &= ~class;
orig_reset = -1;
}
}
if (letter_cnt == 1) {
buffer[word_start].symbol |= class;
buffer[word_start].word &= ~class;
wordBuffer[word_start] &= ~WORD_WHOLE;
}
if (checkAttr(input->chars[i], CTC_Letter, 0, table)) {
word_reset = 0;
word_start = i;
letter_cnt = 1;
buffer[i].word |= class;
} else
word_reset = 1;
continue;
}
if (word_reset) {
word_reset = 0;
word_start = i;
letter_cnt = 0;
buffer[i].word |= class;
}
letter_cnt++;
}
}
}
}
}
if (in_word) {
if (letter_cnt == 1) {
buffer[word_start].symbol |= class;
buffer[word_start].word &= ~class;
wordBuffer[word_start] &= ~WORD_WHOLE;
buffer[i].end &= ~class;
buffer[i].word &= ~class;
}
if (word_reset) {
buffer[i].end &= ~class;
buffer[i].word &= ~class;
}
}
},0

do_add_counters(struct net *net, const void __user *user,
unsigned int len, int compat)
{
unsigned int i;
struct xt_counters_info tmp;
struct xt_counters *paddc;
unsigned int num_counters;
const char *name;
int size;
void *ptmp;
struct xt_table *t;
const struct xt_table_info *private;
int ret = 0;
struct ipt_entry *iter;
unsigned int addend;
#ifdef CONFIG_COMPAT
struct compat_xt_counters_info compat_tmp;
if (compat) {
ptmp = &compat_tmp;
size = sizeof(struct compat_xt_counters_info);
} else
#endif
{
ptmp = &tmp;
size = sizeof(struct xt_counters_info);
}
if (copy_from_user(ptmp, user, size) != 0)
return -EFAULT;
#ifdef CONFIG_COMPAT
if (compat) {
num_counters = compat_tmp.num_counters;
name = compat_tmp.name;
} else
#endif
{
num_counters = tmp.num_counters;
name = tmp.name;
}
if (len != size + num_counters * sizeof(struct xt_counters))
return -EINVAL;
paddc = vmalloc(len - size);
if (!paddc)
return -ENOMEM;
if (copy_from_user(paddc, user + size, len - size) != 0) {
ret = -EFAULT;
goto free;
}
t = xt_find_table_lock(net, AF_INET, name);
if (IS_ERR_OR_NULL(t)) {
ret = t ? PTR_ERR(t) : -ENOENT;
goto free;
}
local_bh_disable();
private = t->private;
if (private->number != num_counters) {
ret = -EINVAL;
goto unlock_up_free;
}
i = 0;
addend = xt_write_recseq_begin();
xt_entry_foreach(iter, private->entries, private->size) {
struct xt_counters *tmp;
tmp = xt_get_this_cpu_counter(&iter->counters);
ADD_COUNTER(*tmp, paddc[i].bcnt, paddc[i].pcnt);
++i;
}
xt_write_recseq_end(addend);
unlock_up_free:
local_bh_enable();
xt_table_unlock(t);
module_put(t->me);
free:
vfree(paddc);
return ret;
},1

build_table_string(void)
{
char buf[HUGE_STRING_LENGTH];
unsigned int col_count;
statement *ptr;
DYNAMIC_STRING table_string;
DBUG_ENTER("build_table_string");
DBUG_PRINT("info", ("num int cols %u num char cols %u",
num_int_cols, num_char_cols));
init_dynamic_string(&table_string, "", 1024, 1024);
dynstr_append(&table_string, "CREATE TABLE `t1` (");
if (auto_generate_sql_autoincrement)
{
dynstr_append(&table_string, "id serial");
if (num_int_cols || num_char_cols)
dynstr_append(&table_string, ",");
}
if (auto_generate_sql_guid_primary)
{
dynstr_append(&table_string, "id varchar(32) primary key");
if (num_int_cols || num_char_cols || auto_generate_sql_guid_primary)
dynstr_append(&table_string, ",");
}
if (auto_generate_sql_secondary_indexes)
{
unsigned int count;
for (count= 0; count < auto_generate_sql_secondary_indexes; count++)
{
if (count)
dynstr_append(&table_string, ",");
if (snprintf(buf, HUGE_STRING_LENGTH, "id%d varchar(32) unique key", count)
> HUGE_STRING_LENGTH)
{
fprintf(stderr, "Memory Allocation error in create table\n");
exit(1);
}
dynstr_append(&table_string, buf);
}
if (num_int_cols || num_char_cols)
dynstr_append(&table_string, ",");
}
if (num_int_cols)
for (col_count= 1; col_count <= num_int_cols; col_count++)
{
if (num_int_cols_index)
{
if (snprintf(buf, HUGE_STRING_LENGTH, "intcol%d INT(32), INDEX(intcol%d)",
col_count, col_count) > HUGE_STRING_LENGTH)
{
fprintf(stderr, "Memory Allocation error in create table\n");
exit(1);
}
}
else
{
if (snprintf(buf, HUGE_STRING_LENGTH, "intcol%d INT(32) ", col_count)
> HUGE_STRING_LENGTH)
{
fprintf(stderr, "Memory Allocation error in create table\n");
exit(1);
}
}
dynstr_append(&table_string, buf);
if (col_count < num_int_cols || num_char_cols > 0)
dynstr_append(&table_string, ",");
}
if (num_char_cols)
for (col_count= 1; col_count <= num_char_cols; col_count++)
{
if (num_char_cols_index)
{
if (snprintf(buf, HUGE_STRING_LENGTH,
"charcol%d VARCHAR(128), INDEX(charcol%d) ",
col_count, col_count) > HUGE_STRING_LENGTH)
{
fprintf(stderr, "Memory Allocation error in creating table\n");
