ReadRankDims(mat_t *mat, matvar_t *matvar, enum matio_types data_type, mat_uint32_t nbytes)
{
size_t bytesread = 0;
if ( data_type == MAT_T_INT32 ) {
matvar->rank = nbytes / sizeof(mat_uint32_t);
matvar->dims = (size_t*)malloc(matvar->rank*sizeof(*matvar->dims));
if ( NULL != matvar->dims ) {
int i;
mat_uint32_t buf;
for ( i = 0; i < matvar->rank; i++) {
size_t readresult = fread(&buf, sizeof(mat_uint32_t), 1, (FILE*)mat->fp);
if ( 1 == readresult ) {
bytesread += sizeof(mat_uint32_t);
if ( mat->byteswap ) {
matvar->dims[i] = Mat_uint32Swap(&buf);
} else {
matvar->dims[i] = buf;
}
} else {
free(matvar->dims);
matvar->dims = NULL;
matvar->rank = 0;
return 0;
}
}
if ( matvar->rank % 2 != 0 ) {
size_t readresult = fread(&buf, sizeof(mat_uint32_t), 1, (FILE*)mat->fp);
if ( 1 == readresult ) {
bytesread += sizeof(mat_uint32_t);
} else {
free(matvar->dims);
matvar->dims = NULL;
matvar->rank = 0;
return 0;
}
}
} else {
matvar->rank = 0;
Mat_Critical("Error allocating memory for dims");
}
}
return bytesread;
},0

static int decode_atari_image_paletted(deark *c, struct atari_img_decode_data *adata)
{
i64 i, j;
i64 plane;
i64 rowspan;
u8 b;
u32 v;
i64 planespan;
i64 ncolors;
planespan = 2*((adata->w+15)/16);
rowspan = planespan*adata->bpp;
if(adata->ncolors>0)
ncolors = adata->ncolors;
else
ncolors = ((i64)1)<<adata->bpp;
for(j=0; j<adata->h; j++) {
for(i=0; i<adata->w; i++) {
v = 0;
for(plane=0; plane<adata->bpp; plane++) {
if(adata->was_compressed==0) {
if(adata->bpp==1) {
b = de_get_bits_symbol(adata->unc_pixels, 1, j*rowspan, i);
}
else if(adata->bpp==2) {
b = de_get_bits_symbol(adata->unc_pixels, 1,
j*rowspan + 2*plane + (i/16)*2, i);
}
else if(adata->bpp==4) {
b = de_get_bits_symbol(adata->unc_pixels, 1,
j*rowspan + 2*plane + (i/2-(i/2)%16)+8*((i%32)/16), i%16);
}
else if(adata->bpp==8) {
b = de_get_bits_symbol(adata->unc_pixels, 1,
j*rowspan + 2*plane + (i-i%16), i%16);
}
else {
b = 0;
}
}
else {
b = de_get_bits_symbol(adata->unc_pixels, 1, j*rowspan + plane*planespan, i);
}
if(b) v |= 1<<plane;
}
if(adata->is_spectrum512) {
v = spectrum512_FindIndex(i, v);
if(j>0) {
v += (unsigned int)(48*(j));
}
}
if(v>=(unsigned int)ncolors) v=(unsigned int)(ncolors-1);
de_bitmap_setpixel_rgb(adata->img, i, j, adata->pal[v]);
}
}
return 1;
},0

parserule(struct scanner *s, struct environment *env)
{
struct rule *r;
char *var;
struct evalstring *val;
bool hascommand = false, hasrspfile = false, hasrspcontent = false;
r = mkrule(scanname(s));
scannewline(s);
while (scanindent(s)) {
var = scanname(s);
parselet(s, &val);
ruleaddvar(r, var, val);
if (strcmp(var, "command") == 0)
hascommand = true;
else if (strcmp(var, "rspfile") == 0)
hasrspfile = true;
else if (strcmp(var, "rspfile_content") == 0)
hasrspcontent = true;
}
if (!hascommand)
fatal("rule '%s' has no command", r->name);
if (hasrspfile != hasrspcontent)
fatal("rule '%s' has rspfile and no rspfile_content or vice versa", r->name);
envaddrule(env, r);
},1

ncp_LogPhysicalRecord(struct ncp_server *server, const char *file_id,
__u8 locktype, __u32 offset, __u32 length, __u16 timeout)
{
int result;
ncp_init_request(server);
ncp_add_byte(server, locktype);
ncp_add_mem(server, file_id, 6);
ncp_add_be32(server, offset);
ncp_add_be32(server, length);
ncp_add_be16(server, timeout);
if ((result = ncp_request(server, 0x1A)) != 0)
{
ncp_unlock_server(server);
return result;
}
ncp_unlock_server(server);
return 0;
},0

