os2_printer_fopen(gx_io_device * iodev, const char *fname, const char *access,
FILE ** pfile, char *rfname, uint rnamelen)
{
os2_printer_t *pr = (os2_printer_t *)iodev->state;
char driver_name[256];
gs_lib_ctx_t *ctx = mem->gs_lib_ctx;
gs_fs_list_t *fs = ctx->core->fs;
*pfile = NULL;
for (fs = ctx->core->fs; fs != NULL && fs->next != NULL; fs = fs->next)
{
int code = 0;
if (fs->fs.open_printer)
code = fs->fs.open_printer(mem, fs->secret, fname, access, pfile);
if (code < 0)
return code;
if (*pfile != NULL)
return code;
}
if (pm_find_queue(pr->memory, fname, driver_name)) {
emprintf(pr->memory, "Invalid queue name. Use one of:\n");
pm_find_queue(pr->memory, NULL, NULL);
return_error(gs_error_undefinedfilename);
}
strncpy(pr->queue, fname, sizeof(pr->queue)-1);
*pfile = gp_open_scratch_file_impl(pr->memory, "gs", pr->filename, access, 0);
if (*pfile == NULL)
return_error(gs_fopen_errno_to_code(errno));
return 0;
},1

static unsigned int rcvbuf_limit(struct sock *sk, struct sk_buff *buf)
{
struct tipc_msg *msg = buf_msg(buf);
unsigned int limit;
if (msg_connected(msg))
limit = sysctl_tipc_rmem[2];
else
limit = sk->sk_rcvbuf >> TIPC_CRITICAL_IMPORTANCE <<
msg_importance(msg);
return limit;
},0

Sass_File_Context* ADDCALL sass_make_file_context(const char* input_path)
{
SharedObj::setTaint(true);
struct Sass_File_Context* ctx = (struct Sass_File_Context*) calloc(1, sizeof(struct Sass_File_Context));
if (ctx == 0) { std::cerr << "Error allocating memory for file context" << std::endl; return 0; }
ctx->type = SASS_CONTEXT_FILE;
init_options(ctx);
try {
if (input_path == 0) { throw(std::runtime_error("File context created without an input path")); }
if (*input_path == 0) { throw(std::runtime_error("File context created with empty input path")); }
sass_option_set_input_path(ctx, input_path);
} catch (...) {
handle_errors(ctx);
}
return ctx;
},0

int xmkstemp(char **tmpname, char *dir)
{
char *localtmp;
char *tmpenv;
mode_t old_mode;
int fd, rc;
if (dir != NULL)
tmpenv = dir;
else
tmpenv = getenv("TMPDIR");
if (tmpenv)
rc = asprintf(&localtmp, "%s/%s.XXXXXX", tmpenv,
program_invocation_short_name);
else
rc = asprintf(&localtmp, "%s/%s.XXXXXX", _PATH_TMP,
program_invocation_short_name);
if (rc < 0)
return -1;
old_mode = umask(077);
fd = mkostemp(localtmp, O_RDWR|O_CREAT|O_EXCL|O_CLOEXEC);
umask(old_mode);
if (fd == -1) {
free(localtmp);
localtmp = NULL;
}
*tmpname = localtmp;
return fd;
},1

static bool io_rw_reissue(struct io_kiocb *req, long res)
{
