void Compute(OpKernelContext* context) override {
const Tensor& encoded_variant = context->input(0);
auto input_ragged_rank_ = input_ragged_rank_attr_;
if (input_ragged_rank_ == -1) {
input_ragged_rank_ = output_ragged_rank_ - encoded_variant.dims();
OP_REQUIRES(context, input_ragged_rank_ >= 0,
errors::InvalidArgument(
"Inferred input_ragged_rank (output_ragged_rank - "
"encoded_variant.dims()) must be >= 0, found "
"output_ragged_rank: ",
output_ragged_rank_,
", encoded_variant.dims(): ", encoded_variant.dims(),
", inferred input_ragged_rank: ", input_ragged_rank_));
}
OP_REQUIRES(
context,
output_ragged_rank_ == encoded_variant.dims() + input_ragged_rank_,
errors::InvalidArgument(
"output_ragged_rank must be equal to input_ragged_rank + "
"encoded_ragged.dims(); output_ragged_rank: ",
output_ragged_rank_, ", input_ragged_rank: ", input_ragged_rank_,
", encoded_variant.dims(): ", encoded_variant.dims(), "."));
const auto value_dtype = DataTypeToEnum<VALUE_TYPE>::v();
const auto split_dtype = DataTypeToEnum<SPLIT_TYPE>::v();
std::vector<RaggedTensorVariant> decoded_components;
OP_REQUIRES_OK(context, RaggedComponentsFromVariant(
encoded_variant, input_ragged_rank_,
value_dtype, split_dtype, &decoded_components));
if (encoded_variant.dims() == 0) {
ReturnRaggedTensor(context, decoded_components[0]);
return;
}
std::vector<int> encoded_dim_sizes(encoded_variant.dims(), 0);
for (int i = 0; i < encoded_variant.dims(); i++) {
encoded_dim_sizes[i] = encoded_variant.dim_size(i);
}
RaggedTensorVariant output_ragged;
OP_REQUIRES_OK(
context, NestedStackRaggedTensors<VALUE_TYPE, SPLIT_TYPE>(
decoded_components, encoded_dim_sizes, input_ragged_rank_,
output_ragged_rank_, &output_ragged));
ReturnRaggedTensor(context, output_ragged);
},0

jas_image_t *ras_decode(jas_stream_t *in, char *optstr)
{
ras_hdr_t hdr;
ras_cmap_t cmap;
jas_image_t *image;
jas_image_cmptparm_t cmptparms[3];
jas_image_cmptparm_t *cmptparm;
int clrspc;
int numcmpts;
int i;
JAS_DBGLOG(10, ("ras_decode(%p, %p, \"%s\"\n", in, optstr ? optstr : ""));
if (optstr) {
jas_eprintf("warning: ignoring RAS decoder options\n");
}
if (ras_gethdr(in, &hdr)) {
return 0;
}
if (hdr.magic != RAS_MAGIC || hdr.width <= 0 || hdr.height <= 0 ||
hdr.depth <= 0 || hdr.depth > 32) {
return 0;
}
if (hdr.type == RAS_TYPE_OLD) {
hdr.length = RAS_ROWSIZE(&hdr) * hdr.height;
}
if (RAS_ISRGB(&hdr)) {
clrspc = JAS_CLRSPC_SRGB;
numcmpts = 3;
} else {
clrspc = JAS_CLRSPC_SGRAY;
numcmpts = 1;
}
for (i = 0, cmptparm = cmptparms; i < numcmpts; ++i, ++cmptparm) {
cmptparm->tlx = 0;
cmptparm->tly = 0;
cmptparm->hstep = 1;
cmptparm->vstep = 1;
cmptparm->width = hdr.width;
cmptparm->height = hdr.height;
cmptparm->prec = RAS_ISRGB(&hdr) ? 8 : hdr.depth;
cmptparm->sgnd = false;
}
if (!(image = jas_image_create(numcmpts, cmptparms, JAS_CLRSPC_UNKNOWN))) {
return 0;
}
if (ras_getcmap(in, &hdr, &cmap)) {
jas_image_destroy(image);
return 0;
}
if (ras_getdata(in, &hdr, &cmap, image)) {
jas_image_destroy(image);
return 0;
}
jas_image_setclrspc(image, clrspc);
if (clrspc == JAS_CLRSPC_SRGB) {
jas_image_setcmpttype(image, 0,
JAS_IMAGE_CT_COLOR(JAS_CLRSPC_CHANIND_RGB_R));
jas_image_setcmpttype(image, 1,
JAS_IMAGE_CT_COLOR(JAS_CLRSPC_CHANIND_RGB_G));
jas_image_setcmpttype(image, 2,
JAS_IMAGE_CT_COLOR(JAS_CLRSPC_CHANIND_RGB_B));
} else {
jas_image_setcmpttype(image, 0,
JAS_IMAGE_CT_COLOR(JAS_CLRSPC_CHANIND_GRAY_Y));
}
return image;
},0

int wc_PemGetHeaderFooter(int type, const char** header, const char** footer)
{
int ret = BAD_FUNC_ARG;
switch (type) {
case CA_TYPE:
case TRUSTED_PEER_TYPE:
case CERT_TYPE:
if (header) *header = BEGIN_CERT;
if (footer) *footer = END_CERT;
ret = 0;
break;
case CRL_TYPE:
if (header) *header = BEGIN_X509_CRL;
if (footer) *footer = END_X509_CRL;
ret = 0;
break;
#ifndef NO_DH
case DH_PARAM_TYPE:
if (header) *header = BEGIN_DH_PARAM;
if (footer) *footer = END_DH_PARAM;
ret = 0;
break;
#endif
#ifndef NO_DSA
case DSA_PARAM_TYPE:
if (header) *header = BEGIN_DSA_PARAM;
if (footer) *footer = END_DSA_PARAM;
ret = 0;
break;
#endif
#ifdef WOLFSSL_CERT_REQ
case CERTREQ_TYPE:
if (header) *header = BEGIN_CERT_REQ;
if (footer) *footer = END_CERT_REQ;
ret = 0;
break;
#endif
#ifndef NO_DSA
case DSA_TYPE:
case DSA_PRIVATEKEY_TYPE:
if (header) *header = BEGIN_DSA_PRIV;
if (footer) *footer = END_DSA_PRIV;
ret = 0;
break;
#endif
#ifdef HAVE_ECC
case ECC_TYPE:
case ECC_PRIVATEKEY_TYPE:
if (header) *header = BEGIN_EC_PRIV;
if (footer) *footer = END_EC_PRIV;
ret = 0;
break;
#endif
case RSA_TYPE:
case PRIVATEKEY_TYPE:
if (header) *header = BEGIN_RSA_PRIV;
if (footer) *footer = END_RSA_PRIV;
ret = 0;
break;
#ifdef HAVE_ED25519
case ED25519_TYPE:
#endif
#ifdef HAVE_ED448
case ED448_TYPE:
#endif
#if defined(HAVE_ED25519) || defined(HAVE_ED448)
case EDDSA_PRIVATEKEY_TYPE:
if (header) *header = BEGIN_EDDSA_PRIV;
if (footer) *footer = END_EDDSA_PRIV;
ret = 0;
break;
#endif
case PUBLICKEY_TYPE:
case ECC_PUBLICKEY_TYPE:
if (header) *header = BEGIN_PUB_KEY;
if (footer) *footer = END_PUB_KEY;
ret = 0;
break;
#ifndef NO_DH
case DH_PRIVATEKEY_TYPE:
#endif
case PKCS8_PRIVATEKEY_TYPE:
if (header) *header = BEGIN_PRIV_KEY;
if (footer) *footer = END_PRIV_KEY;
ret = 0;
break;
case PKCS8_ENC_PRIVATEKEY_TYPE:
if (header) *header = BEGIN_ENC_PRIV_KEY;
if (footer) *footer = END_ENC_PRIV_KEY;
ret = 0;
break;
default:
break;
}
return ret;
},0

PHPAPI php_stream *_php_stream_memory_open(int mode, char *buf, size_t length STREAMS_DC TSRMLS_DC)
{
php_stream *stream;
php_stream_memory_data *ms;
if ((stream = php_stream_memory_create_rel(mode)) != NULL) {
ms = (php_stream_memory_data*)stream->abstract;
if (mode == TEMP_STREAM_READONLY || mode == TEMP_STREAM_TAKE_BUFFER) {
ms->data = buf;
ms->fsize = length;
} else {
if (length) {
assert(buf != NULL);
php_stream_write(stream, buf, length);
}
}
}
return stream;
},1

static int ext4_ext_fiemap_cb(struct inode *inode, struct ext4_ext_path *path,
struct ext4_ext_cache *newex, struct ext4_extent *ex,
void *data)
{
__u64 logical;
__u64 physical;
__u64 length;
loff_t size;
__u32 flags = 0;
int ret = 0;
struct fiemap_extent_info *fieinfo = data;
unsigned char blksize_bits;
blksize_bits = inode->i_sb->s_blocksize_bits;
logical = (__u64)newex->ec_block << blksize_bits;
if (newex->ec_start == 0) {
ext4_lblk_t end = 0;
pgoff_t last_offset;
pgoff_t offset;
pgoff_t index;
struct page **pages = NULL;
struct buffer_head *bh = NULL;
struct buffer_head *head = NULL;
unsigned int nr_pages = PAGE_SIZE / sizeof(struct page *);
pages = kmalloc(PAGE_SIZE, GFP_KERNEL);
if (pages == NULL)
return -ENOMEM;
offset = logical >> PAGE_SHIFT;
repeat:
last_offset = offset;
head = NULL;
ret = find_get_pages_tag(inode->i_mapping, &offset,
PAGECACHE_TAG_DIRTY, nr_pages, pages);
if (!(flags & FIEMAP_EXTENT_DELALLOC)) {
if (ret == 0) {
out:
for (index = 0; index < ret; index++)
page_cache_release(pages[index]);
kfree(pages);
return EXT_CONTINUE;
}
end = ((__u64)pages[0]->index << PAGE_SHIFT) >>
blksize_bits;
if (!page_has_buffers(pages[0]))
goto out;
head = page_buffers(pages[0]);
if (!head)
goto out;
bh = head;
do {
if (buffer_mapped(bh)) {
if (end > newex->ec_block +
newex->ec_len)
goto out;
goto found_mapped_buffer;
}
bh = bh->b_this_page;
end++;
} while (bh != head);
goto out;
} else {
if (ret > 0 && pages[0]->index == last_offset)
head = page_buffers(pages[0]);
bh = head;
}
found_mapped_buffer:
if (bh != NULL && buffer_delay(bh)) {
if (!(flags & FIEMAP_EXTENT_DELALLOC)) {
flags |= FIEMAP_EXTENT_DELALLOC;
newex->ec_block = end;
logical = (__u64)end << blksize_bits;
}
do {
if (!buffer_delay(bh))
goto found_delayed_extent;
bh = bh->b_this_page;
end++;
} while (bh != head);
for (index = 1; index < ret; index++) {
if (!page_has_buffers(pages[index])) {
bh = NULL;
break;
}
head = page_buffers(pages[index]);
if (!head) {
bh = NULL;
break;
}
if (pages[index]->index !=
pages[0]->index + index) {
bh = NULL;
break;
}
bh = head;
do {
if (!buffer_delay(bh))
goto found_delayed_extent;
bh = bh->b_this_page;
end++;
} while (bh != head);
}
} else if (!(flags & FIEMAP_EXTENT_DELALLOC))
goto out;
found_delayed_extent:
newex->ec_len = min(end - newex->ec_block,
(ext4_lblk_t)EXT_INIT_MAX_LEN);
if (ret == nr_pages && bh != NULL &&
newex->ec_len < EXT_INIT_MAX_LEN &&
buffer_delay(bh)) {
for (index = 0; index < ret; index++)
page_cache_release(pages[index]);
goto repeat;
}
for (index = 0; index < ret; index++)
page_cache_release(pages[index]);
kfree(pages);
}
physical = (__u64)newex->ec_start << blksize_bits;
length = (__u64)newex->ec_len << blksize_bits;
if (ex && ext4_ext_is_uninitialized(ex))
flags |= FIEMAP_EXTENT_UNWRITTEN;
size = i_size_read(inode);
if (logical + length >= size)
flags |= FIEMAP_EXTENT_LAST;
ret = fiemap_fill_next_extent(fieinfo, logical, physical,
length, flags);
if (ret < 0)
return ret;
if (ret == 1)
return EXT_BREAK;
return EXT_CONTINUE;
},0

SPL_METHOD(Array, unserialize)
{
spl_array_object *intern = (spl_array_object*)zend_object_store_get_object(getThis() TSRMLS_CC);
char *buf;
int buf_len;
const unsigned char *p, *s;
php_unserialize_data_t var_hash;
