static PHP_FUNCTION(xmlwriter_open_uri)
{
char *valid_file = NULL;
xmlwriter_object *intern;
xmlTextWriterPtr ptr;
char *source;
char resolved_path[MAXPATHLEN + 1];
int source_len;
#ifdef ZEND_ENGINE_2
zval *this = getThis();
ze_xmlwriter_object *ze_obj = NULL;
#endif
#ifndef ZEND_ENGINE_2
xmlOutputBufferPtr out_buffer;
void *ioctx;
#endif
if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "s", &source, &source_len) == FAILURE) {
return;
}
#ifdef ZEND_ENGINE_2
if (this) {
ze_obj = (ze_xmlwriter_object*) zend_object_store_get_object(this TSRMLS_CC);
}
#endif
if (source_len == 0) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Empty string as source");
RETURN_FALSE;
}
valid_file = _xmlwriter_get_valid_file_path(source, resolved_path, MAXPATHLEN TSRMLS_CC);
if (!valid_file) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to resolve file path");
RETURN_FALSE;
}
#ifndef ZEND_ENGINE_2
ioctx = php_xmlwriter_streams_IO_open_write_wrapper(valid_file TSRMLS_CC);
if (ioctx == NULL) {
RETURN_FALSE;
}
out_buffer = xmlOutputBufferCreateIO(php_xmlwriter_streams_IO_write,
php_xmlwriter_streams_IO_close, ioctx, NULL);
if (out_buffer == NULL) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to create output buffer");
RETURN_FALSE;
}
ptr = xmlNewTextWriter(out_buffer);
#else
ptr = xmlNewTextWriterFilename(valid_file, 0);
#endif
if (!ptr) {
RETURN_FALSE;
}
intern = emalloc(sizeof(xmlwriter_object));
intern->ptr = ptr;
intern->output = NULL;
#ifndef ZEND_ENGINE_2
intern->uri_output = out_buffer;
#else
if (this) {
if (ze_obj->xmlwriter_ptr) {
xmlwriter_free_resource_ptr(ze_obj->xmlwriter_ptr TSRMLS_CC);
}
ze_obj->xmlwriter_ptr = intern;
RETURN_TRUE;
} else
#endif
{
ZEND_REGISTER_RESOURCE(return_value,intern,le_xmlwriter);
}
},1

static void initBuf(unsigned char *buf, int w, int h, int pf, int flags)
{
int roffset = tjRedOffset[pf];
int goffset = tjGreenOffset[pf];
int boffset = tjBlueOffset[pf];
int ps = tjPixelSize[pf];
int index, row, col, halfway = 16;
if (pf == TJPF_GRAY) {
memset(buf, 0, w * h * ps);
for (row = 0; row < h; row++) {
for (col = 0; col < w; col++) {
if (flags & TJFLAG_BOTTOMUP) index = (h - row - 1) * w + col;
else index = row * w + col;
if (((row / 8) + (col / 8)) % 2 == 0)
buf[index] = (row < halfway) ? 255 : 0;
else buf[index] = (row < halfway) ? 76 : 226;
}
}
} else if (pf == TJPF_CMYK) {
memset(buf, 255, w * h * ps);
for (row = 0; row < h; row++) {
for (col = 0; col < w; col++) {
if (flags & TJFLAG_BOTTOMUP) index = (h - row - 1) * w + col;
else index = row * w + col;
if (((row / 8) + (col / 8)) % 2 == 0) {
if (row >= halfway) buf[index * ps + 3] = 0;
} else {
buf[index * ps + 2] = 0;
if (row < halfway) buf[index * ps + 1] = 0;
}
}
}
} else {
memset(buf, 0, w * h * ps);
for (row = 0; row < h; row++) {
for (col = 0; col < w; col++) {
if (flags & TJFLAG_BOTTOMUP) index = (h - row - 1) * w + col;
else index = row * w + col;
if (((row / 8) + (col / 8)) % 2 == 0) {
if (row < halfway) {
buf[index * ps + roffset] = 255;
buf[index * ps + goffset] = 255;
buf[index * ps + boffset] = 255;
}
} else {
buf[index * ps + roffset] = 255;
if (row >= halfway) buf[index * ps + goffset] = 255;
}
}
}
}
},0

xfs_attr_calc_size(
struct xfs_inode *ip,
int namelen,
int valuelen,
int *local)
{
struct xfs_mount *mp = ip->i_mount;
int size;
int nblks;
size = xfs_attr_leaf_newentsize(namelen, valuelen,
mp->m_sb.sb_blocksize, local);
nblks = XFS_DAENTER_SPACE_RES(mp, XFS_ATTR_FORK);
if (*local) {
if (size > (mp->m_sb.sb_blocksize >> 1)) {
nblks *= 2;
}
} else {
uint dblocks = XFS_B_TO_FSB(mp, valuelen);
nblks += dblocks;
nblks += XFS_NEXTENTADD_SPACE_RES(mp, dblocks, XFS_ATTR_FORK);
}
return nblks;
},1

apr_array_header_t *h2_push_collect(apr_pool_t *p, const h2_request *req,
apr_uint32_t push_policy, const h2_headers *res)
{
if (req && push_policy != H2_PUSH_NONE) {
if (res->headers) {
link_ctx ctx;
memset(&ctx, 0, sizeof(ctx));
ctx.req = req;
ctx.push_policy = push_policy;
ctx.pool = p;
apr_table_do(head_iter, &ctx, res->headers, NULL);
if (ctx.pushes) {
apr_table_setn(res->headers, "push-policy",
policy_str(push_policy));
}
return ctx.pushes;
}
}
return NULL;
},0

unsigned paravirt_patch_jmp(void *insnbuf, const void *target,
unsigned long addr, unsigned len)
{
struct branch *b = insnbuf;
unsigned long delta = (unsigned long)target - (addr+5);
if (len < 5)
return len;
b->opcode = 0xe9;
b->delta = delta;
return 5;
