rescale_num = atoi(ext+9);
rescale_den = 0;
}
}
else if (!strnicmp(ext+1, "sampdur=", 8)) {
if (sscanf(ext+9, "%u/%u", &rescale_den, &rescale_num) != 2) {
rescale_den = atoi(ext+9);
rescale_num = 0;
}
rescale_override = GF_TRUE;
}
