*sep = 0;
}
kind_scheme = gf_strdup(kind_data);
if (sep) {
*sep = '=';
kind_value = gf_strdup(sep+1);
} else {
kind_value = NULL;
}
gf_list_add(kinds, kind_scheme);
gf_list_add(kinds, kind_value);
}
