if (!strnicmp(ext+1, "txtflags=", 9)) {
sscanf(ext+10, "%x", &txt_flags);
}
else if (!strnicmp(ext+1, "txtflags+=", 10)) {
sscanf(ext+11, "%x", &txt_flags);
