gtk_tree_model_get (GTK_TREE_MODEL (window->priv->list_store), &iter,
COLUMN_FILE_DATA, &fdata,
-1);
if (! file_data_is_dir (fdata)) {
GList *list = g_list_prepend (NULL, fdata->original_path);
fr_window_open_files (window, list, FALSE);
g_list_free (list);
