int wolfSSH_SFTP_RecvRMDIR(WOLFSSH* ssh, int reqId, byte* data, word32 maxSz)
{
word32 sz;
int ret = 0;
char* dir;
word32 idx = 0;
byte* out;
word32 outSz = 0;
byte type;
char err[] = "Remove Directory Error";
char suc[] = "Removed Directory";
char* res = NULL;
if (ssh == NULL) {
return WS_BAD_ARGUMENT;
}
WLOG(WS_LOG_SFTP, "Receiving WOLFSSH_FTP_RMDIR");
ato32(data + idx, &sz); idx += UINT32_SZ;
if (sz + idx > maxSz) {
return WS_BUFFER_E;
}
dir = (char*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (dir == NULL) {
return WS_MEMORY_E;
}
WMEMCPY(dir, data + idx, sz);
dir[sz] = '\0';
if (wolfSSH_CleanPath(ssh, dir) < 0) {
ret = WS_FATAL_ERROR;
}
if (ret == 0) {
#ifndef USE_WINDOWS_API
ret = WRMDIR(ssh->fs, dir);
#else
ret = WS_RemoveDirectoryA(dir, ssh->ctx->heap) == 0;
#endif
}
WFREE(dir, ssh->ctx->heap, DYNTYPE_BUFFER);
res = (ret != 0)? err : suc;
type = (ret != 0)? WOLFSSH_FTP_FAILURE : WOLFSSH_FTP_OK;
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res,
"English", NULL, &outSz) != WS_SIZE_ONLY) {
return WS_FATAL_ERROR;
}
out = (byte*)WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
if (ret != 0) {
WLOG(WS_LOG_SFTP, "Error removing directory %s", dir);
ret = WS_BAD_FILE_E;
}
else {
ret = WS_SUCCESS;
}
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res, "English", out,
&outSz) != WS_SUCCESS) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
return ret;
},1

static const struct vhost_memory_region *find_region(struct vhost_memory *mem,
__u64 addr, __u32 len)
{
const struct vhost_memory_region *reg;
int start = 0, end = mem->nregions;
while (start < end) {
int slot = start + (end - start) / 2;
reg = mem->regions + slot;
if (addr >= reg->guest_phys_addr)
end = slot;
else
start = slot + 1;
}
reg = mem->regions + start;
if (addr >= reg->guest_phys_addr &&
reg->guest_phys_addr + reg->memory_size > addr)
return reg;
return NULL;
},0

static Image *ReadFLIFImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
FLIF_DECODER
*flifdec;
FLIF_IMAGE
*flifimage;
Image
*image;
MagickBooleanType
status;
register PixelPacket
*q;
register ssize_t
x;
register unsigned short
*p;
size_t
count,
image_count,
length;
ssize_t
y;
unsigned char
*stream;
unsigned short
*pixels;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
length=(size_t) GetBlobSize(image);
stream=(unsigned char *) AcquireQuantumMemory(length,sizeof(*stream));
if (stream == (unsigned char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,length,stream);
if (count != length)
{
stream=(unsigned char *) RelinquishMagickMemory(stream);
ThrowReaderException(CorruptImageError,"InsufficientImageDataInFile");
}
flifdec=flif_create_decoder();
if (image_info->quality != UndefinedCompressionQuality)
flif_decoder_set_quality(flifdec,image_info->quality);
if (!flif_decoder_decode_memory(flifdec,stream,length))
{
flif_destroy_decoder(flifdec);
ThrowReaderException(CorruptImageError,"CorruptImage");
}
image_count=flif_decoder_num_images(flifdec);
flifimage=flif_decoder_get_image(flifdec,0);
length=sizeof(unsigned short)*4*flif_image_get_width(flifimage);
pixels=(unsigned short *) AcquireMagickMemory(length);
if (pixels == (unsigned short *) NULL)
{
flif_destroy_decoder(flifdec);
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
for (count=0; count < image_count; count++)
{
if (count > 0)
{
AcquireNextImage(image_info,image);
if (GetNextImageInList(image) == (Image *) NULL)
{
image=DestroyImageList(image);
flif_destroy_decoder(flifdec);
pixels=(unsigned short *) RelinquishMagickMemory(pixels);
return((Image *) NULL);
}
image=SyncNextImageInList(image);
}
flifimage=flif_decoder_get_image(flifdec,count);
image->columns=(size_t) flif_image_get_width(flifimage);
image->rows=(size_t) flif_image_get_height(flifimage);
image->depth=flif_image_get_depth(flifimage);
image->matte=(flif_image_get_nb_channels(flifimage) > 3 ?
MagickTrue : MagickFalse);
image->delay=flif_image_get_frame_delay(flifimage);
image->ticks_per_second=1000;
image->scene=count;
image->dispose=BackgroundDispose;
for (y=0; y < (ssize_t) image->rows; y++)
{
flif_image_read_row_RGBA16(flifimage,y,pixels,length);
p=pixels;
q=QueueAuthenticPixels(image,0,y,image->columns,1,exception);
if (q == (PixelPacket *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
SetPixelRed(q,ScaleShortToQuantum(*p++));
SetPixelGreen(q,ScaleShortToQuantum(*p++));
SetPixelBlue(q,ScaleShortToQuantum(*p++));
SetPixelAlpha(q,ScaleShortToQuantum(*p++));
q++;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
flif_destroy_decoder(flifdec);
pixels=(unsigned short *) RelinquishMagickMemory(pixels);
return(image);
},1

