int do_attack_cfrag( void )
{
int caplen, n;
struct timeval tv;
struct timeval tv2;
float f, ticks[3];
unsigned char bssid[6];
unsigned char smac[6];
unsigned char dmac[6];
unsigned char keystream[128];
unsigned char frag1[128], frag2[128], frag3[128];
unsigned char clear[4096], final[4096], flip[4096];
int isarp;
int z, i;
opt.f_fromds = 0;
read_packets:
if( capture_ask_packet( &caplen, 0 ) != 0 )
return( 1 );
z = ( ( h80211[1] & 3 ) != 3 ) ? 24 : 30;
if ( ( h80211[0] & 0x80 ) == 0x80 )
z+=2;
if(caplen < z)
{
goto read_packets;
}
if(caplen > 3800)
{
goto read_packets;
}
switch( h80211[1] & 3 )
{
case 0:
memcpy( bssid, h80211 + 16, 6 );
memcpy( dmac, h80211 + 4, 6 );
memcpy( smac, h80211 + 10, 6 );
break;
case 1:
memcpy( bssid, h80211 + 4, 6 );
memcpy( dmac, h80211 + 16, 6 );
memcpy( smac, h80211 + 10, 6 );
break;
case 2:
memcpy( bssid, h80211 + 10, 6 );
memcpy( dmac, h80211 + 4, 6 );
memcpy( smac, h80211 + 16, 6 );
break;
default:
memcpy( bssid, h80211 + 10, 6 );
memcpy( dmac, h80211 + 16, 6 );
memcpy( smac, h80211 + 24, 6 );
break;
}
memset(clear, 0, 4096);
memset(final, 0, 4096);
memset(flip, 0, 4096);
memset(frag1, 0, 128);
memset(frag2, 0, 128);
memset(frag3, 0, 128);
memset(keystream, 0, 128);
if( (caplen-z == 68-24 || caplen-z == 86-24) && (memcmp(dmac, BROADCAST, 6) == 0 || (dmac[0]%2) == 0) )
{
printf("Found ARP packet\n");
isarp = 1;
set_clear_arp(clear, smac, dmac);
set_final_arp(final, opt.r_smac);
for(i=0; i<14; i++)
keystream[i] = (h80211+z+4)[i] ^ clear[i];
if( (h80211[1] & 3) == 0x00 )
{
h80211[1] = 0x40;
memcpy(h80211+4, smac, 6);
memcpy(h80211+10, opt.r_smac, 6);
memcpy(h80211+16, bssid, 6);
}
else
{
if(opt.f_tods == 1)
{
h80211[1] = 0x41;
memcpy(h80211+4 , bssid, 6);
memcpy(h80211+10, opt.r_smac, 6);
memcpy(h80211+16, smac, 6);
}
else
{
h80211[1] = 0x42;
memcpy(h80211+4, smac, 6);
memcpy(h80211+10, bssid, 6);
memcpy(h80211+16, opt.r_smac, 6);
}
}
h80211[22] = 0xD0;
h80211[23] = 0x50;
memcpy(frag1, h80211, z+4);
frag1[1] |= 0x04;
memcpy(frag1+z+4, S_LLC_SNAP_ARP, 8);
frag1[z+4+8] = 0x00;
frag1[z+4+9] = 0x01;
add_crc32(frag1+z+4, 10);
for(i=0; i<14; i++)
(frag1+z+4)[i] ^= keystream[i];
for(i=0; i<caplen; i++)
flip[i] = clear[i] ^ final[i];
add_crc32_plain(flip, caplen-z-4-4);
for(i=0; i<caplen-z-4; i++)
(h80211+z+4)[i] ^= flip[i];
h80211[22] = 0xD1;
}
else
{
printf("Found IP packet\n");
isarp = 0;
set_clear_ip(clear, caplen-z-4-8-4);
set_final_ip(final, opt.r_smac);
for(i=0; i<8; i++)
keystream[i] = (h80211+z+4)[i] ^ clear[i];
if( (h80211[1] & 3) == 0x00 )
{
h80211[1] = 0x40;
memcpy(h80211+4, smac, 6);
memcpy(h80211+10, opt.r_smac, 6);
memcpy(h80211+16, bssid, 6);
}
else
{
if(opt.f_tods == 1)
{
h80211[1] = 0x41;
memcpy(h80211+4 , bssid, 6);
memcpy(h80211+10, opt.r_smac, 6);
memcpy(h80211+16, smac, 6);
}
else
{
h80211[1] = 0x42;
memcpy(h80211+4, smac, 6);
memcpy(h80211+10, bssid, 6);
memcpy(h80211+16, opt.r_smac, 6);
}
}
h80211[22] = 0xD0;
h80211[23] = 0x50;
memcpy(frag1, h80211, z+4);
memcpy(frag2, h80211, z+4);
memcpy(frag3, h80211, z+4);
frag1[1] |= 0x04;
frag2[1] |= 0x04;
frag3[1] |= 0x04;
memcpy(frag1+z+4, S_LLC_SNAP_ARP, 4);
add_crc32(frag1+z+4, 4);
for(i=0; i<8; i++)
(frag1+z+4)[i] ^= keystream[i];
memcpy(frag2+z+4, S_LLC_SNAP_ARP+4, 4);
add_crc32(frag2+z+4, 4);
for(i=0; i<8; i++)
(frag2+z+4)[i] ^= keystream[i];
frag2[22] = 0xD1;
frag3[z+4+0] = 0x00;
frag3[z+4+1] = 0x01;
frag3[z+4+2] = 0x08;
frag3[z+4+3] = 0x00;
add_crc32(frag3+z+4, 4);
for(i=0; i<8; i++)
(frag3+z+4)[i] ^= keystream[i];
frag3[22] = 0xD2;
for(i=0; i<caplen; i++)
flip[i] = clear[i] ^ final[i];
add_crc32_plain(flip, caplen-z-4-4);
for(i=0; i<caplen-z-4; i++)
(h80211+z+4)[i] ^= flip[i];
h80211[22] = 0xD3;
}
printf( "You should also start airodump-ng to capture replies.\n\n" );
signal( SIGINT, sighandler );
ctrl_c = 0;
memset( ticks, 0, sizeof( ticks ) );
nb_pkt_sent = 0;
while( 1 )
{
if( ctrl_c )
goto read_packets;
if( dev.fd_rtc >= 0 )
{
if( read( dev.fd_rtc, &n, sizeof( n ) ) < 0 )
{
perror( "read(/dev/rtc) failed" );
return( 1 );
}
ticks[0]++;
ticks[1]++;
ticks[2]++;
}
else
{
gettimeofday( &tv, NULL );
usleep( 1000000/RTC_RESOLUTION );
gettimeofday( &tv2, NULL );
f = 1000000 * (float) ( tv2.tv_sec - tv.tv_sec )
+ (float) ( tv2.tv_usec - tv.tv_usec );
ticks[0] += f / ( 1000000/RTC_RESOLUTION );
ticks[1] += f / ( 1000000/RTC_RESOLUTION );
ticks[2] += f / ( 1000000/RTC_RESOLUTION );
}
if( ticks[1] > (RTC_RESOLUTION/10) )
{
ticks[1] = 0;
printf( "\rSent %ld packets...(%d pps)\33[K\r", nb_pkt_sent, (int)((double)nb_pkt_sent/((double)ticks[0]/(double)RTC_RESOLUTION)));
fflush( stdout );
}
if( ( ticks[2] * opt.r_nbpps ) / RTC_RESOLUTION < 1 )
continue;
ticks[2] = 0;
if( nb_pkt_sent == 0 )
ticks[0] = 0;
if(isarp)
{
if( send_packet( frag1, z+4+10+4 ) < 0 )
return( 1 );
nb_pkt_sent--;
}
else
{
if( send_packet( frag1, z+4+4+4 ) < 0 )
return( 1 );
if( send_packet( frag2, z+4+4+4 ) < 0 )
return( 1 );
if( send_packet( frag3, z+4+4+4 ) < 0 )
return( 1 );
nb_pkt_sent-=3;
}
if( send_packet( h80211, caplen ) < 0 )
return( 1 );
}
return( 0 );
},0

static enum gro_result dev_gro_receive(struct napi_struct *napi, struct sk_buff *skb)
{
struct sk_buff **pp = NULL;
struct packet_offload *ptype;
__be16 type = skb->protocol;
struct list_head *head = &offload_base;
int same_flow;
enum gro_result ret;
int grow;
if (!(skb->dev->features & NETIF_F_GRO))
goto normal;
if (skb_is_gso(skb) || skb_has_frag_list(skb) || skb->csum_bad)
goto normal;
gro_list_prepare(napi, skb);
rcu_read_lock();
list_for_each_entry_rcu(ptype, head, list) {
if (ptype->type != type || !ptype->callbacks.gro_receive)
continue;
skb_set_network_header(skb, skb_gro_offset(skb));
skb_reset_mac_len(skb);
NAPI_GRO_CB(skb)->same_flow = 0;
NAPI_GRO_CB(skb)->flush = 0;
NAPI_GRO_CB(skb)->free = 0;
NAPI_GRO_CB(skb)->udp_mark = 0;
NAPI_GRO_CB(skb)->gro_remcsum_start = 0;
switch (skb->ip_summed) {
case CHECKSUM_COMPLETE:
NAPI_GRO_CB(skb)->csum = skb->csum;
NAPI_GRO_CB(skb)->csum_valid = 1;
NAPI_GRO_CB(skb)->csum_cnt = 0;
break;
case CHECKSUM_UNNECESSARY:
NAPI_GRO_CB(skb)->csum_cnt = skb->csum_level + 1;
NAPI_GRO_CB(skb)->csum_valid = 0;
break;
default:
NAPI_GRO_CB(skb)->csum_cnt = 0;
NAPI_GRO_CB(skb)->csum_valid = 0;
}
pp = ptype->callbacks.gro_receive(&napi->gro_list, skb);
break;
}
rcu_read_unlock();
if (&ptype->list == head)
goto normal;
same_flow = NAPI_GRO_CB(skb)->same_flow;
ret = NAPI_GRO_CB(skb)->free ? GRO_MERGED_FREE : GRO_MERGED;
if (pp) {
struct sk_buff *nskb = *pp;
*pp = nskb->next;
nskb->next = NULL;
napi_gro_complete(nskb);
napi->gro_count--;
}
if (same_flow)
goto ok;
if (NAPI_GRO_CB(skb)->flush)
goto normal;
if (unlikely(napi->gro_count >= MAX_GRO_SKBS)) {
struct sk_buff *nskb = napi->gro_list;
while (nskb->next) {
pp = &nskb->next;
nskb = *pp;
}
*pp = NULL;
nskb->next = NULL;
napi_gro_complete(nskb);
} else {
napi->gro_count++;
}
NAPI_GRO_CB(skb)->count = 1;
NAPI_GRO_CB(skb)->age = jiffies;
NAPI_GRO_CB(skb)->last = skb;
skb_shinfo(skb)->gso_size = skb_gro_len(skb);
skb->next = napi->gro_list;
napi->gro_list = skb;
ret = GRO_HELD;
pull:
grow = skb_gro_offset(skb) - skb_headlen(skb);
if (grow > 0)
gro_pull_from_frag0(skb, grow);
ok:
return ret;
normal:
ret = GRO_NORMAL;
goto pull;,1

static void *set_eth_seg(struct mlx5_wqe_eth_seg *eseg,
const struct ib_send_wr *wr, void *qend,
struct mlx5_ib_qp *qp, int *size)
{
void *seg = eseg;
memset(eseg, 0, sizeof(struct mlx5_wqe_eth_seg));
if (wr->send_flags & IB_SEND_IP_CSUM)
eseg->cs_flags = MLX5_ETH_WQE_L3_CSUM |
MLX5_ETH_WQE_L4_CSUM;
seg += sizeof(struct mlx5_wqe_eth_seg);
*size += sizeof(struct mlx5_wqe_eth_seg) / 16;
if (wr->opcode == IB_WR_LSO) {
struct ib_ud_wr *ud_wr = container_of(wr, struct ib_ud_wr, wr);
int size_of_inl_hdr_start = sizeof(eseg->inline_hdr.start);
u64 left, leftlen, copysz;
void *pdata = ud_wr->header;
left = ud_wr->hlen;
eseg->mss = cpu_to_be16(ud_wr->mss);
eseg->inline_hdr.sz = cpu_to_be16(left);
leftlen = qend - (void *)eseg->inline_hdr.start;
copysz = min_t(u64, leftlen, left);
memcpy(seg - size_of_inl_hdr_start, pdata, copysz);
if (likely(copysz > size_of_inl_hdr_start)) {
seg += ALIGN(copysz - size_of_inl_hdr_start, 16);
*size += ALIGN(copysz - size_of_inl_hdr_start, 16) / 16;
}
if (unlikely(copysz < left)) {
seg = mlx5_get_send_wqe(qp, 0);
left -= copysz;
pdata += copysz;
memcpy(seg, pdata, left);
seg += ALIGN(left, 16);
*size += ALIGN(left, 16) / 16;
}
}
return seg;
},0

jas_image_t *jp2_decode(jas_stream_t *in, const char *optstr)
{
jp2_box_t *box;
int found;
jas_image_t *image;
jp2_dec_t *dec;
bool samedtype;
int dtype;
unsigned int i;
jp2_cmap_t *cmapd;
jp2_pclr_t *pclrd;
jp2_cdef_t *cdefd;
unsigned int channo;
int newcmptno;
int_fast32_t *lutents;
#if 0
jp2_cdefchan_t *cdefent;
int cmptno;
#endif
jp2_cmapent_t *cmapent;
jas_icchdr_t icchdr;
jas_iccprof_t *iccprof;
dec = 0;
box = 0;
image = 0;
JAS_DBGLOG(100, ("jp2_decode(%p, \"%s\")\n", in, optstr));
if (!(dec = jp2_dec_create())) {
goto error;
}
if (!(box = jp2_box_get(in))) {
jas_eprintf("error: cannot get box\n");
goto error;
}
if (box->type != JP2_BOX_JP) {
jas_eprintf("error: expecting signature box\n");
goto error;
}
if (box->data.jp.magic != JP2_JP_MAGIC) {
jas_eprintf("incorrect magic number\n");
goto error;
}
jp2_box_destroy(box);
box = 0;
if (!(box = jp2_box_get(in))) {
goto error;
}
if (box->type != JP2_BOX_FTYP) {
jas_eprintf("expecting file type box\n");
goto error;
}
jp2_box_destroy(box);
box = 0;
found = 0;
while ((box = jp2_box_get(in))) {
if (jas_getdbglevel() >= 1) {
jas_eprintf("got box type %s\n", box->info->name);
}
switch (box->type) {
case JP2_BOX_JP2C:
found = 1;
break;
case JP2_BOX_IHDR:
if (!dec->ihdr) {
dec->ihdr = box;
box = 0;
}
break;
case JP2_BOX_BPCC:
if (!dec->bpcc) {
dec->bpcc = box;
box = 0;
}
break;
case JP2_BOX_CDEF:
if (!dec->cdef) {
dec->cdef = box;
box = 0;
}
break;
case JP2_BOX_PCLR:
if (!dec->pclr) {
dec->pclr = box;
box = 0;
}
break;
case JP2_BOX_CMAP:
if (!dec->cmap) {
dec->cmap = box;
box = 0;
}
break;
case JP2_BOX_COLR:
if (!dec->colr) {
dec->colr = box;
box = 0;
}
break;
}
if (box) {
jp2_box_destroy(box);
box = 0;
}
if (found) {
break;
}
}
if (!found) {
jas_eprintf("error: no code stream found\n");
goto error;
}
if (!(dec->image = jpc_decode(in, optstr))) {
jas_eprintf("error: cannot decode code stream\n");
goto error;
}
if (!dec->ihdr) {
jas_eprintf("error: missing IHDR box\n");
goto error;
}
if (dec->ihdr->data.ihdr.numcmpts != JAS_CAST(jas_uint,
jas_image_numcmpts(dec->image))) {
jas_eprintf("error: number of components mismatch (IHDR)\n");
goto error;
}
if (!jas_image_numcmpts(dec->image)) {
jas_eprintf("error: no components\n");
goto error;
}
samedtype = true;
dtype = jas_image_cmptdtype(dec->image, 0);
for (i = 1; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image)); ++i) {
if (jas_image_cmptdtype(dec->image, i) != dtype) {
samedtype = false;
break;
}
}
if ((samedtype && dec->ihdr->data.ihdr.bpc != JP2_DTYPETOBPC(dtype)) ||
(!samedtype && dec->ihdr->data.ihdr.bpc != JP2_IHDR_BPCNULL)) {
jas_eprintf("error: component data type mismatch (IHDR)\n");
goto error;
}
if (dec->ihdr->data.ihdr.comptype != JP2_IHDR_COMPTYPE) {
jas_eprintf("error: unsupported compression type\n");
goto error;
}
if (dec->bpcc) {
if (dec->bpcc->data.bpcc.numcmpts !=
JAS_CAST(jas_uint, jas_image_numcmpts(dec->image))) {
jas_eprintf("error: number of components mismatch (BPCC)\n");
goto error;
}
if (!samedtype) {
for (i = 0; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image));
++i) {
if (jas_image_cmptdtype(dec->image, i) !=
JP2_BPCTODTYPE(dec->bpcc->data.bpcc.bpcs[i])) {
jas_eprintf("error: component data type mismatch (BPCC)\n");
goto error;
}
}
} else {
jas_eprintf("warning: superfluous BPCC box\n");
}
}
if (!dec->colr) {
jas_eprintf("error: no COLR box\n");
goto error;
}
switch (dec->colr->data.colr.method) {
case JP2_COLR_ENUM:
jas_image_setclrspc(dec->image, jp2_getcs(&dec->colr->data.colr));
break;
case JP2_COLR_ICC:
iccprof = jas_iccprof_createfrombuf(dec->colr->data.colr.iccp,
dec->colr->data.colr.iccplen);
if (!iccprof) {
jas_eprintf("error: failed to parse ICC profile\n");
goto error;
}
jas_iccprof_gethdr(iccprof, &icchdr);
jas_eprintf("ICC Profile CS %08x\n", icchdr.colorspc);
jas_image_setclrspc(dec->image, fromiccpcs(icchdr.colorspc));
dec->image->cmprof_ = jas_cmprof_createfromiccprof(iccprof);
if (!dec->image->cmprof_) {
jas_iccprof_destroy(iccprof);
goto error;
}
jas_iccprof_destroy(iccprof);
break;
}
if (dec->cmap && !dec->pclr) {
jas_eprintf("warning: missing PCLR box or superfluous CMAP box\n");
jp2_box_destroy(dec->cmap);
dec->cmap = 0;
}
if (!dec->cmap && dec->pclr) {
jas_eprintf("warning: missing CMAP box or superfluous PCLR box\n");
jp2_box_destroy(dec->pclr);
dec->pclr = 0;
}
dec->numchans = dec->cmap ? dec->cmap->data.cmap.numchans :
JAS_CAST(jas_uint, jas_image_numcmpts(dec->image));
if (dec->cmap) {
for (i = 0; i < dec->numchans; ++i) {
if (dec->cmap->data.cmap.ents[i].cmptno >= JAS_CAST(jas_uint,
jas_image_numcmpts(dec->image))) {
jas_eprintf("error: invalid component number in CMAP box\n");
goto error;
}
if (dec->cmap->data.cmap.ents[i].pcol >=
dec->pclr->data.pclr.numchans) {
jas_eprintf("error: invalid CMAP LUT index\n");
goto error;
}
}
}
if (!(dec->chantocmptlut = jas_alloc2(dec->numchans,
sizeof(uint_fast16_t)))) {
jas_eprintf("error: no memory\n");
goto error;
}
if (!dec->cmap) {
for (i = 0; i < dec->numchans; ++i) {
dec->chantocmptlut[i] = i;
}
} else {
cmapd = &dec->cmap->data.cmap;
pclrd = &dec->pclr->data.pclr;
cdefd = &dec->cdef->data.cdef;
for (channo = 0; channo < cmapd->numchans; ++channo) {
cmapent = &cmapd->ents[channo];
if (cmapent->map == JP2_CMAP_DIRECT) {
dec->chantocmptlut[channo] = channo;
} else if (cmapent->map == JP2_CMAP_PALETTE) {
if (!pclrd->numlutents) {
goto error;
}
lutents = jas_alloc2(pclrd->numlutents, sizeof(int_fast32_t));
if (!lutents) {
goto error;
}
for (i = 0; i < pclrd->numlutents; ++i) {
lutents[i] = pclrd->lutdata[cmapent->pcol + i * pclrd->numchans];
}
newcmptno = jas_image_numcmpts(dec->image);
jas_image_depalettize(dec->image, cmapent->cmptno,
pclrd->numlutents, lutents,
JP2_BPCTODTYPE(pclrd->bpc[cmapent->pcol]), newcmptno);
dec->chantocmptlut[channo] = newcmptno;
jas_free(lutents);
#if 0
if (dec->cdef) {
cdefent = jp2_cdef_lookup(cdefd, channo);
if (!cdefent) {
abort();
}
jas_image_setcmpttype(dec->image, newcmptno, jp2_getct(jas_image_clrspc(dec->image), cdefent->type, cdefent->assoc));
} else {
jas_image_setcmpttype(dec->image, newcmptno, jp2_getct(jas_image_clrspc(dec->image), 0, channo + 1));
}
#else
(void)cdefd;
#endif
} else {
jas_eprintf("error: invalid MTYP in CMAP box\n");
goto error;
}
}
}
if (dec->numchans != jas_image_numcmpts(dec->image)) {
jas_eprintf("error: mismatch in number of components (%d != %d)\n",
dec->numchans, jas_image_numcmpts(dec->image));
goto error;
}
for (i = 0; i < JAS_CAST(jas_uint, jas_image_numcmpts(dec->image)); ++i) {
