if (cmd.findOption("--key", 0, OFCommandLine::FOM_First))
{
const char *ovKey = NULL;
do {
app.checkValue(cmd.getValue(ovKey));
addOverrideKey(app, ovKey);
} while (cmd.findOption("--key", 0, OFCommandLine::FOM_Next));
}
cmd.beginOptionBlock();
