lp->l2_proto = ISDN_PROTO_L2_X75I;
lp->l3_proto = ISDN_PROTO_L3_TRANS;
lp->triggercps = 6000;
lp->slavedelay = 10 * HZ;
lp->hupflags = ISDN_INHUP;
lp->onhtime = 10;
lp->dialmax = 1;
lp->flags = ISDN_NET_CBHUP | ISDN_NET_DM_MANUAL;
lp->cbdelay = 25;
lp->dialtimeout = -1;
lp->dialwait = 5 * HZ;
lp->dialstarted = 0;
lp->dialwait_timer = 0;
