goto failed;
}
}
if (!asn1_end_tag(data)) {
goto failed;
}
if (!asn1_end_tag(data)) {
goto failed;
}
break;
}
case 5: {
const char *attrib;
DATA_BLOB value;
asn1_start_tag(data, ASN1_CONTEXT(filter_tag));
asn1_read_OctetString_talloc(mem_ctx, data, &attrib);
asn1_read_OctetString(data, mem_ctx, &value);
asn1_end_tag(data);
if ((data->has_error) || (attrib == NULL) || (value.data == NULL)) {
goto failed;
