struct psi_trigger *psi_trigger_create(struct psi_group *group,
char *buf, size_t nbytes, enum psi_res res)
{
struct psi_trigger *t;
enum psi_states state;
u32 threshold_us;
u32 window_us;
if (static_branch_likely(&psi_disabled))
return ERR_PTR(-EOPNOTSUPP);
if (sscanf(buf, "some %u %u", &threshold_us, &window_us) == 2)
state = PSI_IO_SOME + res * 2;
else if (sscanf(buf, "full %u %u", &threshold_us, &window_us) == 2)
state = PSI_IO_FULL + res * 2;
else
return ERR_PTR(-EINVAL);
if (state >= PSI_NONIDLE)
return ERR_PTR(-EINVAL);
if (window_us < WINDOW_MIN_US ||
window_us > WINDOW_MAX_US)
return ERR_PTR(-EINVAL);
if (threshold_us == 0 || threshold_us > window_us)
return ERR_PTR(-EINVAL);
t = kmalloc(sizeof(*t), GFP_KERNEL);
if (!t)
return ERR_PTR(-ENOMEM);
t->group = group;
t->state = state;
t->threshold = threshold_us * NSEC_PER_USEC;
t->win.size = window_us * NSEC_PER_USEC;
window_reset(&t->win, 0, 0, 0);
t->event = 0;
t->last_event_time = 0;
init_waitqueue_head(&t->event_wait);
kref_init(&t->refcount);
mutex_lock(&group->trigger_lock);
if (!rcu_access_pointer(group->poll_task)) {
struct task_struct *task;
task = kthread_create(psi_poll_worker, group, "psimon");
if (IS_ERR(task)) {
kfree(t);
mutex_unlock(&group->trigger_lock);
return ERR_CAST(task);
}
atomic_set(&group->poll_wakeup, 0);
wake_up_process(task);
rcu_assign_pointer(group->poll_task, task);
}
list_add(&t->node, &group->triggers);
group->poll_min_period = min(group->poll_min_period,
div_u64(t->win.size, UPDATES_PER_WINDOW));
group->nr_triggers[t->state]++;
group->poll_states |= (1 << t->state);
mutex_unlock(&group->trigger_lock);
return t;
},1

static int ipa_extdom_extop(Slapi_PBlock *pb)
{
char *oid = NULL;
char *err_msg = NULL;
int rc;
int ret;
struct berval *req_val = NULL;
struct berval *ret_val = NULL;
struct extdom_req *req = NULL;
struct ipa_extdom_ctx *ctx;
enum extdom_version version;
ret = slapi_pblock_get(pb, SLAPI_EXT_OP_REQ_OID, &oid);
if (ret != 0) {
rc = LDAP_OPERATIONS_ERROR;
err_msg = "Could not get OID value from request.\n";
goto done;
}
LOG("Received extended operation request with OID %s\n", oid);
if (strcasecmp(oid, EXOP_EXTDOM_OID) == 0) {
version = EXTDOM_V0;
} else if (strcasecmp(oid, EXOP_EXTDOM_V1_OID) == 0) {
version = EXTDOM_V1;
} else {
return SLAPI_PLUGIN_EXTENDED_NOT_HANDLED;
}
ret = slapi_pblock_get(pb, SLAPI_EXT_OP_REQ_VALUE, &req_val);
if (ret != 0) {
rc = LDAP_UNWILLING_TO_PERFORM;
err_msg = "Missing request data.\n";
goto done;
}
ret = slapi_pblock_get(pb, SLAPI_PLUGIN_PRIVATE, &ctx);
if (ret != 0) {
rc = LDAP_OPERATIONS_ERROR;
err_msg = "Missing plugin context.\n";
goto done;
}
ret = parse_request_data(req_val, &req);
if (ret != LDAP_SUCCESS) {
rc = LDAP_UNWILLING_TO_PERFORM;
err_msg = "Cannot parse request data.\n";
goto done;
}
ret = check_request(req, version);
if (ret != LDAP_SUCCESS) {
rc = LDAP_UNWILLING_TO_PERFORM;
err_msg = "Error in request data.\n";
goto done;
}
ret = handle_request(ctx, req, &ret_val);
if (ret != LDAP_SUCCESS) {
rc = LDAP_OPERATIONS_ERROR;
err_msg = "Failed to handle the request.\n";
goto done;
}
ret = slapi_pblock_set(pb, SLAPI_EXT_OP_RET_OID, oid);
if (ret != 0) {
rc = LDAP_OPERATIONS_ERROR;
err_msg = "Failed to set the OID for the response.\n";
goto done;
}
ret = slapi_pblock_set( pb, SLAPI_EXT_OP_RET_VALUE, ret_val);
if (ret != 0) {
rc = LDAP_OPERATIONS_ERROR;
err_msg = "Failed to set the value for the response.\n";
goto done;
}
rc = LDAP_SUCCESS;
done:
free_req_data(req);
if (err_msg != NULL) {
LOG("%s", err_msg);
}
slapi_send_ldap_result(pb, rc, NULL, err_msg, 0, NULL);
return SLAPI_PLUGIN_EXTENDED_SENT_RESULT;
},0

TfLiteStatus PopulatePrecomputedZPTimesWeightsWithBias(TfLiteContext* context,
OpData* op_data,
TfLiteNode* node) {
const TfLiteTensor* input = GetInput(context, node, kInputTensor);
const TfLiteTensor* output_state =
GetVariableInput(context, node, kOutputStateTensor);
TF_LITE_ENSURE(context, output_state != nullptr);
const int32_t input_zero_point = -input->params.zero_point;
const int32_t output_state_zero_point = -output_state->params.zero_point;
const TfLiteTensor* input_to_input_weights =
GetOptionalInputTensor(context, node, kInputToInputWeightsTensor);
const TfLiteTensor* input_to_forget_weights =
GetInput(context, node, kInputToForgetWeightsTensor);
const TfLiteTensor* input_to_cell_weights =
GetInput(context, node, kInputToCellWeightsTensor);
const TfLiteTensor* input_to_output_weights =
GetInput(context, node, kInputToOutputWeightsTensor);
const TfLiteTensor* recurrent_to_input_weights =
GetOptionalInputTensor(context, node, kRecurrentToInputWeightsTensor);
const TfLiteTensor* recurrent_to_forget_weights =
GetInput(context, node, kRecurrentToForgetWeightsTensor);
const TfLiteTensor* recurrent_to_cell_weights =
GetInput(context, node, kRecurrentToCellWeightsTensor);
const TfLiteTensor* recurrent_to_output_weights =
GetInput(context, node, kRecurrentToOutputWeightsTensor);
const TfLiteTensor* projection_weights =
GetOptionalInputTensor(context, node, kProjectionWeightsTensor);
const TfLiteTensor* projection_bias =
GetOptionalInputTensor(context, node, kProjectionBiasTensor);
lstm_eval::IntegerLstmParameter* integer_lstm_params =
&op_data->integer_lstm_param;
const TfLiteTensor* intermediate =
&context->tensors[node->intermediates->data[4]];
const auto* params =
static_cast<TfLiteAffineQuantization*>(intermediate->quantization.params);
const int32_t hidden_zp = params->zero_point->data[0];
const bool is_layer_norm = op_data->use_layer_norm;
const TfLiteTensor* forget_gate_bias =
is_layer_norm ? nullptr : GetInput(context, node, kForgetGateBiasTensor);
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, input_zero_point, input_to_forget_weights, forget_gate_bias,
&(integer_lstm_params->input_to_forget_effective_bias)));
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, output_state_zero_point, recurrent_to_forget_weights,
nullptr, &(integer_lstm_params->recurrent_to_forget_effective_bias)));
const TfLiteTensor* cell_gate_bias =
is_layer_norm ? nullptr : GetInput(context, node, kCellGateBiasTensor);
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, input_zero_point, input_to_cell_weights, cell_gate_bias,
&(integer_lstm_params->input_to_cell_effective_bias)));
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, output_state_zero_point, recurrent_to_cell_weights, nullptr,
&(integer_lstm_params->recurrent_to_cell_effective_bias)));
const TfLiteTensor* output_gate_bias =
is_layer_norm ? nullptr : GetInput(context, node, kOutputGateBiasTensor);
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, input_zero_point, input_to_output_weights, output_gate_bias,
&(integer_lstm_params->input_to_output_effective_bias)));
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, output_state_zero_point, recurrent_to_output_weights,
nullptr, &(integer_lstm_params->recurrent_to_output_effective_bias)));
const TfLiteTensor* input_gate_bias =
is_layer_norm ? nullptr : GetInput(context, node, kInputGateBiasTensor);
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, input_zero_point, input_to_input_weights, input_gate_bias,
&(integer_lstm_params->input_to_input_effective_bias)));
TF_LITE_ENSURE_OK(
context,
PrecomputeZeroPointTimesWeightWithBias(
context, output_state_zero_point, recurrent_to_input_weights, nullptr,
&(integer_lstm_params->recurrent_to_input_effective_bias)));
TF_LITE_ENSURE_OK(context,
PrecomputeZeroPointTimesWeightWithBias(
context, hidden_zp, projection_weights, projection_bias,
&(integer_lstm_params->projection_effective_bias)));
return kTfLiteOk;
},1

parse_capabilities(FILE * fp, char *name)
{
int type;
char token[MAXTOKEN];
char quoted_string_buffer[MAXQUOTESTR];
struct node *np;
np = alloc_node(current_module);
if (np == NULL)
return (NULL);
type = get_token(fp, token, MAXTOKEN);
if (type != PRODREL) {
print_error("Expected PRODUCT-RELEASE", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Expected STRING after PRODUCT-RELEASE", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != STATUS) {
print_error("Expected STATUS", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != CURRENT && type != OBSOLETE) {
print_error("STATUS should be current or obsolete", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != DESCRIPTION) {
print_error("Expected DESCRIPTION", token, type);
goto skip;
}
type = get_token(fp, quoted_string_buffer, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Bad DESCRIPTION", quoted_string_buffer, type);
goto skip;
}
if (netsnmp_ds_get_boolean(NETSNMP_DS_LIBRARY_ID,
NETSNMP_DS_LIB_SAVE_MIB_DESCRS)) {
np->description = strdup(quoted_string_buffer);
}
type = get_token(fp, token, MAXTOKEN);
if (type == REFERENCE) {
type = get_token(fp, quoted_string_buffer, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Bad REFERENCE", quoted_string_buffer, type);
goto skip;
}
np->reference = strdup(quoted_string_buffer);
type = get_token(fp, token, type);
}
while (type == SUPPORTS) {
int modid;
struct tree *tp;
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad module name", token, type);
goto skip;
}
modid = read_module_internal(token);
if (modid != MODULE_LOADED_OK && modid != MODULE_ALREADY_LOADED) {
print_error("Module not found", token, type);
goto skip;
}
modid = which_module(token);
type = get_token(fp, token, MAXTOKEN);
if (type != INCLUDES) {
print_error("Expected INCLUDES", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != LEFTBRACKET) {
print_error("Expected \"{\"", token, type);
goto skip;
}
do {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Expected group name", token, type);
goto skip;
}
tp = find_tree_node(token, modid);
if (!tp)
print_error("Group not found in module", token, type);
type = get_token(fp, token, MAXTOKEN);
} while (type == COMMA);
if (type != RIGHTBRACKET) {
print_error("Expected \"}\" after group list", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
while (type == VARIATION) {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad object name", token, type);
goto skip;
}
tp = find_tree_node(token, modid);
if (!tp)
print_error("Object not found in module", token, type);
type = get_token(fp, token, MAXTOKEN);
if (type == SYNTAX) {
type = eat_syntax(fp, token, MAXTOKEN);
}
if (type == WRSYNTAX) {
type = eat_syntax(fp, token, MAXTOKEN);
}
if (type == ACCESS) {
type = get_token(fp, token, MAXTOKEN);
if (type != ACCNOTIFY && type != READONLY
&& type != READWRITE && type != READCREATE
&& type != WRITEONLY && type != NOTIMPL) {
print_error("Bad ACCESS", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
if (type == CREATEREQ) {
type = get_token(fp, token, MAXTOKEN);
if (type != LEFTBRACKET) {
print_error("Expected \"{\"", token, type);
goto skip;
}
do {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad object name in list", token,
type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
} while (type == COMMA);
if (type != RIGHTBRACKET) {
print_error("Expected \"}\" after list", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
if (type == DEFVAL) {
int level = 1;
type = get_token(fp, token, MAXTOKEN);
if (type != LEFTBRACKET) {
print_error("Expected \"{\" after DEFVAL", token,
type);
goto skip;
}
do {
type = get_token(fp, token, MAXTOKEN);
if (type == LEFTBRACKET)
level++;
else if (type == RIGHTBRACKET)
level--;
} while ((type != RIGHTBRACKET || level != 0)
&& type != ENDOFFILE);
if (type != RIGHTBRACKET) {
print_error("Missing \"}\" after DEFVAL", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
if (type != DESCRIPTION) {
print_error("Expected DESCRIPTION", token, type);
goto skip;
}
type = get_token(fp, quoted_string_buffer, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Bad DESCRIPTION", quoted_string_buffer, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
}
if (type != EQUALS)
print_error("Expected \"::=\"", token, type);
skip:
while (type != EQUALS && type != ENDOFFILE) {
type = get_token(fp, quoted_string_buffer, MAXQUOTESTR);
}
return merge_parse_objectid(np, fp, name);
},0

static int __io_getxattr_prep(struct io_kiocb *req,
const struct io_uring_sqe *sqe)
{
struct io_xattr *ix = &req->xattr;
const char __user *name;
int ret;
if (unlikely(req->flags & REQ_F_FIXED_FILE))
return -EBADF;
ix->filename = NULL;
ix->ctx.kvalue = NULL;
name = u64_to_user_ptr(READ_ONCE(sqe->addr));
ix->ctx.cvalue = u64_to_user_ptr(READ_ONCE(sqe->addr2));
ix->ctx.size = READ_ONCE(sqe->len);
ix->ctx.flags = READ_ONCE(sqe->xattr_flags);
if (ix->ctx.flags)
return -EINVAL;
ix->ctx.kname = kmalloc(sizeof(*ix->ctx.kname), GFP_KERNEL);
if (!ix->ctx.kname)
return -ENOMEM;
ret = strncpy_from_user(ix->ctx.kname->name, name,
sizeof(ix->ctx.kname->name));
if (!ret || ret == sizeof(ix->ctx.kname->name))
ret = -ERANGE;
if (ret < 0) {
kfree(ix->ctx.kname);
return ret;
}
req->flags |= REQ_F_NEED_CLEANUP;
return 0;
},0

