static noinline int run_delalloc_nocow(struct inode *inode,
struct page *locked_page,
u64 start, u64 end, int *page_started, int force,
unsigned long *nr_written)
{
struct btrfs_root *root = BTRFS_I(inode)->root;
struct btrfs_trans_handle *trans;
struct extent_buffer *leaf;
struct btrfs_path *path;
struct btrfs_file_extent_item *fi;
struct btrfs_key found_key;
u64 cow_start;
u64 cur_offset;
u64 extent_end;
u64 extent_offset;
u64 disk_bytenr;
u64 num_bytes;
u64 disk_num_bytes;
u64 ram_bytes;
int extent_type;
int ret, err;
int type;
int nocow;
int check_prev = 1;
bool nolock;
u64 ino = btrfs_ino(inode);
path = btrfs_alloc_path();
if (!path) {
extent_clear_unlock_delalloc(inode, start, end, locked_page,
EXTENT_LOCKED | EXTENT_DELALLOC |
EXTENT_DO_ACCOUNTING |
EXTENT_DEFRAG, PAGE_UNLOCK |
PAGE_CLEAR_DIRTY |
PAGE_SET_WRITEBACK |
PAGE_END_WRITEBACK);
return -ENOMEM;
}
nolock = btrfs_is_free_space_inode(inode);
if (nolock)
trans = btrfs_join_transaction_nolock(root);
else
trans = btrfs_join_transaction(root);
if (IS_ERR(trans)) {
extent_clear_unlock_delalloc(inode, start, end, locked_page,
EXTENT_LOCKED | EXTENT_DELALLOC |
EXTENT_DO_ACCOUNTING |
EXTENT_DEFRAG, PAGE_UNLOCK |
PAGE_CLEAR_DIRTY |
PAGE_SET_WRITEBACK |
PAGE_END_WRITEBACK);
btrfs_free_path(path);
return PTR_ERR(trans);
}
trans->block_rsv = &root->fs_info->delalloc_block_rsv;
cow_start = (u64)-1;
cur_offset = start;
while (1) {
ret = btrfs_lookup_file_extent(trans, root, path, ino,
cur_offset, 0);
if (ret < 0)
goto error;
if (ret > 0 && path->slots[0] > 0 && check_prev) {
leaf = path->nodes[0];
btrfs_item_key_to_cpu(leaf, &found_key,
path->slots[0] - 1);
if (found_key.objectid == ino &&
found_key.type == BTRFS_EXTENT_DATA_KEY)
path->slots[0]--;
}
check_prev = 0;
next_slot:
leaf = path->nodes[0];
if (path->slots[0] >= btrfs_header_nritems(leaf)) {
ret = btrfs_next_leaf(root, path);
if (ret < 0)
goto error;
if (ret > 0)
break;
leaf = path->nodes[0];
}
nocow = 0;
disk_bytenr = 0;
num_bytes = 0;
btrfs_item_key_to_cpu(leaf, &found_key, path->slots[0]);
if (found_key.objectid > ino ||
found_key.type > BTRFS_EXTENT_DATA_KEY ||
found_key.offset > end)
break;
if (found_key.offset > cur_offset) {
extent_end = found_key.offset;
extent_type = 0;
goto out_check;
}
fi = btrfs_item_ptr(leaf, path->slots[0],
struct btrfs_file_extent_item);
extent_type = btrfs_file_extent_type(leaf, fi);
ram_bytes = btrfs_file_extent_ram_bytes(leaf, fi);
if (extent_type == BTRFS_FILE_EXTENT_REG ||
extent_type == BTRFS_FILE_EXTENT_PREALLOC) {
disk_bytenr = btrfs_file_extent_disk_bytenr(leaf, fi);
extent_offset = btrfs_file_extent_offset(leaf, fi);
extent_end = found_key.offset +
btrfs_file_extent_num_bytes(leaf, fi);
disk_num_bytes =
btrfs_file_extent_disk_num_bytes(leaf, fi);
if (extent_end <= start) {
path->slots[0]++;
goto next_slot;
}
if (disk_bytenr == 0)
goto out_check;
if (btrfs_file_extent_compression(leaf, fi) ||
btrfs_file_extent_encryption(leaf, fi) ||
btrfs_file_extent_other_encoding(leaf, fi))
goto out_check;
if (extent_type == BTRFS_FILE_EXTENT_REG && !force)
goto out_check;
if (btrfs_extent_readonly(root, disk_bytenr))
goto out_check;
if (btrfs_cross_ref_exist(trans, root, ino,
found_key.offset -
extent_offset, disk_bytenr))
goto out_check;
disk_bytenr += extent_offset;
disk_bytenr += cur_offset - found_key.offset;
num_bytes = min(end + 1, extent_end) - cur_offset;
if (!nolock) {
err = btrfs_start_write_no_snapshoting(root);
if (!err)
goto out_check;
}
if (csum_exist_in_range(root, disk_bytenr, num_bytes))
goto out_check;
nocow = 1;
} else if (extent_type == BTRFS_FILE_EXTENT_INLINE) {
extent_end = found_key.offset +
btrfs_file_extent_inline_len(leaf,
path->slots[0], fi);
extent_end = ALIGN(extent_end, root->sectorsize);
} else {
BUG_ON(1);
}
out_check:
if (extent_end <= start) {
path->slots[0]++;
if (!nolock && nocow)
btrfs_end_write_no_snapshoting(root);
goto next_slot;
}
if (!nocow) {
if (cow_start == (u64)-1)
cow_start = cur_offset;
cur_offset = extent_end;
if (cur_offset > end)
break;
path->slots[0]++;
goto next_slot;
}
btrfs_release_path(path);
if (cow_start != (u64)-1) {
ret = cow_file_range(inode, locked_page,
cow_start, found_key.offset - 1,
page_started, nr_written, 1);
if (ret) {
if (!nolock && nocow)
btrfs_end_write_no_snapshoting(root);
goto error;
}
cow_start = (u64)-1;
}
if (extent_type == BTRFS_FILE_EXTENT_PREALLOC) {
struct extent_map *em;
struct extent_map_tree *em_tree;
em_tree = &BTRFS_I(inode)->extent_tree;
em = alloc_extent_map();
BUG_ON(!em);
em->start = cur_offset;
em->orig_start = found_key.offset - extent_offset;
em->len = num_bytes;
em->block_len = num_bytes;
em->block_start = disk_bytenr;
em->orig_block_len = disk_num_bytes;
em->ram_bytes = ram_bytes;
em->bdev = root->fs_info->fs_devices->latest_bdev;
em->mod_start = em->start;
em->mod_len = em->len;
set_bit(EXTENT_FLAG_PINNED, &em->flags);
set_bit(EXTENT_FLAG_FILLING, &em->flags);
em->generation = -1;
while (1) {
write_lock(&em_tree->lock);
ret = add_extent_mapping(em_tree, em, 1);
write_unlock(&em_tree->lock);
if (ret != -EEXIST) {
free_extent_map(em);
break;
}
btrfs_drop_extent_cache(inode, em->start,
em->start + em->len - 1, 0);
}
type = BTRFS_ORDERED_PREALLOC;
} else {
type = BTRFS_ORDERED_NOCOW;
}
ret = btrfs_add_ordered_extent(inode, cur_offset, disk_bytenr,
num_bytes, num_bytes, type);
BUG_ON(ret);
if (root->root_key.objectid ==
BTRFS_DATA_RELOC_TREE_OBJECTID) {
ret = btrfs_reloc_clone_csums(inode, cur_offset,
num_bytes);
if (ret) {
if (!nolock && nocow)
btrfs_end_write_no_snapshoting(root);
goto error;
}
}
extent_clear_unlock_delalloc(inode, cur_offset,
cur_offset + num_bytes - 1,
locked_page, EXTENT_LOCKED |
EXTENT_DELALLOC, PAGE_UNLOCK |
PAGE_SET_PRIVATE2);
if (!nolock && nocow)
btrfs_end_write_no_snapshoting(root);
cur_offset = extent_end;
if (cur_offset > end)
break;
}
btrfs_release_path(path);
if (cur_offset <= end && cow_start == (u64)-1) {
cow_start = cur_offset;
cur_offset = end;
}
if (cow_start != (u64)-1) {
ret = cow_file_range(inode, locked_page, cow_start, end,
page_started, nr_written, 1);
if (ret)
goto error;
}
error:
err = btrfs_end_transaction(trans, root);
if (!ret)
ret = err;
if (ret && cur_offset < end)
extent_clear_unlock_delalloc(inode, cur_offset, end,
locked_page, EXTENT_LOCKED |
EXTENT_DELALLOC | EXTENT_DEFRAG |
EXTENT_DO_ACCOUNTING, PAGE_UNLOCK |
PAGE_CLEAR_DIRTY |
PAGE_SET_WRITEBACK |
PAGE_END_WRITEBACK);
btrfs_free_path(path);
return ret;
},0

int process_zipfiles(__G)
__GDEF
{
#ifndef SFX
char *lastzipfn = (char *)NULL;
int NumWinFiles, NumLoseFiles, NumWarnFiles;
int NumMissDirs, NumMissFiles;
#endif
int error=0, error_in_archive=0;
G.inbuf = (uch *)malloc(INBUFSIZ + 4);
G.outbuf = (uch *)malloc(OUTBUFSIZ + 1);
if ((G.inbuf == (uch *)NULL) || (G.outbuf == (uch *)NULL)) {
Info(slide, 0x401, ((char *)slide,
LoadFarString(CannotAllocateBuffers)));
return(PK_MEM);
}
G.hold = G.inbuf + INBUFSIZ;
#ifndef VMS
#ifdef SMALL_MEM
G.outbuf2 = G.outbuf+RAWBUFSIZ;
#endif
#endif
#if 0
CRC_32_TAB = NULL;
#endif
local_hdr_sig[0] =
central_hdr_sig[0] = end_central_sig[0] =
end_centloc64_sig[0] = end_central64_sig[0] = 0x50;
local_hdr_sig[1] =
central_hdr_sig[1] = end_central_sig[1] =
end_centloc64_sig[1] = end_central64_sig[1] = 0x4B;
#if (defined(WIN32) && defined(USE_EF_UT_TIME))
iz_w32_prepareTZenv();
#endif
#if (defined(IZ_CHECK_TZ) && defined(USE_EF_UT_TIME))
# ifndef VALID_TIMEZONE
# define VALID_TIMEZONE(tmp) \
(((tmp = getenv("TZ")) != NULL) && (*tmp != '\0'))
# endif
{
char *p;
G.tz_is_valid = VALID_TIMEZONE(p);
# ifndef SFX
if (!G.tz_is_valid) {
Info(slide, 0x401, ((char *)slide, LoadFarString(WarnInvalidTZ)));
error_in_archive = error = PK_WARN;
}
# endif
}
#endif
#if (!defined(T20_VMS) && !defined(MACOS) && !defined(RISCOS) && !defined(QDOS))
#if (!defined(BSD) && !defined(MTS) && !defined(CMS_MVS) && !defined(TANDEM))
tzset();
#endif
#endif
#ifdef NEED_ISO_OEM_INIT
prepare_ISO_OEM_translat(__G);
#endif
G.overwrite_mode = (uO.overwrite_none ? OVERWRT_NEVER :
(uO.overwrite_all ? OVERWRT_ALWAYS : OVERWRT_QUERY));
#ifdef SFX
if ((error = do_seekable(__G__ 0)) == PK_NOZIP) {
#ifdef EXE_EXTENSION
int len=strlen(G.argv0);
if ( (G.zipfn = (char *)malloc(len+sizeof(EXE_EXTENSION))) !=
(char *)NULL ) {
strcpy(G.zipfn, G.argv0);
strcpy(G.zipfn+len, EXE_EXTENSION);
error = do_seekable(__G__ 0);
free(G.zipfn);
G.zipfn = G.argv0;
}
#endif
#ifdef WIN32
G.zipfn = G.argv0;
#endif
}
if (error) {
if (error == IZ_DIR)
error_in_archive = PK_NOZIP;
else
error_in_archive = error;
if (error == PK_NOZIP)
Info(slide, 1, ((char *)slide, LoadFarString(CannotFindMyself),
G.zipfn));
}
#ifdef CHEAP_SFX_AUTORUN
if (G.autorun_command[0] && !uO.qflag) {
Info(slide, 0x81, ((char *)slide, LoadFarString(AutorunPrompt),
FnFilter1(G.autorun_command)));
if (fgets(G.answerbuf, 9, stdin) != (char *)NULL
&& toupper(*G.answerbuf) == 'Y')
system(G.autorun_command);
else
Info(slide, 1, ((char *)slide, LoadFarString(NotAutoRunning)));
}
#endif
#else
NumWinFiles = NumLoseFiles = NumWarnFiles = 0;
NumMissDirs = NumMissFiles = 0;
while ((G.zipfn = do_wild(__G__ G.wildzipfn)) != (char *)NULL) {
Trace((stderr, "do_wild( %s ) returns %s\n", G.wildzipfn, G.zipfn));
lastzipfn = G.zipfn;
if (!uO.qflag && error != PK_NOZIP && error != IZ_DIR
#ifdef TIMESTAMP
&& (!uO.T_flag || uO.zipinfo_mode)
#endif
&& (NumWinFiles+NumLoseFiles+NumWarnFiles+NumMissFiles) > 0)
(*G.message)((zvoid *)&G, (uch *)"\n", 1L, 0);
if ((error = do_seekable(__G__ 0)) == PK_WARN)
++NumWarnFiles;
else if (error == IZ_DIR)
++NumMissDirs;
else if (error == PK_NOZIP)
++NumMissFiles;
else if (error != PK_OK)
++NumLoseFiles;
else
++NumWinFiles;
Trace((stderr, "do_seekable(0) returns %d\n", error));
if (error != IZ_DIR && error > error_in_archive)
error_in_archive = error;
#ifdef WINDLL
if (error == IZ_CTRLC) {
free_G_buffers(__G);
return error;
}
#endif
}
if ((NumWinFiles + NumWarnFiles + NumLoseFiles) == 0 &&
(NumMissDirs + NumMissFiles) == 1 && lastzipfn != (char *)NULL)
{
#if (!defined(UNIX) && !defined(AMIGA))
if (iswild(G.wildzipfn)) {
if (iswild(lastzipfn)) {
NumMissDirs = NumMissFiles = 0;
error_in_archive = PK_COOL;
if (uO.qflag < 3)
Info(slide, 0x401, ((char *)slide,
LoadFarString(CannotFindWildcardMatch),
LoadFarStringSmall((uO.zipinfo_mode ? Zipnfo : Unzip)),
G.wildzipfn));
}
} else
#endif
{
#ifndef VMS
#if defined(UNIX) || defined(QDOS)
char *p =
#endif
strcpy(lastzipfn + strlen(lastzipfn), ZSUFX);
#endif
G.zipfn = lastzipfn;
NumMissDirs = NumMissFiles = 0;
error_in_archive = PK_COOL;
#if defined(UNIX) || defined(QDOS)
if ((error = do_seekable(__G__ 0)) == PK_NOZIP || error == IZ_DIR) {
if (error == IZ_DIR)
++NumMissDirs;
strcpy(p, ALT_ZSUFX);
error = do_seekable(__G__ 1);
}
#else
error = do_seekable(__G__ 1);
#endif
Trace((stderr, "do_seekable(1) returns %d\n", error));
switch (error) {
case PK_WARN:
++NumWarnFiles;
break;
case IZ_DIR:
++NumMissDirs;
error = PK_NOZIP;
break;
case PK_NOZIP:
;
break;
default:
if (error)
++NumLoseFiles;
else
++NumWinFiles;
break;
}
if (error > error_in_archive)
error_in_archive = error;
#ifdef WINDLL
if (error == IZ_CTRLC) {
free_G_buffers(__G);
return error;
}
#endif
}
}
#endif
#ifndef SFX
if (iswild(G.wildzipfn) && uO.qflag < 3
#ifdef TIMESTAMP
&& !(uO.T_flag && !uO.zipinfo_mode && uO.qflag > 1)
#endif
)
{
if ((NumMissFiles + NumLoseFiles + NumWarnFiles > 0 || NumWinFiles != 1)
#ifdef TIMESTAMP
&& !(uO.T_flag && !uO.zipinfo_mode && uO.qflag)
#endif
&& !(uO.tflag && uO.qflag > 1))
(*G.message)((zvoid *)&G, (uch *)"\n", 1L, 0x401);
if ((NumWinFiles > 1) ||
(NumWinFiles == 1 &&
NumMissDirs + NumMissFiles + NumLoseFiles + NumWarnFiles > 0))
Info(slide, 0x401, ((char *)slide, LoadFarString(FilesProcessOK),
NumWinFiles, (NumWinFiles == 1)? " was" : "s were"));
if (NumWarnFiles > 0)
Info(slide, 0x401, ((char *)slide, LoadFarString(ArchiveWarning),
NumWarnFiles, (NumWarnFiles == 1)? "" : "s"));
if (NumLoseFiles > 0)
Info(slide, 0x401, ((char *)slide, LoadFarString(ArchiveFatalError),
NumLoseFiles, (NumLoseFiles == 1)? "" : "s"));
if (NumMissFiles > 0)
Info(slide, 0x401, ((char *)slide,
LoadFarString(FileHadNoZipfileDir), NumMissFiles,
(NumMissFiles == 1)? "" : "s"));
if (NumMissDirs == 1)
Info(slide, 0x401, ((char *)slide, LoadFarString(ZipfileWasDir)));
else if (NumMissDirs > 0)
Info(slide, 0x401, ((char *)slide,
LoadFarString(ManyZipfilesWereDir), NumMissDirs));
if (NumWinFiles + NumLoseFiles + NumWarnFiles == 0)
Info(slide, 0x401, ((char *)slide, LoadFarString(NoZipfileFound)));
}
#endif
free_G_buffers(__G);
return error_in_archive;
},0

int Server::getUserID(const QString &name) {
if (qhUserIDCache.contains(name))
return qhUserIDCache.value(name);
int id = -2;
emit nameToIdSig(id, name);
if (id != -2) {
qhUserIDCache.insert(name, id);
qhUserNameCache.insert(id, name);
return id;
}
TransactionHolder th;
QSqlQuery &query = *th.qsqQuery;
SQLPREP("SELECT `user_id` FROM `%1users` WHERE `server_id` = ? AND `name` like ?");
query.addBindValue(iServerNum);
query.addBindValue(name);
SQLEXEC();
if (query.next()) {
id = query.value(0).toInt();
qhUserIDCache.insert(name, id);
qhUserNameCache.insert(id, name);
}
return id;
},1

ext_get_plugin(const char *name, const char *module, const char *revision)
{
uint16_t u;
assert(name);
assert(module);
for (u = 0; u < ext_plugins_count; u++) {
if (!strcmp(name, ext_plugins[u].name) &&
!strcmp(module, ext_plugins[u].module) &&
(!ext_plugins[u].revision || !strcmp(revision, ext_plugins[u].revision))) {
return ext_plugins[u].plugin;
}
}
return NULL;
},1

