fcnr_name, fcnr->addr);
r_cons_printf (" \"0x%08"PFMT64x"\" "
"[label=\"%s\""
" URL=\"%s/0x%08"PFMT64x"\"];\n",
fcnr->addr, fcnr_name,
fcnr_name, fcnr->addr);
break;
case R_GRAPH_FORMAT_JSON:
if (usenames) {
pj_s (pj, fcnr_name);
} else {
char fcnr_addr[20];
snprintf (fcnr_addr, sizeof (fcnr_addr) - 1, "0x%08" PFMT64x, fcnr->addr);
pj_s (pj, fcnr_addr);
