}
if (iteration == 0 && fmt == R_GRAPH_FORMAT_GML) {
iteration++;
goto repeat;
}
if (iteration == 0 && fmt == R_GRAPH_FORMAT_GMLFCN) {
iteration++;
}
switch (fmt) {
case R_GRAPH_FORMAT_GML:
case R_GRAPH_FORMAT_GMLFCN:
case R_GRAPH_FORMAT_JSON:
pj_end (pj);
r_cons_println (pj_string (pj));
pj_free (pj);
