de265_error decoder_context::decode(int* more)
{
decoder_context* ctx = this;
if (ctx->nal_parser.get_NAL_queue_length() == 0 &&
(ctx->nal_parser.is_end_of_stream() || ctx->nal_parser.is_end_of_frame()) &&
ctx->image_units.empty()) {
ctx->dpb.flush_reorder_buffer();
if (more) { *more = ctx->dpb.num_pictures_in_output_queue(); }
return DE265_OK;
}
if (ctx->nal_parser.is_end_of_stream() == false &&
ctx->nal_parser.is_end_of_frame() == false &&
ctx->nal_parser.get_NAL_queue_length() == 0) {
if (more) { *more=1; }
return DE265_ERROR_WAITING_FOR_INPUT_DATA;
}
if (!ctx->dpb.has_free_dpb_picture(false)) {
if (more) *more = 1;
return DE265_ERROR_IMAGE_BUFFER_FULL;
}
de265_error err = DE265_OK;
bool did_work = false;
if (ctx->nal_parser.get_NAL_queue_length()) {
NAL_unit* nal = ctx->nal_parser.pop_from_NAL_queue();
assert(nal);
err = ctx->decode_NAL(nal);
did_work=true;
}
else if (ctx->nal_parser.is_end_of_frame() == true &&
ctx->image_units.empty()) {
if (more) { *more=1; }
return DE265_ERROR_WAITING_FOR_INPUT_DATA;
}
else {
err = decode_some(&did_work);
}
if (more) {
*more = (err==DE265_OK && did_work);
}
return err;
},0

RzList *MACH0_(mach_fields)(RzBinFile *bf) {
RzBuffer *buf = bf->buf;
ut64 length = rz_buf_size(buf);
struct MACH0_(mach_header) *mh = MACH0_(get_hdr)(buf);
if (!mh) {
return NULL;
}
RzList *ret = rz_list_newf((RzListFree)rz_bin_field_free);
if (!ret) {
free(mh);
return NULL;
}
ut64 addr = pa2va(bf, 0);
ut64 paddr = 0;
rz_list_append(ret, rz_bin_field_new(addr, addr, 1, "header", "mach0_header", "mach0_header", true));
addr += 0x20 - 4;
paddr += 0x20 - 4;
bool is64 = mh->cputype >> 16;
if (is64) {
addr += 4;
paddr += 4;
}
bool isBe = false;
switch (mh->cputype) {
case CPU_TYPE_POWERPC:
case CPU_TYPE_POWERPC64:
isBe = true;
break;
}
int n;
for (n = 0; n < mh->ncmds; n++) {
ut32 lcType;
if (!rz_buf_read_ble32_at(buf, paddr, &lcType, isBe)) {
break;
}
ut32 word;
if (!rz_buf_read_ble32_at(buf, paddr + 4, &word, isBe)) {
break;
}
if (paddr + 8 > length) {
break;
}
ut32 lcSize = word;
word &= 0xFFFFFF;
if (lcSize < 1) {
eprintf("Invalid size for a load command\n");
break;
}
if (word == 0) {
break;
}
const char *pf_definition = cmd_to_pf_definition(lcType);
if (pf_definition) {
rz_list_append(ret, rz_bin_field_new(addr, addr, 1, sdb_fmt("load_command_%d_%s", n, cmd_to_string(lcType)), pf_definition, pf_definition, true));
}
switch (lcType) {
case LC_BUILD_VERSION: {
ut32 ntools;
if (!rz_buf_read_le32_at(buf, paddr + 20, &ntools)) {
break;
}
ut64 off = 24;
int j = 0;
while (off < lcSize && ntools--) {
rz_list_append(ret, rz_bin_field_new(addr + off, addr + off, 1, sdb_fmt("tool_%d", j++), "mach0_build_version_tool", "mach0_build_version_tool", true));
off += 8;
}
break;
}
case LC_SEGMENT:
case LC_SEGMENT_64: {
ut32 nsects;
if (!rz_buf_read_le32_at(buf, addr + (is64 ? 64 : 48), &nsects)) {
break;
}
ut64 off = is64 ? 72 : 56;
size_t i, j = 0;
for (i = 0; i < nsects && (addr + off) < length && off < lcSize; i++) {
const char *sname = is64 ? "mach0_section64" : "mach0_section";
RzBinField *f = rz_bin_field_new(addr + off, addr + off, 1,
sdb_fmt("section_%zu", j++), sname, sname, true);
rz_list_append(ret, f);
off += is64 ? 80 : 68;
}
break;
default:
break;
}
}
addr += word;
paddr += word;
}
free(mh);
return ret;
},0

static int get_v4l2_window32(struct v4l2_window *kp, struct v4l2_window32 __user *up)
{
struct v4l2_clip32 __user *uclips;
struct v4l2_clip __user *kclips;
compat_caddr_t p;
u32 n;
if (!access_ok(VERIFY_READ, up, sizeof(*up)) ||
copy_from_user(&kp->w, &up->w, sizeof(up->w)) ||
get_user(kp->field, &up->field) ||
get_user(kp->chromakey, &up->chromakey) ||
get_user(kp->clipcount, &up->clipcount) ||
get_user(kp->global_alpha, &up->global_alpha))
return -EFAULT;
if (kp->clipcount > 2048)
return -EINVAL;
if (!kp->clipcount) {
kp->clips = NULL;
return 0;
}
n = kp->clipcount;
if (get_user(p, &up->clips))
return -EFAULT;
uclips = compat_ptr(p);
kclips = compat_alloc_user_space(n * sizeof(*kclips));
kp->clips = kclips;
while (n--) {
if (copy_in_user(&kclips->c, &uclips->c, sizeof(uclips->c)))
return -EFAULT;
if (put_user(n ? kclips + 1 : NULL, &kclips->next))
return -EFAULT;
uclips++;
kclips++;
}
return 0;
},1

static MagickBooleanType WriteImageChannels(const PSDInfo *psd_info,
const ImageInfo *image_info,Image *image,Image *next_image,
const MagickBooleanType separate,ExceptionInfo *exception)
{
size_t
channels,
packet_size;
unsigned char
*compact_pixels;
channels=1;
packet_size=next_image->depth > 8UL ? 2UL : 1UL;
compact_pixels=(unsigned char *) NULL;
if (next_image->compression == RLECompression)
{
compact_pixels=(unsigned char *) AcquireQuantumMemory(2*channels*
next_image->columns,packet_size*sizeof(*compact_pixels));
if (compact_pixels == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
if (IsImageGray(next_image) != MagickFalse)
{
if (next_image->compression == RLECompression)
{
