!check_sep("{") ||
!(in >> eo) || !check_sep(",") ||
!(in >> epr) || !check_sep(",") ||
!(in >> ene) || !check_sep(",") ||
!(in >> v) || !check_sep(",") ||
!(in >> f) || !check_sep(",") ||
!(in >> m) || !check_sep(",") ||
!(in >> k) || !check_sep("}") )
return false;
CGAL_assertion_msg
(eo >= 0 && eo < en && epr >= 0 && epr < en && ene >= 0 && ene < en &&
v >= 0 && v < vn && f >= 0 && f < fn ,
"wrong index in read_edge");
CGAL_assertion(EI[e->twin()]);
set_prev(e,Edge_of[epr]);
set_next(e,Edge_of[ene]);
set_source(e,SVertex_of[v]);
set_face(e,SFace_of[f]);
e->mark() = m;
e->circle() = k;
return true;
},1

