BOOL rdp_recv_demand_active(rdpRdp* rdp, wStream* s)
{
UINT16 channelId;
UINT16 pduType;
UINT16 pduLength;
UINT16 pduSource;
UINT16 length;
UINT16 numberCapabilities;
UINT16 lengthSourceDescriptor;
UINT16 lengthCombinedCapabilities;
if (!rdp_recv_get_active_header(rdp, s, &channelId, &length))
return FALSE;
if (freerdp_shall_disconnect(rdp->instance))
return TRUE;
if (!rdp_read_share_control_header(s, &pduLength, &pduType, &pduSource))
{
WLog_ERR(TAG, "rdp_read_share_control_header failed");
return FALSE;
}
if (pduType == PDU_TYPE_DATA)
{
if (rdp_recv_data_pdu(rdp, s) < 0)
return FALSE;
return FALSE;
}
if (pduType != PDU_TYPE_DEMAND_ACTIVE)
{
if (pduType != PDU_TYPE_SERVER_REDIRECTION)
WLog_ERR(TAG, "expected PDU_TYPE_DEMAND_ACTIVE %04x, got %04" PRIx16 "",
PDU_TYPE_DEMAND_ACTIVE, pduType);
return FALSE;
}
rdp->settings->PduSource = pduSource;
if (Stream_GetRemainingLength(s) < 8)
return FALSE;
Stream_Read_UINT32(s, rdp->settings->ShareId);
Stream_Read_UINT16(s, lengthSourceDescriptor);
Stream_Read_UINT16(s, lengthCombinedCapabilities);
if (!Stream_SafeSeek(s, lengthSourceDescriptor) ||
Stream_GetRemainingLength(s) < 4)
return FALSE;
Stream_Read_UINT16(s, numberCapabilities);
Stream_Seek(s, 2);
if (!rdp_read_capability_sets(s, rdp->settings, numberCapabilities, lengthCombinedCapabilities))
{
WLog_ERR(TAG, "rdp_read_capability_sets failed");
return FALSE;
}
if (!Stream_SafeSeek(s, 4))
return FALSE;
rdp->update->secondary->glyph_v2 = (rdp->settings->GlyphSupportLevel > GLYPH_SUPPORT_FULL);
return tpkt_ensure_stream_consumed(s, length);
},0

static int acurite_6045_decode(r_device *decoder, bitbuffer_t *bitbuffer, unsigned row)
{
float tempf;
uint8_t humidity;
char raw_str[31], *rawp;
uint16_t sensor_id;
uint8_t strike_count, strike_distance;
int battery_low, active, rfi_detect;
int exception = 0;
data_t *data;
int browlen = (bitbuffer->bits_per_row[row] + 7) / 8;
uint8_t *bb = bitbuffer->bb[row];
char const *channel_str = acurite_getChannel(bb[0]);
sensor_id = ((bb[0] & 0x3f) << 8) | bb[1];
battery_low = (bb[2] & 0x40) == 0;
humidity = (bb[3] & 0x7f);
active = (bb[4] & 0x40) == 0x40;
int temp_raw = ((bb[4] & 0x1F) << 7) | (bb[5] & 0x7F);
tempf = (temp_raw - 1480) * 0.1f;
strike_count = ((bb[6] & 0x7f) << 1) | ((bb[7] & 0x40) >> 6);
strike_distance = bb[7] & 0x1f;
rfi_detect = (bb[7] & 0x20) == 0x20;
rawp = (char *)raw_str;
for (int i=0; i < MIN(browlen, 15); i++) {
sprintf(rawp,"%02x",bb[i]);
rawp += 2;
}
*rawp = '\0';
if (((bb[4] & 0x20) != 0) ||
(humidity > 100) ||
(tempf > 158) ||
(tempf < -40)) {
exception++;
}
data = data_make(
"model", "", DATA_STRING, "Acurite-6045M",
"id", NULL, DATA_INT, sensor_id,
"channel", NULL, DATA_STRING, channel_str,
"battery_ok", "Battery", DATA_INT, !battery_low,
"temperature_F", "temperature", DATA_FORMAT, "%.1f F", DATA_DOUBLE, tempf,
"humidity", "humidity", DATA_FORMAT, "%u %%", DATA_INT, humidity,
"strike_count", "strike_count", DATA_INT, strike_count,
"storm_dist", "storm_distance", DATA_INT, strike_distance,
"active", "active_mode", DATA_INT, active,
"rfi", "rfi_detect", DATA_INT, rfi_detect,
"exception", "data_exception", DATA_INT, exception,
"raw_msg", "raw_message", DATA_STRING, raw_str,
NULL);
decoder_output_data(decoder, data);
return 1;
},0

irc_nick_default_ban_mask (struct t_irc_nick *nick)
{
const char *ptr_ban_mask;
char *pos_hostname, user[128], ident[128], *res, *temp;
if (!nick)
return NULL;
ptr_ban_mask = weechat_config_string (irc_config_network_ban_mask_default);
pos_hostname = (nick->host) ? strchr (nick->host, '@') : NULL;
if (!nick->host || !pos_hostname || !ptr_ban_mask || !ptr_ban_mask[0])
return NULL;
if (pos_hostname - nick->host > (int)sizeof (user) - 1)
return NULL;
strncpy (user, nick->host, pos_hostname - nick->host);
user[pos_hostname - nick->host] = '\0';
strcpy (ident, (user[0] != '~') ? user : "*");
pos_hostname++;
temp = weechat_string_replace (ptr_ban_mask, "$nick", nick->name);
if (!temp)
return NULL;
res = temp;
temp = weechat_string_replace (res, "$user", user);
free (res);
if (!temp)
return NULL;
res = temp;
temp = weechat_string_replace (res, "$ident", ident);
free (res);
if (!temp)
return NULL;
res = temp;
temp = weechat_string_replace (res, "$host", pos_hostname);
free (res);
if (!temp)
return NULL;
res = temp;
return res;
},0

psutil_users(PyObject *self, PyObject *args) {
HANDLE hServer = WTS_CURRENT_SERVER_HANDLE;
WCHAR *buffer_user = NULL;
LPTSTR buffer_addr = NULL;
PWTS_SESSION_INFO sessions = NULL;
DWORD count;
DWORD i;
DWORD sessionId;
DWORD bytes;
PWTS_CLIENT_ADDRESS address;
char address_str[50];
long long unix_time;
WINSTATION_INFO station_info;
ULONG returnLen;
PyObject *py_tuple = NULL;
PyObject *py_address = NULL;
PyObject *py_username = NULL;
PyObject *py_retlist = PyList_New(0);
if (py_retlist == NULL)
return NULL;
if (WTSEnumerateSessions(hServer, 0, 1, &sessions, &count) == 0) {
PyErr_SetFromOSErrnoWithSyscall("WTSEnumerateSessions");
goto error;
}
for (i = 0; i < count; i++) {
py_address = NULL;
py_tuple = NULL;
sessionId = sessions[i].SessionId;
if (buffer_user != NULL)
WTSFreeMemory(buffer_user);
if (buffer_addr != NULL)
WTSFreeMemory(buffer_addr);
buffer_user = NULL;
buffer_addr = NULL;
bytes = 0;
if (WTSQuerySessionInformationW(hServer, sessionId, WTSUserName,
&buffer_user, &bytes) == 0) {
PyErr_SetFromOSErrnoWithSyscall("WTSQuerySessionInformationW");
goto error;
}
if (bytes <= 2)
continue;
bytes = 0;
if (WTSQuerySessionInformation(hServer, sessionId, WTSClientAddress,
&buffer_addr, &bytes) == 0) {
PyErr_SetFromOSErrnoWithSyscall("WTSQuerySessionInformation");
goto error;
}
address = (PWTS_CLIENT_ADDRESS)buffer_addr;
if (address->AddressFamily == 0) {
sprintf_s(address_str,
_countof(address_str),
"%u.%u.%u.%u",
address->Address[0],
address->Address[1],
address->Address[2],
address->Address[3]);
py_address = Py_BuildValue("s", address_str);
if (!py_address)
goto error;
}
else {
py_address = Py_None;
}
if (! psutil_WinStationQueryInformationW(
hServer,
sessionId,
WinStationInformation,
&station_info,
sizeof(station_info),
&returnLen))
{
PyErr_SetFromOSErrnoWithSyscall("WinStationQueryInformationW");
goto error;
}
unix_time = ((LONGLONG)station_info.ConnectTime.dwHighDateTime) << 32;
unix_time += \
station_info.ConnectTime.dwLowDateTime - 116444736000000000LL;
unix_time /= 10000000;
py_username = PyUnicode_FromWideChar(buffer_user, wcslen(buffer_user));
if (py_username == NULL)
goto error;
py_tuple = Py_BuildValue("OOd",
py_username,
py_address,
(double)unix_time);
if (!py_tuple)
goto error;
if (PyList_Append(py_retlist, py_tuple))
goto error;
Py_XDECREF(py_username);
Py_XDECREF(py_address);
Py_XDECREF(py_tuple);
}
WTSFreeMemory(sessions);
WTSFreeMemory(buffer_user);
WTSFreeMemory(buffer_addr);
return py_retlist;
error:
Py_XDECREF(py_username);
Py_XDECREF(py_tuple);
Py_XDECREF(py_address);
Py_DECREF(py_retlist);
if (sessions != NULL)
WTSFreeMemory(sessions);
if (buffer_user != NULL)
WTSFreeMemory(buffer_user);
if (buffer_addr != NULL)
WTSFreeMemory(buffer_addr);
return NULL;
},1

static int wolfSSH_SFTP_RecvRealPath(WOLFSSH* ssh, int reqId, byte* data,
int maxSz)
{
WS_SFTP_FILEATRB atr;
char r[WOLFSSH_MAX_FILENAME];
word32 rSz;
word32 lidx = 0;
word32 i;
int ret;
byte* out;
word32 outSz = 0;
WLOG(WS_LOG_SFTP, "Receiving WOLFSSH_FTP_REALPATH");
if (ssh == NULL) {
WLOG(WS_LOG_SFTP, "Bad argument passed in");
return WS_BAD_ARGUMENT;
}
if (maxSz < UINT32_SZ) {
return WS_BUFFER_E;
}
ato32(data + lidx, &rSz);
if (rSz >= WOLFSSH_MAX_FILENAME || (int)(rSz + UINT32_SZ) > maxSz) {
return WS_BUFFER_E;
}
lidx += UINT32_SZ;
WMEMCPY(r, data + lidx, rSz);
r[rSz] = '\0';
if (r[0] != '/' && r[1] != ':') {
char wd[WOLFSSH_MAX_FILENAME];
WMEMSET(wd, 0, WOLFSSH_MAX_FILENAME);
if (ssh->sftpDefaultPath) {
XSTRNCPY(wd, ssh->sftpDefaultPath, WOLFSSH_MAX_FILENAME - 1);
}
else {
#ifndef USE_WINDOWS_API
if (WGETCWD(ssh->fs, wd, WOLFSSH_MAX_FILENAME) == NULL) {
WLOG(WS_LOG_SFTP, "Unable to get current working directory");
if (wolfSSH_SFTP_CreateStatus(ssh, WOLFSSH_FTP_FAILURE, reqId,
"Directory error", "English", NULL, &outSz)
!= WS_SIZE_ONLY) {
return WS_FATAL_ERROR;
}
out = (byte*) WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
if (wolfSSH_SFTP_CreateStatus(ssh, WOLFSSH_FTP_FAILURE, reqId,
"Directory error", "English", out, &outSz)
!= WS_SUCCESS) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
return WS_BAD_FILE_E;
}
#endif
}
WSTRNCAT(wd, "/", WOLFSSH_MAX_FILENAME);
WSTRNCAT(wd, r, WOLFSSH_MAX_FILENAME);
WMEMCPY(r, wd, WOLFSSH_MAX_FILENAME);
}
if ((ret = wolfSSH_CleanPath(ssh, r)) < 0) {
return WS_FATAL_ERROR;
}
rSz = (word32)ret;
if (r[rSz - 2] == WS_DELIM && r[rSz - 1] == '.') {
r[rSz - 1] = '\0';
rSz -= 1;
}
for (i = 0; i < rSz; i++) {
if (r[i] == WS_DELIM) r[i] = '/';
}
WLOG(WS_LOG_SFTP, "Real Path Directory = %s", r);
outSz = WOLFSSH_SFTP_HEADER + (UINT32_SZ * 3) + (rSz * 2);
WMEMSET(&atr, 0, sizeof(WS_SFTP_FILEATRB));
outSz += SFTP_AtributesSz(ssh, &atr);
lidx = 0;
out = (outSz > (word32)maxSz)?
(byte*)WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER) :
wolfSSH_SFTP_RecvGetData(ssh);
if (out == NULL) {
return WS_MEMORY_E;
}
SFTP_SetHeader(ssh, reqId, WOLFSSH_FTP_NAME,
outSz - WOLFSSH_SFTP_HEADER, out);
lidx += WOLFSSH_SFTP_HEADER;
c32toa(1, out + lidx); lidx += UINT32_SZ;
c32toa(rSz, out + lidx); lidx += UINT32_SZ;
WMEMCPY(out + lidx, r, rSz); lidx += rSz;
c32toa(rSz, out + lidx); lidx += UINT32_SZ;
WMEMCPY(out + lidx, r, rSz); lidx += rSz;
SFTP_SetAttributes(ssh, out + lidx, outSz - lidx, &atr);
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
return WS_SUCCESS;
},0

