glue(glue(cirrus_bitblt_rop_bkwd_transp_, ROP_NAME),_16)(CirrusVGAState *s,
uint32_t dstaddr,
const uint8_t *src,
int dstpitch,
int srcpitch,
int bltwidth,
int bltheight)
{
