p += 2;
break;
case duplicate:
{
register const char *d2, *dend2;
int regno = *p++;
DEBUG_PRINT2 ("EXECUTING duplicate %d.\n", regno);
if (REG_UNSET (regstart[regno]) || REG_UNSET (regend[regno]))
