ftp_genlist(ftpbuf_t *ftp, const char *cmd, const char *path TSRMLS_DC)
{
php_stream *tmpstream = NULL;
databuf_t *data = NULL;
char *ptr;
int ch, lastch;
size_t size, rcvd;
size_t lines;
char **ret = NULL;
char **entry;
char *text;
if ((tmpstream = php_stream_fopen_tmpfile()) == NULL) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to create temporary file. Check permissions in temporary files directory.");
return NULL;
}
if (!ftp_type(ftp, FTPTYPE_ASCII)) {
goto bail;
}
if ((data = ftp_getdata(ftp TSRMLS_CC)) == NULL) {
goto bail;
}
ftp->data = data;
if (!ftp_putcmd(ftp, cmd, path)) {
goto bail;
}
if (!ftp_getresp(ftp) || (ftp->resp != 150 && ftp->resp != 125 && ftp->resp != 226)) {
goto bail;
}
if (ftp->resp == 226) {
ftp->data = data_close(ftp, data);
php_stream_close(tmpstream);
return ecalloc(1, sizeof(char*));
}
if ((data = data_accept(data, ftp TSRMLS_CC)) == NULL) {
goto bail;
}
size = 0;
lines = 0;
lastch = 0;
while ((rcvd = my_recv(ftp, data->fd, data->buf, FTP_BUFSIZE))) {
if (rcvd == -1 || rcvd > ((size_t)(-1))-size) {
goto bail;
}
php_stream_write(tmpstream, data->buf, rcvd);
size += rcvd;
for (ptr = data->buf; rcvd; rcvd--, ptr++) {
if (*ptr == '\n' && lastch == '\r') {
lines++;
} else {
size++;
}
lastch = *ptr;
}
}
ftp->data = data_close(ftp, data);
php_stream_rewind(tmpstream);
ret = safe_emalloc((lines + 1), sizeof(char*), size);
entry = ret;
text = (char*) (ret + lines + 1);
*entry = text;
lastch = 0;
while ((ch = php_stream_getc(tmpstream)) != EOF) {
if (ch == '\n' && lastch == '\r') {
*(text - 1) = 0;
*++entry = text;
} else {
*text++ = ch;
}
lastch = ch;
}
*entry = NULL;
php_stream_close(tmpstream);
if (!ftp_getresp(ftp) || (ftp->resp != 226 && ftp->resp != 250)) {
efree(ret);
return NULL;
}
return ret;
bail:
ftp->data = data_close(ftp, data);
php_stream_close(tmpstream);
if (ret)
efree(ret);
return NULL;
},1

horDiff32(TIFF* tif, uint8* cp0, tmsize_t cc)
{
TIFFPredictorState* sp = PredictorState(tif);
tmsize_t stride = sp->stride;
uint32 *wp = (uint32*) cp0;
tmsize_t wc = cc/4;
assert((cc%(4*stride))==0);
if (wc > stride) {
wc -= stride;
wp += wc - 1;
do {
REPEAT4(stride, wp[stride] -= wp[0]; wp--)
wc -= stride;
} while (wc > 0);
}
},1

port::Status CudnnSupport::DoRnnForwardImpl(
Stream* stream, const CudnnRnnDescriptor& rnn_desc,
const CudnnRnnSequenceTensorDescriptor& input_desc,
const DeviceMemory<T>& input_data,
const CudnnRnnStateTensorDescriptor& input_h_desc,
const DeviceMemory<T>& input_h_data,
const CudnnRnnStateTensorDescriptor& input_c_desc,
const DeviceMemory<T>& input_c_data, const DeviceMemory<T>& params,
const CudnnRnnSequenceTensorDescriptor& output_desc,
DeviceMemory<T>* output_data,
const CudnnRnnStateTensorDescriptor& output_h_desc,
DeviceMemory<T>* output_h_data,
const CudnnRnnStateTensorDescriptor& output_c_desc,
DeviceMemory<T>* output_c_data, bool is_training,
ScratchAllocator* reserve_space_allocator,
ScratchAllocator* workspace_allocator,
dnn::ProfileResult* output_profile_result) {
SE_ASSIGN_OR_RETURN(
RnnModelDims model_dims,
ExtractAndCheckRnnForward(
rnn_desc, input_desc, input_data, input_h_desc, input_h_data,
input_c_desc, input_c_data, params, output_desc, *output_data,
output_h_desc, *output_h_data, output_c_desc, *output_c_data));
auto cudnn = cudnn_->GetHandle(parent_, stream);
SE_RETURN_IF_ERROR(CheckRNNParameterSize(cudnn, rnn_desc, input_desc));
SE_ASSIGN_OR_RETURN(DeviceMemory<uint8> workspace,
CreateRnnWorkspace(stream, cudnn, rnn_desc, input_desc,
workspace_allocator))
DeviceMemory<uint8> reserve_space;
if (is_training) {
size_t reserve_space_size_in_bytes = 0;
RETURN_IF_CUDNN_ERROR(cudnnGetRNNTrainingReserveSize(
cudnn.handle(), rnn_desc.handle(),
model_dims.max_seq_length, input_desc.handles(),
&reserve_space_size_in_bytes));
if (reserve_space_size_in_bytes > 0) {
SE_ASSIGN_OR_RETURN(reserve_space, reserve_space_allocator->AllocateBytes(
reserve_space_size_in_bytes));
}
}
std::unique_ptr<GpuTimer, GpuTimerDeleter> timer;
const bool is_profiling = output_profile_result != nullptr;
if (is_profiling) {
timer.reset(new GpuTimer(parent_));
if (!timer->Init() || !timer->Start(AsGpuStream(stream))) {
return port::Status(port::error::INTERNAL, "Failed to start timer");
}
}
if (!is_training) {
if (input_desc.is_var_seq_lengths()) {
RETURN_IF_CUDNN_ERROR(cudnnRNNForwardInferenceEx(
cudnn.handle(), rnn_desc.handle(),
input_desc.data_handle(), input_data.opaque(),
input_h_desc.handle(), input_h_data.opaque(),
input_c_desc.handle(), input_c_data.opaque(),
rnn_desc.params_handle(), params.opaque(),
output_desc.data_handle(),
output_data->opaque(),
output_h_desc.handle(), output_h_data->opaque(),
output_c_desc.handle(), output_c_data->opaque(),
nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
nullptr,
workspace.opaque(),
workspace.size()));
} else {
RETURN_IF_CUDNN_ERROR(cudnnRNNForwardInference(
cudnn.handle(), rnn_desc.handle(),
model_dims.max_seq_length,
input_desc.handles(),
input_data.opaque(), input_h_desc.handle(),
input_h_data.opaque(), input_c_desc.handle(),
input_c_data.opaque(), rnn_desc.params_handle(),
params.opaque(), output_desc.handles(),
output_data->opaque(), output_h_desc.handle(),
output_h_data->opaque(), output_c_desc.handle(),
output_c_data->opaque(), workspace.opaque(),
workspace.size()));
}
} else {
if (input_desc.is_var_seq_lengths()) {
RETURN_IF_CUDNN_ERROR(cudnnRNNForwardTrainingEx(
cudnn.handle(), rnn_desc.handle(),
input_desc.data_handle(), input_data.opaque(),
input_h_desc.handle(), input_h_data.opaque(),
input_c_desc.handle(), input_c_data.opaque(),
rnn_desc.params_handle(), params.opaque(),
output_desc.data_handle(),
output_data->opaque(),
output_h_desc.handle(), output_h_data->opaque(),
output_c_desc.handle(), output_c_data->opaque(),
nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
nullptr,
workspace.opaque(),
workspace.size(),
reserve_space.opaque(),
reserve_space.size()));
} else {
RETURN_IF_CUDNN_ERROR(cudnnRNNForwardTraining(
cudnn.handle(), rnn_desc.handle(),
model_dims.max_seq_length,
input_desc.handles(),
input_data.opaque(), input_h_desc.handle(),
input_h_data.opaque(), input_c_desc.handle(),
input_c_data.opaque(), rnn_desc.params_handle(),
params.opaque(), output_desc.handles(),
output_data->opaque(), output_h_desc.handle(),
output_h_data->opaque(), output_c_desc.handle(),
output_c_data->opaque(), workspace.opaque(),
workspace.size(),
reserve_space.opaque(),
reserve_space.size()));
}
}
if (is_profiling) {
if (!timer->Stop(AsGpuStream(stream))) {
return port::Status(port::error::INTERNAL, "Failed to stop timer");
}
auto algo_desc = *rnn_desc.algorithm_config().algorithm();
output_profile_result->set_algorithm(algo_desc);
output_profile_result->set_elapsed_time_in_ms(
timer->GetElapsedMilliseconds());
}
return port::Status::OK();
},0

nbd_unlocked_aio_zero (struct nbd_handle *h,
uint64_t count, uint64_t offset,
nbd_completion_callback *completion,
uint32_t flags)
{
struct command_cb cb = { .completion = *completion };
if (h->strict & LIBNBD_STRICT_COMMANDS) {
if (nbd_unlocked_can_zero (h) != 1) {
set_error (EINVAL, "server does not support zero operations");
return -1;
}
if (nbd_unlocked_is_read_only (h) == 1) {
set_error (EPERM, "server does not support write operations");
return -1;
}
if ((flags & LIBNBD_CMD_FLAG_FUA) != 0 &&
nbd_unlocked_can_fua (h) != 1) {
set_error (EINVAL, "server does not support the FUA flag");
return -1;
}
if ((flags & LIBNBD_CMD_FLAG_FAST_ZERO) != 0 &&
nbd_unlocked_can_fast_zero (h) != 1) {
set_error (EINVAL, "server does not support the fast zero flag");
return -1;
}
}
SET_CALLBACK_TO_NULL (*completion);
return nbd_internal_command_common (h, flags, NBD_CMD_WRITE_ZEROES, offset,
count, ENOSPC, NULL, &cb);
},0

mesh_state_compare(const void* ap, const void* bp)
{
struct mesh_state* a = (struct mesh_state*)ap;
struct mesh_state* b = (struct mesh_state*)bp;
int cmp;
if(a->unique < b->unique)
return -1;
if(a->unique > b->unique)
return 1;
if(a->s.is_priming && !b->s.is_priming)
return -1;
if(!a->s.is_priming && b->s.is_priming)
return 1;
if(a->s.is_valrec && !b->s.is_valrec)
return -1;
if(!a->s.is_valrec && b->s.is_valrec)
return 1;
if((a->s.query_flags&BIT_RD) && !(b->s.query_flags&BIT_RD))
return -1;
if(!(a->s.query_flags&BIT_RD) && (b->s.query_flags&BIT_RD))
return 1;
if((a->s.query_flags&BIT_CD) && !(b->s.query_flags&BIT_CD))
return -1;
if(!(a->s.query_flags&BIT_CD) && (b->s.query_flags&BIT_CD))
return 1;
cmp = query_info_compare(&a->s.qinfo, &b->s.qinfo);
if(cmp != 0)
return cmp;
return client_info_compare(a->s.client_info, b->s.client_info);
},0

bfad_im_get_stats(struct Scsi_Host *shost)
{
struct bfad_im_port_s *im_port =
(struct bfad_im_port_s *) shost->hostdata[0];
struct bfad_s *bfad = im_port->bfad;
struct bfad_hal_comp fcomp;
union bfa_port_stats_u *fcstats;
struct fc_host_statistics *hstats;
bfa_status_t rc;
unsigned long flags;
fcstats = kzalloc(sizeof(union bfa_port_stats_u), GFP_KERNEL);
if (fcstats == NULL)
return NULL;
hstats = &bfad->link_stats;
init_completion(&fcomp.comp);
spin_lock_irqsave(&bfad->bfad_lock, flags);
memset(hstats, 0, sizeof(struct fc_host_statistics));
rc = bfa_port_get_stats(BFA_FCPORT(&bfad->bfa),
fcstats, bfad_hcb_comp, &fcomp);
spin_unlock_irqrestore(&bfad->bfad_lock, flags);
if (rc != BFA_STATUS_OK)
return NULL;
wait_for_completion(&fcomp.comp);
hstats->seconds_since_last_reset = fcstats->fc.secs_reset;
hstats->tx_frames = fcstats->fc.tx_frames;
hstats->tx_words = fcstats->fc.tx_words;
hstats->rx_frames = fcstats->fc.rx_frames;
hstats->rx_words = fcstats->fc.rx_words;
hstats->lip_count = fcstats->fc.lip_count;
hstats->nos_count = fcstats->fc.nos_count;
hstats->error_frames = fcstats->fc.error_frames;
hstats->dumped_frames = fcstats->fc.dropped_frames;
hstats->link_failure_count = fcstats->fc.link_failures;
hstats->loss_of_sync_count = fcstats->fc.loss_of_syncs;
hstats->loss_of_signal_count = fcstats->fc.loss_of_signals;
hstats->prim_seq_protocol_err_count = fcstats->fc.primseq_errs;
hstats->invalid_crc_count = fcstats->fc.invalid_crcs;
kfree(fcstats);
return hstats;
},1

