lyd_get_node_siblings(const struct lyd_node *data, const struct lys_node *schema, struct ly_set *set)
{
const struct lyd_node *iter;
assert(set && !set->number);
assert(schema);
assert(schema->nodetype & (LYS_CONTAINER | LYS_LEAF | LYS_LIST | LYS_LEAFLIST | LYS_ANYDATA | LYS_NOTIF | LYS_RPC |
LYS_ACTION));
if (!data) {
return 0;
}
LY_TREE_FOR(data, iter) {
if (iter->schema == schema) {
ly_set_add(set, (void*)iter, LY_SET_OPT_USEASLIST);
}
}
return set->number;
},0

static void lsr_read_update_value(GF_LASeRCodec *lsr, GF_Node *node, u32 att_tag, u32 fieldType, void *val, u32 node_tag)
{
u32 is_default, has_escape, escape_val = 0;
SVG_Number num, *n;
switch (fieldType) {
case SVG_Boolean_datatype:
GF_LSR_READ_INT(lsr, *(SVG_Boolean*)val, 1, "val");
break;
case SVG_Paint_datatype:
lsr_read_paint(lsr, (SVG_Paint*)val, "val");
break;
case SVG_Transform_Scale_datatype:
((SVG_Point *)val)->x = lsr_read_fixed_16_8(lsr, "scale_x");
((SVG_Point *)val)->y = lsr_read_fixed_16_8(lsr, "scale_y");
break;
case LASeR_Size_datatype:
case SVG_Transform_Translate_datatype:
lsr_read_coordinate(lsr, &num, 0, "translation_x");
((SVG_Point *)val)->x = num.value;
lsr_read_coordinate(lsr, &num, 0, "translation_y");
((SVG_Point *)val)->y = num.value;
break;
case SVG_Transform_Rotate_datatype:
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) ((SVG_Point_Angle*)val)->angle = 0;
else {
GF_LSR_READ_INT(lsr, has_escape, 1, "escapeFlag");
if (has_escape) {
GF_LSR_READ_INT(lsr, escape_val, 2, "escapeEnum");
((SVG_Point_Angle*)val)->angle = 0;
}
else {
((SVG_Point_Angle*)val)->angle = lsr_read_fixed_16_8(lsr, "rotate");
}
}
break;
case SVG_Transform_datatype:
lsr_read_matrix(lsr, val);
break;
case SVG_Number_datatype:
case SVG_FontSize_datatype:
case SVG_Length_datatype:
n = (SVG_Number*)val;
switch (att_tag) {
case TAG_SVG_ATT_audio_level:
case TAG_SVG_ATT_fill_opacity:
case TAG_SVG_ATT_offset:
case TAG_SVG_ATT_opacity:
case TAG_SVG_ATT_solid_opacity:
case TAG_SVG_ATT_stop_opacity:
case TAG_SVG_ATT_stroke_opacity:
case TAG_SVG_ATT_viewport_fill_opacity:
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) n->type=SVG_NUMBER_INHERIT;
else {
n->type = SVG_NUMBER_VALUE;
n->value = lsr_read_fixed_clamp(lsr, "val");
}
break;
case TAG_SVG_ATT_width:
case TAG_SVG_ATT_height:
if (node_tag==TAG_SVG_svg) {
lsr_read_value_with_units(lsr, n, "val");
} else {
lsr_read_coordinate(lsr, n, 0, "val");
}
break;
default:
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) n->type=SVG_NUMBER_INHERIT;
else {
GF_LSR_READ_INT(lsr, has_escape, 1, "escapeFlag");
if (has_escape) {
GF_LSR_READ_INT(lsr, escape_val, 2, "escapeEnum");
n->type = SVG_NUMBER_AUTO;
} else {
n->type = SVG_NUMBER_VALUE;
n->value = lsr_read_fixed_16_8(lsr, "val");
}
}
break;
}
break;
case SVG_Coordinate_datatype:
n = (SVG_Number*)val;
n->type = SVG_NUMBER_VALUE;
lsr_read_coordinate(lsr, n, 0, "val");
break;
case SVG_Rotate_datatype:
n = (SVG_Number*)val;
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) n->type=SVG_NUMBER_INHERIT;
else {
GF_LSR_READ_INT(lsr, has_escape, 1, "escapeFlag");
if (has_escape) {
GF_LSR_READ_INT(lsr, escape_val, 2, "escapeEnum");
n->type = escape_val ? SVG_NUMBER_AUTO_REVERSE : SVG_NUMBER_AUTO;
} else {
n->type = SVG_NUMBER_VALUE;
n->value = lsr_read_fixed_16_8(lsr, "rotate");
}
}
break;
case SVG_Coordinates_datatype:
lsr_read_float_list(lsr, NULL, 0, val, "val");
break;
case SVG_ViewBox_datatype:
{
u32 count;
SVG_ViewBox *vb = (SVG_ViewBox *)val;
GF_LSR_READ_INT(lsr, count, 1, "isDefault");
if (count) {
vb->is_set = 0;
} else {
vb->is_set = 1;
GF_LSR_READ_INT(lsr, count, 1, "escapeFlag");
count = lsr_read_vluimsbf5(lsr, "count");
if (count) {
vb->x = lsr_read_fixed_16_8(lsr, "val");
count--;
}
if (count) {
vb->y = lsr_read_fixed_16_8(lsr, "val");
count--;
}
if (count) {
vb->width = lsr_read_fixed_16_8(lsr, "val");
count--;
}
if (count) {
vb->height = lsr_read_fixed_16_8(lsr, "val");
}
}
}
break;
case XMLRI_datatype:
case SVG_Focus_datatype:
if ((att_tag==TAG_XLINK_ATT_href) || (att_tag==TAG_SVG_ATT_syncReference)) {
lsr_read_any_uri(lsr, (XMLRI*)val, "val");
} else {
Bool is_escape;
u32 ID;
escape_val = ID = 0;
is_escape = 0;
GF_LSR_READ_INT(lsr, is_default, 1, "isDefault");
if (!is_default) {
GF_LSR_READ_INT(lsr, is_escape, 1, "isEscape");
if (is_escape) {
GF_LSR_READ_INT(lsr, escape_val, 2, "escapeEnumVal");
} else {
ID = lsr_read_vluimsbf5(lsr, "ID");
}
}
if (att_tag==SVG_Focus_datatype) {
if (is_default) ((SVG_Focus*)val)->type = SVG_FOCUS_AUTO;
else if (is_escape) ((SVG_Focus*)val)->type = escape_val;
else {
((SVG_Focus*)val)->type = SVG_FOCUS_IRI;
((SVG_Focus*)val)->target.type = XMLRI_ELEMENTID;
((SVG_Focus*)val)->target.node_id = ID;
}
} else {
if (is_default) ((XMLRI*)val)->type = XMLRI_STRING;
else {
((XMLRI *)val)->type = XMLRI_ELEMENTID;
((XMLRI *)val)->node_id = ID;
}
}
}
break;
case DOM_String_datatype:
case SVG_ContentType_datatype:
case SVG_LanguageID_datatype:
lsr_read_byte_align_string(lsr, (char**)val, "val");
break;
case SVG_Motion_datatype:
lsr_read_coordinate(lsr, &num, 0, "pointValueX");
((GF_Matrix2D*)val)->m[2] = num.value;
lsr_read_coordinate(lsr, &num, 0, "pointValueY");
((GF_Matrix2D*)val)->m[5] = num.value;
break;
case SVG_Points_datatype:
lsr_read_point_sequence(lsr, *(GF_List **)val, "val");
break;
case SVG_PathData_datatype:
lsr_read_path_type(lsr, NULL, 0, (SVG_PathData*)val, "val");
break;
case SVG_FontFamily_datatype:
{
u32 idx;
SVG_FontFamily *ff = (SVG_FontFamily *)val;
GF_LSR_READ_INT(lsr, idx, 1, "isDefault");
ff->type = SVG_FONTFAMILY_INHERIT;
if (!idx) {
char *ft;
GF_LSR_READ_INT(lsr, idx, 1, "escapeFlag");
idx = lsr_read_vluimsbf5(lsr, "index");
if (ff->value) gf_free(ff->value);
ff->value = NULL;
ft = (char*)gf_list_get(lsr->font_table, idx);
if (ft) {
ff->value = gf_strdup(ft);
ff->type = SVG_FONTFAMILY_VALUE;
}
}
}
break;
case LASeR_Choice_datatype:
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) ((LASeR_Choice *)val)->type = LASeR_CHOICE_ALL;
else {
GF_LSR_READ_INT(lsr, has_escape, 1, "escapeFlag");
if (has_escape) {
GF_LSR_READ_INT(lsr, escape_val, 2, "escapeEnum");
((LASeR_Choice *)val)->type = escape_val ? LASeR_CHOICE_NONE : LASeR_CHOICE_ALL;
} else {
((LASeR_Choice *)val)->type = LASeR_CHOICE_N;
((LASeR_Choice *)val)->choice_index = lsr_read_vluimsbf5(lsr, "value");
}
}
break;
default:
if ((fieldType>=SVG_FillRule_datatype) && (fieldType<=SVG_LAST_U8_PROPERTY)) {
GF_LSR_READ_INT(lsr, is_default, 1, "isDefaultValue");
if (is_default) *(u8 *)val = 0;
else *(u8 *)val = lsr_read_vluimsbf5(lsr, "val");
} else {
GF_LOG(GF_LOG_WARNING, GF_LOG_CODING, ("[LASeR] Warning: update value not supported: fieldType %d - attribute tag %d\n", fieldType, att_tag));
}
}
if (node) {
gf_node_changed(node, NULL);
}
},0

static CURLcode tftp_option_add(tftp_state_data_t *state, size_t *csize,
char *buf, const char *option)
{
if(( strlen(option) + *csize + 1) > (size_t)state->blksize)
return CURLE_TFTP_ILLEGAL;
strcpy(buf, option);
*csize += strlen(option) + 1;
return CURLE_OK;
},0

static int decode_attr_space_avail(struct xdr_stream *xdr, uint32_t *bitmap, uint64_t *res)
{
__be32 *p;
int status = 0;
*res = 0;
if (unlikely(bitmap[1] & (FATTR4_WORD1_SPACE_AVAIL - 1U)))
return -EIO;
if (likely(bitmap[1] & FATTR4_WORD1_SPACE_AVAIL)) {
READ_BUF(8);
READ64(*res);
bitmap[1] &= ~FATTR4_WORD1_SPACE_AVAIL;
}
dprintk("%s: space avail=%Lu\n", __func__, (unsigned long long)*res);
return status;
},0

static int adjust_ptr_min_max_vals(struct bpf_verifier_env *env,
struct bpf_insn *insn,
const struct bpf_reg_state *ptr_reg,
const struct bpf_reg_state *off_reg)
{
struct bpf_verifier_state *vstate = env->cur_state;
struct bpf_func_state *state = vstate->frame[vstate->curframe];
struct bpf_reg_state *regs = state->regs, *dst_reg;
bool known = tnum_is_const(off_reg->var_off);
s64 smin_val = off_reg->smin_value, smax_val = off_reg->smax_value,
smin_ptr = ptr_reg->smin_value, smax_ptr = ptr_reg->smax_value;
u64 umin_val = off_reg->umin_value, umax_val = off_reg->umax_value,
umin_ptr = ptr_reg->umin_value, umax_ptr = ptr_reg->umax_value;
struct bpf_sanitize_info info = {};
u8 opcode = BPF_OP(insn->code);
u32 dst = insn->dst_reg;
int ret;
dst_reg = &regs[dst];
if ((known && (smin_val != smax_val || umin_val != umax_val)) ||
smin_val > smax_val || umin_val > umax_val) {
__mark_reg_unknown(env, dst_reg);
return 0;
}
if (BPF_CLASS(insn->code) != BPF_ALU64) {
if (opcode == BPF_SUB && env->allow_ptr_leaks) {
__mark_reg_unknown(env, dst_reg);
return 0;
}
verbose(env,
"R%d 32-bit pointer arithmetic prohibited\n",
dst);
return -EACCES;
}
switch (ptr_reg->type) {
case PTR_TO_MAP_VALUE_OR_NULL:
verbose(env, "R%d pointer arithmetic on %s prohibited, null-check it first\n",
dst, reg_type_str[ptr_reg->type]);
return -EACCES;
case CONST_PTR_TO_MAP:
if (known && smin_val == 0 && opcode == BPF_ADD)
break;
fallthrough;
case PTR_TO_PACKET_END:
case PTR_TO_SOCKET:
case PTR_TO_SOCKET_OR_NULL:
case PTR_TO_SOCK_COMMON:
case PTR_TO_SOCK_COMMON_OR_NULL:
case PTR_TO_TCP_SOCK:
case PTR_TO_TCP_SOCK_OR_NULL:
case PTR_TO_XDP_SOCK:
verbose(env, "R%d pointer arithmetic on %s prohibited\n",
dst, reg_type_str[ptr_reg->type]);
return -EACCES;
default:
break;
}
dst_reg->type = ptr_reg->type;
dst_reg->id = ptr_reg->id;
if (!check_reg_sane_offset(env, off_reg, ptr_reg->type) ||
!check_reg_sane_offset(env, ptr_reg, ptr_reg->type))
return -EINVAL;
__mark_reg32_unbounded(dst_reg);
if (sanitize_needed(opcode)) {
ret = sanitize_ptr_alu(env, insn, ptr_reg, off_reg, dst_reg,
&info, false);
if (ret < 0)
return sanitize_err(env, insn, ret, off_reg, dst_reg);
}
switch (opcode) {
case BPF_ADD:
if (known && (ptr_reg->off + smin_val ==
(s64)(s32)(ptr_reg->off + smin_val))) {
dst_reg->smin_value = smin_ptr;
dst_reg->smax_value = smax_ptr;
dst_reg->umin_value = umin_ptr;
dst_reg->umax_value = umax_ptr;
dst_reg->var_off = ptr_reg->var_off;
dst_reg->off = ptr_reg->off + smin_val;
dst_reg->raw = ptr_reg->raw;
break;
}
if (signed_add_overflows(smin_ptr, smin_val) ||
signed_add_overflows(smax_ptr, smax_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = smin_ptr + smin_val;
dst_reg->smax_value = smax_ptr + smax_val;
}
if (umin_ptr + umin_val < umin_ptr ||
umax_ptr + umax_val < umax_ptr) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value = umin_ptr + umin_val;
dst_reg->umax_value = umax_ptr + umax_val;
}
dst_reg->var_off = tnum_add(ptr_reg->var_off, off_reg->var_off);
dst_reg->off = ptr_reg->off;
dst_reg->raw = ptr_reg->raw;
if (reg_is_pkt_pointer(ptr_reg)) {
dst_reg->id = ++env->id_gen;
memset(&dst_reg->raw, 0, sizeof(dst_reg->raw));
}
break;
case BPF_SUB:
if (dst_reg == off_reg) {
verbose(env, "R%d tried to subtract pointer from scalar\n",
dst);
return -EACCES;
}
if (ptr_reg->type == PTR_TO_STACK) {
verbose(env, "R%d subtraction from stack pointer prohibited\n",
dst);
return -EACCES;
}
if (known && (ptr_reg->off - smin_val ==
(s64)(s32)(ptr_reg->off - smin_val))) {
dst_reg->smin_value = smin_ptr;
dst_reg->smax_value = smax_ptr;
dst_reg->umin_value = umin_ptr;
dst_reg->umax_value = umax_ptr;
dst_reg->var_off = ptr_reg->var_off;
dst_reg->id = ptr_reg->id;
dst_reg->off = ptr_reg->off - smin_val;
dst_reg->raw = ptr_reg->raw;
break;
}
if (signed_sub_overflows(smin_ptr, smax_val) ||
signed_sub_overflows(smax_ptr, smin_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = smin_ptr - smax_val;
dst_reg->smax_value = smax_ptr - smin_val;
}
if (umin_ptr < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value = umin_ptr - umax_val;
dst_reg->umax_value = umax_ptr - umin_val;
}
dst_reg->var_off = tnum_sub(ptr_reg->var_off, off_reg->var_off);
dst_reg->off = ptr_reg->off;
dst_reg->raw = ptr_reg->raw;
if (reg_is_pkt_pointer(ptr_reg)) {
dst_reg->id = ++env->id_gen;
if (smin_val < 0)
memset(&dst_reg->raw, 0, sizeof(dst_reg->raw));
}
break;
case BPF_AND:
case BPF_OR:
case BPF_XOR:
verbose(env, "R%d bitwise operator %s on pointer prohibited\n",
dst, bpf_alu_string[opcode >> 4]);
return -EACCES;
default:
verbose(env, "R%d pointer arithmetic with %s operator prohibited\n",
dst, bpf_alu_string[opcode >> 4]);
return -EACCES;
}
if (!check_reg_sane_offset(env, dst_reg, ptr_reg->type))
return -EINVAL;
__update_reg_bounds(dst_reg);
__reg_deduce_bounds(dst_reg);
__reg_bound_offset(dst_reg);
if (sanitize_check_bounds(env, insn, dst_reg) < 0)
return -EACCES;
if (sanitize_needed(opcode)) {
ret = sanitize_ptr_alu(env, insn, dst_reg, off_reg, dst_reg,
&info, true);
if (ret < 0)
return sanitize_err(env, insn, ret, off_reg, dst_reg);
}
return 0;
},0

int ssl3_generate_master_secret(SSL *s, unsigned char *out, unsigned char *p,
int len)
{
static const unsigned char *salt[3]={
#ifndef CHARSET_EBCDIC
(const unsigned char *)"A",
(const unsigned char *)"BB",
(const unsigned char *)"CCC",
#else
(const unsigned char *)"\x41",
(const unsigned char *)"\x42\x42",
(const unsigned char *)"\x43\x43\x43",
#endif
};
unsigned char buf[EVP_MAX_MD_SIZE];
EVP_MD_CTX ctx;
int i,ret=0;
unsigned int n;
EVP_MD_CTX_init(&ctx);
for (i=0; i<3; i++)
{
EVP_DigestInit_ex(&ctx,s->ctx->sha1, NULL);
EVP_DigestUpdate(&ctx,salt[i],strlen((const char *)salt[i]));
EVP_DigestUpdate(&ctx,p,len);
EVP_DigestUpdate(&ctx,&(s->s3->client_random[0]),
SSL3_RANDOM_SIZE);
EVP_DigestUpdate(&ctx,&(s->s3->server_random[0]),
SSL3_RANDOM_SIZE);
EVP_DigestFinal_ex(&ctx,buf,&n);
EVP_DigestInit_ex(&ctx,s->ctx->md5, NULL);
EVP_DigestUpdate(&ctx,p,len);
EVP_DigestUpdate(&ctx,buf,n);
EVP_DigestFinal_ex(&ctx,out,&n);
out+=n;
ret+=n;
}
EVP_MD_CTX_cleanup(&ctx);
return(ret);
},0

static av_cold int vqa_decode_init(AVCodecContext *avctx)
{
VqaContext *s = avctx->priv_data;
int i, j, codebook_index, ret;
s->avctx = avctx;
avctx->pix_fmt = AV_PIX_FMT_PAL8;
if (s->avctx->extradata_size != VQA_HEADER_SIZE) {
av_log(s->avctx, AV_LOG_ERROR, "expected extradata size of %d\n", VQA_HEADER_SIZE);
return AVERROR(EINVAL);
}
s->vqa_version = s->avctx->extradata[0];
switch (s->vqa_version) {
case 1:
case 2:
break;
case 3:
avpriv_report_missing_feature(avctx, "VQA Version %d", s->vqa_version);
return AVERROR_PATCHWELCOME;
default:
avpriv_request_sample(avctx, "VQA Version %i", s->vqa_version);
return AVERROR_PATCHWELCOME;
}
s->width = AV_RL16(&s->avctx->extradata[6]);
s->height = AV_RL16(&s->avctx->extradata[8]);
if ((ret = av_image_check_size(s->width, s->height, 0, avctx)) < 0) {
s->width= s->height= 0;
return ret;
}
s->vector_width = s->avctx->extradata[10];
s->vector_height = s->avctx->extradata[11];
s->partial_count = s->partial_countdown = s->avctx->extradata[13];
if ((s->vector_width != 4) ||
((s->vector_height != 2) && (s->vector_height != 4))) {
return AVERROR_INVALIDDATA;
}
if (s->width % s->vector_width || s->height % s->vector_height) {
av_log(avctx, AV_LOG_ERROR, "Image size not multiple of block size\n");
return AVERROR_INVALIDDATA;
}
s->codebook_size = MAX_CODEBOOK_SIZE;
s->codebook = av_malloc(s->codebook_size);
if (!s->codebook)
goto fail;
s->next_codebook_buffer = av_malloc(s->codebook_size);
if (!s->next_codebook_buffer)
goto fail;
s->decode_buffer_size = (s->width / s->vector_width) *
(s->height / s->vector_height) * 2;
s->decode_buffer = av_mallocz(s->decode_buffer_size);
if (!s->decode_buffer)
goto fail;
if (s->vector_height == 4) {
codebook_index = 0xFF00 * 16;
for (i = 0; i < 256; i++)
for (j = 0; j < 16; j++)
s->codebook[codebook_index++] = i;
} else {
codebook_index = 0xF00 * 8;
for (i = 0; i < 256; i++)
for (j = 0; j < 8; j++)
s->codebook[codebook_index++] = i;
}
s->next_codebook_buffer_index = 0;
return 0;
fail:
av_freep(&s->codebook);
av_freep(&s->next_codebook_buffer);
av_freep(&s->decode_buffer);
return AVERROR(ENOMEM);
},1

void show_help( void )
{
fprintf(msgout, "Usage: %s [switches] input_file [output_file]", appname );
fprintf(msgout, "\n" );
fprintf(msgout, "\n" );
fprintf(msgout, " [-version] File format version of lepton codec\n" );
fprintf(msgout, " [-revision] GIT Hash of lepton source that built this binary\n");
fprintf(msgout, " [-zlib0] Instead of a jpg, return a zlib-compressed jpeg\n");
fprintf(msgout, " [-startbyte=<n>] Encoded file will only contain data at and after <n>\n");
fprintf(msgout, " [-trunc=<n>] Encoded file will be truncated at size <n> - startbyte\n");
fprintf(msgout, " [-unjailed] Do not jail this process (use only with trusted data)\n" );
fprintf(msgout, " [-singlethread] Do not clone threads to operate on the input file\n" );
fprintf(msgout, " [-maxencodethreads=<n>] Can use <n> threads to decode: higher=bigger file\n");
fprintf(msgout, " [-allowprogressive] Allow progressive jpegs through the compressor\n");
fprintf(msgout, " [-rejectprogressive] Reject encoding of progressive jpegs\n");
fprintf(msgout, " [-timebound=<>ms]For -socket, enforce a timeout since first byte received\n");
fprintf(msgout, " [-lepcat] Concatenate lepton files together into a file that contains multiple substrings\n");
fprintf(msgout, " [-memory=<>M] Upper bound on the amount of memory allocated by main\n");
fprintf(msgout, " [-threadmemory=<>M] Bound on the amount of memory allocated by threads\n");
fprintf(msgout, " [-recodememory=<>M] Check that a singlethreaded recode only uses <>M mem\n");
#ifndef _WIN32
fprintf(msgout, " [-hugepages] Allocate from the hugepages on the system\n");
fprintf(msgout, " [-socket=<name>] Serve requests on a Unix Domain Socket at path <name>\n" );
fprintf(msgout, " [-listen=<port>] Serve requests on a TCP socket on <port> (default 2402)\n" );
fprintf(msgout, " [-listenbacklog=<n>] n clients queued for encoding if maxchildren reached\n" );
fprintf(msgout, " [-zliblisten=<port>] Serve requests on a TCP socket on <port> (def 2403)\n" );
fprintf(msgout, " [-maxchildren] Max codes to ever spawn at the same time in socket mode\n");
#endif
fprintf(msgout, " [-benchmark] Run a benchmark on optional [<input_file>] (or included file)\n");
fprintf(msgout, " [-verbose] Run the benchmark in verbose mode (more output to stderr)\n");
fprintf(msgout, " [-benchreps=<n>] Number of trials to run the benchmark for each category\n");
fprintf(msgout, " [-benchthreads=<n>] Max number of parallel codings to benchmark\n");
#ifdef SKIP_VALIDATION
fprintf(msgout, " [-validate] Round-trip this file when encoding [default:off]\n");
#else
fprintf(msgout, " [-validate] Round-trip this file when encoding [default:on]\n");
fprintf(msgout, " [-skipvalidate] Avoid round-trip check when encoding (Warning: unsafe)\n");
#endif
},0

stf_status ikev2parent_inR2(struct msg_digest *md)
{
struct state *st = md->st;
struct connection *c = st->st_connection;
unsigned char *idhash_in;
struct state *pst = st;
if (st->st_clonedfrom != 0)
pst = state_with_serialno(st->st_clonedfrom);
DBG(DBG_CONTROLMORE,
DBG_log(
"ikev2 parent inR2: calculating g^{xy} in order to decrypt I2"));
if (!md->chain[ISAKMP_NEXT_v2E]) {
libreswan_log("R2 state should receive an encrypted payload");
return STF_FATAL;
}
{
stf_status ret;
ret = ikev2_decrypt_msg(md, INITIATOR);
if (ret != STF_OK)
return ret;
}
if (!ikev2_decode_peer_id(md, INITIATOR))
return STF_FAIL + v2N_AUTHENTICATION_FAILED;
{
struct hmac_ctx id_ctx;
const pb_stream *id_pbs = &md->chain[ISAKMP_NEXT_v2IDr]->pbs;
unsigned char *idstart = id_pbs->start + 4;
unsigned int idlen = pbs_room(id_pbs) - 4;
hmac_init_chunk(&id_ctx, pst->st_oakley.prf_hasher,
pst->st_skey_pr);
DBG(DBG_CRYPT,
DBG_dump_chunk("idhash verify pr", pst->st_skey_pr));
DBG(DBG_CRYPT, DBG_dump("idhash auth R2", idstart, idlen));
hmac_update(&id_ctx, idstart, idlen);
idhash_in = alloca(pst->st_oakley.prf_hasher->hash_digest_len);
hmac_final(idhash_in, &id_ctx);
}
if (md->chain[ISAKMP_NEXT_v2CERT]) {
DBG(DBG_CONTROLMORE,
DBG_log("has a v2_CERT payload going to decode it"));
ikev2_decode_cert(md);
}
if (!md->chain[ISAKMP_NEXT_v2AUTH]) {
libreswan_log("no authentication payload found");
return STF_FAIL;
}
switch (md->chain[ISAKMP_NEXT_v2AUTH]->payload.v2a.isaa_type) {
case v2_AUTH_RSA:
{
stf_status authstat = ikev2_verify_rsa_sha1(pst,
INITIATOR,
idhash_in,
NULL,
NULL,
&md->chain[
ISAKMP_NEXT_v2AUTH]->pbs);
if (authstat != STF_OK) {
libreswan_log("authentication failed");
SEND_NOTIFICATION(v2N_AUTHENTICATION_FAILED);
return STF_FAIL;
}
break;
}
case v2_AUTH_SHARED:
{
stf_status authstat = ikev2_verify_psk_auth(pst,
INITIATOR,
idhash_in,
&md->chain[
ISAKMP_NEXT_v2AUTH]->pbs);
if (authstat != STF_OK) {
libreswan_log("PSK authentication failed");
SEND_NOTIFICATION(v2N_AUTHENTICATION_FAILED);
return STF_FAIL;
}
break;
}
default:
libreswan_log("authentication method: %s not supported",
enum_name(&ikev2_auth_names,
md->chain[ISAKMP_NEXT_v2AUTH]->payload.
v2a.isaa_type));
return STF_FAIL;
}
change_state(pst, STATE_PARENT_I3);
c->newest_isakmp_sa = pst->st_serialno;
if (md->chain[ISAKMP_NEXT_v2SA] == NULL ||
md->chain[ISAKMP_NEXT_v2TSi] == NULL ||
md->chain[ISAKMP_NEXT_v2TSr] == NULL) {
DBG(DBG_CONTROLMORE,
DBG_log(
"no v2SA, v2TSi or v2TSr received, not attempting to setup child SA"));
DBG(DBG_CONTROLMORE,
DBG_log(" Should we check for some notify?"));
delete_event(st);
return STF_OK;
