FileInputSource::read(char* buffer, size_t length)
{
this->last_offset = this->tell();
size_t len = fread(buffer, 1, length, this->file);
if (len == 0)
{
if (ferror(this->file))
{
throw QPDFExc(qpdf_e_system,
this->filename, "",
this->last_offset,
std::string("read ") +
QUtil::int_to_string(length) + " bytes");
}
else if (length > 0)
{
this->seek(0, SEEK_END);
this->last_offset = this->tell();
}
}
return len;
},1

rfbSendFramebufferUpdate(rfbClientPtr cl,
sraRegionPtr givenUpdateRegion)
{
sraRectangleIterator* i=NULL;
sraRect rect;
int nUpdateRegionRects;
rfbFramebufferUpdateMsg *fu = (rfbFramebufferUpdateMsg *)cl->updateBuf;
sraRegionPtr updateRegion, updateCopyRegion, tmpRegion, cursorRegion;
sraRect cursorBounds = { 0, 0, 0, 0 };
int dx, dy;
rfbBool sendCursorShape = FALSE;
rfbBool sendCursorPos = FALSE;
rfbBool cursorIsDrawn = FALSE;
if (cl->useNewFBSize && cl->newFBSizePending) {
LOCK(cl->updateMutex);
cl->newFBSizePending = FALSE;
UNLOCK(cl->updateMutex);
cl->rfbFramebufferUpdateMessagesSent++;
fu->type = rfbFramebufferUpdate;
fu->nRects = Swap16IfLE(1);
cl->ublen = sz_rfbFramebufferUpdateMsg;
if (!rfbSendNewFBSize(cl, cl->screen->width, cl->screen->height)) {
return FALSE;
}
return rfbSendUpdateBuf(cl);
}
LOCK(cl->updateMutex);
sraRgnSubtract(cl->copyRegion,cl->modifiedRegion);
updateRegion = sraRgnCreateRgn(givenUpdateRegion);
sraRgnOr(updateRegion,cl->copyRegion);
LOCK(cl->screen->cursorMutex);
cursorRegion = NULL;
if (cl->enableCursorUpdates) {
sendCursorShape = cl->cursorWasChanged;
sendCursorPos = cl->cursorWasMoved;
} else {
sraRegionPtr lastDrawnCursorRegion;
if (rfbGetCursorBounds(cl->screen, &cursorBounds)) {
cursorRegion = sraRgnCreateRect(cursorBounds.x1, cursorBounds.y1,
cursorBounds.x2, cursorBounds.y2);
}
lastDrawnCursorRegion = sraRgnCreateRect(cl->lastDrawnCursorBounds.x1,
cl->lastDrawnCursorBounds.y1,
cl->lastDrawnCursorBounds.x2,
cl->lastDrawnCursorBounds.y2);
if (cursorRegion) {
sraRgnOr(cursorRegion, lastDrawnCursorRegion);
sraRgnDestroy(lastDrawnCursorRegion);
} else {
cursorRegion = lastDrawnCursorRegion;
}
if (cl->cursorWasChanged || cl->cursorWasMoved)
sraRgnOr(updateRegion, cursorRegion);
}
if (!sraRgnAnd(updateRegion, cl->requestedRegion) &&
!sendCursorShape && !sendCursorPos) {
sraRgnDestroy(updateRegion);
if (cursorRegion)
sraRgnDestroy(cursorRegion);
UNLOCK(cl->updateMutex);
UNLOCK(cl->cursorMutex);
return TRUE;
}
if (cursorRegion) {
tmpRegion = sraRgnCreateRgn(cursorRegion);
if (sraRgnAnd(tmpRegion, updateRegion)) {
rfbDrawCursor(cl->screen, &cursorBounds);
cursorIsDrawn = TRUE;
cl->cursorWasMoved = FALSE;
cl->cursorWasChanged = FALSE;
cl->lastDrawnCursorBounds = cursorBounds;
sraRgnOr(cl->modifiedRegion, cursorRegion);
sraRgnOr(updateRegion, cursorRegion);
sraRgnAnd(updateRegion, cl->requestedRegion);
}
sraRgnDestroy(tmpRegion);
sraRgnDestroy(cursorRegion);
}
updateCopyRegion = sraRgnCreateRgn(cl->copyRegion);
sraRgnAnd(updateCopyRegion,cl->requestedRegion);
tmpRegion = sraRgnCreateRgn(cl->requestedRegion);
sraRgnOffset(tmpRegion,cl->copyDX,cl->copyDY);
sraRgnAnd(updateCopyRegion,tmpRegion);
sraRgnDestroy(tmpRegion);
dx = cl->copyDX;
dy = cl->copyDY;
sraRgnSubtract(updateRegion,updateCopyRegion);
sraRgnOr(cl->modifiedRegion,cl->copyRegion);
sraRgnSubtract(cl->modifiedRegion,updateRegion);
sraRgnSubtract(cl->modifiedRegion,updateCopyRegion);
sraRgnMakeEmpty(cl->requestedRegion);
sraRgnMakeEmpty(cl->copyRegion);
cl->copyDX = 0;
cl->copyDY = 0;
UNLOCK(cl->updateMutex);
cl->rfbFramebufferUpdateMessagesSent++;
if (cl->preferredEncoding == rfbEncodingCoRRE) {
nUpdateRegionRects = 0;
for(i = sraRgnGetIterator(updateRegion); sraRgnIteratorNext(i,&rect);){
int x = rect.x1;
int y = rect.y1;
int w = rect.x2 - x;
int h = rect.y2 - y;
nUpdateRegionRects += (((w-1) / cl->correMaxWidth + 1)
* ((h-1) / cl->correMaxHeight + 1));
}
sraRgnReleaseIterator(i);
#ifdef HAVE_LIBZ
} else if (cl->preferredEncoding == rfbEncodingZlib) {
nUpdateRegionRects = 0;
for(i = sraRgnGetIterator(updateRegion); sraRgnIteratorNext(i,&rect);){
int x = rect.x1;
int y = rect.y1;
int w = rect.x2 - x;
int h = rect.y2 - y;
nUpdateRegionRects += (((h-1) / (ZLIB_MAX_SIZE( w ) / w)) + 1);
}
#ifdef HAVE_LIBJPEG
} else if (cl->preferredEncoding == rfbEncodingTight) {
nUpdateRegionRects = 0;
for(i = sraRgnGetIterator(updateRegion); sraRgnIteratorNext(i,&rect);){
int x = rect.x1;
int y = rect.y1;
int w = rect.x2 - x;
int h = rect.y2 - y;
int n = rfbNumCodedRectsTight(cl, x, y, w, h);
if (n == 0) {
nUpdateRegionRects = 0xFFFF;
break;
}
nUpdateRegionRects += n;
}
sraRgnReleaseIterator(i);
#endif
#endif
} else {
nUpdateRegionRects = sraRgnCountRects(updateRegion);
}
fu->type = rfbFramebufferUpdate;
if (nUpdateRegionRects != 0xFFFF) {
if(cl->screen->maxRectsPerUpdate>0
&& cl->preferredEncoding != rfbEncodingCoRRE
#ifdef HAVE_LIBZ
&& cl->preferredEncoding != rfbEncodingZlib
#ifdef HAVE_LIBJPEG
&& cl->preferredEncoding != rfbEncodingTight
#endif
#endif
&& nUpdateRegionRects>cl->screen->maxRectsPerUpdate) {
sraRegion* newUpdateRegion = sraRgnBBox(updateRegion);
sraRgnDestroy(updateRegion);
updateRegion = newUpdateRegion;
nUpdateRegionRects = sraRgnCountRects(updateRegion);
}
fu->nRects = Swap16IfLE((uint16_t)(sraRgnCountRects(updateCopyRegion) +
nUpdateRegionRects +
!!sendCursorShape + !!sendCursorPos));
} else {
fu->nRects = 0xFFFF;
}
cl->ublen = sz_rfbFramebufferUpdateMsg;
UNLOCK(cl->cursorMutex);
if (sendCursorShape) {
cl->cursorWasChanged = FALSE;
if (!rfbSendCursorShape(cl))
goto tx_error;
}
if (sendCursorPos) {
cl->cursorWasMoved = FALSE;
if (!rfbSendCursorPos(cl))
goto tx_error;
}
if (!sraRgnEmpty(updateCopyRegion)) {
if (!rfbSendCopyRegion(cl,updateCopyRegion,dx,dy))
goto tx_error;
}
for(i = sraRgnGetIterator(updateRegion); sraRgnIteratorNext(i,&rect);){
int x = rect.x1;
int y = rect.y1;
int w = rect.x2 - x;
int h = rect.y2 - y;
cl->rfbRawBytesEquivalent += (sz_rfbFramebufferUpdateRectHeader
+ w * (cl->format.bitsPerPixel / 8) * h);
switch (cl->preferredEncoding) {
case rfbEncodingRaw:
if (!rfbSendRectEncodingRaw(cl, x, y, w, h))
goto tx_error;
break;
case rfbEncodingRRE:
if (!rfbSendRectEncodingRRE(cl, x, y, w, h))
goto tx_error;
break;
case rfbEncodingCoRRE:
if (!rfbSendRectEncodingCoRRE(cl, x, y, w, h))
goto tx_error;
break;
case rfbEncodingHextile:
if (!rfbSendRectEncodingHextile(cl, x, y, w, h))
goto tx_error;
break;
#ifdef HAVE_LIBZ
case rfbEncodingZlib:
if (!rfbSendRectEncodingZlib(cl, x, y, w, h))
goto tx_error;
break;
#ifdef HAVE_LIBJPEG
case rfbEncodingTight:
if (!rfbSendRectEncodingTight(cl, x, y, w, h))
goto tx_error;
break;
#endif
#endif
#ifdef HAVE_LIBZ
case rfbEncodingZRLE:
if (!rfbSendRectEncodingZRLE(cl, x, y, w, h))
goto tx_error;
break;
#endif
}
}
if (cursorIsDrawn)
rfbUndrawCursor(cl->screen, &cursorBounds);
if ( nUpdateRegionRects == 0xFFFF &&
!rfbSendLastRectMarker(cl) )
goto tx_error;
if (!rfbSendUpdateBuf(cl))
goto tx_error;
sraRgnReleaseIterator(i);
sraRgnDestroy(updateCopyRegion);
sraRgnDestroy(updateRegion);
return TRUE;
tx_error:
if (cursorIsDrawn)
rfbUndrawCursor(cl->screen, &cursorBounds);
if (i)
sraRgnReleaseIterator(i);
sraRgnDestroy(updateCopyRegion);
sraRgnDestroy(updateRegion);
return FALSE;
},1

key_share_send_params(gnutls_session_t session,
gnutls_buffer_st * extdata)
{
unsigned i;
int ret;
unsigned char *lengthp;
unsigned int cur_length;
unsigned int generated = 0;
const gnutls_group_entry_st *group;
const version_entry_st *ver;
if (session->security_parameters.entity == GNUTLS_CLIENT) {
ver = _gnutls_version_max(session);
if (unlikely(ver == NULL || ver->key_shares == 0))
return 0;
if (!have_creds_for_tls13(session))
return 0;
lengthp = &extdata->data[extdata->length];
ret =
_gnutls_buffer_append_prefix(extdata, 16, 0);
if (ret < 0)
return gnutls_assert_val(ret);
cur_length = extdata->length;
if (session->internals.hsk_flags & HSK_HRR_RECEIVED) {
group = get_group(session);
if (unlikely(group == NULL))
return gnutls_assert_val(GNUTLS_E_RECEIVED_ILLEGAL_PARAMETER);
ret = client_gen_key_share(session, group, extdata);
if (ret == GNUTLS_E_INT_RET_0)
return gnutls_assert_val(GNUTLS_E_NO_COMMON_KEY_SHARE);
if (ret < 0)
return gnutls_assert_val(ret);
} else {
gnutls_pk_algorithm_t selected_groups[3];
unsigned max_groups = 2;
if (session->internals.flags & GNUTLS_KEY_SHARE_TOP)
max_groups = 1;
else if (session->internals.flags & GNUTLS_KEY_SHARE_TOP3)
max_groups = 3;
assert(max_groups <= sizeof(selected_groups)/sizeof(selected_groups[0]));
for (i = 0; i < session->internals.priorities->groups.size; i++) {
group = session->internals.priorities->groups.entry[i];
if (generated == 1 && group->pk == selected_groups[0])
continue;
else if (generated == 2 && (group->pk == selected_groups[1] || group->pk == selected_groups[0]))
continue;
selected_groups[generated] = group->pk;
ret = client_gen_key_share(session, group, extdata);
if (ret == GNUTLS_E_INT_RET_0)
continue;
if (ret < 0)
return gnutls_assert_val(ret);
generated++;
if (generated >= max_groups)
break;
}
}
_gnutls_write_uint16(extdata->length - cur_length, lengthp);
} else {
ver = get_version(session);
if (unlikely(ver == NULL || ver->key_shares == 0))
return gnutls_assert_val(0);
if (_gnutls_ext_get_msg(session) == GNUTLS_EXT_FLAG_HRR) {
group = session->internals.cand_group;
if (group == NULL)
return gnutls_assert_val(GNUTLS_E_NO_COMMON_KEY_SHARE);
_gnutls_session_group_set(session, group);
_gnutls_handshake_log("EXT[%p]: requesting retry with group %s\n", session, group->name);
ret =
_gnutls_buffer_append_prefix(extdata, 16, group->tls_id);
if (ret < 0)
return gnutls_assert_val(ret);
} else {
if ((session->internals.hsk_flags & HSK_PSK_SELECTED) &&
(session->internals.hsk_flags & HSK_PSK_KE_MODE_PSK))
return gnutls_assert_val(0);
group = get_group(session);
if (unlikely(group == NULL))
return gnutls_assert_val(GNUTLS_E_RECEIVED_ILLEGAL_PARAMETER);
ret = server_gen_key_share(session, group, extdata);
if (ret < 0)
return gnutls_assert_val(ret);
}
session->internals.hsk_flags |= HSK_KEY_SHARE_SENT;
}
return 0;
},1

REDIS_STATIC int _quicklistNodeAllowInsert(const quicklistNode *node,
const int fill, const size_t sz) {
if (unlikely(!node))
return 0;
int ziplist_overhead;
if (sz < 254)
ziplist_overhead = 1;
else
ziplist_overhead = 5;
if (sz < 64)
ziplist_overhead += 1;
else if (likely(sz < 16384))
ziplist_overhead += 2;
else
ziplist_overhead += 5;
unsigned int new_sz = node->sz + sz + ziplist_overhead;
if (likely(_quicklistNodeSizeMeetsOptimizationRequirement(new_sz, fill)))
return 1;
else if (!sizeMeetsSafetyLimit(new_sz))
return 0;
else if ((int)node->count < fill)
return 1;
else
return 0;
},1

ncp_get_volume_root(struct ncp_server *server,
const char *volname, __u32* volume, __le32* dirent, __le32* dosdirent)
{
int result;
ncp_dbg(1, "looking up vol %s\n", volname);
ncp_init_request(server);
ncp_add_byte(server, 22);
ncp_add_byte(server, 0);
ncp_add_byte(server, 0);
ncp_add_byte(server, 0);
ncp_add_byte(server, 0);
ncp_add_byte(server, 0);
ncp_add_dword(server, 0);
ncp_add_byte(server, 0xff);
ncp_add_byte(server, 1);
ncp_add_pstring(server, volname);
if ((result = ncp_request(server, 87)) != 0) {
ncp_unlock_server(server);
return result;
}
