{
case 0:
size = ReadBlobXXXLong(image2);
size = 4 * (ssize_t) ((size + 3 + 1) / 4);
(void) SeekBlob(image2, size, SEEK_CUR);
break;
case 1:
case 2:
case 3:
case 4:
(void) ReadBlob(image2, 4, (unsigned char *) &size);
break;
default:
goto MATLAB_KO;
