long2str(c+4,length);
if( avi_write(AVI->fdes,(char *)c,8) != 8 ||
avi_write(AVI->fdes,(char *)data,length) != length ||
avi_write(AVI->fdes,&p,length&1) != (length&1))
{
gf_fseek(AVI->fdes,AVI->pos,SEEK_SET);
AVI_errno = AVI_ERR_WRITE;
return -1;
}
AVI->pos += 8 + PAD_EVEN(length);
return 0;
