clibcode = compname_to_clibcode(compname);
clibname = clibcode_to_clibname(clibcode);
if (clibcode == BLOSC_BLOSCLZ_LIB) {
clibversion = BLOSCLZ_VERSION_STRING;
}
#if defined(HAVE_LZ4)
else if (clibcode == BLOSC_LZ4_LIB) {
#if defined(LZ4_VERSION_MAJOR)
sprintf(sbuffer, "%d.%d.%d",
LZ4_VERSION_MAJOR, LZ4_VERSION_MINOR, LZ4_VERSION_RELEASE);
clibversion = sbuffer;
#endif
}
#endif
#if defined(HAVE_LIZARD)
else if (clibcode == BLOSC_LIZARD_LIB) {
sprintf(sbuffer, "%d.%d.%d",
LIZARD_VERSION_MAJOR, LIZARD_VERSION_MINOR, LIZARD_VERSION_RELEASE);
clibversion = sbuffer;
}
#endif
#if defined(HAVE_SNAPPY)
else if (clibcode == BLOSC_SNAPPY_LIB) {
#if defined(SNAPPY_VERSION)
sprintf(sbuffer, "%d.%d.%d", SNAPPY_MAJOR, SNAPPY_MINOR, SNAPPY_PATCHLEVEL);
clibversion = sbuffer;
#endif
}
#endif
#if defined(HAVE_ZLIB)
else if (clibcode == BLOSC_ZLIB_LIB) {
clibversion = ZLIB_VERSION;
}
#endif
#if defined(HAVE_ZSTD)
else if (clibcode == BLOSC_ZSTD_LIB) {
sprintf(sbuffer, "%d.%d.%d",
ZSTD_VERSION_MAJOR, ZSTD_VERSION_MINOR, ZSTD_VERSION_RELEASE);
clibversion = sbuffer;
}
#endif
#ifdef _MSC_VER
*complib = _strdup(clibname);
*version = _strdup(clibversion);
#else
*complib = strdup(clibname);
*version = strdup(clibversion);
#endif
return clibcode;
},0

static UINT drive_process_irp_query_volume_information(DRIVE_DEVICE* drive, IRP* irp)
{
UINT32 FsInformationClass;
wStream* output = NULL;
char* volumeLabel = { "FREERDP" };
char* diskType = { "FAT32" };
WCHAR* outStr = NULL;
int length;
DWORD lpSectorsPerCluster;
DWORD lpBytesPerSector;
DWORD lpNumberOfFreeClusters;
DWORD lpTotalNumberOfClusters;
WIN32_FILE_ATTRIBUTE_DATA wfad;
if (!drive || !irp)
return ERROR_INVALID_PARAMETER;
output = irp->output;
if (Stream_GetRemainingLength(irp->input) < 4)
return ERROR_INVALID_DATA;
Stream_Read_UINT32(irp->input, FsInformationClass);
GetDiskFreeSpaceW(drive->path, &lpSectorsPerCluster, &lpBytesPerSector, &lpNumberOfFreeClusters,
&lpTotalNumberOfClusters);
switch (FsInformationClass)
{
case FileFsVolumeInformation:
if (!Stream_EnsureRemainingCapacity(output, 17 + length))
{
WLog_ERR(TAG, "Stream_EnsureRemainingCapacity failed!");
free(outStr);
return CHANNEL_RC_NO_MEMORY;
}
GetFileAttributesExW(drive->path, GetFileExInfoStandard, &wfad);
Stream_Write_UINT32(output, wfad.ftCreationTime.dwLowDateTime);
Stream_Write_UINT32(output,
wfad.ftCreationTime.dwHighDateTime);
Stream_Write_UINT32(output, lpNumberOfFreeClusters & 0xffff);
Stream_Write_UINT32(output, length);
Stream_Write_UINT8(output, 0);
Stream_Write(output, outStr, length);
free(outStr);
break;
case FileFsSizeInformation:
if (!Stream_EnsureRemainingCapacity(output, 24))
{
WLog_ERR(TAG, "Stream_EnsureRemainingCapacity failed!");
return CHANNEL_RC_NO_MEMORY;
}
Stream_Write_UINT64(output, lpTotalNumberOfClusters);
Stream_Write_UINT64(output, lpNumberOfFreeClusters);
Stream_Write_UINT32(output, lpSectorsPerCluster);
Stream_Write_UINT32(output, lpBytesPerSector);
break;
case FileFsAttributeInformation:
if (!Stream_EnsureRemainingCapacity(output, 12 + length))
{
free(outStr);
WLog_ERR(TAG, "Stream_EnsureRemainingCapacity failed!");
return CHANNEL_RC_NO_MEMORY;
}
Stream_Write_UINT32(output, FILE_CASE_SENSITIVE_SEARCH | FILE_CASE_PRESERVED_NAMES |
FILE_UNICODE_ON_DISK);
Stream_Write_UINT32(output, MAX_PATH);
Stream_Write_UINT32(output, length);
Stream_Write(output, outStr, length);
free(outStr);
break;
case FileFsFullSizeInformation:
if (!Stream_EnsureRemainingCapacity(output, 32))
{
WLog_ERR(TAG, "Stream_EnsureRemainingCapacity failed!");
return CHANNEL_RC_NO_MEMORY;
}
Stream_Write_UINT64(output, lpTotalNumberOfClusters);
Stream_Write_UINT64(output,
lpNumberOfFreeClusters);
Stream_Write_UINT64(output, lpNumberOfFreeClusters);
Stream_Write_UINT32(output, lpSectorsPerCluster);
Stream_Write_UINT32(output, lpBytesPerSector);
break;
case FileFsDeviceInformation:
if (!Stream_EnsureRemainingCapacity(output, 8))
{
WLog_ERR(TAG, "Stream_EnsureRemainingCapacity failed!");
return CHANNEL_RC_NO_MEMORY;
}
Stream_Write_UINT32(output, FILE_DEVICE_DISK);
Stream_Write_UINT32(output, 0);
break;
default:
irp->IoStatus = STATUS_UNSUCCESSFUL;
Stream_Write_UINT32(output, 0);
break;
}
return irp->Complete(irp);
},0

int ext4_write_inode(struct inode *inode, struct writeback_control *wbc)
{
int err;
if (WARN_ON_ONCE(current->flags & PF_MEMALLOC) ||
sb_rdonly(inode->i_sb))
return 0;
if (unlikely(ext4_forced_shutdown(EXT4_SB(inode->i_sb))))
return -EIO;
if (EXT4_SB(inode->i_sb)->s_journal) {
if (ext4_journal_current_handle()) {
jbd_debug(1, "called recursively, non-PF_MEMALLOC!\n");
dump_stack();
return -EIO;
}
if (wbc->sync_mode != WB_SYNC_ALL || wbc->for_sync)
return 0;
err = jbd2_complete_transaction(EXT4_SB(inode->i_sb)->s_journal,
EXT4_I(inode)->i_sync_tid);
} else {
struct ext4_iloc iloc;
err = __ext4_get_inode_loc(inode, &iloc, 0);
if (err)
return err;
if (wbc->sync_mode == WB_SYNC_ALL && !wbc->for_sync)
sync_dirty_buffer(iloc.bh);
if (buffer_req(iloc.bh) && !buffer_uptodate(iloc.bh)) {
ext4_error_inode_block(inode, iloc.bh->b_blocknr, EIO,
"IO error syncing inode");
err = -EIO;
}
brelse(iloc.bh);
}
return err;
},0

int regcomp(regex_t *preg, const char *pattern, int cflags)
{
conopt_t globopts;
globopts.nested_negative_tags = !(cflags & (REG_NFA | REG_REGLESS));
globopts.FFlag = true;
globopts.backward = cflags & REG_BACKWARD;
globopts.stadfa = cflags & REG_STADFA;
Msg msg;
Opt opts(globopts, msg);
opts.set_subhistories((cflags & REG_SUBHIST) != 0);
opts.set_autotags((cflags & REG_AUTOTAGS) != 0);
opts.set_posix_syntax(true);
opts.set_posix_semantics((cflags & REG_LEFTMOST) == 0);
const opt_t *opt = opts.snapshot();
preg->flags = cflags;
const AST *a = parse(pattern);
preg->rmgr = new RangeMgr;
ASTRule ar(a, new SemAct(NOWHERE));
std::vector<ASTRule> arv;
arv.push_back(ar);
RESpec re(arv, opt, msg, *preg->rmgr);
find_fixed_tags(re);
insert_default_tags(re);
nfa_t *nfa = new nfa_t(re);
nfa_t *nfa0 = NULL;
if (cflags & REG_BACKWARD) {
conopt_t globopts0;
globopts0.FFlag = true;
Opt opts0(globopts0, msg);
const opt_t *opt0 = opts0.snapshot();
RESpec re0(arv, opt0, msg, *preg->rmgr);
nfa0 = new nfa_t(re0);
delete opt0;
}
dfa_t *dfa = NULL;
rldfa_t *rldfa = NULL;
if (cflags & REG_NFA) {
if ((cflags & REG_TRIE) && (cflags & REG_LEFTMOST)) {
preg->simctx = new lzsimctx_t(*nfa, nfa0, preg->re_nsub, cflags);
} else if (cflags & REG_TRIE) {
preg->simctx = new pzsimctx_t(*nfa, nfa0, preg->re_nsub, cflags);
} else if (cflags & REG_LEFTMOST) {
preg->simctx = new lsimctx_t(*nfa, nfa0, preg->re_nsub, cflags);
} else if (cflags & REG_KUKLEWICZ) {
preg->simctx = new ksimctx_t(*nfa, nfa0, preg->re_nsub, cflags);
} else {
preg->simctx = new psimctx_t(*nfa, nfa0, preg->re_nsub, cflags);
}
} else {
preg->char2class = new size_t[256];
split_charset(re);
for (uint32_t i = 1, j = 0; i < re.charset.size(); ++i) {
for (; j < re.charset[i]; ++j) {
preg->char2class[j] = i - 1;
}
}
dfa = new dfa_t(*nfa, Rule::NONE, Rule::NONE);
if (cflags & REG_REGLESS) {
DASSERT((cflags & REG_STADFA) == 0);
rldfa = new rldfa_t(*nfa, *dfa, opt, cflags);
opt = NULL;
} else {
determinization(*nfa, *dfa, opt, msg, "");
cutoff_dead_rules(*dfa, opt, "", msg);
insert_fallback_tags(opt, *dfa);
compact_and_optimize_tags(opt, *dfa);
