preg->nfa = nfa;
preg->dfa = dfa;
preg->rldfa = rldfa;
DASSERT(nfa->rules.size() == 1);
preg->re_nsub = nfa->rules[0].ncap + 1;
preg->re_ntag = nfa->tags.size();
