parse_cmdline( int* argc,
char*** argv )
{
char* execname;
int option;
execname = ft_basename( (*argv)[0] );
while ( 1 )
{
option = getopt( *argc, *argv, "e:m:r:" );
if ( option == -1 )
break;
switch ( option )
{
case 'e':
status.encoding = FTDemo_Make_Encoding_Tag( optarg );
break;
case 'r':
status.res = atoi( optarg );
if ( status.res < 1 )
usage( execname );
break;
case 'm':
if ( *argc < 3 )
usage( execname );
Text = optarg;
break;
default:
usage( execname );
break;
}
}
*argc -= optind;
*argv += optind;
if ( *argc <= 1 )
usage( execname );
status.ptsize = (int)(atof( *argv[0] ) * 64.0);
if ( status.ptsize == 0 )
status.ptsize = 64;
(*argc)--;
(*argv)++;
},0

static void __init memory_map_bottom_up(unsigned long map_start,
unsigned long map_end)
{
unsigned long next, start;
unsigned long mapped_ram_size = 0;
unsigned long step_size = PMD_SIZE;
start = map_start;
min_pfn_mapped = start >> PAGE_SHIFT;
while (start < map_end) {
if (step_size && map_end - start > step_size) {
next = round_up(start + 1, step_size);
if (next > map_end)
next = map_end;
} else {
next = map_end;
}
mapped_ram_size += init_range_memory_mapping(start, next);
start = next;
if (mapped_ram_size >= step_size)
step_size = get_new_step_size(step_size);
}
},0

MagickPrivate MagickBooleanType OpenModules(ExceptionInfo *exception)
{
char
**modules;
ssize_t
i;
size_t
number_modules;
(void) GetMagickInfo((char *) NULL,exception);
number_modules=0;
modules=GetModuleList("*",MagickImageCoderModule,&number_modules,exception);
if ((modules == (char **) NULL) || (*modules == (char *) NULL))
{
if (modules != (char **) NULL)
modules=(char **) RelinquishMagickMemory(modules);
return(MagickFalse);
}
for (i=0; i < (ssize_t) number_modules; i++)
(void) OpenModule(modules[i],exception);
for (i=0; i < (ssize_t) number_modules; i++)
modules[i]=DestroyString(modules[i]);
modules=(char **) RelinquishMagickMemory(modules);
return(MagickTrue);
},0

