filter_desc, &filter_backprop_ptr_rz, allocator_used,
profile_config, &profile_result);
} else {
cudnn_launch_status = stream->ConvolveBackwardFilterWithAlgorithm(
input_desc, input_ptr, output_desc, out_backprop_ptr, conv_desc,
filter_desc, &filter_backprop_ptr_rz, allocator_used,
profile_config, &profile_result);
}
