{
if (policy->version != 0)
return -EINVAL;
if (!inode_has_encryption_context(inode)) {
if (!inode->i_sb->s_cop->empty_dir)
return -EOPNOTSUPP;
if (!inode->i_sb->s_cop->empty_dir(inode))
return -ENOTEMPTY;
return create_encryption_context_from_policy(inode, policy);
}
if (is_encryption_context_consistent_with_policy(inode, policy))
return 0;
printk(KERN_WARNING "%s: Policy inconsistent with encryption context\n",
__func__);
return -EINVAL;
},1

LoadCommand* Binary::add(const SegmentCommand& segment) {
LIEF_DEBUG("Adding the new segment '{}' ({} bytes)", segment.name(), segment.content().size());
const uint32_t alignment = page_size();
const uint64_t new_fsize = align(segment.content().size(), alignment);
SegmentCommand new_segment = segment;
if (new_segment.file_size() == 0) {
new_segment.file_size(new_fsize);
new_segment.content_resize(new_fsize);
}
if (new_segment.virtual_size() == 0) {
const uint64_t new_size = align(new_segment.file_size(), alignment);
new_segment.virtual_size(new_size);
}
if (segment.sections().size() > 0) {
new_segment.nb_sections_ = segment.sections().size();
}
if (is64_) {
new_segment.command(LOAD_COMMAND_TYPES::LC_SEGMENT_64);
size_t needed_size = sizeof(details::segment_command_64);
needed_size += new_segment.numberof_sections() * sizeof(details::section_64);
new_segment.size(needed_size);
} else {
new_segment.command(LOAD_COMMAND_TYPES::LC_SEGMENT);
size_t needed_size = sizeof(details::segment_command_32);
needed_size += new_segment.numberof_sections() * sizeof(details::section_32);
new_segment.size(needed_size);
}
LIEF_DEBUG(" -> sizeof(LC_SEGMENT): {}", new_segment.size());
const auto it_linkedit = std::find_if(std::begin(commands_), std::end(commands_),
[] (const std::unique_ptr<LoadCommand>& cmd) {
if (!SegmentCommand::classof(cmd.get())) {
return false;
}
return cmd->as<SegmentCommand>()->name() == "__LINKEDIT";
});
const bool has_linkedit = it_linkedit != std::end(commands_);
size_t pos = std::distance(std::begin(commands_), it_linkedit);
LIEF_DEBUG(" -> index: {}", pos);
auto* segment_added = add(new_segment, pos)->as<SegmentCommand>();
if (segment_added == nullptr) {
LIEF_WARN("Fail to insert new '{}' segment", segment.name());
return nullptr;
}
if (!has_linkedit) {
range_t new_va_ranges = this->va_ranges();
range_t new_off_ranges = off_ranges();
if (segment.virtual_address() == 0 && segment_added->virtual_size() != 0) {
const uint64_t new_va = align(new_va_ranges.end, alignment);
segment_added->virtual_address(new_va);
size_t current_va = segment_added->virtual_address();
for (Section& section : segment_added->sections()) {
section.virtual_address(current_va);
current_va += section.size();
}
}
if (segment.file_offset() == 0 && segment_added->virtual_size() != 0) {
const uint64_t new_offset = align(new_off_ranges.end, alignment);
segment_added->file_offset(new_offset);
size_t current_offset = new_offset;
for (Section& section : segment_added->sections()) {
section.offset(current_offset);
current_offset += section.size();
}
}
refresh_seg_offset();
return segment_added;
}
uint64_t lnk_offset = 0;
uint64_t lnk_va = 0;
if (const SegmentCommand* lnk = get_segment("__LINKEDIT")) {
lnk_offset = lnk->file_offset();
lnk_va = lnk->virtual_address();
}
shift_linkedit(new_fsize);
LIEF_DEBUG(" -> offset : 0x{:06x}", lnk_offset);
LIEF_DEBUG(" -> virtual address: 0x{:06x}", lnk_va);
segment_added->virtual_address(lnk_va);
segment_added->virtual_size(segment_added->virtual_size());
size_t current_va = segment_added->virtual_address();
for (Section& section : segment_added->sections()) {
section.virtual_address(current_va);
current_va += section.size();
}
segment_added->file_offset(lnk_offset);
size_t current_offset = lnk_offset;
for (Section& section : segment_added->sections()) {
section.offset(current_offset);
current_offset += section.size();
}
refresh_seg_offset();
return segment_added;
},1

set_text_distance(gs_point *pdist, double dx, double dy, const gs_matrix *pmat)
{
int code = gs_distance_transform_inverse(dx, dy, pmat, pdist);
double rounded;
if (code == gs_error_undefinedresult) {
pdist->x = pdist->y = 0;
} else if (code < 0)
return code;
if (fabs(pdist->x - (rounded = floor(pdist->x + 0.5))) < 0.0005)
pdist->x = rounded;
if (fabs(pdist->y - (rounded = floor(pdist->y + 0.5))) < 0.0005)
pdist->y = rounded;
return 0;
},1

soup_ntlm_response (const char *nonce,
const char *user,
guchar nt_hash[21],
guchar lm_hash[21],
const char *host,
const char *domain,
gboolean ntlmv2_session)
{
int offset;
gsize hlen, dlen, ulen;
guchar lm_resp[24], nt_resp[24];
char *user_conv, *host_conv, *domain_conv;
NTLMResponse resp;
char *out, *p;
int state, save;
if (ntlmv2_session) {
calc_ntlm2_session_response (nonce, nt_hash, lm_hash,
lm_resp, sizeof(lm_resp), nt_resp);
} else {
calc_response (nt_hash, (guchar *) nonce, nt_resp);
calc_response (lm_hash, (guchar *) nonce, lm_resp);
}
memset (&resp, 0, sizeof (resp));
memcpy (resp.header, NTLM_RESPONSE_HEADER, sizeof (resp.header));
resp.flags = GUINT32_TO_LE (NTLM_RESPONSE_FLAGS);
if (ntlmv2_session)
resp.flags |= GUINT32_TO_LE (NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY);
offset = sizeof (resp);
if (!host)
host = "UNKNOWN";
domain_conv = g_convert (domain, -1, "UCS-2LE", "UTF-8", NULL, &dlen, NULL);
user_conv = g_convert (user, -1, "UCS-2LE", "UTF-8", NULL, &ulen, NULL);
host_conv = g_convert (host, -1, "UCS-2LE", "UTF-8", NULL, &hlen, NULL);
ntlm_set_string (&resp.domain, &offset, dlen);
ntlm_set_string (&resp.user, &offset, ulen);
ntlm_set_string (&resp.host, &offset, hlen);
ntlm_set_string (&resp.lm_resp, &offset, sizeof (lm_resp));
ntlm_set_string (&resp.nt_resp, &offset, sizeof (nt_resp));
out = g_malloc (((offset + 3) * 4) / 3 + 6);
memcpy (out, "NTLM ", 5);
p = out + 5;
state = save = 0;
p += g_base64_encode_step ((const guchar *) &resp, sizeof (resp),
FALSE, p, &state, &save);
p += g_base64_encode_step ((const guchar *) domain_conv, dlen,
FALSE, p, &state, &save);
p += g_base64_encode_step ((const guchar *) user_conv, ulen,
FALSE, p, &state, &save);
p += g_base64_encode_step ((const guchar *) host_conv, hlen,
FALSE, p, &state, &save);
p += g_base64_encode_step (lm_resp, sizeof (lm_resp),
FALSE, p, &state, &save);
p += g_base64_encode_step (nt_resp, sizeof (nt_resp),
FALSE, p, &state, &save);
p += g_base64_encode_close (FALSE, p, &state, &save);
*p = '\0';
g_free (domain_conv);
g_free (user_conv);
g_free (host_conv);
return out;
},1

int jpc_dec_decodepkts(jpc_dec_t *dec, jas_stream_t *pkthdrstream, jas_stream_t *in)
{
jpc_dec_tile_t *tile;
jpc_pi_t *pi;
int ret;
tile = dec->curtile;
pi = tile->pi;
for (;;) {
if (!tile->pkthdrstream || jas_stream_peekc(tile->pkthdrstream) == EOF) {
switch (jpc_dec_lookahead(in)) {
case JPC_MS_EOC:
case JPC_MS_SOT:
return 0;
break;
case JPC_MS_SOP:
case JPC_MS_EPH:
case 0:
break;
default:
return -1;
break;
}
}
if ((ret = jpc_pi_next(pi))) {
return ret;
}
if (dec->maxpkts >= 0 && dec->numpkts >= dec->maxpkts) {
jas_eprintf("warning: stopping decode prematurely as requested\n");
return 0;
}
if (jas_getdbglevel() >= 1) {
jas_eprintf("packet offset=%08ld prg=%d cmptno=%02d "
"rlvlno=%02d prcno=%03d lyrno=%02d\n", (long)
jas_stream_getrwcount(in), jpc_pi_prg(pi), jpc_pi_cmptno(pi),
jpc_pi_rlvlno(pi), jpc_pi_prcno(pi), jpc_pi_lyrno(pi));
}
if (jpc_dec_decodepkt(dec, pkthdrstream, in, jpc_pi_cmptno(pi), jpc_pi_rlvlno(pi),
jpc_pi_prcno(pi), jpc_pi_lyrno(pi))) {
return -1;
}
++dec->numpkts;
}
return 0;
},1

static int dn_fib_dnaddr_event(struct notifier_block *this, unsigned long event, void *ptr)
{
struct dn_ifaddr *ifa = (struct dn_ifaddr *)ptr;
switch (event) {
case NETDEV_UP:
dn_fib_add_ifaddr(ifa);
dn_fib_sync_up(ifa->ifa_dev->dev);
dn_rt_cache_flush(-1);
break;
case NETDEV_DOWN:
dn_fib_del_ifaddr(ifa);
if (ifa->ifa_dev && ifa->ifa_dev->ifa_list == NULL) {
dn_fib_disable_addr(ifa->ifa_dev->dev, 1);
} else {
dn_rt_cache_flush(-1);
}
break;
}
return NOTIFY_DONE;
},0

int qeth_snmp_command(struct qeth_card *card, char __user *udata)
{
struct qeth_cmd_buffer *iob;
struct qeth_ipa_cmd *cmd;
struct qeth_snmp_ureq *ureq;
int req_len;
struct qeth_arp_query_info qinfo = {0, };
int rc = 0;
QETH_CARD_TEXT(card, 3, "snmpcmd");
if (card->info.guestlan)
return -EOPNOTSUPP;
if ((!qeth_adp_supported(card, IPA_SETADP_SET_SNMP_CONTROL)) &&
(!card->options.layer2)) {
return -EOPNOTSUPP;
}
if (copy_from_user(&req_len, udata + sizeof(int), sizeof(int)))
return -EFAULT;
ureq = memdup_user(udata, req_len + sizeof(struct qeth_snmp_ureq_hdr));
if (IS_ERR(ureq)) {
QETH_CARD_TEXT(card, 2, "snmpnome");
return PTR_ERR(ureq);
}
qinfo.udata_len = ureq->hdr.data_len;
qinfo.udata = kzalloc(qinfo.udata_len, GFP_KERNEL);
if (!qinfo.udata) {
kfree(ureq);
return -ENOMEM;
}
qinfo.udata_offset = sizeof(struct qeth_snmp_ureq_hdr);
iob = qeth_get_adapter_cmd(card, IPA_SETADP_SET_SNMP_CONTROL,
QETH_SNMP_SETADP_CMDLENGTH + req_len);
cmd = (struct qeth_ipa_cmd *)(iob->data+IPA_PDU_HEADER_SIZE);
