AlgorithmEnum* ZRtp::findBestSASType(ZrtpPacketHello *hello) {
int i;
int ii;
int numAlgosOffered;
AlgorithmEnum* algosOffered[ZrtpConfigure::maxNoOfAlgos+1];
int numAlgosConf;
AlgorithmEnum* algosConf[ZrtpConfigure::maxNoOfAlgos+1];
int num = hello->getNumSas();
if (num == 0) {
return &zrtpSasTypes.getByName(mandatorySasType);
}
numAlgosConf = configureAlgos.getNumConfiguredAlgos(SasType);
for (i = 0; i < numAlgosConf; i++) {
algosConf[i] = &configureAlgos.getAlgoAt(SasType, i);
}
for (numAlgosOffered = 0, i = 0; i < num; i++) {
algosOffered[numAlgosOffered] = &zrtpSasTypes.getByName((const char*)hello->getSasType(i++));
if (!algosOffered[numAlgosOffered]->isValid())
continue;
numAlgosOffered++;
}
for (i = 0; i < numAlgosOffered; i++) {
for (ii = 0; ii < numAlgosConf; ii++) {
if (*(int32_t*)(algosOffered[i]->getName()) == *(int32_t*)(algosConf[ii]->getName())) {
return algosConf[ii];
}
}
}
return &zrtpSasTypes.getByName(mandatorySasType);
},1

bool process_pending_requests(JSContext *cx) {
if (pending_requests->length() == 0)
return true;
size_t count = pending_requests->length();
auto handles = mozilla::MakeUnique<PendingRequestHandle[]>(sizeof(PendingRequestHandle) * count);
if (!handles)
return false;
for (size_t i = 0; i < count; i++) {
handles[i] = Request::pending_handle((*pending_requests)[i]);
}
uint32_t done_index;
ResponseHandle response_handle = {INVALID_HANDLE};
BodyHandle body = {INVALID_HANDLE};
int result =
xqd_req_pending_req_select(handles.get(), count, &done_index, &response_handle, &body);
if (!HANDLE_RESULT(cx, result))
return false;
HandleObject request = (*pending_requests)[done_index];
RootedObject response_promise(cx, Request::response_promise(request));
if (response_handle.handle == INVALID_HANDLE) {
pending_requests->erase(const_cast<JSObject **>(request.address()));
JS_ReportErrorUTF8(cx, "NetworkError when attempting to fetch resource.");
RootedValue exn(cx);
if (!JS_IsExceptionPending(cx) || !JS_GetPendingException(cx, &exn)) {
return false;
}
JS_ClearPendingException(cx);
return JS::RejectPromise(cx, response_promise, exn);
}
RootedObject response_instance(
cx, JS_NewObjectWithGivenProto(cx, &Response::class_, Response::proto_obj));
if (!response_instance)
return false;
RootedObject response(cx, Response::create(cx, response_instance, response_handle, body, true));
if (!response)
return false;
RequestOrResponse::set_url(response, RequestOrResponse::url(request));
RootedValue response_val(cx, JS::ObjectValue(*response));
pending_requests->erase(const_cast<JSObject **>(request.address()));
return JS::ResolvePromise(cx, response_promise, response_val);
},0

rsock_init_unixsock(VALUE sock, VALUE path, int server)
{
struct sockaddr_un sockaddr;
socklen_t sockaddrlen;
int fd, status;
rb_io_t *fptr;
SafeStringValue(path);
INIT_SOCKADDR_UN(&sockaddr, sizeof(struct sockaddr_un));
if (sizeof(sockaddr.sun_path) < (size_t)RSTRING_LEN(path)) {
rb_raise(rb_eArgError, "too long unix socket path (%ldbytes given but %dbytes max)",
RSTRING_LEN(path), (int)sizeof(sockaddr.sun_path));
}
memcpy(sockaddr.sun_path, RSTRING_PTR(path), RSTRING_LEN(path));
sockaddrlen = rsock_unix_sockaddr_len(path);
fd = rsock_socket(AF_UNIX, SOCK_STREAM, 0);
if (fd < 0) {
rsock_sys_fail_path("socket(2)", path);
}
if (server) {
status = bind(fd, (struct sockaddr*)&sockaddr, sockaddrlen);
}
else {
int prot;
struct unixsock_arg arg;
arg.sockaddr = &sockaddr;
arg.sockaddrlen = sockaddrlen;
arg.fd = fd;
status = (int)rb_protect(unixsock_connect_internal, (VALUE)&arg, &prot);
if (prot) {
close(fd);
rb_jump_tag(prot);
}
}
if (status < 0) {
int e = errno;
close(fd);
rsock_syserr_fail_path(e, "connect(2)", path);
}
if (server) {
if (listen(fd, SOMAXCONN) < 0) {
int e = errno;
close(fd);
rsock_syserr_fail_path(e, "listen(2)", path);
}
}
rsock_init_sock(sock, fd);
if (server) {
GetOpenFile(sock, fptr);
fptr->pathv = rb_str_new_frozen(path);
}
return sock;
},1

Status PySeqToTensor(PyObject* obj, DataType dtype, Tensor* ret) {
ConverterState state;
TF_RETURN_IF_ERROR(InferShapeAndType(obj, &state));
DataType requested_dtype = DT_INVALID;
if (dtype != DT_INVALID) {
requested_dtype = dtype;
}
switch (requested_dtype) {
case DT_FLOAT:
if (FloatConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_DOUBLE:
if (DoubleConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_HALF:
if (NumpyHalfConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_INT64:
if (Int64Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_INT32:
if (Int32Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_UINT64:
if (UInt64Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_COMPLEX128:
if (Complex128Converter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_STRING:
if (StringConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
case DT_BOOL:
if (BoolConverter::Convert(obj, &state, ret) == nullptr)
return Status::OK();
break;
default:
break;
}
switch (state.inferred_dtype) {
case DT_FLOAT:
if (requested_dtype == DT_INVALID) {
RETURN_STRING_AS_STATUS(FloatConverter::Convert(obj, &state, ret));
} else {
RETURN_STRING_AS_STATUS(DoubleConverter::Convert(obj, &state, ret));
}
case DT_DOUBLE:
RETURN_STRING_AS_STATUS(DoubleConverter::Convert(obj, &state, ret));
case DT_HALF:
RETURN_STRING_AS_STATUS(NumpyHalfConverter::Convert(obj, &state, ret));
case DT_INT64:
if (requested_dtype == DT_INVALID) {
const char* error = Int32Converter::Convert(obj, &state, ret);
if (error == ErrorFoundInt64) {
error = Int64Converter::Convert(obj, &state, ret);
}
if (error == ErrorFoundFloat) {
error = FloatConverter::Convert(obj, &state, ret);
}
RETURN_STRING_AS_STATUS(error);
} else {
const char* error = Int64Converter::Convert(obj, &state, ret);
if (error == ErrorFoundFloat) {
error = DoubleConverter::Convert(obj, &state, ret);
}
RETURN_STRING_AS_STATUS(error);
}
case DT_STRING:
RETURN_STRING_AS_STATUS(StringConverter::Convert(obj, &state, ret));
case DT_COMPLEX128:
RETURN_STRING_AS_STATUS(Complex128Converter::Convert(obj, &state, ret));
case DT_BOOL:
RETURN_STRING_AS_STATUS(BoolConverter::Convert(obj, &state, ret));
case DT_INVALID:
*ret = Tensor(requested_dtype == DT_INVALID ? DT_FLOAT : requested_dtype,
state.inferred_shape);
return Status::OK();
default:
return errors::Unimplemented("Missing Python -> Tensor conversion for ",
DataTypeString(state.inferred_dtype));
}
return Status::OK();
},0

