glue(glue(cirrus_bitblt_rop_fwd_transp_, ROP_NAME),_8)(CirrusVGAState *s,
uint8_t *dst,const uint8_t *src,
int dstpitch,int srcpitch,
int bltwidth,int bltheight)
{
int x,y;
uint8_t p;
dstpitch -= bltwidth;
srcpitch -= bltwidth;
if (bltheight > 1 && (dstpitch < 0 || srcpitch < 0)) {
return;
}
for (y = 0; y < bltheight; y++) {
for (x = 0; x < bltwidth; x++) {
p = *dst;
ROP_OP(&p, *src);
if (p != s->vga.gr[0x34]) *dst = p;
dst++;
src++;
}
dst += dstpitch;
src += srcpitch;
}
},1

static __poll_t unix_dgram_poll(struct file *file, struct socket *sock,
poll_table *wait)
{
struct sock *sk = sock->sk, *other;
unsigned int writable;
__poll_t mask;
sock_poll_wait(file, sock, wait);
mask = 0;
if (sk->sk_err || !skb_queue_empty_lockless(&sk->sk_error_queue))
mask |= EPOLLERR |
(sock_flag(sk, SOCK_SELECT_ERR_QUEUE) ? EPOLLPRI : 0);
if (sk->sk_shutdown & RCV_SHUTDOWN)
mask |= EPOLLRDHUP | EPOLLIN | EPOLLRDNORM;
if (sk->sk_shutdown == SHUTDOWN_MASK)
mask |= EPOLLHUP;
if (!skb_queue_empty_lockless(&sk->sk_receive_queue))
mask |= EPOLLIN | EPOLLRDNORM;
if (sk->sk_type == SOCK_SEQPACKET) {
if (sk->sk_state == TCP_CLOSE)
mask |= EPOLLHUP;
if (sk->sk_state == TCP_SYN_SENT)
return mask;
}
if (!(poll_requested_events(wait) & (EPOLLWRBAND|EPOLLWRNORM|EPOLLOUT)))
return mask;
writable = unix_writable(sk);
if (writable) {
unix_state_lock(sk);
other = unix_peer(sk);
if (other && unix_peer(other) != sk &&
unix_recvq_full(other) &&
unix_dgram_peer_wake_me(sk, other))
writable = 0;
unix_state_unlock(sk);
}
if (writable)
mask |= EPOLLOUT | EPOLLWRNORM | EPOLLWRBAND;
else
sk_set_bit(SOCKWQ_ASYNC_NOSPACE, sk);
return mask;
},0

static void get_socket_name( char* buf, int len )
{
char* dpy = g_strdup(g_getenv("DISPLAY"));
if(dpy && *dpy)
{
char* p = strchr(dpy, ':');
for(++p; *p && *p != '.' && *p != '\n';)
++p;
if(*p)
*p = '\0';
}
g_snprintf( buf, len, "%s/.menu-cached-%s-%s", g_get_tmp_dir(),
dpy ? dpy : ":0", g_get_user_name() );
g_free(dpy);
},1

void ieee80211_sta_ps_deliver_uapsd(struct sta_info *sta)
{
int n_frames = sta->sta.max_sp;
u8 delivery_enabled = sta->sta.uapsd_queues;
if (!delivery_enabled)
return;
switch (sta->sta.max_sp) {
case 1:
n_frames = 2;
break;
case 2:
n_frames = 4;
break;
case 3:
n_frames = 6;
break;
case 0:
n_frames = 8;
break;
}
ieee80211_sta_ps_deliver_response(sta, n_frames, ~delivery_enabled,
IEEE80211_FRAME_RELEASE_UAPSD);
},0

protocol_common_open (struct connection *conn,
uint64_t *exportsize, uint16_t *flags)
{
int64_t size;
uint16_t eflags = NBD_FLAG_HAS_FLAGS;
int fl;
if (backend->open (backend, conn, readonly) == -1)
return -1;
if (backend->prepare (backend, conn) == -1)
return -1;
size = backend->get_size (backend, conn);
if (size == -1)
return -1;
if (size < 0) {
nbdkit_error (".get_size function returned invalid value "
"(%" PRIi64 ")", size);
return -1;
}
fl = backend->can_write (backend, conn);
if (fl == -1)
return -1;
if (readonly || !fl) {
eflags |= NBD_FLAG_READ_ONLY;
conn->readonly = true;
}
if (!conn->readonly) {
fl = backend->can_zero (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_SEND_WRITE_ZEROES;
conn->can_zero = true;
}
fl = backend->can_trim (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_SEND_TRIM;
conn->can_trim = true;
}
fl = backend->can_fua (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_SEND_FUA;
conn->can_fua = true;
}
}
fl = backend->can_flush (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_SEND_FLUSH;
conn->can_flush = true;
}
fl = backend->is_rotational (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_ROTATIONAL;
conn->is_rotational = true;
}
if (backend->thread_model (backend) >
NBDKIT_THREAD_MODEL_SERIALIZE_CONNECTIONS) {
fl = backend->can_multi_conn (backend, conn);
if (fl == -1)
return -1;
if (fl) {
eflags |= NBD_FLAG_CAN_MULTI_CONN;
conn->can_multi_conn = true;
}
}
fl = backend->can_extents (backend, conn);
if (fl == -1)
return -1;
if (fl)
conn->can_extents = true;
if (conn->structured_replies)
eflags |= NBD_FLAG_SEND_DF;
*exportsize = size;
*flags = eflags;
return 0;
},0

