bool Messageheader::Parser::state_fieldbody_crlf(char ch)
{
if (ch == '\r')
SET_STATE(state_end_cr);
else if (ch == '\n')
{
log_debug("header " << fieldnamePtr << ": " << fieldbodyPtr);
switch (header.onField(fieldnamePtr, fieldbodyPtr))
{
case OK:
case END: return true;
break;
case FAIL: failedFlag = true;
log_warn("invalid character " << chartoprint(ch) << " in fieldbody");
break;
}
*headerdataPtr = '\0';
return true;
}
else if (std::isspace(ch))
{
checkHeaderspace(1);
*(headerdataPtr - 1) = '\n';
*headerdataPtr++ = ch;
SET_STATE(state_fieldbody);
}
else if (ch >= 33 && ch <= 126)
{
switch (header.onField(fieldnamePtr, fieldbodyPtr))
{
case OK: SET_STATE(state_fieldname);
break;
case FAIL: failedFlag = true;
log_warn("invalid character " << chartoprint(ch) << " in fieldbody");
break;
case END: return true;
break;
}
fieldnamePtr = headerdataPtr;
checkHeaderspace(1);
*headerdataPtr++ = ch;
}
return false;
},1

rfbSendRectEncodingRaw(rfbClientPtr cl,
int x,
int y,
int w,
int h)
{
rfbFramebufferUpdateRectHeader rect;
int nlines;
int bytesPerLine = w * (cl->format.bitsPerPixel / 8);
char *fbptr = (cl->scaledScreen->frameBuffer + (cl->scaledScreen->paddedWidthInBytes * y)
+ (x * (cl->scaledScreen->bitsPerPixel / 8)));
if (cl->ublen > 0) {
if (!rfbSendUpdateBuf(cl))
return FALSE;
}
rect.r.x = Swap16IfLE(x);
rect.r.y = Swap16IfLE(y);
rect.r.w = Swap16IfLE(w);
rect.r.h = Swap16IfLE(h);
rect.encoding = Swap32IfLE(rfbEncodingRaw);
memcpy(&cl->updateBuf[cl->ublen], (char *)&rect,sz_rfbFramebufferUpdateRectHeader);
cl->ublen += sz_rfbFramebufferUpdateRectHeader;
rfbStatRecordEncodingSent(cl, rfbEncodingRaw, sz_rfbFramebufferUpdateRectHeader + bytesPerLine * h,
sz_rfbFramebufferUpdateRectHeader + bytesPerLine * h);
nlines = (UPDATE_BUF_SIZE - cl->ublen) / bytesPerLine;
while (TRUE) {
if (nlines > h)
nlines = h;
(*cl->translateFn)(cl->translateLookupTable,
&(cl->screen->serverFormat),
&cl->format, fbptr, &cl->updateBuf[cl->ublen],
cl->scaledScreen->paddedWidthInBytes, w, nlines);
cl->ublen += nlines * bytesPerLine;
h -= nlines;
if (h == 0)
return TRUE;
if (!rfbSendUpdateBuf(cl))
return FALSE;
fbptr += (cl->scaledScreen->paddedWidthInBytes * nlines);
nlines = (UPDATE_BUF_SIZE - cl->ublen) / bytesPerLine;
if (nlines == 0) {
rfbErr("rfbSendRectEncodingRaw: send buffer too small for %d "
"bytes per line\n", bytesPerLine);
rfbCloseClient(cl);
return FALSE;
}
}
},1

static int nntp_msg_open(struct Context *ctx, struct Message *msg, int msgno)
{
struct NntpData *nntp_data = ctx->data;
struct Header *hdr = ctx->hdrs[msgno];
char article[16];
struct NntpAcache *acache = &nntp_data->acache[hdr->index % NNTP_ACACHE_LEN];
if (acache->path)
{
if (acache->index == hdr->index)
{
msg->fp = mutt_file_fopen(acache->path, "r");
if (msg->fp)
return 0;
}
else
{
unlink(acache->path);
FREE(&acache->path);
}
}
snprintf(article, sizeof(article), "%d", NHDR(hdr)->article_num);
msg->fp = mutt_bcache_get(nntp_data->bcache, article);
if (msg->fp)
{
if (NHDR(hdr)->parsed)
return 0;
}
else
{
char buf[PATH_MAX];
if (nntp_data->deleted)
return -1;
const char *fetch_msg = _("Fetching message...");
mutt_message(fetch_msg);
msg->fp = mutt_bcache_put(nntp_data->bcache, article);
if (!msg->fp)
{
mutt_mktemp(buf, sizeof(buf));
acache->path = mutt_str_strdup(buf);
acache->index = hdr->index;
msg->fp = mutt_file_fopen(acache->path, "w+");
if (!msg->fp)
{
mutt_perror(acache->path);
unlink(acache->path);
FREE(&acache->path);
return -1;
}
}
snprintf(buf, sizeof(buf), "ARTICLE %s\r\n",
NHDR(hdr)->article_num ? article : hdr->env->message_id);
const int rc = nntp_fetch_lines(nntp_data, buf, sizeof(buf), fetch_msg,
fetch_tempfile, msg->fp);
if (rc)
{
mutt_file_fclose(&msg->fp);
if (acache->path)
{
unlink(acache->path);
FREE(&acache->path);
}
if (rc > 0)
{
if (mutt_str_strncmp(NHDR(hdr)->article_num ? "423" : "430", buf, 3) == 0)
{
mutt_error(_("Article %d not found on the server."),
NHDR(hdr)->article_num ? article : hdr->env->message_id);
}
else
mutt_error("ARTICLE: %s", buf);
}
return -1;
}
if (!acache->path)
mutt_bcache_commit(nntp_data->bcache, article);
}
if (ctx->id_hash && hdr->env->message_id)
mutt_hash_delete(ctx->id_hash, hdr->env->message_id, hdr);
if (ctx->subj_hash && hdr->env->real_subj)
mutt_hash_delete(ctx->subj_hash, hdr->env->real_subj, hdr);
mutt_env_free(&hdr->env);
hdr->env = mutt_rfc822_read_header(msg->fp, hdr, 0, 0);
if (ctx->id_hash && hdr->env->message_id)
mutt_hash_insert(ctx->id_hash, hdr->env->message_id, hdr);
if (ctx->subj_hash && hdr->env->real_subj)
mutt_hash_insert(ctx->subj_hash, hdr->env->real_subj, hdr);
fseek(msg->fp, 0, SEEK_END);
hdr->content->length = ftell(msg->fp) - hdr->content->offset;
NHDR(hdr)->parsed = true;
mutt_parse_mime_message(ctx, hdr);
if (WithCrypto)
hdr->security = crypt_query(hdr->content);
rewind(msg->fp);
mutt_clear_error();
return 0;
},0

static int open_user_core(uid_t uid, uid_t fsuid, pid_t pid, char **percent_values)
{
errno = 0;
if (user_pwd == NULL
|| chdir(user_pwd) != 0
) {
perror_msg("Can't cd to '%s'", user_pwd);
return -1;
}
struct passwd* pw = getpwuid(uid);
gid_t gid = pw ? pw->pw_gid : uid;
xsetegid(gid);
xseteuid(fsuid);
if (strcmp(core_basename, "core") == 0)
{
char buf[] = "0\n";
int fd = open("/proc/sys/kernel/core_uses_pid", O_RDONLY);
if (fd >= 0)
{
IGNORE_RESULT(read(fd, buf, sizeof(buf)));
close(fd);
}
if (strcmp(buf, "1\n") == 0)
{
core_basename = xasprintf("%s.%lu", core_basename, (long)pid);
}
}
else
{
core_basename = xstrdup(core_basename);
unsigned idx = 0;
while (1)
{
char c = core_basename[idx];
if (!c)
break;
idx++;
if (c != '%')
continue;
c = core_basename[idx];
unsigned specifier_num = strchrnul(percent_specifiers, c) - percent_specifiers;
if (percent_specifiers[specifier_num] != '\0')
{
const char *val = "%";
if (specifier_num > 0)
val = percent_values[specifier_num - 1];
idx--;
char *old = core_basename;
core_basename = xasprintf("%.*s%s%s", idx, core_basename, val, core_basename + idx + 2);
free(old);
idx += strlen(val);
}
}
}
full_core_basename = core_basename;
if (core_basename[0] != '/')
core_basename = concat_path_file(user_pwd, core_basename);
struct stat sb;
errno = 0;
int user_core_fd = open(core_basename, O_WRONLY | O_CREAT | O_NOFOLLOW, 0600);
xsetegid(0);
xseteuid(0);
if (user_core_fd < 0
|| fstat(user_core_fd, &sb) != 0
|| !S_ISREG(sb.st_mode)
|| sb.st_nlink != 1
) {
if (user_core_fd < 0)
perror_msg("Can't open '%s'", full_core_basename);
else
perror_msg("'%s' is not a regular file with link count 1", full_core_basename);
return -1;
}
if (ftruncate(user_core_fd, 0) != 0) {
perror_msg("Can't truncate '%s' to size 0", full_core_basename);
unlink(core_basename);
return -1;
}
return user_core_fd;
},1

