int parse_header(davs2_t *h, davs2_bs_t *p_bs)
{
const uint8_t *data = p_bs->p_stream;
int *bitpos = &p_bs->i_bit_pos;
int len = p_bs->i_stream;
const uint8_t *p_start_code = 0;
if (len <= 4) {
return -1;
}
while ((p_start_code = find_start_code(data + (*bitpos >> 3), len - (*bitpos >> 3))) != 0) {
uint32_t start_code;
*bitpos = (int)((p_start_code - data) << 3);
if ((*bitpos >> 3) + 4 > len) {
break;
}
start_code = data[(*bitpos >> 3) + 3];
switch (start_code) {
case SC_INTRA_PICTURE:
case SC_INTER_PICTURE:
if (task_decoder_update(h) < 0) {
return -1;
}
if (parse_picture_header(h, p_bs, start_code) < 0) {
return -1;
}
return 0;
case SC_SEQUENCE_HEADER:
davs2_seq_t new_seq;
if (parse_sequence_header(h->task_info.taskmgr, &new_seq, p_bs) < 0) {
davs2_log(h, 0, "Invalid sequence header.");
return -1;
}
if (task_set_sequence_head(h->task_info.taskmgr, &new_seq) < 0) {
return -1;
}
break;
case SC_EXTENSION:
case SC_USER_DATA:
case SC_SEQUENCE_END:
case SC_VIDEO_EDIT_CODE:
default:
*bitpos += 32;
break;
}
}
return 1;
},0

char *theme_format_expand_data(THEME_REC *theme, const char **format,
theme_rm_col default_fg, theme_rm_col default_bg,
theme_rm_col *save_last_fg, theme_rm_col *save_last_bg,
int flags)
{
GString *str;
char *ret, *abstract;
theme_rm_col last_fg, last_bg;
int recurse_flags;
last_fg = default_fg;
last_bg = default_bg;
recurse_flags = flags & EXPAND_FLAG_RECURSIVE_MASK;
str = g_string_new(NULL);
while (**format != '\0') {
if ((flags & EXPAND_FLAG_ROOT) == 0 && **format == '}') {
(*format)++;
break;
}
if (**format != '{') {
if ((flags & EXPAND_FLAG_LASTCOLOR_ARG) &&
**format == '$' && (*format)[1] == '0') {
if (save_last_fg != NULL) {
*save_last_fg = last_fg;
save_last_fg = NULL;
}
if (save_last_bg != NULL) {
*save_last_bg = last_bg;
save_last_bg = NULL;
}
}
theme_format_append_next(theme, str, format,
default_fg, default_bg,
&last_fg, &last_bg,
recurse_flags);
continue;
}
(*format)++;
if (**format == '\0' || **format == '}')
break;
abstract = theme_format_expand_abstract(theme, format,
&last_fg, &last_bg,
recurse_flags);
if (abstract != NULL) {
g_string_append(str, abstract);
g_free(abstract);
}
}
if (save_last_fg != NULL)
*save_last_fg = last_fg;
if (save_last_bg != NULL)
*save_last_bg = last_bg;
ret = str->str;
g_string_free(str, FALSE);
return ret;
},0

void operator()(OpKernelContext* ctx, const CPUDevice& d, const T* rate_flat,
int num_rate, int num_samples,
const random::PhiloxRandom& rng, U* samples_flat) {
typedef random::UniformDistribution<random::PhiloxRandom, CT> Uniform;
auto DoWork = [num_samples, num_rate, &rng, samples_flat, rate_flat](
int start_output, int limit_output) {
Uniform uniform;
typename Uniform::ResultType uniform_result;
for (int64 output_idx = start_output; output_idx < limit_output;
) {
const int64 rate_idx = output_idx / num_samples;
const CT rate = CT(rate_flat[rate_idx]);
auto samples_rate_output = samples_flat + rate_idx;
if (rate < CT(10)) {
const CT exp_neg_rate = Eigen::numext::exp(-rate);
for (int64 sample_idx = output_idx % num_samples;
sample_idx < num_samples && output_idx < limit_output;
sample_idx++, output_idx++) {
random::PhiloxRandom gen = rng;
gen.Skip(kReservedSamplesPerOutput * output_idx);
int16 uniform_remaining = 0;
CT prod = 1;
CT x = 0;
while (true) {
UNIFORM(u);
prod = prod * u;
if (prod <= exp_neg_rate &&
x <= CT(Eigen::NumTraits<U>::highest())) {
samples_rate_output[sample_idx * num_rate] = U(x);
break;
}
x += 1;
}
}
continue;
}
using Eigen::numext::log;
const CT log_rate = log(rate);
const CT b = CT(0.931) + CT(2.53) * Eigen::numext::sqrt(rate);
const CT a = CT(-0.059) + CT(0.02483) * b;
const CT inv_alpha = CT(1.1239) + CT(1.1328) / (b - CT(3.4));
for (int64 sample_idx = output_idx % num_samples;
sample_idx < num_samples && output_idx < limit_output;
sample_idx++, output_idx++) {
random::PhiloxRandom gen = rng;
gen.Skip(kReservedSamplesPerOutput * output_idx);
int16 uniform_remaining = 0;
while (true) {
UNIFORM(u);
u -= CT(0.5);
UNIFORM(v);
CT u_shifted = CT(0.5) - Eigen::numext::abs(u);
CT k = Eigen::numext::floor((CT(2) * a / u_shifted + b) * u + rate +
CT(0.43));
if (k > CT(Eigen::NumTraits<U>::highest())) {
continue;
}
if (u_shifted >= CT(0.07) &&
v <= CT(0.9277) - CT(3.6224) / (b - CT(2))) {
samples_rate_output[sample_idx * num_rate] = U(k);
break;
}
if (k < 0 || (u_shifted < CT(0.013) && v > u_shifted)) {
continue;
}
CT s = log(v * inv_alpha / (a / (u_shifted * u_shifted) + b));
CT t = -rate + k * log_rate - Eigen::numext::lgamma(k + 1);
if (s <= t) {
samples_rate_output[sample_idx * num_rate] = U(k);
break;
}
}
}
}
};
static const int kElementCost = 165 + 6 * Uniform::kElementCost +
6 * random::PhiloxRandom::kElementCost;
auto worker_threads = *(ctx->device()->tensorflow_cpu_worker_threads());
Shard(worker_threads.num_threads, worker_threads.workers,
num_rate * num_samples, kElementCost, DoWork);
