h2_vsl_frame(const struct h2_sess *h2, const void *ptr, size_t len)
{
const uint8_t *b;
struct vsb *vsb;
const char *p;
unsigned u;
AN(ptr);
assert(len >= 9);
b = ptr;
vsb = VSB_new_auto();
AN(vsb);
p = h2_framename((enum h2frame)b[3]);
if (p != NULL)
VSB_cat(vsb, p);
else
VSB_quote(vsb, b + 3, 1, VSB_QUOTE_HEX);
u = vbe32dec(b) >> 8;
VSB_printf(vsb, "[%u] ", u);
VSB_quote(vsb, b + 4, 1, VSB_QUOTE_HEX);
VSB_putc(vsb, ' ');
VSB_quote(vsb, b + 5, 4, VSB_QUOTE_HEX);
if (u > 0) {
VSB_putc(vsb, ' ');
VSB_quote(vsb, b + 9, len - 9, VSB_QUOTE_HEX);
}
AZ(VSB_finish(vsb));
Lck_Lock(&h2->sess->mtx);
VSLb_bin(h2->vsl, SLT_H2RxHdr, 9, b);
if (len > 9)
VSLb_bin(h2->vsl, SLT_H2RxBody, len - 9, b + 9);
VSLb(h2->vsl, SLT_Debug, "H2RXF %s", VSB_data(vsb));
Lck_Unlock(&h2->sess->mtx);
VSB_destroy(&vsb);
},0

int key_reject_and_link(struct key *key,
unsigned timeout,
unsigned error,
struct key *keyring,
struct key *authkey)
{
struct assoc_array_edit *edit;
struct timespec now;
int ret, awaken, link_ret = 0;
key_check(key);
key_check(keyring);
awaken = 0;
ret = -EBUSY;
if (keyring) {
if (keyring->restrict_link)
return -EPERM;
link_ret = __key_link_begin(keyring, &key->index_key, &edit);
}
mutex_lock(&key_construction_mutex);
if (!test_bit(KEY_FLAG_INSTANTIATED, &key->flags)) {
atomic_inc(&key->user->nikeys);
key->reject_error = -error;
smp_wmb();
set_bit(KEY_FLAG_NEGATIVE, &key->flags);
set_bit(KEY_FLAG_INSTANTIATED, &key->flags);
now = current_kernel_time();
key->expiry = now.tv_sec + timeout;
key_schedule_gc(key->expiry + key_gc_delay);
if (test_and_clear_bit(KEY_FLAG_USER_CONSTRUCT, &key->flags))
awaken = 1;
ret = 0;
if (keyring && link_ret == 0)
__key_link(key, &edit);
if (authkey)
key_revoke(authkey);
}
mutex_unlock(&key_construction_mutex);
if (keyring && link_ret == 0)
__key_link_end(keyring, &key->index_key, edit);
if (awaken)
wake_up_bit(&key->flags, KEY_FLAG_USER_CONSTRUCT);
return ret == 0 ? link_ret : ret;
},1

