static int ldb_kv_index_add1(struct ldb_module *module,
struct ldb_kv_private *ldb_kv,
const struct ldb_message *msg,
struct ldb_message_element *el,
int v_idx)
{
struct ldb_context *ldb;
struct ldb_dn *dn_key;
int ret;
const struct ldb_schema_attribute *a;
struct dn_list *list;
unsigned alloc_len;
enum key_truncation truncation = KEY_TRUNCATED;
ldb = ldb_module_get_ctx(module);
list = talloc_zero(module, struct dn_list);
if (list == NULL) {
return LDB_ERR_OPERATIONS_ERROR;
}
dn_key = ldb_kv_index_key(ldb,
list,
ldb_kv,
el->name,
&el->values[v_idx],
&a,
&truncation);
if (!dn_key) {
talloc_free(list);
return LDB_ERR_OPERATIONS_ERROR;
}
if ((truncation == KEY_TRUNCATED) && (a != NULL &&
(a->flags & LDB_ATTR_FLAG_UNIQUE_INDEX ||
(el->flags & LDB_FLAG_INTERNAL_FORCE_UNIQUE_INDEX)))) {
ldb_asprintf_errstring(
ldb,
__location__ ": unique index key on %s in %s, "
"exceeds maximum key length of %u (encoded).",
el->name,
ldb_dn_get_linearized(msg->dn),
ldb_kv->max_key_length);
talloc_free(list);
return LDB_ERR_CONSTRAINT_VIOLATION;
}
ret = ldb_kv_dn_list_load(module, ldb_kv, dn_key, list,
DN_LIST_MUTABLE);
if (ret != LDB_SUCCESS && ret != LDB_ERR_NO_SUCH_OBJECT) {
talloc_free(list);
return ret;
}
if (list->count > 0 &&
ldb_attr_cmp(el->name, LDB_KV_IDXDN) == 0 &&
truncation == KEY_NOT_TRUNCATED) {
talloc_free(list);
return LDB_ERR_CONSTRAINT_VIOLATION;
} else if (list->count > 0
&& ldb_attr_cmp(el->name, LDB_KV_IDXDN) == 0) {
unsigned int i;
for (i=0; i < list->count; i++) {
uint8_t guid_key[LDB_KV_GUID_KEY_SIZE];
struct ldb_val key = {
.data = guid_key,
.length = sizeof(guid_key)
};
const int flags = LDB_UNPACK_DATA_FLAG_NO_ATTRS;
struct ldb_message *rec = ldb_msg_new(ldb);
if (rec == NULL) {
return LDB_ERR_OPERATIONS_ERROR;
}
ret = ldb_kv_idx_to_key(
module, ldb_kv, ldb, &list->dn[i], &key);
if (ret != LDB_SUCCESS) {
TALLOC_FREE(list);
TALLOC_FREE(rec);
return ret;
}
ret =
ldb_kv_search_key(module, ldb_kv, key, rec, flags);
if (key.data != guid_key) {
TALLOC_FREE(key.data);
}
if (ret == LDB_ERR_NO_SUCH_OBJECT) {
talloc_free(rec);
continue;
}
if (ret != LDB_SUCCESS) {
TALLOC_FREE(rec);
TALLOC_FREE(list);
return LDB_ERR_OPERATIONS_ERROR;
}
if (ldb_dn_compare(msg->dn, rec->dn) == 0) {
TALLOC_FREE(rec);
TALLOC_FREE(list);
return LDB_ERR_CONSTRAINT_VIOLATION;
}
}
}
if (list->count > 0 &&
((a != NULL
&& (a->flags & LDB_ATTR_FLAG_UNIQUE_INDEX ||
(el->flags & LDB_FLAG_INTERNAL_FORCE_UNIQUE_INDEX))))) {
if (ldb_kv->cache->GUID_index_attribute == NULL) {
ldb_debug(ldb, LDB_DEBUG_WARNING,
__location__
": unique index violation on %s in %s, "
"conflicts with %*.*s in %s",
el->name, ldb_dn_get_linearized(msg->dn),
(int)list->dn[0].length,
(int)list->dn[0].length,
list->dn[0].data,
ldb_dn_get_linearized(dn_key));
} else {
const struct ldb_schema_attribute *attr =
ldb_schema_attribute_by_name(
ldb, ldb_kv->cache->GUID_index_attribute);
struct ldb_val v;
ret = attr->syntax->ldif_write_fn(ldb, list,
&list->dn[0], &v);
if (ret == LDB_SUCCESS) {
ldb_debug(ldb,
LDB_DEBUG_WARNING,
__location__
": unique index violation on %s in "
"%s, conflicts with %s %*.*s in %s",
el->name,
ldb_dn_get_linearized(msg->dn),
ldb_kv->cache->GUID_index_attribute,
(int)v.length,
(int)v.length,
v.data,
ldb_dn_get_linearized(dn_key));
}
}
ldb_asprintf_errstring(ldb,
__location__ ": unique index violation "
"on %s in %s",
el->name,
ldb_dn_get_linearized(msg->dn));
talloc_free(list);
return LDB_ERR_CONSTRAINT_VIOLATION;
}
alloc_len = ((list->count+1)+7) & ~7;
list->dn = talloc_realloc(list, list->dn, struct ldb_val, alloc_len);
if (list->dn == NULL) {
talloc_free(list);
return LDB_ERR_OPERATIONS_ERROR;
}
if (ldb_kv->cache->GUID_index_attribute == NULL) {
const char *dn_str = ldb_dn_get_linearized(msg->dn);
list->dn[list->count].data
= (uint8_t *)talloc_strdup(list->dn, dn_str);
if (list->dn[list->count].data == NULL) {
talloc_free(list);
return LDB_ERR_OPERATIONS_ERROR;
}
list->dn[list->count].length = strlen(dn_str);
} else {
const struct ldb_val *key_val;
struct ldb_val *exact = NULL, *next = NULL;
key_val = ldb_msg_find_ldb_val(
msg, ldb_kv->cache->GUID_index_attribute);
if (key_val == NULL) {
talloc_free(list);
return ldb_module_operr(module);
}
if (key_val->length != LDB_KV_GUID_SIZE) {
talloc_free(list);
return ldb_module_operr(module);
}
BINARY_ARRAY_SEARCH_GTE(list->dn, list->count,
*key_val, ldb_val_equal_exact_ordered,
exact, next);
if (exact != NULL && truncation == KEY_NOT_TRUNCATED) {
const struct ldb_schema_attribute *attr =
ldb_schema_attribute_by_name(
ldb, ldb_kv->cache->GUID_index_attribute);
struct ldb_val v;
ret = attr->syntax->ldif_write_fn(ldb, list,
exact, &v);
if (ret == LDB_SUCCESS) {
ldb_debug(ldb,
LDB_DEBUG_WARNING,
__location__
": duplicate attribute value in %s "
"for index on %s, "
"duplicate of %s %*.*s in %s",
ldb_dn_get_linearized(msg->dn),
el->name,
ldb_kv->cache->GUID_index_attribute,
(int)v.length,
(int)v.length,
v.data,
ldb_dn_get_linearized(dn_key));
}
}
if (next == NULL) {
next = &list->dn[list->count];
} else {
memmove(&next[1], next,
sizeof(*next) * (list->count - (next - list->dn)));
}
*next = ldb_val_dup(list->dn, key_val);
if (next->data == NULL) {
talloc_free(list);
return ldb_module_operr(module);
}
}
list->count++;
ret = ldb_kv_dn_list_store(module, dn_key, list);
talloc_free(list);
return ret;
},0

static int chip_probe(struct i2c_client *client, const struct i2c_device_id *id)
{
struct CHIPSTATE *chip;
struct CHIPDESC *desc;
if (debug) {
printk(KERN_INFO "tvaudio: TV audio decoder + audio/video mux driver\n");
printk(KERN_INFO "tvaudio: known chips: ");
for (desc = chiplist; desc->name != NULL; desc++)
printk("%s%s", (desc == chiplist) ? "" : ", ", desc->name);
printk("\n");
}
chip = kzalloc(sizeof(*chip),GFP_KERNEL);
if (!chip)
return -ENOMEM;
chip->c = client;
i2c_set_clientdata(client, chip);
v4l_dbg(1, debug, client, "chip found @ 0x%x\n", client->addr<<1);
for (desc = chiplist; desc->name != NULL; desc++) {
if (0 == *(desc->insmodopt))
continue;
if (client->addr < desc->addr_lo ||
client->addr > desc->addr_hi)
continue;
if (desc->checkit && !desc->checkit(chip))
continue;
break;
}
if (desc->name == NULL) {
v4l_dbg(1, debug, client, "no matching chip description found\n");
kfree(chip);
return -EIO;
}
v4l_info(client, "%s found @ 0x%x (%s)\n", desc->name, client->addr<<1, client->adapter->name);
if (desc->flags) {
v4l_dbg(1, debug, client, "matches:%s%s%s.\n",
(desc->flags & CHIP_HAS_VOLUME) ? " volume" : "",
(desc->flags & CHIP_HAS_BASSTREBLE) ? " bass/treble" : "",
(desc->flags & CHIP_HAS_INPUTSEL) ? " audiomux" : "");
}
if (!id)
strlcpy(client->name, desc->name, I2C_NAME_SIZE);
chip->desc = desc;
chip->shadow.count = desc->registers+1;
chip->prevmode = -1;
chip->audmode = V4L2_TUNER_MODE_LANG1;
if (desc->initialize != NULL)
desc->initialize(chip);
else
chip_cmd(chip,"init",&desc->init);
if (desc->flags & CHIP_HAS_VOLUME) {
if (!desc->volfunc) {
v4l_info(chip->c, "volume callback undefined!\n");
desc->flags &= ~CHIP_HAS_VOLUME;
} else {
chip->left = desc->leftinit ? desc->leftinit : 65535;
chip->right = desc->rightinit ? desc->rightinit : 65535;
chip_write(chip, desc->leftreg,
desc->volfunc(chip->left));
chip_write(chip, desc->rightreg,
desc->volfunc(chip->right));
}
}
if (desc->flags & CHIP_HAS_BASSTREBLE) {
if (!desc->bassfunc || !desc->treblefunc) {
v4l_info(chip->c, "bass/treble callbacks undefined!\n");
desc->flags &= ~CHIP_HAS_BASSTREBLE;
} else {
chip->treble = desc->trebleinit ?
desc->trebleinit : 32768;
chip->bass = desc->bassinit ?
desc->bassinit : 32768;
chip_write(chip, desc->bassreg,
desc->bassfunc(chip->bass));
chip_write(chip, desc->treblereg,
desc->treblefunc(chip->treble));
}
}
chip->thread = NULL;
if (desc->flags & CHIP_NEED_CHECKMODE) {
if (!desc->getmode || !desc->setmode) {
v4l_info(chip->c, "set/get mode callbacks undefined!\n");
return 0;
}
init_timer(&chip->wt);
chip->wt.function = chip_thread_wake;
chip->wt.data = (unsigned long)chip;
chip->thread = kthread_run(chip_thread, chip, chip->c->name);
if (IS_ERR(chip->thread)) {
v4l_warn(chip->c, "%s: failed to create kthread\n",
chip->c->name);
chip->thread = NULL;
}
}
return 0;
},0

onigenc_strlen_null(OnigEncoding enc, const UChar* s)
{
int n = 0;
UChar* p = (UChar* )s;
UChar* e;
while (1) {
if (*p == '\0') {
UChar* q;
int len = ONIGENC_MBC_MINLEN(enc);
if (len == 1) return n;
q = p + 1;
while (len > 1) {
if (*q != '\0') break;
q++;
len--;
}
if (len == 1) return n;
}
e = p + ONIGENC_MBC_MAXLEN(enc);
p += ONIGENC_MBC_ENC_LEN(enc, p, e);
n++;
}
},0

static void atl2_intr_rx(struct atl2_adapter *adapter)
{
struct net_device *netdev = adapter->netdev;
struct rx_desc *rxd;
struct sk_buff *skb;
do {
rxd = adapter->rxd_ring+adapter->rxd_write_ptr;
if (!rxd->status.update)
break;
rxd->status.update = 0;
if (rxd->status.ok && rxd->status.pkt_size >= 60) {
int rx_size = (int)(rxd->status.pkt_size - 4);
skb = netdev_alloc_skb_ip_align(netdev, rx_size);
if (NULL == skb) {
netdev->stats.rx_dropped++;
break;
}
memcpy(skb->data, rxd->packet, rx_size);
skb_put(skb, rx_size);
skb->protocol = eth_type_trans(skb, netdev);
if (rxd->status.vlan) {
u16 vlan_tag = (rxd->status.vtag>>4) |
((rxd->status.vtag&7) << 13) |
((rxd->status.vtag&8) << 9);
__vlan_hwaccel_put_tag(skb, htons(ETH_P_8021Q), vlan_tag);
}
netif_rx(skb);
netdev->stats.rx_bytes += rx_size;
netdev->stats.rx_packets++;
} else {
netdev->stats.rx_errors++;
if (rxd->status.ok && rxd->status.pkt_size <= 60)
netdev->stats.rx_length_errors++;
if (rxd->status.mcast)
netdev->stats.multicast++;
if (rxd->status.crc)
netdev->stats.rx_crc_errors++;
if (rxd->status.align)
netdev->stats.rx_frame_errors++;
}
if (++adapter->rxd_write_ptr == adapter->rxd_ring_size)
adapter->rxd_write_ptr = 0;
} while (1);
adapter->rxd_read_ptr = adapter->rxd_write_ptr;
ATL2_WRITE_REGW(&adapter->hw, REG_MB_RXD_RD_IDX, adapter->rxd_read_ptr);
},0

static ptrdiff_t finderrfunc(lua_State *L)
{
cTValue *frame = L->base-1, *bot = tvref(L->stack);
void *cf = L->cframe;
while (frame > bot && cf) {
while (cframe_nres(cframe_raw(cf)) < 0) {
if (frame >= restorestack(L, -cframe_nres(cf)))
break;
if (cframe_errfunc(cf) >= 0)
return cframe_errfunc(cf);
cf = cframe_prev(cf);
if (cf == NULL)
return 0;
}
switch (frame_typep(frame)) {
case FRAME_LUA:
case FRAME_LUAP:
frame = frame_prevl(frame);
break;
case FRAME_C:
cf = cframe_prev(cf);
case FRAME_VARG:
frame = frame_prevd(frame);
break;
case FRAME_CONT:
#if LJ_HASFFI
if ((frame-1)->u32.lo == LJ_CONT_FFI_CALLBACK)
cf = cframe_prev(cf);
#endif
frame = frame_prevd(frame);
break;
case FRAME_CP:
if (cframe_canyield(cf)) return 0;
if (cframe_errfunc(cf) >= 0)
return cframe_errfunc(cf);
frame = frame_prevd(frame);
break;
case FRAME_PCALL:
case FRAME_PCALLH:
if (frame_ftsz(frame) >= (ptrdiff_t)(2*sizeof(TValue)))
return savestack(L, frame-1);
return 0;
default:
lua_assert(0);
return 0;
}
}
return 0;
},1

