void oidc_util_set_app_infos(request_rec *r, const json_t *j_attrs,
const char *claim_prefix, const char *claim_delimiter,
apr_byte_t as_header, apr_byte_t as_env_var, apr_byte_t base64url) {
char s_int[255];
json_t *j_value = NULL;
const char *s_key = NULL;
if (j_attrs == NULL) {
oidc_debug(r, "no attributes to set");
return;
}
void *iter = json_object_iter((json_t*) j_attrs);
while (iter) {
s_key = json_object_iter_key(iter);
j_value = json_object_iter_value(iter);
if (json_is_string(j_value)) {
oidc_util_set_app_info(r, s_key, json_string_value(j_value),
claim_prefix, as_header, as_env_var, base64url);
} else if (json_is_boolean(j_value)) {
oidc_util_set_app_info(r, s_key,
(json_is_true(j_value) ? "1" : "0"), claim_prefix,
as_header, as_env_var, base64url);
} else if (json_is_integer(j_value)) {
if (sprintf(s_int, "%ld", (long) json_integer_value(j_value)) > 0) {
oidc_util_set_app_info(r, s_key, s_int, claim_prefix, as_header,
as_env_var, base64url);
} else {
oidc_warn(r,
"could not convert JSON number to string (> 255 characters?), skipping");
}
} else if (json_is_real(j_value)) {
oidc_util_set_app_info(r, s_key,
apr_psprintf(r->pool, "%lf", json_real_value(j_value)),
claim_prefix, as_header, as_env_var, base64url);
} else if (json_is_object(j_value)) {
oidc_util_set_app_info(r, s_key,
oidc_util_encode_json_object(r, j_value, 0), claim_prefix,
as_header, as_env_var, base64url);
} else if (json_is_array(j_value)) {
oidc_debug(r,
"parsing attribute array for key \"%s\" (#nr-of-elems: %llu)",
s_key, (unsigned long long )json_array_size(j_value));
char *s_concat = apr_pstrdup(r->pool, "");
size_t i = 0;
for (i = 0; i < json_array_size(j_value); i++) {
json_t *elem = json_array_get(j_value, i);
if (json_is_string(elem)) {
if (apr_strnatcmp(s_concat, "") != 0) {
s_concat = apr_psprintf(r->pool, "%s%s%s", s_concat,
claim_delimiter, json_string_value(elem));
} else {
s_concat = apr_psprintf(r->pool, "%s",
json_string_value(elem));
}
} else if (json_is_boolean(elem)) {
if (apr_strnatcmp(s_concat, "") != 0) {
s_concat = apr_psprintf(r->pool, "%s%s%s", s_concat,
claim_delimiter,
json_is_true(elem) ? "1" : "0");
} else {
s_concat = apr_psprintf(r->pool, "%s",
json_is_true(elem) ? "1" : "0");
}
} else {
oidc_warn(r,
"unhandled in-array JSON object type [%d] for key \"%s\" when parsing claims array elements",
elem->type, s_key);
}
}
oidc_util_set_app_info(r, s_key, s_concat, claim_prefix, as_header,
as_env_var, base64url);
} else {
oidc_warn(r,
"unhandled JSON object type [%d] for key \"%s\" when parsing claims",
j_value->type, s_key);
}
iter = json_object_iter_next((json_t*) j_attrs, iter);
}
},0

static GF_Node *lsr_read_listener(GF_LASeRCodec *lsr, SVG_Element *parent)
{
u32 flag;
GF_FieldInfo info;
XMLEV_Event *ev = NULL;
XMLRI *observer, *target, *handler;
GF_Node *elt = gf_node_new(lsr->sg, TAG_SVG_listener);
observer = target = handler = NULL;
lsr_read_id(lsr, elt);
lsr_read_rare(lsr, elt);
GF_LSR_READ_INT(lsr, flag, 1, "hasDefaultAction");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_defaultAction, 1, 0, &info);
GF_LSR_READ_INT(lsr, *(XMLEV_DefaultAction*)info.far_ptr, 1, "defaultAction");
}
GF_LSR_READ_INT(lsr, flag, 1, "hasEvent");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_event, 1, 0, &info);
lsr_read_event_type(lsr, info.far_ptr);
ev = info.far_ptr;
}
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_handler, 1, 0, &info);
handler = info.far_ptr;
GF_LSR_READ_INT(lsr, flag, 1, "hasHandler");
if (flag) {
lsr_read_any_uri(lsr, info.far_ptr, "handler");
}
GF_LSR_READ_INT(lsr, flag, 1, "hasObserver");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_observer, 1, 0, &info);
lsr_read_codec_IDREF(lsr, info.far_ptr, "observer");
observer = info.far_ptr;
}
GF_LSR_READ_INT(lsr, flag, 1, "hasPhase");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_phase, 1, 0, &info);
GF_LSR_READ_INT(lsr, *(XMLEV_Phase*)info.far_ptr, 1, "phase");
}
GF_LSR_READ_INT(lsr, flag, 1, "hasPropagate");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_propagate, 1, 0, &info);
GF_LSR_READ_INT(lsr, *(XMLEV_Propagate*)info.far_ptr, 1, "propagate");
}
GF_LSR_READ_INT(lsr, flag, 1, "hasTarget");
if (flag) {
lsr->last_error = gf_node_get_attribute_by_tag(elt, TAG_XMLEV_ATT_target, 1, 0, &info);
lsr_read_codec_IDREF(lsr, info.far_ptr, "target");
target = info.far_ptr;
}
lsr_read_lsr_enabled(lsr, elt);
lsr_read_any_attribute(lsr, elt, 1);
lsr_read_group_content(lsr, elt, 0);
{
Bool post_pone = 0;
SVG_Element *par = NULL;
if (observer && observer->type == XMLRI_ELEMENTID) {
if (observer->target) par = observer->target;
}
if (!par && target && (target->type == XMLRI_ELEMENTID)) {
if (!target->target) post_pone = 1;
else par = target->target;
}
if (!handler->target && !handler->string) {
handler->type = XMLRI_ELEMENTID;
handler->target = parent;
}
if (!par && !observer) {
if (ev && (ev->type>GF_EVENT_MOUSEWHEEL)) {
par = (SVG_Element*) lsr->current_root;
}
else if (parent) par = parent;
else par = (SVG_Element*) lsr->current_root;
}
if (!par) post_pone = 1;
if (post_pone) {
gf_list_add(lsr->deferred_listeners, elt);
} else {
if (!par) par = parent;
gf_node_dom_listener_add((GF_Node *)par, elt);
}
}
return elt;
},0

static struct inode *read_inode(unsigned int start_block, unsigned int offset)
{
static union squashfs_inode_header_3 header;
long long start = sBlk.s.inode_table_start + start_block;
int bytes = lookup_entry(inode_table_hash, start);
char *block_ptr = inode_table + bytes + offset;
static struct inode i;
TRACE("read_inode: reading inode [%d:%d]\n", start_block, offset);
if(bytes == -1)
EXIT_UNSQUASH("read_inode: inode table block %lld not found\n",
start);
if(swap) {
squashfs_base_inode_header_3 sinode;
memcpy(&sinode, block_ptr, sizeof(header.base));
SQUASHFS_SWAP_BASE_INODE_HEADER_3(&header.base, &sinode,
sizeof(squashfs_base_inode_header_3));
} else
memcpy(&header.base, block_ptr, sizeof(header.base));
i.xattr = SQUASHFS_INVALID_XATTR;
i.uid = (uid_t) uid_table[header.base.uid];
i.gid = header.base.guid == SQUASHFS_GUIDS ? i.uid :
(uid_t) guid_table[header.base.guid];
i.mode = lookup_type[header.base.inode_type] | header.base.mode;
i.type = header.base.inode_type;
i.time = header.base.mtime;
i.inode_number = header.base.inode_number;
switch(header.base.inode_type) {
case SQUASHFS_DIR_TYPE: {
squashfs_dir_inode_header_3 *inode = &header.dir;
if(swap) {
squashfs_dir_inode_header_3 sinode;
memcpy(&sinode, block_ptr, sizeof(header.dir));
SQUASHFS_SWAP_DIR_INODE_HEADER_3(&header.dir,
&sinode);
} else
memcpy(&header.dir, block_ptr,
sizeof(header.dir));
i.data = inode->file_size;
i.offset = inode->offset;
i.start = inode->start_block;
break;
}
case SQUASHFS_LDIR_TYPE: {
squashfs_ldir_inode_header_3 *inode = &header.ldir;
if(swap) {
squashfs_ldir_inode_header_3 sinode;
memcpy(&sinode, block_ptr, sizeof(header.ldir));
SQUASHFS_SWAP_LDIR_INODE_HEADER_3(&header.ldir,
&sinode);
} else
memcpy(&header.ldir, block_ptr,
sizeof(header.ldir));
i.data = inode->file_size;
i.offset = inode->offset;
i.start = inode->start_block;
break;
}
case SQUASHFS_FILE_TYPE: {
squashfs_reg_inode_header_3 *inode = &header.reg;
if(swap) {
squashfs_reg_inode_header_3 sinode;
memcpy(&sinode, block_ptr, sizeof(sinode));
SQUASHFS_SWAP_REG_INODE_HEADER_3(inode,
&sinode);
} else
memcpy(inode, block_ptr, sizeof(*inode));
i.data = inode->file_size;
i.frag_bytes = inode->fragment == SQUASHFS_INVALID_FRAG
? 0 : inode->file_size % sBlk.s.block_size;
i.fragment = inode->fragment;
i.offset = inode->offset;
i.blocks = inode->fragment == SQUASHFS_INVALID_FRAG ?
(i.data + sBlk.s.block_size - 1) >>
sBlk.s.block_log :
i.data >> sBlk.s.block_log;
i.start = inode->start_block;
i.sparse = 1;
i.block_ptr = block_ptr + sizeof(*inode);
break;
}
case SQUASHFS_LREG_TYPE: {
squashfs_lreg_inode_header_3 *inode = &header.lreg;
if(swap) {
squashfs_lreg_inode_header_3 sinode;
memcpy(&sinode, block_ptr, sizeof(sinode));
SQUASHFS_SWAP_LREG_INODE_HEADER_3(inode,
&sinode);
} else
memcpy(inode, block_ptr, sizeof(*inode));
i.data = inode->file_size;
i.frag_bytes = inode->fragment == SQUASHFS_INVALID_FRAG
? 0 : inode->file_size % sBlk.s.block_size;
i.fragment = inode->fragment;
i.offset = inode->offset;
i.blocks = inode->fragment == SQUASHFS_INVALID_FRAG ?
(inode->file_size + sBlk.s.block_size - 1) >>
sBlk.s.block_log :
inode->file_size >> sBlk.s.block_log;
i.start = inode->start_block;
i.sparse = 1;
i.block_ptr = block_ptr + sizeof(*inode);
break;
}
case SQUASHFS_SYMLINK_TYPE: {
squashfs_symlink_inode_header_3 *inodep =
&header.symlink;
if(swap) {
squashfs_symlink_inode_header_3 sinodep;
memcpy(&sinodep, block_ptr, sizeof(sinodep));
SQUASHFS_SWAP_SYMLINK_INODE_HEADER_3(inodep,
&sinodep);
} else
memcpy(inodep, block_ptr, sizeof(*inodep));
i.symlink = malloc(inodep->symlink_size + 1);
if(i.symlink == NULL)
EXIT_UNSQUASH("read_inode: failed to malloc "
"symlink data\n");
strncpy(i.symlink, block_ptr +
sizeof(squashfs_symlink_inode_header_3),
inodep->symlink_size);
i.symlink[inodep->symlink_size] = '\0';
i.data = inodep->symlink_size;
break;
}
case SQUASHFS_BLKDEV_TYPE:
case SQUASHFS_CHRDEV_TYPE: {
squashfs_dev_inode_header_3 *inodep = &header.dev;
if(swap) {
squashfs_dev_inode_header_3 sinodep;
memcpy(&sinodep, block_ptr, sizeof(sinodep));
SQUASHFS_SWAP_DEV_INODE_HEADER_3(inodep,
&sinodep);
} else
memcpy(inodep, block_ptr, sizeof(*inodep));
i.data = inodep->rdev;
break;
}
case SQUASHFS_FIFO_TYPE:
case SQUASHFS_SOCKET_TYPE:
i.data = 0;
break;
default:
EXIT_UNSQUASH("Unknown inode type %d in read_inode!\n",
header.base.inode_type);
}
return &i;
},0

