_pixops_composite_real (guchar *dest_buf,
int render_x0,
int render_y0,
int render_x1,
int render_y1,
int dest_rowstride,
int dest_channels,
gboolean dest_has_alpha,
const guchar *src_buf,
int src_width,
int src_height,
int src_rowstride,
int src_channels,
gboolean src_has_alpha,
double scale_x,
double scale_y,
PixopsInterpType interp_type,
int overall_alpha)
{
PixopsFilter filter;
PixopsLineFunc line_func;
#ifdef USE_MMX
gboolean found_mmx = _pixops_have_mmx ();
#endif
g_return_if_fail (!(dest_channels == 3 && dest_has_alpha));
g_return_if_fail (!(src_channels == 3 && src_has_alpha));
if (scale_x == 0 || scale_y == 0)
return;
if (interp_type == PIXOPS_INTERP_NEAREST)
{
if (scale_x == 1.0 && scale_y == 1.0)
pixops_composite_nearest_noscale (dest_buf, render_x0, render_y0, render_x1, render_y1,
dest_rowstride, dest_channels, dest_has_alpha,
src_buf, src_width, src_height, src_rowstride, src_channels,
src_has_alpha, overall_alpha);
else
pixops_composite_nearest (dest_buf, render_x0, render_y0, render_x1, render_y1,
dest_rowstride, dest_channels, dest_has_alpha,
src_buf, src_width, src_height, src_rowstride, src_channels,
src_has_alpha, scale_x, scale_y, overall_alpha);
return;
}
filter.overall_alpha = overall_alpha / 255.;
make_weights (&filter, interp_type, scale_x, scale_y);
if (filter.x.n == 2 && filter.y.n == 2 && dest_channels == 4 &&
src_channels == 4 && src_has_alpha && !dest_has_alpha)
{
#ifdef USE_MMX
if (found_mmx)
line_func = composite_line_22_4a4_mmx_stub;
else
#endif
line_func = composite_line_22_4a4;
}
else
line_func = composite_line;
pixops_process (dest_buf, render_x0, render_y0, render_x1, render_y1,
dest_rowstride, dest_channels, dest_has_alpha,
src_buf, src_width, src_height, src_rowstride, src_channels,
src_has_alpha, scale_x, scale_y, 0, 0, 0, 0, 0,
&filter, line_func, composite_pixel);
g_free (filter.x.weights);
g_free (filter.y.weights);
},1

static int replmd_replicated_uptodate_vector(struct replmd_replicated_request *ar)
{
struct ldb_context *ldb = ldb_module_get_ctx(ar->module);
struct replmd_private *replmd_private =
talloc_get_type_abort(ldb_module_get_private(ar->module),
struct replmd_private);
int ret;
static const char *attrs[] = {
"replUpToDateVector",
"repsFrom",
"instanceType",
NULL
};
struct ldb_request *search_req;
ar->search_msg = NULL;
ar->objs->originating_updates = replmd_private->originating_updates;
ret = ldb_build_search_req(&search_req,
ldb,
ar,
ar->objs->partition_dn,
LDB_SCOPE_BASE,
"(objectClass=*)",
attrs,
NULL,
ar,
replmd_replicated_uptodate_search_callback,
ar->req);
LDB_REQ_SET_LOCATION(search_req);
if (ret != LDB_SUCCESS) return replmd_replicated_request_error(ar, ret);
return ldb_next_request(ar->module, search_req);
},0

