DU_cmoveStatusString(Uint16 statusCode)
{
const char *s = NULL;
switch (statusCode) {
case STATUS_Success:
s = "Success";
break;
case STATUS_Pending:
s = "Pending";
break;
case STATUS_MOVE_Refused_OutOfResourcesNumberOfMatches:
s = "Refused: OutOfResourcesNumberOfMatches";
break;
case STATUS_MOVE_Refused_OutOfResourcesSubOperations:
s = "Refused: OutOfResourcesSubOperations";
break;
case STATUS_MOVE_Failed_SOPClassNotSupported:
s = "Failed: SOPClassNotSupported";
break;
case STATUS_MOVE_Failed_MoveDestinationUnknown:
s = "Failed: MoveDestinationUnknown";
break;
case STATUS_MOVE_Failed_IdentifierDoesNotMatchSOPClass:
s = "Failed: IdentifierDoesNotMatchSOPClass";
break;
case STATUS_MOVE_Cancel_SubOperationsTerminatedDueToCancelIndication:
s = "Cancel: SubOperationsTerminatedDueToCancelIndication";
break;
case STATUS_MOVE_Warning_SubOperationsCompleteOneOrMoreFailures:
s = "Warning: SubOperationsCompleteOneOrMoreFailures";
break;
}
if (s)
return s;
switch (statusCode & 0xf000) {
case STATUS_MOVE_Failed_UnableToProcess:
s = "Failed: UnableToProcess";
break;
}
if (s == NULL) {
sprintf(staticBuf, "Unknown Status: 0x%x", (unsigned int)statusCode);
s = staticBuf;
}
return s;
},0

rdp_in_unistr(STREAM s, int in_len, char **string, uint32 * str_size)
{
*string = xmalloc(in_len * 2);
*str_size = in_len * 2;
#ifdef HAVE_ICONV
size_t ibl = in_len, obl = *str_size - 1;
char *pin = (char *) s->p, *pout = *string;
static iconv_t iconv_h = (iconv_t) - 1;
if (g_iconv_works)
{
if (iconv_h == (iconv_t) - 1)
{
if ((iconv_h = iconv_open(g_codepage, WINDOWS_CODEPAGE)) == (iconv_t) - 1)
{
warning("rdp_in_unistr: iconv_open[%s -> %s] fail %p\n",
WINDOWS_CODEPAGE, g_codepage, iconv_h);
g_iconv_works = False;
return rdp_in_unistr(s, in_len, string, str_size);
}
}
if (iconv(iconv_h, (ICONV_CONST char **) &pin, &ibl, &pout, &obl) == (size_t) - 1)
{
if (errno == E2BIG)
{
warning("server sent an unexpectedly long string, truncating\n");
}
else
{
warning("rdp_in_unistr: iconv fail, errno %d\n", errno);
free(*string);
*string = NULL;
*str_size = 0;
}
}
s->p += in_len;
*pout = 0;
if (*string)
*str_size = pout - *string;
}
else
#endif
{
int i = 0;
int rem = 0;
uint32 len = in_len / 2;
if (len > *str_size - 1)
{
warning("server sent an unexpectedly long string, truncating\n");
len = *str_size - 1;
rem = in_len - 2 * len;
}
while (i < len)
{
in_uint8a(s, &string[i++], 1);
in_uint8s(s, 1);
}
in_uint8s(s, rem);
string[len] = 0;
*str_size = len;
}
},1

listen_loop(void *x) {
int optval = 1;
struct pollfd pa[100];
struct pollfd *p;
struct _agooErr err = AGOO_ERR_INIT;
struct sockaddr_in client_addr;
int client_sock;
int pcnt = 0;
socklen_t alen = 0;
agooCon con;
int i;
uint64_t cnt = 0;
agooBind b;
for (b = agoo_server.binds, p = pa; NULL != b; b = b->next, p++, pcnt++) {
p->fd = b->fd;
p->events = POLLIN;
p->revents = 0;
}
memset(&client_addr, 0, sizeof(client_addr));
atomic_fetch_add(&agoo_server.running, 1);
while (agoo_server.active) {
if (0 > (i = poll(pa, pcnt, 200))) {
if (EAGAIN == errno) {
continue;
}
agoo_log_cat(&agoo_error_cat, "Server polling error. %s.", strerror(errno));
break;
}
if (0 == i) {
continue;
}
for (b = agoo_server.binds, p = pa; NULL != b; b = b->next, p++) {
if (0 != (p->revents & POLLIN)) {
if (0 > (client_sock = accept(p->fd, (struct sockaddr*)&client_addr, &alen))) {
agoo_log_cat(&agoo_error_cat, "Server with pid %d accept connection failed. %s.", getpid(), strerror(errno));
} else if (NULL == (con = agoo_con_create(&err, client_sock, ++cnt, b))) {
agoo_log_cat(&agoo_error_cat, "Server with pid %d accept connection failed. %s.", getpid(), err.msg);
close(client_sock);
cnt--;
agoo_err_clear(&err);
} else {
int con_cnt;
#ifdef OSX_OS
setsockopt(client_sock, SOL_SOCKET, SO_NOSIGPIPE, &optval, sizeof(optval));
#endif
#ifdef PLATFORM_LINUX
setsockopt(client_sock, IPPROTO_TCP, TCP_QUICKACK, &optval, sizeof(optval));
#endif
fcntl(client_sock, F_SETFL, O_NONBLOCK);
setsockopt(client_sock, SOL_SOCKET, SO_KEEPALIVE, &optval, sizeof(optval));
setsockopt(client_sock, IPPROTO_TCP, TCP_NODELAY, &optval, sizeof(optval));
agoo_log_cat(&agoo_con_cat, "Server with pid %d accepted connection %llu on %s [%d]",
getpid(), (unsigned long long)cnt, b->id, con->sock);
con_cnt = atomic_fetch_add(&agoo_server.con_cnt, 1);
if (agoo_server.loop_max > agoo_server.loop_cnt && agoo_server.loop_cnt * LOOP_UP < con_cnt) {
add_con_loop();
}
agoo_queue_push(&agoo_server.con_queue, (void*)con);
}
}
if (0 != (p->revents & (POLLERR | POLLHUP | POLLNVAL))) {
if (0 != (p->revents & (POLLHUP | POLLNVAL))) {
agoo_log_cat(&agoo_error_cat, "Agoo server with pid %d socket on %s closed.", getpid(), b->id);
} else {
agoo_log_cat(&agoo_error_cat, "Agoo server with pid %d socket on %s error.", getpid(), b->id);
}
agoo_server.active = false;
}
p->revents = 0;
}
}
for (b = agoo_server.binds; NULL != b; b = b->next) {
agoo_bind_close(b);
}
atomic_fetch_sub(&agoo_server.running, 1);
return NULL;
},1

static void store_adapter_info(struct btd_adapter *adapter)
{
GKeyFile *key_file;
char filename[PATH_MAX];
char *str;
gsize length = 0;
gboolean discoverable;
key_file = g_key_file_new();
if (adapter->pairable_timeout != btd_opts.pairto)
g_key_file_set_integer(key_file, "General", "PairableTimeout",
adapter->pairable_timeout);
if ((adapter->current_settings & MGMT_SETTING_DISCOVERABLE) &&
!adapter->discoverable_timeout)
discoverable = TRUE;
else
discoverable = FALSE;
g_key_file_set_boolean(key_file, "General", "Discoverable",
discoverable);
if (adapter->discoverable_timeout != btd_opts.discovto)
g_key_file_set_integer(key_file, "General",
"DiscoverableTimeout",
adapter->discoverable_timeout);
if (adapter->stored_alias)
g_key_file_set_string(key_file, "General", "Alias",
adapter->stored_alias);
snprintf(filename, PATH_MAX, STORAGEDIR "/%s/settings",
btd_adapter_get_storage_dir(adapter));
create_file(filename, 0600);
str = g_key_file_to_data(key_file, &length, NULL);
g_file_set_contents(filename, str, length, NULL);
g_free(str);
g_key_file_free(key_file);
},0

