encodeJsonStructure(const void *src, const UA_DataType *type, CtxJson *ctx) {
if(ctx->depth > UA_JSON_ENCODING_MAX_RECURSION)
return UA_STATUSCODE_BADENCODINGERROR;
ctx->depth++;
status ret = writeJsonObjStart(ctx);
uintptr_t ptr = (uintptr_t) src;
u8 membersSize = type->membersSize;
const UA_DataType * typelists[2] = {UA_TYPES, &type[-type->typeIndex]};
for(size_t i = 0; i < membersSize && ret == UA_STATUSCODE_GOOD; ++i) {
const UA_DataTypeMember *m = &type->members[i];
const UA_DataType *mt = &typelists[!m->namespaceZero][m->memberTypeIndex];
if(m->memberName != NULL && *m->memberName != 0)
ret |= writeJsonKey(ctx, m->memberName);
if(!m->isArray) {
ptr += m->padding;
size_t memSize = mt->memSize;
ret |= encodeJsonJumpTable[mt->typeKind]((const void*) ptr, mt, ctx);
ptr += memSize;
} else {
ptr += m->padding;
const size_t length = *((const size_t*) ptr);
ptr += sizeof (size_t);
ret |= encodeJsonArray(ctx, *(void * const *)ptr, length, mt);
ptr += sizeof (void*);
}
}
ret |= writeJsonObjEnd(ctx);
ctx->depth--;
return ret;
},1

soup_auth_ntlm_update_connection (SoupConnectionAuth *auth, SoupMessage *msg,
const char *auth_header, gpointer state)
{
SoupAuthNTLM *auth_ntlm = SOUP_AUTH_NTLM (auth);
SoupAuthNTLMPrivate *priv = soup_auth_ntlm_get_instance_private (auth_ntlm);
SoupNTLMConnectionState *conn = state;
gboolean success = TRUE;
if (!g_str_has_prefix (auth_header, "NTLM"))
return FALSE;
if (conn->state > SOUP_NTLM_SENT_REQUEST) {
if (priv->password_state == SOUP_NTLM_PASSWORD_ACCEPTED) {
conn->state = SOUP_NTLM_FAILED;
if (soup_message_is_keepalive (msg)) {
soup_message_headers_append (msg->response_headers,
"Connection", "close");
}
return TRUE;
}
#ifdef USE_NTLM_AUTH
if (priv->sso_available) {
conn->state = SOUP_NTLM_SSO_FAILED;
priv->password_state = SOUP_NTLM_PASSWORD_NONE;
} else {
#endif
conn->state = SOUP_NTLM_FAILED;
priv->password_state = SOUP_NTLM_PASSWORD_REJECTED;
#ifdef USE_NTLM_AUTH
}
#endif
return TRUE;
}
if (conn->state == SOUP_NTLM_NEW && !auth_header[4])
return TRUE;
if (!auth_header[4] || !auth_header[5]) {
conn->state = SOUP_NTLM_FAILED;
return FALSE;
}
if (!soup_ntlm_parse_challenge (auth_header + 5, &conn->nonce,
priv->domain ? NULL : &priv->domain,
&conn->ntlmv2_session)) {
conn->state = SOUP_NTLM_FAILED;
return FALSE;
}
#ifdef USE_NTLM_AUTH
if (priv->sso_available && conn->state == SOUP_NTLM_SENT_REQUEST) {
char *input, *response;
if (!sso_ntlm_initiate (priv)) {
conn->state = SOUP_NTLM_SSO_FAILED;
success = FALSE;
goto out;
}
input = g_strdup_printf ("TT %s\n", auth_header + 5);
response = sso_ntlm_response (priv, input, conn->state);
sso_ntlm_close (priv);
g_free (input);
if (!response) {
conn->state = SOUP_NTLM_SSO_FAILED;
success = FALSE;
} else if (!g_ascii_strcasecmp (response, "PW")) {
conn->state = SOUP_NTLM_SSO_FAILED;
priv->sso_available = FALSE;
g_free (response);
} else {
conn->response_header = response;
if (priv->password_state != SOUP_NTLM_PASSWORD_ACCEPTED)
priv->password_state = SOUP_NTLM_PASSWORD_PROVIDED;
}
}
out:
#endif
if (conn->state == SOUP_NTLM_SENT_REQUEST)
conn->state = SOUP_NTLM_RECEIVED_CHALLENGE;
g_object_set (G_OBJECT (auth),
SOUP_AUTH_REALM, priv->domain,
SOUP_AUTH_HOST, soup_message_get_uri (msg)->host,
NULL);
return success;
},1

check_tgs_flags(astgs_request_t r, KDC_REQ_BODY *b,
krb5_const_principal tgt_name,
const EncTicketPart *tgt, EncTicketPart *et)
{
krb5_context context = r->context;
KDCOptions f = b->kdc_options;
if(f.validate){
if (!tgt->flags.invalid || tgt->starttime == NULL) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request to validate ticket");
return KRB5KDC_ERR_BADOPTION;
}
if(*tgt->starttime > kdc_time){
_kdc_audit_addreason((kdc_request_t)r,
"Early request to validate ticket");
return KRB5KRB_AP_ERR_TKT_NYV;
}
et->flags.invalid = 0;
} else if (tgt->flags.invalid) {
_kdc_audit_addreason((kdc_request_t)r,
"Ticket-granting ticket has INVALID flag set");
return KRB5KRB_AP_ERR_TKT_INVALID;
}
if(f.forwardable){
if (!tgt->flags.forwardable) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request for forwardable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.forwardable = 1;
}
if(f.forwarded){
if (!tgt->flags.forwardable) {
_kdc_audit_addreason((kdc_request_t)r,
"Request to forward non-forwardable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.forwarded = 1;
et->caddr = b->addresses;
}
if(tgt->flags.forwarded)
et->flags.forwarded = 1;
if(f.proxiable){
if (!tgt->flags.proxiable) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request for proxiable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.proxiable = 1;
}
if(f.proxy){
if (!tgt->flags.proxiable) {
_kdc_audit_addreason((kdc_request_t)r,
"Request to proxy non-proxiable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.proxy = 1;
et->caddr = b->addresses;
}
if(tgt->flags.proxy)
et->flags.proxy = 1;
if(f.allow_postdate){
if (!tgt->flags.may_postdate) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request for post-datable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.may_postdate = 1;
}
if(f.postdated){
if (!tgt->flags.may_postdate) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request for postdated ticket");
return KRB5KDC_ERR_BADOPTION;
}
if(b->from)
*et->starttime = *b->from;
et->flags.postdated = 1;
et->flags.invalid = 1;
} else if (b->from && *b->from > kdc_time + context->max_skew) {
_kdc_audit_addreason((kdc_request_t)r,
"Ticket cannot be postdated");
return KRB5KDC_ERR_CANNOT_POSTDATE;
}
if(f.renewable){
if (!tgt->flags.renewable || tgt->renew_till == NULL) {
_kdc_audit_addreason((kdc_request_t)r,
"Bad request for renewable ticket");
return KRB5KDC_ERR_BADOPTION;
}
et->flags.renewable = 1;
ALLOC(et->renew_till);
_kdc_fix_time(&b->rtime);
*et->renew_till = *b->rtime;
}
if(f.renew){
time_t old_life;
if (!tgt->flags.renewable || tgt->renew_till == NULL) {
_kdc_audit_addreason((kdc_request_t)r,
"Request to renew non-renewable ticket");
return KRB5KDC_ERR_BADOPTION;
}
old_life = tgt->endtime;
if(tgt->starttime)
old_life -= *tgt->starttime;
else
old_life -= tgt->authtime;
et->endtime = *et->starttime + old_life;
if (et->renew_till != NULL)
et->endtime = min(*et->renew_till, et->endtime);
}
if (tgt->flags.anonymous &&
!_kdc_is_anonymous(context, tgt_name)) {
_kdc_audit_addreason((kdc_request_t)r,
"Anonymous ticket flag set without "
"anonymous principal");
return KRB5KDC_ERR_BADOPTION;
}
if (is_anon_tgs_request_p(b, tgt))
et->flags.anonymous = 1;
return 0;
},0

