xmlParseAttValueComplex(xmlParserCtxtPtr ctxt, int *attlen, int normalize) {
xmlChar limit = 0;
xmlChar *buf = NULL;
xmlChar *rep = NULL;
size_t len = 0;
size_t buf_size = 0;
int c, l, in_space = 0;
xmlChar *current = NULL;
xmlEntityPtr ent;
if (NXT(0) == '"') {
ctxt->instate = XML_PARSER_ATTRIBUTE_VALUE;
limit = '"';
NEXT;
} else if (NXT(0) == '\'') {
limit = '\'';
ctxt->instate = XML_PARSER_ATTRIBUTE_VALUE;
NEXT;
} else {
xmlFatalErr(ctxt, XML_ERR_ATTRIBUTE_NOT_STARTED, NULL);
return(NULL);
}
buf_size = XML_PARSER_BUFFER_SIZE;
buf = (xmlChar *) xmlMallocAtomic(buf_size);
if (buf == NULL) goto mem_error;
c = CUR_CHAR(l);
while (((NXT(0) != limit) &&
(IS_CHAR(c)) && (c != '<')) &&
(ctxt->instate != XML_PARSER_EOF)) {
if ((len > XML_MAX_TEXT_LENGTH) &&
((ctxt->options & XML_PARSE_HUGE) == 0)) {
xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
"AttValue length too long\n");
goto mem_error;
}
if (c == 0) break;
if (c == '&') {
in_space = 0;
if (NXT(1) == '#') {
int val = xmlParseCharRef(ctxt);
if (val == '&') {
if (ctxt->replaceEntities) {
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
buf[len++] = '&';
} else {
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
buf[len++] = '&';
buf[len++] = '#';
buf[len++] = '3';
buf[len++] = '8';
buf[len++] = ';';
}
} else if (val != 0) {
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
len += xmlCopyChar(0, &buf[len], val);
}
} else {
ent = xmlParseEntityRef(ctxt);
ctxt->nbentities++;
if (ent != NULL)
ctxt->nbentities += ent->owner;
if ((ent != NULL) &&
(ent->etype == XML_INTERNAL_PREDEFINED_ENTITY)) {
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
if ((ctxt->replaceEntities == 0) &&
(ent->content[0] == '&')) {
buf[len++] = '&';
buf[len++] = '#';
buf[len++] = '3';
buf[len++] = '8';
buf[len++] = ';';
} else {
buf[len++] = ent->content[0];
}
} else if ((ent != NULL) &&
(ctxt->replaceEntities != 0)) {
if (ent->etype != XML_INTERNAL_PREDEFINED_ENTITY) {
rep = xmlStringDecodeEntities(ctxt, ent->content,
XML_SUBSTITUTE_REF,
0, 0, 0);
if (rep != NULL) {
current = rep;
while (*current != 0) {
if ((*current == 0xD) || (*current == 0xA) ||
(*current == 0x9)) {
buf[len++] = 0x20;
current++;
} else
buf[len++] = *current++;
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
}
xmlFree(rep);
rep = NULL;
}
} else {
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
if (ent->content != NULL)
buf[len++] = ent->content[0];
}
} else if (ent != NULL) {
int i = xmlStrlen(ent->name);
const xmlChar *cur = ent->name;
if ((ent->etype != XML_INTERNAL_PREDEFINED_ENTITY) &&
(ent->content != NULL)) {
rep = xmlStringDecodeEntities(ctxt, ent->content,
XML_SUBSTITUTE_REF, 0, 0, 0);
if (rep != NULL) {
xmlFree(rep);
rep = NULL;
}
}
buf[len++] = '&';
while (len + i + 10 > buf_size) {
growBuffer(buf, i + 10);
}
for (;i > 0;i--)
buf[len++] = *cur++;
buf[len++] = ';';
}
}
} else {
if ((c == 0x20) || (c == 0xD) || (c == 0xA) || (c == 0x9)) {
if ((len != 0) || (!normalize)) {
if ((!normalize) || (!in_space)) {
COPY_BUF(l,buf,len,0x20);
while (len + 10 > buf_size) {
growBuffer(buf, 10);
}
}
in_space = 1;
}
} else {
in_space = 0;
COPY_BUF(l,buf,len,c);
if (len + 10 > buf_size) {
growBuffer(buf, 10);
}
}
NEXTL(l);
}
GROW;
c = CUR_CHAR(l);
}
if (ctxt->instate == XML_PARSER_EOF)
goto error;
if ((in_space) && (normalize)) {
while ((len > 0) && (buf[len - 1] == 0x20)) len--;
}
buf[len] = 0;
if (RAW == '<') {
xmlFatalErr(ctxt, XML_ERR_LT_IN_ATTRIBUTE, NULL);
} else if (RAW != limit) {
if ((c != 0) && (!IS_CHAR(c))) {
xmlFatalErrMsg(ctxt, XML_ERR_INVALID_CHAR,
"invalid character in attribute value\n");
} else {
xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
"AttValue: ' expected\n");
}
} else
NEXT;
if (len >= INT_MAX) {
xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
"AttValue length too long\n");
goto mem_error;
}
if (attlen != NULL) *attlen = (int) len;
return(buf);
mem_error:
xmlErrMemory(ctxt, NULL);
error:
if (buf != NULL)
xmlFree(buf);
if (rep != NULL)
xmlFree(rep);
return(NULL);
},0

void Filter::onUpstreamHeaders(uint64_t response_code, Http::ResponseHeaderMapPtr&& headers,
UpstreamRequest& upstream_request, bool end_stream) {
ENVOY_STREAM_LOG(debug, "upstream headers complete: end_stream={}", *callbacks_, end_stream);
modify_headers_(*headers);
absl::optional<Grpc::Status::GrpcStatus> grpc_status;
uint64_t grpc_to_http_status = 0;
if (grpc_request_) {
grpc_status = Grpc::Common::getGrpcStatus(*headers);
if (grpc_status.has_value()) {
grpc_to_http_status = Grpc::Utility::grpcToHttpStatus(grpc_status.value());
}
}
if (grpc_status.has_value()) {
upstream_request.upstreamHost()->outlierDetector().putHttpResponseCode(grpc_to_http_status);
} else {
upstream_request.upstreamHost()->outlierDetector().putHttpResponseCode(response_code);
}
if (headers->EnvoyImmediateHealthCheckFail() != nullptr) {
upstream_request.upstreamHost()->healthChecker().setUnhealthy(
Upstream::HealthCheckHostMonitor::UnhealthyType::ImmediateHealthCheckFail);
}
bool could_not_retry = false;
if (retry_state_) {
if (upstream_request.retried()) {
could_not_retry = retry_state_->wouldRetryFromHeaders(*headers);
} else {
const RetryStatus retry_status =
retry_state_->shouldRetryHeaders(*headers, [this]() -> void { doRetry(); });
if (retry_status == RetryStatus::Yes) {
runRetryOptionsPredicates(upstream_request);
pending_retries_++;
upstream_request.upstreamHost()->stats().rq_error_.inc();
Http::CodeStats& code_stats = httpContext().codeStats();
code_stats.chargeBasicResponseStat(
cluster_->statsScope(), config_.stats_.stat_names_.retry_,
static_cast<Http::Code>(response_code), exclude_http_code_stats_);
if (!end_stream || !upstream_request.encodeComplete()) {
upstream_request.resetStream();
}
auto request_ptr = upstream_request.removeFromList(upstream_requests_);
if (Runtime::runtimeFeatureEnabled(
"envoy.reloadable_features.allow_upstream_inline_write")) {
request_ptr->cleanUp();
callbacks_->dispatcher().deferredDelete(std::move(request_ptr));
}
return;
} else if (retry_status == RetryStatus::NoOverflow) {
callbacks_->streamInfo().setResponseFlag(StreamInfo::ResponseFlag::UpstreamOverflow);
could_not_retry = true;
} else if (retry_status == RetryStatus::NoRetryLimitExceeded) {
callbacks_->streamInfo().setResponseFlag(
StreamInfo::ResponseFlag::UpstreamRetryLimitExceeded);
could_not_retry = true;
}
}
}
if (route_entry_->internalRedirectPolicy().enabled() &&
route_entry_->internalRedirectPolicy().shouldRedirectForResponseCode(
static_cast<Http::Code>(response_code)) &&
setupRedirect(*headers)) {
return;
}
if (could_not_retry && (numRequestsAwaitingHeaders() > 0 || pending_retries_ > 0)) {
upstream_request.upstreamHost()->stats().rq_error_.inc();
auto request_ptr = upstream_request.removeFromList(upstream_requests_);
request_ptr->resetStream();
if (Runtime::runtimeFeatureEnabled("envoy.reloadable_features.allow_upstream_inline_write")) {
request_ptr->cleanUp();
callbacks_->dispatcher().deferredDelete(std::move(request_ptr));
}
return;
}
if (retry_state_) {
retry_state_.reset();
}
if (DateUtil::timePointValid(downstream_request_complete_time_)) {
Event::Dispatcher& dispatcher = callbacks_->dispatcher();
MonotonicTime response_received_time = dispatcher.timeSource().monotonicTime();
std::chrono::milliseconds ms = std::chrono::duration_cast<std::chrono::milliseconds>(
response_received_time - downstream_request_complete_time_);
if (!config_.suppress_envoy_headers_) {
headers->setEnvoyUpstreamServiceTime(ms.count());
}
}
upstream_request.upstreamCanary(
(headers->EnvoyUpstreamCanary() && headers->EnvoyUpstreamCanary()->value() == "true") ||
upstream_request.upstreamHost()->canary());
chargeUpstreamCode(response_code, *headers, upstream_request.upstreamHost(), false);
if (!Http::CodeUtility::is5xx(response_code)) {
handleNon5xxResponseHeaders(grpc_status, upstream_request, end_stream, grpc_to_http_status);
}
for (const auto& header_value : downstream_set_cookies_) {
headers->addReferenceKey(Http::Headers::get().SetCookie, header_value);
}
route_entry_->finalizeResponseHeaders(*headers, callbacks_->streamInfo());
downstream_response_started_ = true;
final_upstream_request_ = &upstream_request;
callbacks_->streamInfo().setUpstreamInfo(final_upstream_request_->streamInfo().upstreamInfo());
resetOtherUpstreams(upstream_request);
if (end_stream) {
onUpstreamComplete(upstream_request);
}
callbacks_->encodeHeaders(std::move(headers), end_stream,
StreamInfo::ResponseCodeDetails::get().ViaUpstream);
},0

readconf_acl(void)
{
uschar *p;
acl_line = get_config_line();
while(acl_line != NULL)
{
uschar name[64];
tree_node *node;
uschar *error;
p = readconf_readname(name, sizeof(name), acl_line);
if (isupper(*name) && *p == '=')
{
read_macro_assignment(acl_line);
acl_line = get_config_line();
continue;
}
if (*p != ':' || name[0] == 0)
log_write(0, LOG_PANIC_DIE|LOG_CONFIG_IN, "missing or malformed ACL name");
node = store_get(sizeof(tree_node) + Ustrlen(name));
Ustrcpy(node->name, name);
if (!tree_insertnode(&acl_anchor, node))
log_write(0, LOG_PANIC_DIE|LOG_CONFIG_IN,
"there are two ACLs called \"%s\"", name);
node->data.ptr = acl_read(acl_callback, &error);
if (node->data.ptr == NULL && error != NULL)
log_write(0, LOG_PANIC_DIE|LOG_CONFIG_IN, "error in ACL: %s", error);
}
},0

static bool load_buffer(RzBinFile *bf, RzBinObject *obj, RzBuffer *buf, Sdb *sdb) {
lmf_record lrec;
lmf_resource lres;
lmf_data ldata;
ut64 offset = QNX_RECORD_SIZE;
QnxObj *qo = RZ_NEW0(QnxObj);
if (!qo) {
return false;
}
RzList *sections = rz_list_newf((RzListFree)rz_bin_section_free);
RzList *maps = rz_list_newf((RzListFree)rz_bin_map_free);
RzList *fixups = rz_list_newf(free);
if (!sections || !maps || !fixups) {
goto beach;
}
qo->kv = sdb_new0();
if (!qo->kv) {
goto beach;
}
if (rz_buf_fread_at(bf->buf, 0, (ut8 *)&lrec, "ccss", 1) < QNX_RECORD_SIZE) {
goto beach;
}
lmf_header_load(&qo->lmfh, bf->buf, qo->kv);
offset += lrec.data_nbytes;
for (;;) {
if (rz_buf_fread_at(bf->buf, offset, (ut8 *)&lrec, "ccss", 1) < QNX_RECORD_SIZE) {
goto beach;
}
offset += sizeof(lmf_record);
if (lrec.rec_type == LMF_IMAGE_END_REC) {
break;
} else if (lrec.rec_type == LMF_RESOURCE_REC) {
if (rz_buf_fread_at(bf->buf, offset, (ut8 *)&lres, "ssss", 1) < sizeof(lmf_resource)) {
goto beach;
}
RzBinSection *ptr = RZ_NEW0(RzBinSection);
if (!ptr) {
goto beach;
}
ptr->name = strdup("LMF_RESOURCE");
ptr->paddr = offset;
ptr->vsize = lrec.data_nbytes - sizeof(lmf_resource);
ptr->size = ptr->vsize;
rz_list_append(sections, ptr);
RzBinMap *map = RZ_NEW0(RzBinMap);
if (!map) {
goto beach;
}
map->name = ptr->name ? strdup(ptr->name) : NULL;
map->paddr = ptr->paddr;
map->psize = ptr->size;
map->vsize = ptr->vsize;
rz_list_append(maps, map);
} else if (lrec.rec_type == LMF_LOAD_REC) {
RzBinSection *ptr = RZ_NEW0(RzBinSection);
if (!ptr) {
goto beach;
}
if (rz_buf_fread_at(bf->buf, offset, (ut8 *)&ldata, "si", 1) < sizeof(lmf_data)) {
free(ptr);
goto beach;
}
ptr->name = strdup("LMF_LOAD");
ptr->paddr = offset;
ptr->vaddr = ldata.offset;
ptr->vsize = lrec.data_nbytes - sizeof(lmf_data);
ptr->size = ptr->vsize;
rz_list_append(sections, ptr);
RzBinMap *map = RZ_NEW0(RzBinMap);
if (!map) {
goto beach;
}
map->name = ptr->name ? strdup(ptr->name) : NULL;
map->paddr = ptr->paddr;
map->psize = ptr->size;
map->vsize = ptr->vsize;
rz_list_append(maps, map);
} else if (lrec.rec_type == LMF_FIXUP_REC) {
RzBinReloc *ptr = RZ_NEW0(RzBinReloc);
if (!ptr || rz_buf_fread_at(bf->buf, offset, (ut8 *)&ldata, "si", 1) < sizeof(lmf_data)) {
free(ptr);
goto beach;
}
ptr->vaddr = ptr->paddr = ldata.offset;
ptr->type = 'f';
rz_list_append(fixups, ptr);
} else if (lrec.rec_type == LMF_8087_FIXUP_REC) {
RzBinReloc *ptr = RZ_NEW0(RzBinReloc);
if (!ptr || rz_buf_fread_at(bf->buf, offset, (ut8 *)&ldata, "si", 1) < sizeof(lmf_data)) {
free(ptr);
goto beach;
}
ptr->vaddr = ptr->paddr = ldata.offset;
ptr->type = 'F';
rz_list_append(fixups, ptr);
} else if (lrec.rec_type == LMF_RW_END_REC) {
rz_buf_fread_at(bf->buf, offset, (ut8 *)&qo->rwend, "si", 1);
}
offset += lrec.data_nbytes;
}
sdb_ns_set(sdb, "info", qo->kv);
qo->sections = sections;
qo->maps = maps;
qo->fixups = fixups;
obj->bin_obj = qo;
return true;
beach:
free(qo);
rz_list_free(fixups);
rz_list_free(maps);
rz_list_free(sections);
return false;
},0

