int error;
if (!(res_file= popen(cmd, "r")))
die("popen(\"%s\", \"r\") failed", cmd);
while (fgets(buf, sizeof(buf), res_file))
{
DBUG_PRINT("info", ("buf: %s", buf));
if(ds_res)
{
dynstr_append(ds_res, buf);
}
else
{
fprintf(stdout, "%s", buf);
}
}
error= pclose(res_file);
return WEXITSTATUS(error);
