gif_get_next_step (GifContext *context)
{
unsigned char c;
while (TRUE) {
if (!gif_read (context, &c, 1)) {
return -1;
}
if (c == ';') {
context->state = GIF_DONE;
return 0;
}
if (c == '!') {
gif_set_get_extension (context);
return 0;
}
if (c != ',') {
continue;
}
gif_set_get_frame_info (context);
return 0;
}
