y_log_message(Y_LOG_LEVEL_ERROR, "check_credential_id - Error executing j_query");
config->glewlwyd_module_callback_metrics_increment_counter(config, GLWD_METRICS_DATABSE_ERROR, 1, NULL);
ret = G_ERROR_DB;
}
return ret;
