pos = (u_int8_t*)frame;
if (length < 2*ETHER_ADDR_LEN + sizeof(u_int16_t) +
8 + 4 ) {
log_warn("cdp", "too short CDP/FDP frame received on %s", hardware->h_ifname);
goto malformed;
