PEEK_DISCARD(6);
proto = PEEK_UINT16;
if (proto != LLC_PID_CDP) {
if ((proto != LLC_PID_DRIP) &&
(proto != LLC_PID_PAGP) &&
(proto != LLC_PID_PVSTP) &&
(proto != LLC_PID_UDLD) &&
(proto != LLC_PID_VTP) &&
(proto != LLC_PID_DTP) &&
