chassis->c_ttl = PEEK_UINT8;
PEEK_DISCARD_UINT16;
while (length) {
if (length < 4) {
log_warnx("cdp", "CDP/FDP TLV header is too large for "
"frame received on %s",
hardware->h_ifname);
goto malformed;
