cdata_read (cdata_t *cd, guint8 res_data, gint comptype,
GDataInputStream *in, GCancellable *cancellable, GError **error)
{
gboolean success = FALSE;
int ret, zret = Z_OK;
gint compression = comptype & GCAB_COMPRESSION_MASK;
guint8 *buf = compression == GCAB_COMPRESSION_NONE ? cd->out : cd->in;
guint32 datacsum;
guint8 sizecsum[4];
guint16 nbytes_le;
if (compression > GCAB_COMPRESSION_MSZIP &&
compression != GCAB_COMPRESSION_LZX) {
g_set_error (error, GCAB_ERROR, GCAB_ERROR_NOT_SUPPORTED,
"unsupported compression method %d", compression);
return FALSE;
}
R4 (cd->checksum);
R2 (cd->ncbytes);
R2 (cd->nubytes);
cd->reserved = g_malloc (res_data);
RN (cd->reserved, res_data);
RN (buf, cd->ncbytes);
datacsum = compute_checksum(buf, cd->ncbytes, 0);
nbytes_le = GUINT16_TO_LE (cd->ncbytes);
memcpy (&sizecsum[0], &nbytes_le, 2);
nbytes_le = GUINT16_TO_LE (cd->nubytes);
memcpy (&sizecsum[2], &nbytes_le, 2);
if (_enforce_checksum () && cd->checksum != compute_checksum (sizecsum, sizeof(sizecsum), datacsum)) {
g_set_error_literal (error, GCAB_ERROR, GCAB_ERROR_INVALID_DATA,
"incorrect checksum detected");
return FALSE;
}
if (g_getenv ("GCAB_DEBUG")) {
g_debug ("CDATA");
P4 (cd, checksum);
P2 (cd, ncbytes);
P2 (cd, nubytes);
if (res_data)
PN (cd, reserved, res_data);
PND (cd, buf, 64);
}
if (compression == GCAB_COMPRESSION_LZX) {
if (cd->fdi.alloc == NULL) {
cd->fdi.alloc = g_malloc;
cd->fdi.free = g_free;
cd->decomp.fdi = &cd->fdi;
cd->decomp.inbuf = cd->in;
cd->decomp.outbuf = cd->out;
cd->decomp.comptype = compression;
ret = LZXfdi_init((comptype >> 8) & 0x1f, &cd->decomp);
if (ret < 0)
goto end;
}
ret = LZXfdi_decomp (cd->ncbytes, cd->nubytes, &cd->decomp);
if (ret < 0)
goto end;
}
if (compression == GCAB_COMPRESSION_MSZIP) {
if (cd->in[0] != 'C' || cd->in[1] != 'K')
goto end;
cd->decomp.comptype = compression;
z_stream *z = &cd->z;
z->avail_in = cd->ncbytes - 2;
z->next_in = cd->in + 2;
z->avail_out = cd->nubytes;
z->next_out = cd->out;
z->total_out = 0;
if (!z->opaque) {
z->zalloc = zalloc;
z->zfree = zfree;
z->opaque = cd;
zret = inflateInit2 (z, -MAX_WBITS);
if (zret != Z_OK)
goto end;
}
while (1) {
zret = inflate (z, Z_BLOCK);
if (zret == Z_STREAM_END)
break;
if (zret != Z_OK)
goto end;
}
g_warn_if_fail (z->avail_in == 0);
g_warn_if_fail (z->avail_out == 0);
if (z->avail_in != 0 || z->avail_out != 0)
goto end;
zret = inflateReset (z);
if (zret != Z_OK)
goto end;
zret = inflateSetDictionary (z, cd->out, cd->nubytes);
if (zret != Z_OK)
goto end;
}
success = TRUE;
end:
if (zret != Z_OK)
g_set_error (error, GCAB_ERROR, GCAB_ERROR_FAILED,
"zlib failed: %s", zError (zret));
if (error != NULL && *error == NULL && !success)
g_set_error (error, GCAB_ERROR, GCAB_ERROR_FAILED,
"Invalid cabinet chunk");
return success;
},0

static void ProcessExifDir(unsigned char * DirStart, unsigned char * OffsetBase,
int ExifLength, int NestingLevel)
{
int de;
int a;
int NumDirEntries;
int ThumbnailOffset = 0;
int ThumbnailSize = 0;
char IndentString[25];
int OffsetVal;
if (NestingLevel > 4){
ErrNonfatal("Maximum Exif directory nesting exceeded (corrupt Exif header)", 0,0);
return;
}
memset(IndentString, ' ', 25);
IndentString[NestingLevel * 4] = '\0';
NumDirEntries = Get16u(DirStart);
#define DIR_ENTRY_ADDR(Start, Entry) (Start+2+12*(Entry))
{
unsigned char * DirEnd;
DirEnd = DIR_ENTRY_ADDR(DirStart, NumDirEntries);
if (DirEnd+4 > (OffsetBase+ExifLength)){
if (DirEnd+2 == OffsetBase+ExifLength || DirEnd == OffsetBase+ExifLength){
}else{
ErrNonfatal("Illegally sized Exif subdirectory (%d entries)",NumDirEntries,0);
return;
}
}
if (DumpExifMap){
printf("Map: %05u-%05u: Directory\n",(int)(DirStart-OffsetBase), (int)(DirEnd+4-OffsetBase));
}
}
if (ShowTags){
printf("(dir has %d entries)\n",NumDirEntries);
}
for (de=0;de<NumDirEntries;de++){
int Tag, Format, Components;
unsigned char * ValuePtr;
int ByteCount;
unsigned char * DirEntry;
DirEntry = DIR_ENTRY_ADDR(DirStart, de);
Tag = Get16u(DirEntry);
Format = Get16u(DirEntry+2);
Components = Get32u(DirEntry+4);
if (Components > 0x10000){
ErrNonfatal("Bad components count %x", Components,0);
continue;
}
if ((Format-1) >= NUM_FORMATS) {
ErrNonfatal("Illegal number format %d for tag %04x in Exif", Format, Tag);
continue;
}
if ((unsigned)Components > 0x10000){
ErrNonfatal("Too many components %d for tag %04x in Exif", Components, Tag);
continue;
}
ByteCount = Components * BytesPerFormat[Format];
if (ByteCount > 4){
OffsetVal = Get32u(DirEntry+8);
if (OffsetVal+ByteCount > ExifLength || OffsetVal < 0 || OffsetVal > 65536){
ErrNonfatal("Illegal value pointer for tag %04x in Exif", Tag,0);
continue;
}
ValuePtr = OffsetBase+OffsetVal;
if (OffsetVal > ImageInfo.LargestExifOffset){
ImageInfo.LargestExifOffset = OffsetVal;
}
if (DumpExifMap){
printf("Map: %05u-%05u: Data for tag %04x\n",OffsetVal, OffsetVal+ByteCount, Tag);
}
}else{
ValuePtr = DirEntry+8;
}
if (Tag == TAG_MAKER_NOTE){
if (ShowTags){
printf("%s Maker note: ",IndentString);
}
ProcessMakerNote(ValuePtr, ByteCount, OffsetBase, ExifLength);
continue;
}
if (ShowTags){
for (a=0;;a++){
if (a >= TAG_TABLE_SIZE){
printf("%s Unknown Tag %04x Value = ", IndentString, Tag);
break;
}
if (TagTable[a].Tag == Tag){
printf("%s %s = ",IndentString, TagTable[a].Desc);
break;
}
}
switch(Format){
case FMT_BYTE:
if(ByteCount>1){
for (a=0;a<ByteCount;a+=2){
int cv = *(char *)(ValuePtr+a)+(*(char *)(ValuePtr+a+1)<<8);
putchar(cv);
}
putchar('\n');
}else{
PrintFormatNumber(ValuePtr, Format, ByteCount);
printf("\n");
}
break;
case FMT_UNDEFINED:
case FMT_STRING:
{
int NoPrint = 0;
printf("\"");
for (a=0;a<ByteCount;a++){
if (ValuePtr[a] >= 32){
putchar(ValuePtr[a]);
NoPrint = 0;
}else{
if (!NoPrint && a != ByteCount-1){
putchar('?');
NoPrint = 1;
}
}
}
printf("\"\n");
}
break;
default:
PrintFormatNumber(ValuePtr, Format, ByteCount);
printf("\n");
}
}
switch(Tag){
case TAG_MAKE:
strncpy(ImageInfo.CameraMake, (char *)ValuePtr, ByteCount < 31 ? ByteCount : 31);
break;
case TAG_MODEL:
strncpy(ImageInfo.CameraModel, (char *)ValuePtr, ByteCount < 39 ? ByteCount : 39);
