globus_gsi_cred_handle_t x509_proxy_read( const char *proxy_file )
{
globus_gsi_cred_handle_t handle = NULL;
globus_gsi_cred_handle_attrs_t handle_attrs = NULL;
char *my_proxy_file = NULL;
bool error = false;
if ( activate_globus_gsi() != 0 ) {
return NULL;
}
if ((*globus_gsi_cred_handle_attrs_init_ptr)(&handle_attrs)) {
set_error_string( "problem during internal initialization1" );
error = true;
goto cleanup;
}
if ((*globus_gsi_cred_handle_init_ptr)(&handle, handle_attrs)) {
set_error_string( "problem during internal initialization2" );
error = true;
goto cleanup;
}
if (proxy_file == NULL) {
my_proxy_file = get_x509_proxy_filename();
if (my_proxy_file == NULL) {
goto cleanup;
}
proxy_file = my_proxy_file;
}
if ((*globus_gsi_cred_read_proxy_ptr)(handle, proxy_file)) {
set_error_string( "unable to read proxy file" );
error = true;
goto cleanup;
}
cleanup:
if (my_proxy_file) {
free(my_proxy_file);
}
if (handle_attrs) {
(*globus_gsi_cred_handle_attrs_destroy_ptr)(handle_attrs);
}
if (error && handle) {
(*globus_gsi_cred_handle_destroy_ptr)(handle);
handle = NULL;
}
return handle;
},0

mbfl_identify_encoding2(mbfl_string *string, const mbfl_encoding **elist, int elistsz, int strict)
{
int i, n, num, bad;
unsigned char *p;
mbfl_identify_filter *flist, *filter;
const mbfl_encoding *encoding;
flist = (mbfl_identify_filter *)mbfl_calloc(elistsz, sizeof(mbfl_identify_filter));
if (flist == NULL) {
return NULL;
}
num = 0;
if (elist != NULL) {
for (i = 0; i < elistsz; i++) {
if (!mbfl_identify_filter_init2(&flist[num], elist[i])) {
num++;
}
}
}
n = string->len;
p = string->val;
if (p != NULL) {
bad = 0;
while (n > 0) {
for (i = 0; i < num; i++) {
filter = &flist[i];
if (!filter->flag) {
(*filter->filter_function)(*p, filter);
if (filter->flag) {
bad++;
}
}
}
if ((num - 1) <= bad && !strict) {
break;
}
p++;
n--;
}
}
encoding = NULL;
for (i = 0; i < num; i++) {
filter = &flist[i];
if (!filter->flag) {
if (strict && filter->status) {
continue;
}
encoding = filter->encoding;
break;
}
}
if (!encoding) {
for (i = 0; i < num; i++) {
filter = &flist[i];
if (!filter->flag && (!strict || !filter->status)) {
encoding = filter->encoding;
break;
}
}
}
i = num; while (--i >= 0) {
mbfl_identify_filter_cleanup(&flist[i]);
}
mbfl_free((void *)flist);
return encoding;
},1

