static int nntp_mbox_open(struct Mailbox *m)
{
if (!m || !m->account)
return -1;
char buf[8192];
char server[1024];
char *group = NULL;
int rc;
void *hc = NULL;
anum_t first, last, count = 0;
struct Url *url = url_parse(mailbox_path(m));
if (!url || !url->host || !url->path ||
!((url->scheme == U_NNTP) || (url->scheme == U_NNTPS)))
{
url_free(&url);
mutt_error(_("%s is an invalid newsgroup specification"), mailbox_path(m));
return -1;
}
group = url->path;
if (group[0] == '/')
group++;
url->path = strchr(url->path, '\0');
url_tostring(url, server, sizeof(server), 0);
mutt_account_hook(m->realpath);
struct NntpAccountData *adata = m->account->adata;
if (!adata)
{
adata = nntp_select_server(m, server, true);
m->account->adata = adata;
m->account->adata_free = nntp_adata_free;
}
if (!adata)
{
url_free(&url);
return -1;
}
CurrentNewsSrv = adata;
m->msg_count = 0;
m->msg_unread = 0;
m->vcount = 0;
if (group[0] == '/')
group++;
struct NntpMboxData *mdata = mutt_hash_find(adata->groups_hash, group);
if (!mdata)
{
nntp_newsrc_close(adata);
mutt_error(_("Newsgroup %s not found on the server"), group);
url_free(&url);
return -1;
}
m->rights &= ~MUTT_ACL_INSERT;
if (!mdata->newsrc_ent && !mdata->subscribed && !C_SaveUnsubscribed)
m->readonly = true;
mutt_message(_("Selecting %s..."), group);
url_free(&url);
buf[0] = '\0';
if (nntp_query(mdata, buf, sizeof(buf)) < 0)
{
nntp_newsrc_close(adata);
return -1;
}
if (mutt_str_startswith(buf, "411", CASE_MATCH))
{
mutt_error(_("Newsgroup %s has been removed from the server"), mdata->group);
if (!mdata->deleted)
{
mdata->deleted = true;
nntp_active_save_cache(adata);
}
if (mdata->newsrc_ent && !mdata->subscribed && !C_SaveUnsubscribed)
{
FREE(&mdata->newsrc_ent);
mdata->newsrc_len = 0;
nntp_delete_group_cache(mdata);
nntp_newsrc_update(adata);
}
}
else
{
if (sscanf(buf, "211 " ANUM " " ANUM " " ANUM, &count, &first, &last) != 3)
{
nntp_newsrc_close(adata);
mutt_error("GROUP: %s", buf);
return -1;
}
mdata->first_message = first;
mdata->last_message = last;
mdata->deleted = false;
if (C_NntpLoadDescription && !mdata->desc)
{
if (get_description(mdata, NULL, NULL) < 0)
{
nntp_newsrc_close(adata);
return -1;
}
if (mdata->desc)
nntp_active_save_cache(adata);
}
}
adata->check_time = mutt_date_epoch();
m->mdata = mdata;
if (!mdata->bcache && (mdata->newsrc_ent || mdata->subscribed || C_SaveUnsubscribed))
mdata->bcache = mutt_bcache_open(&adata->conn->account, mdata->group);
first = mdata->first_message;
if (C_NntpContext && (mdata->last_message - first + 1 > C_NntpContext))
first = mdata->last_message - C_NntpContext + 1;
mdata->last_loaded = first ? first - 1 : 0;
count = mdata->first_message;
mdata->first_message = first;
nntp_bcache_update(mdata);
mdata->first_message = count;
#ifdef USE_HCACHE
hc = nntp_hcache_open(mdata);
nntp_hcache_update(mdata, hc);
#endif
if (!hc)
m->rights &= ~(MUTT_ACL_WRITE | MUTT_ACL_DELETE);
nntp_newsrc_close(adata);
rc = nntp_fetch_headers(m, hc, first, mdata->last_message, false);
#ifdef USE_HCACHE
mutt_hcache_close(hc);
#endif
if (rc < 0)
return -1;
mdata->last_loaded = mdata->last_message;
adata->newsrc_modified = false;
return 0;
},0

int crxParamInit(CrxBandParam **param, uint64_t subbandMdatOffset,
uint64_t subbandDataSize, uint32_t subbandWidth,
uint32_t subbandHeight, int32_t supportsPartial,
uint32_t roundedBitsMask, LibRaw_abstract_datastream *input)
{
int32_t progrDataSize = supportsPartial ? 0 : sizeof(int32_t) * subbandWidth;
int32_t paramLength = 2 * subbandWidth + 4;
uint8_t *paramBuf = (uint8_t *)calloc(
1, sizeof(CrxBandParam) + sizeof(int32_t) * paramLength + progrDataSize);
if (!paramBuf)
return -1;
*param = (CrxBandParam *)paramBuf;
paramBuf += sizeof(CrxBandParam);
(*param)->paramData = (int32_t *)paramBuf;
(*param)->nonProgrData =
progrDataSize ? (*param)->paramData + paramLength : 0;
(*param)->subbandWidth = subbandWidth;
(*param)->subbandHeight = subbandHeight;
(*param)->roundedBits = 0;
(*param)->curLine = 0;
(*param)->roundedBitsMask = roundedBitsMask;
(*param)->supportsPartial = supportsPartial;
(*param)->bitStream.bitData = 0;
(*param)->bitStream.bitsLeft = 0;
(*param)->bitStream.mdatSize = subbandDataSize;
(*param)->bitStream.curPos = 0;
(*param)->bitStream.curBufSize = 0;
(*param)->bitStream.curBufOffset = subbandMdatOffset;
(*param)->bitStream.input = input;
crxFillBuffer(&(*param)->bitStream);
return 0;
},1

ldp_pdu_print(netdissect_options *ndo,
register const u_char *pptr)
{
const struct ldp_common_header *ldp_com_header;
const struct ldp_msg_header *ldp_msg_header;
const u_char *tptr,*msg_tptr;
u_short tlen;
u_short pdu_len,msg_len,msg_type,msg_tlen;
int hexdump,processed;
ldp_com_header = (const struct ldp_common_header *)pptr;
ND_TCHECK(*ldp_com_header);
if (EXTRACT_16BITS(&ldp_com_header->version) != LDP_VERSION) {
ND_PRINT((ndo, "%sLDP version %u packet not supported",
(ndo->ndo_vflag < 1) ? "" : "\n\t",
EXTRACT_16BITS(&ldp_com_header->version)));
return 0;
}
pdu_len = EXTRACT_16BITS(&ldp_com_header->pdu_length);
if (pdu_len < sizeof(const struct ldp_common_header)-4) {
ND_PRINT((ndo, "%sLDP, pdu-length: %u (too short, < %u)",
(ndo->ndo_vflag < 1) ? "" : "\n\t",
pdu_len,
(u_int)(sizeof(const struct ldp_common_header)-4)));
return 0;
}
ND_PRINT((ndo, "%sLDP, Label-Space-ID: %s:%u, pdu-length: %u",
(ndo->ndo_vflag < 1) ? "" : "\n\t",
ipaddr_string(ndo, &ldp_com_header->lsr_id),
EXTRACT_16BITS(&ldp_com_header->label_space),
pdu_len));
if (ndo->ndo_vflag < 1)
return 0;
tptr = pptr + sizeof(const struct ldp_common_header);
tlen = pdu_len - (sizeof(const struct ldp_common_header)-4);
while(tlen>0) {
ND_TCHECK2(*tptr, sizeof(struct ldp_msg_header));
ldp_msg_header = (const struct ldp_msg_header *)tptr;
msg_len=EXTRACT_16BITS(ldp_msg_header->length);
msg_type=LDP_MASK_MSG_TYPE(EXTRACT_16BITS(ldp_msg_header->type));
if (msg_len < sizeof(struct ldp_msg_header)-4) {
ND_PRINT((ndo, "\n\t %s Message (0x%04x), length: %u (too short, < %u)",
tok2str(ldp_msg_values,
"Unknown",
msg_type),
msg_type,
msg_len,
(u_int)(sizeof(struct ldp_msg_header)-4)));
return 0;
}
ND_PRINT((ndo, "\n\t %s Message (0x%04x), length: %u, Message ID: 0x%08x, Flags: [%s if unknown]",
tok2str(ldp_msg_values,
"Unknown",
msg_type),
msg_type,
msg_len,
EXTRACT_32BITS(&ldp_msg_header->id),
LDP_MASK_U_BIT(EXTRACT_16BITS(&ldp_msg_header->type)) ? "continue processing" : "ignore"));
msg_tptr=tptr+sizeof(struct ldp_msg_header);
msg_tlen=msg_len-(sizeof(struct ldp_msg_header)-4);
ND_TCHECK2(*tptr, msg_len);
hexdump=FALSE;
switch(msg_type) {
case LDP_MSG_NOTIF:
case LDP_MSG_HELLO:
case LDP_MSG_INIT:
case LDP_MSG_KEEPALIVE:
case LDP_MSG_ADDRESS:
case LDP_MSG_LABEL_MAPPING:
case LDP_MSG_ADDRESS_WITHDRAW:
case LDP_MSG_LABEL_WITHDRAW:
while(msg_tlen >= 4) {
processed = ldp_tlv_print(ndo, msg_tptr, msg_tlen);
if (processed == 0)
break;
msg_tlen-=processed;
msg_tptr+=processed;
}
break;
case LDP_MSG_LABEL_REQUEST:
case LDP_MSG_LABEL_RELEASE:
case LDP_MSG_LABEL_ABORT_REQUEST:
default:
if (ndo->ndo_vflag <= 1)
print_unknown_data(ndo, msg_tptr, "\n\t ", msg_tlen);
break;
}
if (ndo->ndo_vflag > 1 || hexdump==TRUE)
print_unknown_data(ndo, tptr+sizeof(struct ldp_msg_header), "\n\t ",
msg_len);
tptr += msg_len+4;
tlen -= msg_len+4;
}
return pdu_len+4;
trunc:
ND_PRINT((ndo, "\n\t\t packet exceeded snapshot"));
return 0;
},1

