{
switch (reg_index) {
case 0x00:
return s->cirrus_shadow_gr0;
case 0x01:
return s->cirrus_shadow_gr1;
case 0x02:
case 0x03:
case 0x04:
case 0x06:
case 0x07:
case 0x08:
return s->vga.gr[s->vga.gr_index];
case 0x05:
default:
break;
}
if (reg_index < 0x3a) {
return s->vga.gr[reg_index];
} else {
#ifdef DEBUG_CIRRUS
printf("cirrus: inport gr_index %02x\n", reg_index);
#endif
return 0xff;
}
