fclose (fd);
} else {
eprintf ("cannot open file '%s' to read offsets\n", each + 1);
}
}
break;
default:
core->rcmd->macro.counter = 0;
for (; *each == ' '; each++) {
;
}
i = 0;
while (str[i]) {
j = i;
for (; str[j] && str[j] == ' '; j++) {
;
}
for (i = j; str[i] && str[i] != ' '; i++) {
;
}
ch = str[i];
str[i] = '\0';
word = strdup (str + j);
if (!word) {
break;
}
str[i] = ch;
{
const RSpace *flagspace = r_flag_space_cur (core->flags);
RList *match_flag_items = r_list_newf ((RListFree)r_flag_item_free);
if (!match_flag_items) {
break;
}
struct duplicate_flag_t u = {
.ret = match_flag_items,
.word = word,
};
r_flag_foreach_space (core->flags, flagspace, duplicate_flag, &u);
r_list_foreach (match_flag_items, iter, flag) {
if (r_cons_is_breaked ()) {
break;
}
char *buf = NULL;
const char *tmp = NULL;
r_core_seek (core, flag->offset, 1);
r_cons_push ();
r_core_cmd (core, cmd, 0);
tmp = r_cons_get_buffer ();
buf = tmp? strdup (tmp): NULL;
r_cons_pop ();
r_cons_strcat (buf);
free (buf);
}
r_list_free (match_flag_items);
core->rcmd->macro.counter++ ;
R_FREE (word);
}
}
}
r_cons_break_pop ();
core->offset = oseek;
free (word);
free (ostr);
return true;
out_finish:
free (ostr);
r_cons_break_pop ();
return false;
