bool input_match_device_id(const struct input_dev *dev,
const struct input_device_id *id)
{
if (id->flags & INPUT_DEVICE_ID_MATCH_BUS)
if (id->bustype != dev->id.bustype)
return false;
if (id->flags & INPUT_DEVICE_ID_MATCH_VENDOR)
if (id->vendor != dev->id.vendor)
return false;
if (id->flags & INPUT_DEVICE_ID_MATCH_PRODUCT)
if (id->product != dev->id.product)
return false;
if (id->flags & INPUT_DEVICE_ID_MATCH_VERSION)
if (id->version != dev->id.version)
return false;
if (!bitmap_subset(id->evbit, dev->evbit, EV_MAX) ||
!bitmap_subset(id->keybit, dev->keybit, KEY_MAX) ||
!bitmap_subset(id->relbit, dev->relbit, REL_MAX) ||
!bitmap_subset(id->absbit, dev->absbit, ABS_MAX) ||
!bitmap_subset(id->mscbit, dev->mscbit, MSC_MAX) ||
!bitmap_subset(id->ledbit, dev->ledbit, LED_MAX) ||
!bitmap_subset(id->sndbit, dev->sndbit, SND_MAX) ||
!bitmap_subset(id->ffbit, dev->ffbit, FF_MAX) ||
!bitmap_subset(id->swbit, dev->swbit, SW_MAX) ||
!bitmap_subset(id->propbit, dev->propbit, INPUT_PROP_MAX)) {
return false;
}
return true;
},0

adv_error adv_png_read_ihdr(
unsigned* pix_width, unsigned* pix_height, unsigned* pix_pixel,
unsigned char** dat_ptr, unsigned* dat_size,
unsigned char** pix_ptr, unsigned* pix_scanline,
unsigned char** pal_ptr, unsigned* pal_size,
unsigned char** rns_ptr, unsigned* rns_size,
adv_fz* f, const unsigned char* data, unsigned data_size)
{
unsigned char* ptr;
unsigned ptr_size;
unsigned type;
unsigned long res_size;
unsigned pixel;
unsigned width;
unsigned width_align;
unsigned height;
unsigned depth;
int r;
z_stream z;
adv_bool has_palette;
*dat_ptr = 0;
*pix_ptr = 0;
*pal_ptr = 0;
*pal_size = 0;
*rns_ptr = 0;
*rns_size = 0;
if (data_size != 13) {
error_set("Invalid IHDR size %d instead of 13", data_size);
goto err;
}
*pix_width = width = be_uint32_read(data + 0);
*pix_height = height = be_uint32_read(data + 4);
depth = data[8];
if (data[9] == 3 && depth == 8) {
pixel = 1;
width_align = width;
has_palette = 1;
} else if (data[9] == 3 && depth == 4) {
pixel = 1;
width_align = (width + 1) & ~1;
has_palette = 1;
} else if (data[9] == 3 && depth == 2) {
pixel = 1;
width_align = (width + 3) & ~3;
has_palette = 1;
} else if (data[9] == 3 && depth == 1) {
pixel = 1;
width_align = (width + 7) & ~7;
has_palette = 1;
} else if (data[9] == 2 && depth == 8) {
pixel = 3;
width_align = width;
has_palette = 0;
} else if (data[9] == 6 && depth == 8) {
pixel = 4;
width_align = width;
has_palette = 0;
} else {
error_unsupported_set("Unsupported bit depth/color type, %d/%d", (unsigned)data[8], (unsigned)data[9]);
goto err;
}
*pix_pixel = pixel;
if (data[10] != 0) {
error_unsupported_set("Unsupported compression, %d instead of 0", (unsigned)data[10]);
goto err;
}
if (data[11] != 0) {
error_unsupported_set("Unsupported filter, %d instead of 0", (unsigned)data[11]);
goto err;
}
if (data[12] != 0) {
error_unsupported_set("Unsupported interlace %d", (unsigned)data[12]);
goto err;
}
if (adv_png_read_chunk(f, &ptr, &ptr_size, &type) != 0)
goto err;
while (type != ADV_PNG_CN_IDAT) {
if (type == ADV_PNG_CN_PLTE) {
if (ptr_size > 256*3) {
error_set("Invalid palette size in PLTE chunk");
goto err_ptr;
}
if (*pal_ptr) {
error_set("Double palette specification");
goto err_ptr;
}
*pal_ptr = ptr;
*pal_size = ptr_size;
} else if (type == ADV_PNG_CN_tRNS) {
if (*rns_ptr) {
error_set("Double rns specification");
goto err_ptr;
}
*rns_ptr = ptr;
*rns_size = ptr_size;
} else {
if ((type & 0x20000000) == 0) {
char buf[4];
be_uint32_write(buf, type);
error_unsupported_set("Unsupported critical chunk '%c%c%c%c'", buf[0], buf[1], buf[2], buf[3]);
goto err_ptr;
}
free(ptr);
}
if (adv_png_read_chunk(f, &ptr, &ptr_size, &type) != 0)
goto err;
}
if (has_palette && !*pal_ptr) {
error_set("Missing PLTE chunk");
goto err_ptr;
}
if (!has_palette && *pal_ptr) {
error_set("Unexpected PLTE chunk");
goto err_ptr;
}
*dat_size = height * (width_align * pixel + 1);
*dat_ptr = malloc(*dat_size);
*pix_scanline = width_align * pixel + 1;
*pix_ptr = *dat_ptr + 1;
z.zalloc = 0;
z.zfree = 0;
z.next_out = *dat_ptr;
z.avail_out = *dat_size;
z.next_in = 0;
z.avail_in = 0;
r = inflateInit(&z);
while (r == Z_OK && type == ADV_PNG_CN_IDAT) {
z.next_in = ptr;
z.avail_in = ptr_size;
r = inflate(&z, Z_NO_FLUSH);
free(ptr);
if (adv_png_read_chunk(f, &ptr, &ptr_size, &type) != 0) {
inflateEnd(&z);
goto err;
}
}
res_size = z.total_out;
inflateEnd(&z);
if (r != Z_STREAM_END) {
error_set("Invalid compressed data");
goto err_ptr;
}
if (depth == 8) {
if (res_size != *dat_size) {
error_set("Invalid decompressed size");
goto err_ptr;
}
if (pixel == 1)
adv_png_unfilter_8(width * pixel, height, *dat_ptr, width_align * pixel + 1);
else if (pixel == 3)
adv_png_unfilter_24(width * pixel, height, *dat_ptr, width_align * pixel + 1);
else if (pixel == 4)
adv_png_unfilter_32(width * pixel, height, *dat_ptr, width_align * pixel + 1);
else {
error_set("Unsupported format");
goto err_ptr;
}
} else if (depth == 4) {
if (res_size != height * (width_align / 2 + 1)) {
error_set("Invalid decompressed size");
goto err_ptr;
}
adv_png_unfilter_8(width_align / 2, height, *dat_ptr, width_align / 2 + 1);
adv_png_expand_4(width_align, height, *dat_ptr);
} else if (depth == 2) {
if (res_size != height * (width_align / 4 + 1)) {
error_set("Invalid decompressed size");
goto err_ptr;
}
adv_png_unfilter_8(width_align / 4, height, *dat_ptr, width_align / 4 + 1);
adv_png_expand_2(width_align, height, *dat_ptr);
} else if (depth == 1) {
if (res_size != height * (width_align / 8 + 1)) {
error_set("Invalid decompressed size");
goto err_ptr;
}
adv_png_unfilter_8(width_align / 8, height, *dat_ptr, width_align / 8 + 1);
adv_png_expand_1(width_align, height, *dat_ptr);
}
if (adv_png_read_iend(f, ptr, ptr_size, type)!=0) {
goto err_ptr;
}
free(ptr);
return 0;
err_ptr:
free(ptr);
err:
free(*dat_ptr);
free(*pal_ptr);
free(*rns_ptr);
return -1;
},1

QPDFObjectHandle::parseInternal(PointerHolder<InputSource> input,
std::string const& object_description,
QPDFTokenizer& tokenizer, bool& empty,
StringDecrypter* decrypter, QPDF* context,
bool content_stream)
{
empty = false;
QPDFObjectHandle object;
std::vector<std::vector<QPDFObjectHandle> > olist_stack;
olist_stack.push_back(std::vector<QPDFObjectHandle>());
enum state_e { st_top, st_start, st_stop, st_eof, st_dictionary, st_array };
std::vector<state_e> state_stack;
state_stack.push_back(st_top);
std::vector<qpdf_offset_t> offset_stack;
offset_stack.push_back(input->tell());
bool done = false;
while (! done)
{
std::vector<QPDFObjectHandle>& olist = olist_stack.back();
state_e state = state_stack.back();
qpdf_offset_t offset = offset_stack.back();
object = QPDFObjectHandle();
QPDFTokenizer::Token token =
tokenizer.readToken(input, object_description);
switch (token.getType())
{
case QPDFTokenizer::tt_eof:
if (content_stream)
{
state = st_eof;
}
else
{
throw std::logic_error(
"EOF received while not in content stream mode");
}
break;
case QPDFTokenizer::tt_brace_open:
case QPDFTokenizer::tt_brace_close:
QTC::TC("qpdf", "QPDFObjectHandle bad brace");
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"treating unexpected brace token as null"));
object = newNull();
break;
case QPDFTokenizer::tt_array_close:
if (state == st_array)
{
state = st_stop;
}
else
{
QTC::TC("qpdf", "QPDFObjectHandle bad array close");
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"treating unexpected array close token as null"));
object = newNull();
}
break;
case QPDFTokenizer::tt_dict_close:
if (state == st_dictionary)
{
state = st_stop;
}
else
{
QTC::TC("qpdf", "QPDFObjectHandle bad dictionary close");
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"unexpected dictionary close token"));
object = newNull();
}
break;
case QPDFTokenizer::tt_array_open:
case QPDFTokenizer::tt_dict_open:
olist_stack.push_back(std::vector<QPDFObjectHandle>());
state = st_start;
offset_stack.push_back(input->tell());
state_stack.push_back(
(token.getType() == QPDFTokenizer::tt_array_open) ?
st_array : st_dictionary);
break;
case QPDFTokenizer::tt_bool:
object = newBool((token.getValue() == "true"));
break;
case QPDFTokenizer::tt_null:
object = newNull();
break;
case QPDFTokenizer::tt_integer:
object = newInteger(QUtil::string_to_ll(token.getValue().c_str()));
break;
case QPDFTokenizer::tt_real:
object = newReal(token.getValue());
break;
case QPDFTokenizer::tt_name:
object = newName(token.getValue());
break;
case QPDFTokenizer::tt_word:
{
std::string const& value = token.getValue();
if (content_stream)
{
object = QPDFObjectHandle::newOperator(value);
}
else if ((value == "R") && (state != st_top) &&
(olist.size() >= 2) &&
(! olist.at(olist.size() - 1).isIndirect()) &&
(olist.at(olist.size() - 1).isInteger()) &&
(! olist.at(olist.size() - 2).isIndirect()) &&
(olist.at(olist.size() - 2).isInteger()))
{
if (context == 0)
{
QTC::TC("qpdf", "QPDFObjectHandle indirect without context");
throw std::logic_error(
"QPDFObjectHandle::parse called without context"
" on an object with indirect references");
}
object = newIndirect(
context,
olist.at(olist.size() - 2).getIntValue(),
olist.at(olist.size() - 1).getIntValue());
olist.pop_back();
olist.pop_back();
}
else if ((value == "endobj") && (state == st_top))
{
object = newNull();
input->seek(input->getLastOffset(), SEEK_SET);
empty = true;
}
else
{
QTC::TC("qpdf", "QPDFObjectHandle treat word as string");
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"unknown token while reading object;"
" treating as string"));
object = newString(value);
}
}
break;
case QPDFTokenizer::tt_string:
{
std::string val = token.getValue();
if (decrypter)
{
decrypter->decryptString(val);
}
object = QPDFObjectHandle::newString(val);
}
break;
default:
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"treating unknown token type as null while "
"reading object"));
object = newNull();
break;
}
if ((! object.isInitialized()) &&
(! ((state == st_start) ||
(state == st_stop) ||
(state == st_eof))))
{
throw std::logic_error(
"QPDFObjectHandle::parseInternal: "
"unexpected uninitialized object");
object = newNull();
}
switch (state)
{
case st_eof:
if (state_stack.size() > 1)
{
warn(context,
QPDFExc(qpdf_e_damaged_pdf, input->getName(),
object_description,
input->getLastOffset(),
"parse error while reading object"));
}
done = true;
break;
case st_dictionary:
case st_array:
olist.push_back(object);
break;
case st_top:
done = true;
break;
case st_start:
break;
case st_stop:
if ((state_stack.size() < 2) || (olist_stack.size() < 2))
{
throw std::logic_error(
"QPDFObjectHandle::parseInternal: st_stop encountered"
" with insufficient elements in stack");
}
state_e old_state = state_stack.back();
state_stack.pop_back();
if (old_state == st_array)
{
object = newArray(olist);
}
else if (old_state == st_dictionary)
{
std::set<std::string> names;
for (std::vector<QPDFObjectHandle>::iterator iter =
olist.begin();
iter != olist.end(); ++iter)
{
if ((! (*iter).isIndirect()) && (*iter).isName())
{
names.insert((*iter).getName());
}
}
std::map<std::string, QPDFObjectHandle> dict;
int next_fake_key = 1;
for (unsigned int i = 0; i < olist.size(); ++i)
{
QPDFObjectHandle key_obj = olist.at(i);
QPDFObjectHandle val;
if (key_obj.isIndirect() || (! key_obj.isName()))
{
bool found_fake = false;
std::string candidate;
while (! found_fake)
{
candidate =
"/QPDFFake" +
QUtil::int_to_string(next_fake_key++);
found_fake = (names.count(candidate) == 0);
QTC::TC("qpdf", "QPDFObjectHandle found fake",
(found_fake ? 0 : 1));
}
warn(context,
QPDFExc(
qpdf_e_damaged_pdf,
input->getName(), object_description, offset,
"expected dictionary key but found"
" non-name object; inserting key " +
candidate));
val = key_obj;
key_obj = newName(candidate);
}
else if (i + 1 >= olist.size())
{
QTC::TC("qpdf", "QPDFObjectHandle no val for last key");
warn(context,
QPDFExc(
qpdf_e_damaged_pdf,
input->getName(), object_description, offset,
"dictionary ended prematurely; "
"using null as value for last key"));
val = newNull();
}
else
{
val = olist.at(++i);
}
dict[key_obj.getName()] = val;
}
object = newDictionary(dict);
}
olist_stack.pop_back();
offset_stack.pop_back();
if (state_stack.back() == st_top)
{
done = true;
}
else
{
olist_stack.back().push_back(object);
}
}
}
return object;
},0

static void xml_parser_dtor(zend_rsrc_list_entry *rsrc TSRMLS_DC)
{
xml_parser *parser = (xml_parser *)rsrc->ptr;
if (parser->parser) {
XML_ParserFree(parser->parser);
}
if (parser->ltags) {
int inx;
for (inx = 0; ((inx < parser->level) && (inx < XML_MAXLEVEL)); inx++)
efree(parser->ltags[ inx ]);
efree(parser->ltags);
}
if (parser->startElementHandler) {
zval_ptr_dtor(&parser->startElementHandler);
}
if (parser->endElementHandler) {
zval_ptr_dtor(&parser->endElementHandler);
}
if (parser->characterDataHandler) {
zval_ptr_dtor(&parser->characterDataHandler);
}
if (parser->processingInstructionHandler) {
zval_ptr_dtor(&parser->processingInstructionHandler);
}
if (parser->defaultHandler) {
zval_ptr_dtor(&parser->defaultHandler);
}
if (parser->unparsedEntityDeclHandler) {
zval_ptr_dtor(&parser->unparsedEntityDeclHandler);
}
if (parser->notationDeclHandler) {
zval_ptr_dtor(&parser->notationDeclHandler);
}
if (parser->externalEntityRefHandler) {
zval_ptr_dtor(&parser->externalEntityRefHandler);
}
if (parser->unknownEncodingHandler) {
zval_ptr_dtor(&parser->unknownEncodingHandler);
}
if (parser->startNamespaceDeclHandler) {
zval_ptr_dtor(&parser->startNamespaceDeclHandler);
}
if (parser->endNamespaceDeclHandler) {
zval_ptr_dtor(&parser->endNamespaceDeclHandler);
}
if (parser->baseURI) {
efree(parser->baseURI);
}
if (parser->object) {
zval_ptr_dtor(&parser->object);
}
efree(parser);
},1

static struct property *dlpar_parse_cc_property(struct cc_workarea *ccwa)
{
struct property *prop;
char *name;
char *value;
prop = kzalloc(sizeof(*prop), GFP_KERNEL);
if (!prop)
return NULL;
name = (char *)ccwa + be32_to_cpu(ccwa->name_offset);
prop->name = kstrdup(name, GFP_KERNEL);
prop->length = be32_to_cpu(ccwa->prop_length);
value = (char *)ccwa + be32_to_cpu(ccwa->prop_offset);
prop->value = kmemdup(value, prop->length, GFP_KERNEL);
if (!prop->value) {
dlpar_free_cc_property(prop);
return NULL;
}
return prop;
},1

