reg = opa;
break;
case DW_CFA_restore:
reg = opa;
break;
case DW_CFA_set_loc:
if ((size_t) (block_end - start) < encoded_ptr_size)
start = block_end;
else
start += encoded_ptr_size;
break;
case DW_CFA_advance_loc1:
if ((size_t) (block_end - start) < 1)
start = block_end;
else
start += 1;
