void CLASS kodak_radc_load_raw()
{
#ifdef LIBRAW_LIBRARY_BUILD
if(width>768 || raw_width>768 || height > 512 || raw_height>512 )
throw LIBRAW_EXCEPTION_IO_CORRUPT;
