static bool validate_oplock_types(struct share_mode_lock *lck)
{
struct share_mode_data *d = lck->data;
bool batch = false;
bool ex_or_batch = false;
bool level2 = false;
bool no_oplock = false;
uint32_t num_non_stat_opens = 0;
uint32_t i;
for (i=0; i<d->num_share_modes; i++) {
struct share_mode_entry *e = &d->share_modes[i];
if (!is_valid_share_mode_entry(e)) {
continue;
}
if (e->op_mid == 0) {
continue;
}
if (e->op_type == NO_OPLOCK && is_stat_open(e->access_mask)) {
continue;
}
num_non_stat_opens += 1;
if (BATCH_OPLOCK_TYPE(e->op_type)) {
if (share_mode_stale_pid(d, i)) {
DEBUG(10, ("Found stale batch oplock\n"));
continue;
}
if (ex_or_batch || batch || level2 || no_oplock) {
DEBUG(0, ("Bad batch oplock entry %u.",
(unsigned)i));
return false;
}
batch = true;
}
if (EXCLUSIVE_OPLOCK_TYPE(e->op_type)) {
if (share_mode_stale_pid(d, i)) {
DEBUG(10, ("Found stale duplicate oplock\n"));
continue;
}
if (ex_or_batch || level2 || no_oplock) {
DEBUG(0, ("Bad exclusive or batch oplock "
"entry %u.", (unsigned)i));
return false;
}
ex_or_batch = true;
}
if (LEVEL_II_OPLOCK_TYPE(e->op_type)) {
if (batch || ex_or_batch) {
if (share_mode_stale_pid(d, i)) {
DEBUG(10, ("Found stale LevelII "
"oplock\n"));
continue;
}
DEBUG(0, ("Bad levelII oplock entry %u.",
(unsigned)i));
return false;
}
level2 = true;
}
if (e->op_type == NO_OPLOCK) {
if (batch || ex_or_batch) {
if (share_mode_stale_pid(d, i)) {
DEBUG(10, ("Found stale NO_OPLOCK "
"entry\n"));
continue;
}
DEBUG(0, ("Bad no oplock entry %u.",
(unsigned)i));
return false;
}
no_oplock = true;
}
}
remove_stale_share_mode_entries(d);
if ((batch || ex_or_batch) && (num_non_stat_opens != 1)) {
DEBUG(1, ("got batch (%d) or ex (%d) non-exclusively (%d)\n",
(int)batch, (int)ex_or_batch,
(int)d->num_share_modes));
return false;
}
return true;
},0

make_text_segment(Node** node, ScanEnv* env)
{
int r;
int i;
Node* x;
Node* ns[2];
ns[1] = NULL_NODE;
r = ONIGERR_MEMORY;
ns[0] = onig_node_new_anchor(ANCR_NO_TEXT_SEGMENT_BOUNDARY, FALSE);
if (IS_NULL(ns[0])) goto err;
r = node_new_true_anychar(&ns[1], env);
if (r != 0) goto err1;
x = make_list(2, ns);
if (IS_NULL(x)) goto err;
ns[0] = x;
ns[1] = NULL_NODE;
x = node_new_quantifier(0, INFINITE_REPEAT, TRUE);
if (IS_NULL(x)) goto err;
NODE_BODY(x) = ns[0];
ns[0] = NULL_NODE;
ns[1] = x;
r = node_new_true_anychar(&ns[0], env);
if (r != 0) goto err1;
x = make_list(2, ns);
if (IS_NULL(x)) goto err;
ns[0] = x;
ns[1] = NULL_NODE;
x = node_new_bag(BAG_STOP_BACKTRACK);
if (IS_NULL(x)) goto err;
NODE_BODY(x) = ns[0];
*node = x;
return ONIG_NORMAL;
err:
r = ONIGERR_MEMORY;
err1:
for (i = 0; i < 2; i++) onig_node_free(ns[i]);
return r;
},0

bool WebSocketProtocol<isServer>::handleFragment(char *data, size_t length, unsigned int remainingBytes, int opCode, bool fin, void *user) {
uS::Socket s((uv_poll_t *) user);
typename WebSocket<isServer>::Data *webSocketData = (typename WebSocket<isServer>::Data *) s.getSocketData();
if (opCode < 3) {
if (!remainingBytes && fin && !webSocketData->fragmentBuffer.length()) {
if (webSocketData->compressionStatus == WebSocket<isServer>::Data::CompressionStatus::COMPRESSED_FRAME) {
webSocketData->compressionStatus = WebSocket<isServer>::Data::CompressionStatus::ENABLED;
Hub *hub = ((Group<isServer> *) s.getSocketData()->nodeData)->hub;
data = hub->inflate(data, length);
}
if (opCode == 1 && !isValidUtf8((unsigned char *) data, length)) {
forceClose(user);
return true;
}
((Group<isServer> *) s.getSocketData()->nodeData)->messageHandler(WebSocket<isServer>(s), data, length, (OpCode) opCode);
if (s.isClosed() || s.isShuttingDown()) {
return true;
}
} else {
webSocketData->fragmentBuffer.append(data, length);
if (!remainingBytes && fin) {
length = webSocketData->fragmentBuffer.length();
if (webSocketData->compressionStatus == WebSocket<isServer>::Data::CompressionStatus::COMPRESSED_FRAME) {
webSocketData->compressionStatus = WebSocket<isServer>::Data::CompressionStatus::ENABLED;
Hub *hub = ((Group<isServer> *) s.getSocketData()->nodeData)->hub;
webSocketData->fragmentBuffer.append("....");
data = hub->inflate((char *) webSocketData->fragmentBuffer.data(), length);
} else {
data = (char *) webSocketData->fragmentBuffer.data();
}
if (opCode == 1 && !isValidUtf8((unsigned char *) data, length)) {
forceClose(user);
return true;
}
((Group<isServer> *) s.getSocketData()->nodeData)->messageHandler(WebSocket<isServer>(s), data, length, (OpCode) opCode);
if (s.isClosed() || s.isShuttingDown()) {
return true;
}
webSocketData->fragmentBuffer.clear();
}
}
} else {
webSocketData->controlBuffer.append(data, length);
if (!remainingBytes && fin) {
if (opCode == CLOSE) {
CloseFrame closeFrame = parseClosePayload((char *) webSocketData->controlBuffer.data(), webSocketData->controlBuffer.length());
WebSocket<isServer>(s).close(closeFrame.code, closeFrame.message, closeFrame.length);
return true;
} else {
if (opCode == PING) {
WebSocket<isServer>(s).send(webSocketData->controlBuffer.data(), webSocketData->controlBuffer.length(), (OpCode) OpCode::PONG);
((Group<isServer> *) s.getSocketData()->nodeData)->pingHandler(WebSocket<isServer>(s), (char *) webSocketData->controlBuffer.data(), webSocketData->controlBuffer.length());
if (s.isClosed() || s.isShuttingDown()) {
return true;
}
} else if (opCode == PONG) {
((Group<isServer> *) s.getSocketData()->nodeData)->pongHandler(WebSocket<isServer>(s), (char *) webSocketData->controlBuffer.data(), webSocketData->controlBuffer.length());
if (s.isClosed() || s.isShuttingDown()) {
return true;
}
}
}
webSocketData->controlBuffer.clear();
}
}
return false;
},1

