static void lru_maintainer_crawler_check(struct crawler_expired_data *cdata) {
int i;
static rel_time_t next_crawls[MAX_NUMBER_OF_SLAB_CLASSES];
static rel_time_t next_crawl_wait[MAX_NUMBER_OF_SLAB_CLASSES];
uint8_t todo[MAX_NUMBER_OF_SLAB_CLASSES];
memset(todo, 0, sizeof(uint8_t) * MAX_NUMBER_OF_SLAB_CLASSES);
bool do_run = false;
if (!cdata->crawl_complete) {
return;
}
for (i = POWER_SMALLEST; i < MAX_NUMBER_OF_SLAB_CLASSES; i++) {
crawlerstats_t *s = &cdata->crawlerstats[i];
if (s->run_complete) {
pthread_mutex_lock(&cdata->lock);
int x;
uint64_t possible_reclaims = s->seen - s->noexp;
uint64_t available_reclaims = 0;
uint64_t low_watermark = (s->seen / 100) + 1;
rel_time_t since_run = current_time - s->end_time;
if (settings.verbose > 1)
fprintf(stderr, "maint crawler[%d]: low_watermark: %llu, possible_reclaims: %llu, since_run: %u\n",
i, (unsigned long long)low_watermark, (unsigned long long)possible_reclaims,
(unsigned int)since_run);
for (x = 0; x < 60; x++) {
available_reclaims += s->histo[x];
if (available_reclaims > low_watermark) {
if (next_crawl_wait[i] < (x * 60)) {
next_crawl_wait[i] += 60;
} else if (next_crawl_wait[i] >= 60) {
next_crawl_wait[i] -= 60;
}
break;
}
}
if (available_reclaims == 0) {
next_crawl_wait[i] += 60;
}
if (next_crawl_wait[i] > MAX_MAINTCRAWL_WAIT) {
next_crawl_wait[i] = MAX_MAINTCRAWL_WAIT;
}
next_crawls[i] = current_time + next_crawl_wait[i] + 5;
if (settings.verbose > 1)
fprintf(stderr, "maint crawler[%d]: next_crawl: %u, [%d] now: [%d]\n",
i, next_crawl_wait[i], next_crawls[i], current_time);
s->run_complete = false;
pthread_mutex_unlock(&cdata->lock);
}
if (current_time > next_crawls[i]) {
todo[i] = 1;
do_run = true;
next_crawls[i] = current_time + 5;
}
}
if (do_run) {
lru_crawler_start(todo, 0, CRAWLER_EXPIRED, cdata, NULL, 0);
}
},0

int cipso_v4_sock_setattr(struct sock *sk,
const struct cipso_v4_doi *doi_def,
const struct netlbl_lsm_secattr *secattr)
{
int ret_val = -EPERM;
unsigned char *buf = NULL;
u32 buf_len;
u32 opt_len;
struct ip_options *opt = NULL;
struct inet_sock *sk_inet;
struct inet_connection_sock *sk_conn;
if (sk == NULL)
return 0;
buf_len = CIPSO_V4_OPT_LEN_MAX;
buf = kmalloc(buf_len, GFP_ATOMIC);
if (buf == NULL) {
ret_val = -ENOMEM;
goto socket_setattr_failure;
}
ret_val = cipso_v4_genopt(buf, buf_len, doi_def, secattr);
if (ret_val < 0)
goto socket_setattr_failure;
buf_len = ret_val;
opt_len = (buf_len + 3) & ~3;
opt = kzalloc(sizeof(*opt) + opt_len, GFP_ATOMIC);
if (opt == NULL) {
ret_val = -ENOMEM;
goto socket_setattr_failure;
}
memcpy(opt->__data, buf, buf_len);
opt->optlen = opt_len;
opt->cipso = sizeof(struct iphdr);
kfree(buf);
buf = NULL;
sk_inet = inet_sk(sk);
if (sk_inet->is_icsk) {
sk_conn = inet_csk(sk);
if (sk_inet->opt)
sk_conn->icsk_ext_hdr_len -= sk_inet->opt->optlen;
sk_conn->icsk_ext_hdr_len += opt->optlen;
sk_conn->icsk_sync_mss(sk, sk_conn->icsk_pmtu_cookie);
}
opt = xchg(&sk_inet->opt, opt);
kfree(opt);
return 0;
socket_setattr_failure:
kfree(buf);
kfree(opt);
return ret_val;
},1

poppler_document_get_property (GObject *object,
guint prop_id,
GValue *value,
GParamSpec *pspec)
{
PopplerDocument *document = POPPLER_DOCUMENT (object);
guint version;
switch (prop_id)
{
case PROP_TITLE:
g_value_take_string (value, poppler_document_get_title (document));
break;
case PROP_FORMAT:
g_value_take_string (value, poppler_document_get_pdf_version_string (document));
break;
case PROP_FORMAT_MAJOR:
poppler_document_get_pdf_version (document, &version, nullptr);
g_value_set_uint (value, version);
break;
case PROP_FORMAT_MINOR:
poppler_document_get_pdf_version (document, nullptr, &version);
g_value_set_uint (value, version);
break;
case PROP_AUTHOR:
g_value_take_string (value, poppler_document_get_author (document));
break;
case PROP_SUBJECT:
g_value_take_string (value, poppler_document_get_subject (document));
break;
case PROP_KEYWORDS:
g_value_take_string (value, poppler_document_get_keywords (document));
break;
case PROP_CREATOR:
g_value_take_string (value, poppler_document_get_creator (document));
break;
case PROP_PRODUCER:
g_value_take_string (value, poppler_document_get_producer (document));
break;
case PROP_CREATION_DATE:
g_value_set_int (value, poppler_document_get_creation_date (document));
break;
case PROP_MOD_DATE:
g_value_set_int (value, poppler_document_get_modification_date (document));
break;
case PROP_LINEARIZED:
g_value_set_boolean (value, poppler_document_is_linearized (document));
break;
case PROP_PAGE_LAYOUT:
g_value_set_enum (value, poppler_document_get_page_layout (document));
break;
case PROP_PAGE_MODE:
g_value_set_enum (value, poppler_document_get_page_mode (document));
break;
case PROP_VIEWER_PREFERENCES:
g_value_set_flags (value, POPPLER_VIEWER_PREFERENCES_UNSET);
break;
case PROP_PERMISSIONS:
g_value_set_flags (value, poppler_document_get_permissions (document));
break;
case PROP_METADATA:
g_value_take_string (value, poppler_document_get_metadata (document));
break;
default:
G_OBJECT_WARN_INVALID_PROPERTY_ID (object, prop_id, pspec);
}
},0

