static void ok_jpg_decode2(ok_jpg_decoder *decoder) {
ok_jpg *jpg = decoder->jpg;
uint8_t jpg_header[2];
if (!ok_read(decoder, jpg_header, 2)) {
return;
}
if (jpg_header[0] != 0xFF || jpg_header[1] != 0xD8) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Invalid signature (not a JPEG file)");
return;
}
while (!decoder->eoi_found) {
uint8_t buffer[2];
int marker;
if (decoder->next_marker != 0) {
marker = decoder->next_marker;
decoder->next_marker = 0;
} else {
if (!ok_read(decoder, buffer, 2)) {
return;
}
if (buffer[0] == 0xFF) {
marker = buffer[1];
} else if (buffer[0] == 0x00 && buffer[1] == 0xFF) {
if (!ok_read(decoder, buffer, 1)) {
return;
}
marker = buffer[0];
} else {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Invalid JPEG marker");
return;
}
}
bool success = true;
if (marker == 0xC0 || marker == 0xC1 || marker == 0xC2) {
decoder->progressive = (marker == 0xC2);
success = ok_jpg_read_sof(decoder);
if (success && decoder->info_only) {
return;
}
} else if (marker == 0xC4) {
success = decoder->info_only ? ok_jpg_skip_segment(decoder) : ok_jpg_read_dht(decoder);
} else if (marker >= 0xD0 && marker <= 0xD7) {
decoder->next_marker = marker;
ok_jpg_decode_restart_if_needed(decoder);
success = ok_jpg_scan_to_next_marker(decoder);
} else if (marker == 0xD9) {
decoder->eoi_found = true;
if (!decoder->info_only && decoder->progressive) {
ok_jpg_progressive_finish(decoder);
}
} else if (marker == 0xDA) {
if (!decoder->info_only) {
success = ok_jpg_read_sos(decoder);
} else {
success = ok_jpg_skip_segment(decoder);
if (success) {
success = ok_jpg_scan_to_next_marker(decoder);
}
}
} else if (marker == 0xDB) {
success = decoder->info_only ? ok_jpg_skip_segment(decoder) : ok_jpg_read_dqt(decoder);
} else if (marker == 0xDD) {
success = ok_jpg_read_dri(decoder);
} else if (marker == 0xE1) {
success = ok_jpg_read_exif(decoder);
} else if ((marker >= 0xE0 && marker <= 0xEF) || marker == 0xFE) {
success = ok_jpg_skip_segment(decoder);
} else if (marker == 0xFF) {
} else {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Unsupported or corrupt JPEG");
success = false;
}
if (!success) {
return;
}
}
if (decoder->num_components == 0) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "SOF not found");
} else {
for (int i = 0; i < decoder->num_components; i++) {
if (!decoder->components[i].complete) {
ok_jpg_error(jpg, OK_JPG_ERROR_INVALID, "Missing JPEG image data");
break;
}
}
}
},1

static int copy_verifier_state(struct bpf_verifier_state *dst_state,
const struct bpf_verifier_state *src)
{
struct bpf_func_state *dst;
int i, err;
for (i = src->curframe + 1; i <= dst_state->curframe; i++) {
free_func_state(dst_state->frame[i]);
dst_state->frame[i] = NULL;
}
dst_state->curframe = src->curframe;
for (i = 0; i <= src->curframe; i++) {
dst = dst_state->frame[i];
if (!dst) {
dst = kzalloc(sizeof(*dst), GFP_KERNEL);
if (!dst)
return -ENOMEM;
dst_state->frame[i] = dst;
}
err = copy_func_state(dst, src->frame[i]);
if (err)
return err;
}
return 0;
},1

static int add_time_element(struct ldb_message *msg, const char *attr, time_t t)
{
struct ldb_message_element *el;
char *s;
int ret;
if (ldb_msg_find_element(msg, attr) != NULL) {
return LDB_SUCCESS;
}
s = ldb_timestring(msg, t);
if (s == NULL) {
return LDB_ERR_OPERATIONS_ERROR;
}
ret = ldb_msg_add_string(msg, attr, s);
if (ret != LDB_SUCCESS) {
return ret;
}
el = ldb_msg_find_element(msg, attr);
el->flags = LDB_FLAG_MOD_REPLACE;
return LDB_SUCCESS;
},1

struct dst_entry *fib6_rule_lookup(struct net *net, struct flowi6 *fl6,
const struct sk_buff *skb,
int flags, pol_lookup_t lookup)
{
if (net->ipv6.fib6_has_custom_rules) {
struct fib6_result res = {};
struct fib_lookup_arg arg = {
.lookup_ptr = lookup,
.lookup_data = skb,
.result = &res,
.flags = FIB_LOOKUP_NOREF,
};
l3mdev_update_flow(net, flowi6_to_flowi(fl6));
fib_rules_lookup(net->ipv6.fib6_rules_ops,
flowi6_to_flowi(fl6), flags, &arg);
if (res.rt6)
return &res.rt6->dst;
} else {
struct rt6_info *rt;
rt = lookup(net, net->ipv6.fib6_local_tbl, fl6, skb, flags);
if (rt != net->ipv6.ip6_null_entry && rt->dst.error != -EAGAIN)
return &rt->dst;
ip6_rt_put_flags(rt, flags);
rt = lookup(net, net->ipv6.fib6_main_tbl, fl6, skb, flags);
if (rt->dst.error != -EAGAIN)
return &rt->dst;
ip6_rt_put_flags(rt, flags);
}
if (!(flags & RT6_LOOKUP_F_DST_NOREF))
dst_hold(&net->ipv6.ip6_null_entry->dst);
return &net->ipv6.ip6_null_entry->dst;
},0

static void rtl8xxxu_stop_tx_beacon(struct rtl8xxxu_priv *priv)
{
u8 val8;
val8 = rtl8xxxu_read8(priv, REG_FWHW_TXQ_CTRL + 2);
val8 &= ~BIT(6);
rtl8xxxu_write8(priv, REG_FWHW_TXQ_CTRL + 2, val8);
rtl8xxxu_write8(priv, REG_TBTT_PROHIBIT + 1, 0x64);
val8 = rtl8xxxu_read8(priv, REG_TBTT_PROHIBIT + 2);
val8 &= ~BIT(0);
rtl8xxxu_write8(priv, REG_TBTT_PROHIBIT + 2, val8);
},0

int agp_generic_remove_memory(struct agp_memory *mem, off_t pg_start, int type)
{
size_t i;
struct agp_bridge_data *bridge;
int mask_type;
bridge = mem->bridge;
if (!bridge)
return -EINVAL;
if (mem->page_count == 0)
return 0;
if (type != mem->type)
return -EINVAL;
mask_type = bridge->driver->agp_type_to_mask_type(bridge, type);
if (mask_type != 0) {
return -EINVAL;
}
for (i = pg_start; i < (mem->page_count + pg_start); i++) {
writel(bridge->scratch_page, bridge->gatt_table+i);
}
readl(bridge->gatt_table+i-1);
bridge->driver->tlb_flush(mem);
return 0;
},1

void hns_ppe_set_indir_table(struct hns_ppe_cb *ppe_cb,
const u32 rss_tab[HNS_PPEV2_RSS_IND_TBL_SIZE])
{
int i;
int reg_value;
for (i = 0; i < (HNS_PPEV2_RSS_IND_TBL_SIZE / 4); i++) {
reg_value = dsaf_read_dev(ppe_cb,
PPEV2_INDRECTION_TBL_REG + i * 0x4);
dsaf_set_field(reg_value, PPEV2_CFG_RSS_TBL_4N0_M,
PPEV2_CFG_RSS_TBL_4N0_S,
rss_tab[i * 4 + 0] & 0x1F);
dsaf_set_field(reg_value, PPEV2_CFG_RSS_TBL_4N1_M,
PPEV2_CFG_RSS_TBL_4N1_S,
rss_tab[i * 4 + 1] & 0x1F);
dsaf_set_field(reg_value, PPEV2_CFG_RSS_TBL_4N2_M,
PPEV2_CFG_RSS_TBL_4N2_S,
rss_tab[i * 4 + 2] & 0x1F);
dsaf_set_field(reg_value, PPEV2_CFG_RSS_TBL_4N3_M,
PPEV2_CFG_RSS_TBL_4N3_S,
rss_tab[i * 4 + 3] & 0x1F);
dsaf_write_dev(
ppe_cb, PPEV2_INDRECTION_TBL_REG + i * 0x4, reg_value);
}
