static int DecodeSubjKeyId(const byte* input, int sz, DecodedCert* cert)
{
word32 idx = 0;
int length = 0, ret = 0;
WOLFSSL_ENTER("DecodeSubjKeyId");
if (sz <= 0)
return ASN_PARSE_E;
ret = GetOctetString(input, &idx, &length, sz);
if (ret < 0)
return ret;
#if defined(OPENSSL_EXTRA) || defined(OPENSSL_EXTRA_X509_SMALL)
cert->extSubjKeyIdSrc = &input[idx];
cert->extSubjKeyIdSz = length;
#endif
if (length == KEYID_SIZE) {
XMEMCPY(cert->extSubjKeyId, input + idx, length);
}
else
ret = CalcHashId(input + idx, length, cert->extSubjKeyId);
return ret;
},0

Value ExpressionIndexOfCP::evaluate(const Document& root) const {
Value stringArg = vpOperand[0]->evaluate(root);
if (stringArg.nullish()) {
return Value(BSONNULL);
}
uassert(40093,
str::stream() << "$indexOfCP requires a string as the first argument, found: "
<< typeName(stringArg.getType()),
stringArg.getType() == String);
const std::string& input = stringArg.getString();
Value tokenArg = vpOperand[1]->evaluate(root);
uassert(40094,
str::stream() << "$indexOfCP requires a string as the second argument, found: "
<< typeName(tokenArg.getType()),
tokenArg.getType() == String);
const std::string& token = tokenArg.getString();
size_t startCodePointIndex = 0;
if (vpOperand.size() > 2) {
Value startIndexArg = vpOperand[2]->evaluate(root);
uassertIfNotIntegralAndNonNegative(startIndexArg, getOpName(), "starting index");
startCodePointIndex = static_cast<size_t>(startIndexArg.coerceToInt());
}
size_t codePointLength = 0;
size_t startByteIndex = 0;
for (size_t byteIx = 0; byteIx < input.size(); ++codePointLength) {
if (codePointLength == startCodePointIndex) {
startByteIndex = byteIx;
}
uassert(40095,
"$indexOfCP found bad UTF-8 in the input",
!str::isUTF8ContinuationByte(input[byteIx]));
byteIx += getCodePointLength(input[byteIx]);
}
size_t endCodePointIndex = codePointLength;
if (vpOperand.size() > 3) {
Value endIndexArg = vpOperand[3]->evaluate(root);
uassertIfNotIntegralAndNonNegative(endIndexArg, getOpName(), "ending index");
endCodePointIndex =
std::min(codePointLength, static_cast<size_t>(endIndexArg.coerceToInt()));
}
if (startByteIndex == 0 && input.empty() && token.empty()) {
return Value(0);
}
size_t currentCodePointIndex = startCodePointIndex;
for (size_t byteIx = startByteIndex; currentCodePointIndex < endCodePointIndex;
++currentCodePointIndex) {
if (stringHasTokenAtIndex(byteIx, input, token)) {
return Value(static_cast<int>(currentCodePointIndex));
}
byteIx += getCodePointLength(input[byteIx]);
}
return Value(-1);
},0

static char* get_icu_value_internal( const char* loc_name , char* tag_name, int* result , int fromParseLocale)
{
char* tag_value = NULL;
int32_t tag_value_len = 512;
int singletonPos = 0;
char* mod_loc_name = NULL;
int grOffset = 0;
int32_t buflen = 512;
UErrorCode status = U_ZERO_ERROR;
if( strcmp(tag_name, LOC_CANONICALIZE_TAG) != 0 ){
grOffset = findOffset( LOC_GRANDFATHERED , loc_name );
if( grOffset >= 0 ){
if( strcmp(tag_name , LOC_LANG_TAG)==0 ){
return estrdup(loc_name);
} else {
return NULL;
}
}
if( fromParseLocale==1 ){
if( strcmp(tag_name , LOC_LANG_TAG)==0 ){
if( strlen(loc_name)>1 && (isIDPrefix(loc_name) == 1) ){
return estrdup(loc_name);
}
}
singletonPos = getSingletonPos( loc_name );
if( singletonPos == 0){
return NULL;
} else if( singletonPos > 0 ){
mod_loc_name = estrndup ( loc_name , singletonPos-1);
}
}
}
if( mod_loc_name == NULL){
mod_loc_name = estrdup(loc_name );
}
do{
tag_value = erealloc( tag_value , buflen );
tag_value_len = buflen;
if( strcmp(tag_name , LOC_SCRIPT_TAG)==0 ){
buflen = uloc_getScript ( mod_loc_name ,tag_value , tag_value_len , &status);
}
if( strcmp(tag_name , LOC_LANG_TAG )==0 ){
buflen = uloc_getLanguage ( mod_loc_name ,tag_value , tag_value_len , &status);
}
if( strcmp(tag_name , LOC_REGION_TAG)==0 ){
buflen = uloc_getCountry ( mod_loc_name ,tag_value , tag_value_len , &status);
}
if( strcmp(tag_name , LOC_VARIANT_TAG)==0 ){
buflen = uloc_getVariant ( mod_loc_name ,tag_value , tag_value_len , &status);
}
if( strcmp(tag_name , LOC_CANONICALIZE_TAG)==0 ){
buflen = uloc_canonicalize ( mod_loc_name ,tag_value , tag_value_len , &status);
}
if( U_FAILURE( status ) ) {
if( status == U_BUFFER_OVERFLOW_ERROR ) {
status = U_ZERO_ERROR;
continue;
}
*result = 0;
if( tag_value ){
efree( tag_value );
}
if( mod_loc_name ){
efree( mod_loc_name);
}
return NULL;
}
} while( buflen > tag_value_len );
if( buflen ==0 ){
*result = -1;
if( tag_value ){
efree( tag_value );
}
if( mod_loc_name ){
efree( mod_loc_name);
}
return NULL;
} else {
*result = 1;
}
if( mod_loc_name ){
efree( mod_loc_name);
}
return tag_value;
},1

