bool bdoAdd = false;
switch (Type)
{
case pTypeLighting1:
case pTypeLighting2:
case pTypeLighting3:
case pTypeLighting4:
case pTypeLighting5:
case pTypeLighting6:
case pTypeFan:
case pTypeColorSwitch:
case pTypeSecurity1:
