if (
(sunitcode.empty()) ||
(sgroupcode.empty()) ||
((iUnitTest < 1) || (iUnitTest > 128))
)
return;
sunitcode = sgroupcode;
CDomoticzHardwareBase *pBaseHardware = reinterpret_cast<CDomoticzHardwareBase*>(m_mainworker.GetHardware(atoi(hwdid.c_str())));
