return;
unsigned long rID = 0;
if (pBaseHardware->HwdType == HTYPE_EnOceanESP2)
{
CEnOceanESP2 *pEnoceanHardware = reinterpret_cast<CEnOceanESP2 *>(pBaseHardware);
