parse_compliance(FILE * fp, char *name)
{
int type;
char token[MAXTOKEN];
char quoted_string_buffer[MAXQUOTESTR];
struct node *np;
np = alloc_node(current_module);
if (np == NULL)
return (NULL);
type = get_token(fp, token, MAXTOKEN);
if (type != STATUS) {
print_error("Expected STATUS", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != CURRENT && type != DEPRECATED && type != OBSOLETE) {
print_error("Bad STATUS", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != DESCRIPTION) {
print_error("Expected DESCRIPTION", token, type);
goto skip;
}
type = get_token(fp, quoted_string_buffer, MAXQUOTESTR);
if (type != QUOTESTRING) {
print_error("Bad DESCRIPTION", quoted_string_buffer, type);
goto skip;
}
if (netsnmp_ds_get_boolean(NETSNMP_DS_LIBRARY_ID,
NETSNMP_DS_LIB_SAVE_MIB_DESCRS))
np->description = strdup(quoted_string_buffer);
type = get_token(fp, token, MAXTOKEN);
if (type == REFERENCE) {
type = get_token(fp, quoted_string_buffer, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Bad REFERENCE", quoted_string_buffer, type);
goto skip;
}
np->reference = strdup(quoted_string_buffer);
type = get_token(fp, token, MAXTOKEN);
}
if (type != MODULE) {
print_error("Expected MODULE", token, type);
goto skip;
}
while (type == MODULE) {
int modid = -1;
char modname[MAXTOKEN];
type = get_token(fp, token, MAXTOKEN);
if (type == LABEL
&& strcmp(token, module_name(current_module, modname))) {
modid = read_module_internal(token);
if (modid != MODULE_LOADED_OK
&& modid != MODULE_ALREADY_LOADED) {
print_error("Unknown module", token, type);
goto skip;
}
modid = which_module(token);
type = get_token(fp, token, MAXTOKEN);
}
if (type == MANDATORYGROUPS) {
type = get_token(fp, token, MAXTOKEN);
if (type != LEFTBRACKET) {
print_error("Expected \"{\"", token, type);
goto skip;
}
do {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad group name", token, type);
goto skip;
}
if (!compliance_lookup(token, modid))
print_error("Unknown group", token, type);
type = get_token(fp, token, MAXTOKEN);
} while (type == COMMA);
if (type != RIGHTBRACKET) {
print_error("Expected \"}\"", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
while (type == GROUP || type == OBJECT) {
if (type == GROUP) {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad group name", token, type);
goto skip;
}
if (!compliance_lookup(token, modid))
print_error("Unknown group", token, type);
type = get_token(fp, token, MAXTOKEN);
} else {
type = get_token(fp, token, MAXTOKEN);
if (type != LABEL) {
print_error("Bad object name", token, type);
goto skip;
}
if (!compliance_lookup(token, modid))
print_error("Unknown group", token, type);
type = get_token(fp, token, MAXTOKEN);
if (type == SYNTAX)
type = eat_syntax(fp, token, MAXTOKEN);
if (type == WRSYNTAX)
type = eat_syntax(fp, token, MAXTOKEN);
if (type == MINACCESS) {
type = get_token(fp, token, MAXTOKEN);
if (type != NOACCESS && type != ACCNOTIFY
&& type != READONLY && type != WRITEONLY
&& type != READCREATE && type != READWRITE) {
print_error("Bad MIN-ACCESS spec", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
}
if (type != DESCRIPTION) {
print_error("Expected DESCRIPTION", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
if (type != QUOTESTRING) {
print_error("Bad DESCRIPTION", token, type);
goto skip;
}
type = get_token(fp, token, MAXTOKEN);
}
}
skip:
while (type != EQUALS && type != ENDOFFILE)
type = get_token(fp, quoted_string_buffer, MAXQUOTESTR);
return merge_parse_objectid(np, fp, name);
},0

pid_t wait_process(pid_t pid, int *status_ptr, int flags)
{
pid_t waited_pid;
do {
waited_pid = waitpid(pid, status_ptr, flags);
} while (waited_pid == -1 && errno == EINTR);
if (waited_pid == -1 && errno == ECHILD) {
int cnt;
for (cnt = 0; cnt < MAXCHILDPROCS; cnt++) {
if (pid == pid_stat_table[cnt].pid) {
*status_ptr = pid_stat_table[cnt].status;
pid_stat_table[cnt].pid = 0;
return pid;
}
}
}
return waited_pid;
},0

void next_character(void)
{
strlcpy(cipher, english_alphabet, ENGLISH_ALPHABET_BUF);
random_permute_char(cipher, strlen(cipher));
static char CONFIDENTIAL current_word[CURRENT_WORD_BUF];
get_current_word(current_word);
if (strlen(current_word) > 4) {
memzero(current_word, sizeof(current_word));
recovery_abort();
fsm_sendFailure(FailureType_Failure_SyntaxError,
"Words were not entered correctly. Make sure you are using the substition cipher.");
layoutHome();
return;
}
CharacterRequest resp;
memset(&resp, 0, sizeof(CharacterRequest));
resp.word_pos = get_current_word_pos();
resp.character_pos = strlen(current_word);
msg_write(MessageType_MessageType_CharacterRequest, &resp);
bool auto_completed = false;
if (strlen(current_word) >= 3) {
auto_completed = attempt_auto_complete(current_word);
}
#if DEBUG_LINK
if (auto_completed) {
strlcpy(auto_completed_word, current_word, CURRENT_WORD_BUF);
} else {
auto_completed_word[0] = '\0';
}
#endif
format_current_word(current_word, auto_completed);
layout_cipher(current_word, cipher);
memzero(current_word, sizeof(current_word));
},1

static int g2m_init_buffers(G2MContext *c)
{
int aligned_height;
if (!c->framebuf || c->old_width < c->width || c->old_height < c->height) {
c->framebuf_stride = FFALIGN(c->width * 3, 16);
aligned_height = FFALIGN(c->height, 16);
av_free(c->framebuf);
c->framebuf = av_mallocz(c->framebuf_stride * aligned_height);
if (!c->framebuf)
return AVERROR(ENOMEM);
}
if (!c->synth_tile || !c->jpeg_tile ||
c->old_tile_w < c->tile_width ||
c->old_tile_h < c->tile_height) {
c->tile_stride = FFALIGN(c->tile_width, 16) * 3;
aligned_height = FFALIGN(c->tile_height, 16);
av_free(c->synth_tile);
av_free(c->jpeg_tile);
av_free(c->kempf_buf);
av_free(c->kempf_flags);
c->synth_tile = av_mallocz(c->tile_stride * aligned_height);
c->jpeg_tile = av_mallocz(c->tile_stride * aligned_height);
c->kempf_buf = av_mallocz((c->tile_width + 1) * aligned_height
+ FF_INPUT_BUFFER_PADDING_SIZE);
c->kempf_flags = av_mallocz( c->tile_width * aligned_height);
if (!c->synth_tile || !c->jpeg_tile ||
!c->kempf_buf || !c->kempf_flags)
return AVERROR(ENOMEM);
}
return 0;
},1

CWD_API void realpath_cache_del(const char *path, int path_len TSRMLS_DC)
{
#ifdef PHP_WIN32
unsigned long key = realpath_cache_key(path, path_len TSRMLS_CC);
#else
unsigned long key = realpath_cache_key(path, path_len);
#endif
unsigned long n = key % (sizeof(CWDG(realpath_cache)) / sizeof(CWDG(realpath_cache)[0]));
realpath_cache_bucket **bucket = &CWDG(realpath_cache)[n];
while (*bucket != NULL) {
if (key == (*bucket)->key && path_len == (*bucket)->path_len &&
memcmp(path, (*bucket)->path, path_len) == 0) {
realpath_cache_bucket *r = *bucket;
*bucket = (*bucket)->next;
if(r->path == r->realpath) {
CWDG(realpath_cache_size) -= sizeof(realpath_cache_bucket) + r->path_len + 1;
} else {
CWDG(realpath_cache_size) -= sizeof(realpath_cache_bucket) + r->path_len + 1 + r->realpath_len + 1;
}
free(r);
return;
} else {
bucket = &(*bucket)->next;
}
}
},1

int rsa_pkcs1_verify( rsa_context *ctx,
int mode,
int hash_id,
unsigned int hashlen,
const unsigned char *hash,
unsigned char *sig )
{
switch( ctx->padding )
{
case RSA_PKCS_V15:
return rsa_rsassa_pkcs1_v15_verify( ctx, mode, hash_id,
hashlen, hash, sig );
#if defined(POLARSSL_PKCS1_V21)
case RSA_PKCS_V21:
return rsa_rsassa_pss_verify( ctx, mode, hash_id,
hashlen, hash, sig );
#endif
default:
return( POLARSSL_ERR_RSA_INVALID_PADDING );
}
},1

