DBUG_ENTER("get_replace_columns");
free_replace_column();
if (!*from)
die("Missing argument in %s", command->query);
start= buff= (char*)my_malloc(PSI_NOT_INSTRUMENTED,
strlen(from)+1,MYF(MY_WME | MY_FAE));
while (*from)
{
char *to;
uint column_number;
to= get_string(&buff, &from, command);
if (!(column_number= atoi(to)) || column_number > MAX_COLUMNS)
die("Wrong column number to replace_column in '%s'", command->query);
if (!*from)
die("Wrong number of arguments to replace_column in '%s'", command->query);
to= get_string(&buff, &from, command);
my_free(replace_column[column_number-1]);
replace_column[column_number-1]= my_strdup(PSI_NOT_INSTRUMENTED,
to, MYF(MY_WME | MY_FAE));
set_if_bigger(max_replace_column, column_number);
}
my_free(start);
command->last_argument= command->end;
DBUG_VOID_RETURN;
},0

static void StoreSimpleHuffmanTree(const uint8_t* depths,
size_t symbols[4],
size_t num_symbols,
size_t max_bits,
size_t* storage_ix, uint8_t* storage) {
BrotliWriteBits(2, 1, storage_ix, storage);
BrotliWriteBits(2, num_symbols - 1, storage_ix, storage);
{
size_t i;
for (i = 0; i < num_symbols; i++) {
size_t j;
for (j = i + 1; j < num_symbols; j++) {
if (depths[symbols[j]] < depths[symbols[i]]) {
BROTLI_SWAP(size_t, symbols, j, i);
}
}
}
}
if (num_symbols == 2) {
BrotliWriteBits(max_bits, symbols[0], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[1], storage_ix, storage);
} else if (num_symbols == 3) {
BrotliWriteBits(max_bits, symbols[0], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[1], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[2], storage_ix, storage);
} else {
BrotliWriteBits(max_bits, symbols[0], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[1], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[2], storage_ix, storage);
BrotliWriteBits(max_bits, symbols[3], storage_ix, storage);
BrotliWriteBits(1, depths[symbols[0]] == 1 ? 1 : 0, storage_ix, storage);
}
},0

int esp6_output_head(struct xfrm_state *x, struct sk_buff *skb, struct esp_info *esp)
{
u8 *tail;
int nfrags;
int esph_offset;
struct page *page;
struct sk_buff *trailer;
int tailen = esp->tailen;
if (x->encap) {
int err = esp6_output_encap(x, skb, esp);
if (err < 0)
return err;
}
if (!skb_cloned(skb)) {
if (tailen <= skb_tailroom(skb)) {
nfrags = 1;
trailer = skb;
tail = skb_tail_pointer(trailer);
goto skip_cow;
} else if ((skb_shinfo(skb)->nr_frags < MAX_SKB_FRAGS)
&& !skb_has_frag_list(skb)) {
int allocsize;
struct sock *sk = skb->sk;
struct page_frag *pfrag = &x->xfrag;
esp->inplace = false;
allocsize = ALIGN(tailen, L1_CACHE_BYTES);
spin_lock_bh(&x->lock);
if (unlikely(!skb_page_frag_refill(allocsize, pfrag, GFP_ATOMIC))) {
spin_unlock_bh(&x->lock);
goto cow;
}
page = pfrag->page;
get_page(page);
tail = page_address(page) + pfrag->offset;
esp_output_fill_trailer(tail, esp->tfclen, esp->plen, esp->proto);
nfrags = skb_shinfo(skb)->nr_frags;
__skb_fill_page_desc(skb, nfrags, page, pfrag->offset,
tailen);
skb_shinfo(skb)->nr_frags = ++nfrags;
pfrag->offset = pfrag->offset + allocsize;
spin_unlock_bh(&x->lock);
nfrags++;
skb->len += tailen;
skb->data_len += tailen;
skb->truesize += tailen;
if (sk && sk_fullsock(sk))
refcount_add(tailen, &sk->sk_wmem_alloc);
goto out;
}
}
cow:
esph_offset = (unsigned char *)esp->esph - skb_transport_header(skb);
nfrags = skb_cow_data(skb, tailen, &trailer);
if (nfrags < 0)
goto out;
tail = skb_tail_pointer(trailer);
esp->esph = (struct ip_esp_hdr *)(skb_transport_header(skb) + esph_offset);
skip_cow:
esp_output_fill_trailer(tail, esp->tfclen, esp->plen, esp->proto);
pskb_put(skb, trailer, tailen);
out:
return nfrags;
},1

static void enter_rmode(struct kvm_vcpu *vcpu)
{
unsigned long flags;
struct vcpu_vmx *vmx = to_vmx(vcpu);
struct kvm_vmx *kvm_vmx = to_kvm_vmx(vcpu->kvm);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_TR], VCPU_SREG_TR);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_ES], VCPU_SREG_ES);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_DS], VCPU_SREG_DS);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_FS], VCPU_SREG_FS);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_GS], VCPU_SREG_GS);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_SS], VCPU_SREG_SS);
vmx_get_segment(vcpu, &vmx->rmode.segs[VCPU_SREG_CS], VCPU_SREG_CS);
vmx->rmode.vm86_active = 1;
if (!kvm_vmx->tss_addr)
printk_once(KERN_WARNING "kvm: KVM_SET_TSS_ADDR need to be "
"called before entering vcpu\n");
vmx_segment_cache_clear(vmx);
vmcs_writel(GUEST_TR_BASE, kvm_vmx->tss_addr);
vmcs_write32(GUEST_TR_LIMIT, RMODE_TSS_SIZE - 1);
vmcs_write32(GUEST_TR_AR_BYTES, 0x008b);
flags = vmcs_readl(GUEST_RFLAGS);
vmx->rmode.save_rflags = flags;
flags |= X86_EFLAGS_IOPL | X86_EFLAGS_VM;
vmcs_writel(GUEST_RFLAGS, flags);
vmcs_writel(GUEST_CR4, vmcs_readl(GUEST_CR4) | X86_CR4_VME);
vmx_update_exception_bitmap(vcpu);
fix_rmode_seg(VCPU_SREG_SS, &vmx->rmode.segs[VCPU_SREG_SS]);
fix_rmode_seg(VCPU_SREG_CS, &vmx->rmode.segs[VCPU_SREG_CS]);
fix_rmode_seg(VCPU_SREG_ES, &vmx->rmode.segs[VCPU_SREG_ES]);
fix_rmode_seg(VCPU_SREG_DS, &vmx->rmode.segs[VCPU_SREG_DS]);
fix_rmode_seg(VCPU_SREG_GS, &vmx->rmode.segs[VCPU_SREG_GS]);
fix_rmode_seg(VCPU_SREG_FS, &vmx->rmode.segs[VCPU_SREG_FS]);
kvm_mmu_reset_context(vcpu);
},0

int main(int argc, const char **argv)
{
int force = 0;
const char *stateFile = STATEFILE;
const char *logFile = NULL;
FILE *logFd = NULL;
int rc = 0;
int arg;
const char **files;
poptContext optCon;
struct logInfo *log;
struct poptOption options[] = {
{"debug", 'd', 0, NULL, 'd',
"Don't do anything, just test and print debug messages", NULL},
{"force", 'f', 0, &force, 0, "Force file rotation", NULL},
{"mail", 'm', POPT_ARG_STRING, &mailCommand, 0,
"Command to send mail (instead of `" DEFAULT_MAIL_COMMAND "')",
"command"},
{"state", 's', POPT_ARG_STRING, &stateFile, 0,
"Path of state file",
"statefile"},
{"verbose", 'v', 0, NULL, 'v', "Display messages during rotation", NULL},
{"log", 'l', POPT_ARG_STRING, &logFile, 'l', "Log file or 'syslog' to log to syslog",
"logfile"},
{"version", '\0', POPT_ARG_NONE, NULL, 'V', "Display version information", NULL},
POPT_AUTOHELP { NULL, 0, 0, NULL, 0, NULL, NULL }
};
logSetLevel(MESS_NORMAL);
setlocale (LC_ALL, "");
optCon = poptGetContext("logrotate", argc, argv, options, 0);
poptReadDefaultConfig(optCon, 1);
poptSetOtherOptionHelp(optCon, "[OPTION...] <configfile>");
while ((arg = poptGetNextOpt(optCon)) >= 0) {
switch (arg) {
case 'd':
debug = 1;
message(MESS_NORMAL, "WARNING: logrotate in debug mode does nothing"
" except printing debug messages! Consider using verbose"
" mode (-v) instead if this is not what you want.\n\n");
case 'v':
logSetLevel(MESS_DEBUG);
break;
case 'l':
if (strcmp(logFile, "syslog") == 0) {
logToSyslog(1);
}
else {
logFd = fopen(logFile, "w");
if (!logFd) {
message(MESS_ERROR, "error opening log file %s: %s\n",
logFile, strerror(errno));
break;
}
logSetMessageFile(logFd);
}
break;
case 'V':
printf("logrotate %s\n", VERSION);
printf("\n");
printf(" Default mail command: %s\n", DEFAULT_MAIL_COMMAND);
printf(" Default compress command: %s\n", COMPRESS_COMMAND);
printf(" Default uncompress command: %s\n", UNCOMPRESS_COMMAND);
printf(" Default compress extension: %s\n", COMPRESS_EXT);
printf(" Default state file path: %s\n", STATEFILE);
#ifdef WITH_ACL
printf(" ACL support: yes\n");
#else
printf(" ACL support: no\n");
#endif
#ifdef WITH_SELINUX
printf(" SELinux support: yes\n");
#else
printf(" SELinux support: no\n");
#endif
poptFreeContext(optCon);
exit(0);
default:
break;
}
}
if (arg < -1) {
fprintf(stderr, "logrotate: bad argument %s: %s\n",
poptBadOption(optCon, POPT_BADOPTION_NOALIAS),
poptStrerror(rc));
poptFreeContext(optCon);
return 2;
}
files = poptGetArgs(optCon);
if (!files) {
fprintf(stderr, "logrotate " VERSION
" - Copyright (C) 1995-2001 Red Hat, Inc.\n");
fprintf(stderr,
"This may be freely redistributed under the terms of "
"the GNU General Public License\n\n");
poptPrintUsage(optCon, stderr, 0);
poptFreeContext(optCon);
exit(1);
}
#ifdef WITH_SELINUX
selinux_enabled = (is_selinux_enabled() > 0);
selinux_enforce = security_getenforce();
#endif
TAILQ_INIT(&logs);
if (readAllConfigPaths(files))
rc = 1;
poptFreeContext(optCon);
nowSecs = time(NULL);
if (readState(stateFile))
rc = 1;
message(MESS_DEBUG, "\nHandling %d logs\n", numLogs);
for (log = logs.tqh_first; log != NULL; log = log->list.tqe_next)
rc |= rotateLogSet(log, force);
if (!debug)
rc |= writeState(stateFile);
return (rc != 0);
},1

int special(DviContext *dvi, int opcode)
{
char *s;
Int32 arg;
arg = dugetn(dvi, opcode - DVI_XXX1 + 1);
s = mdvi_malloc(arg + 1);
dread(dvi, s, arg);
s[arg] = 0;
mdvi_do_special(dvi, s);
SHOWCMD((dvi, "XXXX", opcode - DVI_XXX1 + 1,
"[%s]", s));
mdvi_free(s);
return 0;
},1

