process_copy_in ()
{
FILE *tty_in = NULL;
FILE *tty_out = NULL;
FILE *rename_in = NULL;
struct stat file_stat;
struct cpio_file_stat file_hdr = CPIO_FILE_STAT_INITIALIZER;
int in_file_des;
char skip_file;
int i;
newdir_umask = umask (0);
if (pattern_file_name)
{
read_pattern_file ();
}
if (rename_batch_file)
{
rename_in = fopen (rename_batch_file, "r");
if (rename_in == NULL)
{
error (PAXEXIT_FAILURE, errno, TTY_NAME);
}
}
else if (rename_flag)
{
tty_in = fopen (TTY_NAME, "r");
if (tty_in == NULL)
{
error (PAXEXIT_FAILURE, errno, TTY_NAME);
}
tty_out = fopen (TTY_NAME, "w");
if (tty_out == NULL)
{
error (PAXEXIT_FAILURE, errno, TTY_NAME);
}
}
if (table_flag && verbose_flag)
{
time (&current_time);
}
in_file_des = archive_des;
if (_isrmt (in_file_des))
{
input_is_special = 1;
input_is_seekable = 0;
}
else
{
if (fstat (in_file_des, &file_stat))
error (PAXEXIT_FAILURE, errno, _("standard input is closed"));
input_is_special =
#ifdef S_ISBLK
S_ISBLK (file_stat.st_mode) ||
#endif
S_ISCHR (file_stat.st_mode);
input_is_seekable = S_ISREG (file_stat.st_mode);
}
output_is_seekable = true;
change_dir ();
while (1)
{
swapping_halfwords = swapping_bytes = false;
read_in_header (&file_hdr, in_file_des);
#ifdef DEBUG_CPIO
if (debug_flag)
{
struct cpio_file_stat *h;
h = &file_hdr;
fprintf (stderr,
"magic = 0%o, ino = %ld, mode = 0%o, uid = %d, gid = %d\n",
h->c_magic, (long)h->c_ino, h->c_mode, h->c_uid, h->c_gid);
fprintf (stderr,
"nlink = %d, mtime = %d, filesize = %d, dev_maj = 0x%x\n",
h->c_nlink, h->c_mtime, h->c_filesize, h->c_dev_maj);
fprintf (stderr,
"dev_min = 0x%x, rdev_maj = 0x%x, rdev_min = 0x%x, namesize = %d\n",
h->c_dev_min, h->c_rdev_maj, h->c_rdev_min, h->c_namesize);
fprintf (stderr,
"chksum = %d, name = \"%s\", tar_linkname = \"%s\"\n",
h->c_chksum, h->c_name,
h->c_tar_linkname ? h->c_tar_linkname : "(null)" );
}
#endif
if (file_hdr.c_namesize == 0)
skip_file = true;
else
{
if (strcmp (CPIO_TRAILER_NAME, file_hdr.c_name) == 0)
break;
cpio_safer_name_suffix (file_hdr.c_name, false, !no_abs_paths_flag,
false);
if (num_patterns <= 0)
skip_file = false;
else
{
skip_file = copy_matching_files;
for (i = 0; i < num_patterns
&& skip_file == copy_matching_files; i++)
{
if (fnmatch (save_patterns[i], file_hdr.c_name, 0) == 0)
skip_file = !copy_matching_files;
}
}
}
if (skip_file)
{
if (file_hdr.c_nlink > 1 && (archive_format == arf_newascii
|| archive_format == arf_crcascii) )
{
if (create_defered_links_to_skipped(&file_hdr, in_file_des) < 0)
{
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
}
}
else
{
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
}
}
else if (table_flag)
{
list_file (&file_hdr, in_file_des);
}
else if (append_flag)
{
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
}
else if (only_verify_crc_flag)
{
#ifdef CP_IFLNK
if ((file_hdr.c_mode & CP_IFMT) == CP_IFLNK)
{
if (archive_format != arf_tar && archive_format != arf_ustar)
{
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
continue;
}
}
#endif
crc = 0;
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
if (crc != file_hdr.c_chksum)
{
error (0, 0, _("%s: checksum error (0x%x, should be 0x%x)"),
file_hdr.c_name, crc, file_hdr.c_chksum);
}
if (verbose_flag)
{
fprintf (stderr, "%s\n", file_hdr.c_name);
}
if (dot_flag)
{
fputc ('.', stderr);
}
}
else
{
if (rename_flag || rename_batch_file)
{
if (query_rename(&file_hdr, tty_in, tty_out, rename_in) < 0)
{
tape_toss_input (in_file_des, file_hdr.c_filesize);
tape_skip_padding (in_file_des, file_hdr.c_filesize);
continue;
}
}
copyin_file(&file_hdr, in_file_des);
if (verbose_flag)
fprintf (stderr, "%s\n", file_hdr.c_name);
if (dot_flag)
fputc ('.', stderr);
}
}
if (dot_flag)
fputc ('\n', stderr);
apply_delayed_set_stat ();
cpio_file_stat_free (&file_hdr);
if (append_flag)
return;
if (archive_format == arf_newascii || archive_format == arf_crcascii)
{
create_final_defers ();
}
if (!quiet_flag)
{
size_t blocks;
blocks = (input_bytes + io_block_size - 1) / io_block_size;
fprintf (stderr,
ngettext ("%lu block\n", "%lu blocks\n",
(unsigned long) blocks),
(unsigned long) blocks);
}
},1

R_API char *r_egg_option_get(REgg *egg, const char *key) {
return sdb_get (egg->db, key, NULL);
},0

GF_RTPHinter *gf_hinter_track_new(GF_ISOFile *file, u32 TrackNum,
u32 Path_MTU, u32 max_ptime, u32 default_rtp_rate, u32 flags, u8 PayloadID,
Bool copy_media, u32 InterleaveGroupID, u8 InterleaveGroupPriority, GF_Err *e)
{
GF_SLConfig my_sl;
u32 descIndex, MinSize, MaxSize, avgTS, streamType, codecid, const_dur, nb_ch, maxDTSDelta;
u8 OfficialPayloadID;
u32 TrackMediaSubType, TrackMediaType, hintType, nbEdts, required_rate, force_dts_delta, avc_nalu_size, PL_ID, bandwidth, IV_length, KI_length;
const char *url, *urn;
char *mpeg4mode;
Bool is_crypted, has_mpeg4_mapping;
GF_RTPHinter *tmp;
GF_ESD *esd;
*e = GF_BAD_PARAM;
if (!file || !TrackNum || !gf_isom_get_track_id(file, TrackNum)) return NULL;
if (!gf_isom_get_sample_count(file, TrackNum)) {
*e = GF_OK;
return NULL;
}
*e = GF_NOT_SUPPORTED;
nbEdts = gf_isom_get_edits_count(file, TrackNum);
if (nbEdts>1) {
u64 et, sd, mt;
GF_ISOEditType em;
gf_isom_get_edit(file, TrackNum, 1, &et, &sd, &mt, &em);
if ((nbEdts>2) || (em!=GF_ISOM_EDIT_EMPTY)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("[rtp hinter] Cannot hint track whith EditList\n"));
return NULL;
}
}
if (nbEdts) gf_isom_remove_edits(file, TrackNum);
if (!gf_isom_is_track_enabled(file, TrackNum)) return NULL;
PL_ID = 0;
OfficialPayloadID = 0;
force_dts_delta = 0;
streamType = 0;
mpeg4mode = NULL;
required_rate = 0;
is_crypted = 0;
IV_length = KI_length = 0;
codecid = 0;
nb_ch = 0;
avc_nalu_size = 0;
has_mpeg4_mapping = 1;
const_dur = 0;
bandwidth=0;
TrackMediaType = gf_isom_get_media_type(file, TrackNum);
if (!default_rtp_rate) default_rtp_rate = 90000;
if ( (TrackMediaType==GF_ISOM_MEDIA_TEXT) || (TrackMediaType==GF_ISOM_MEDIA_SUBT)) {
hintType = GF_RTP_PAYT_3GPP_TEXT;
codecid = GF_CODECID_TEXT_MPEG4;
streamType = GF_STREAM_TEXT;
PL_ID = 0x10;
} else {
if (gf_isom_get_sample_description_count(file, TrackNum) > 1) return NULL;
TrackMediaSubType = gf_isom_get_media_subtype(file, TrackNum, 1);
switch (TrackMediaSubType) {
case GF_ISOM_SUBTYPE_MPEG4_CRYP:
is_crypted = 1;
case GF_ISOM_SUBTYPE_MPEG4:
esd = gf_isom_get_esd(file, TrackNum, 1);
hintType = GF_RTP_PAYT_MPEG4;
if (esd && esd->decoderConfig) {
streamType = esd->decoderConfig->streamType;
codecid = esd->decoderConfig->objectTypeIndication;
if (esd->URLString) hintType = 0;
if ((streamType==GF_STREAM_AUDIO)
&& esd->decoderConfig->decoderSpecificInfo && esd->decoderConfig->decoderSpecificInfo->data
&& ((codecid==GF_CODECID_AAC_MPEG4) || (codecid==GF_CODECID_AAC_MPEG2_MP) || (codecid==GF_CODECID_AAC_MPEG2_LCP) || (codecid==GF_CODECID_AAC_MPEG2_SSRP)) ) {
u32 sample_rate;
GF_M4ADecSpecInfo a_cfg;
gf_m4a_get_config(esd->decoderConfig->decoderSpecificInfo->data, esd->decoderConfig->decoderSpecificInfo->dataLength, &a_cfg);
nb_ch = a_cfg.nb_chan;
sample_rate = a_cfg.base_sr;
PL_ID = a_cfg.audioPL;
switch (a_cfg.base_object_type) {
case GF_M4A_AAC_MAIN:
case GF_M4A_AAC_LC:
if (flags & GP_RTP_PCK_USE_LATM_AAC) {
hintType = GF_RTP_PAYT_LATM;
break;
}
case GF_M4A_AAC_SBR:
case GF_M4A_AAC_PS:
case GF_M4A_AAC_LTP:
case GF_M4A_AAC_SCALABLE:
case GF_M4A_ER_AAC_LC:
case GF_M4A_ER_AAC_LTP:
case GF_M4A_ER_AAC_SCALABLE:
mpeg4mode = "AAC";
break;
case GF_M4A_CELP:
case GF_M4A_ER_CELP:
mpeg4mode = "CELP";
break;
}
required_rate = sample_rate;
}
else if ((streamType==GF_STREAM_AUDIO) && ((codecid==GF_CODECID_MPEG2_PART3) || (codecid==GF_CODECID_MPEG_AUDIO))) {
