switch ((insn >> 27) & 7) {
case 0:
trace_lsi_execute_script_tc_jump(addr);
s->adder = addr;
s->dsp = addr;
break;
case 1:
trace_lsi_execute_script_tc_call(addr);
s->temp = s->dsp;
s->dsp = addr;
break;
case 2:
trace_lsi_execute_script_tc_return(s->temp);
s->dsp = s->temp;
break;
case 3:
trace_lsi_execute_script_tc_interrupt(s->dsps);
