static void dynamicRefresh(PromptBase& pi, UChar32* buf32, int len, int pos) {
int xEndOfPrompt, yEndOfPrompt;
calculateScreenPosition(
0, 0, pi.promptScreenColumns, pi.promptChars, xEndOfPrompt, yEndOfPrompt);
pi.promptIndentation = xEndOfPrompt;
int xEndOfInput, yEndOfInput;
calculateScreenPosition(xEndOfPrompt,
yEndOfPrompt,
pi.promptScreenColumns,
calculateColumnPosition(buf32, len),
xEndOfInput,
yEndOfInput);
int xCursorPos, yCursorPos;
calculateScreenPosition(xEndOfPrompt,
yEndOfPrompt,
pi.promptScreenColumns,
calculateColumnPosition(buf32, pos),
xCursorPos,
yCursorPos);
#ifdef _WIN32
CONSOLE_SCREEN_BUFFER_INFO inf;
GetConsoleScreenBufferInfo(console_out, &inf);
inf.dwCursorPosition.X = 0;
inf.dwCursorPosition.Y -= pi.promptCursorRowOffset ;
SetConsoleCursorPosition(console_out, inf.dwCursorPosition);
DWORD count;
FillConsoleOutputCharacterA(console_out,
' ',
pi.promptPreviousLen + pi.promptPreviousInputLen,
inf.dwCursorPosition,
&count);
pi.promptPreviousLen = pi.promptIndentation;
pi.promptPreviousInputLen = len;
if (write32(1, pi.promptText.get(), pi.promptChars) == -1)
return;
if (write32(1, buf32, len) == -1)
return;
GetConsoleScreenBufferInfo(console_out, &inf);
inf.dwCursorPosition.X = xCursorPos;
inf.dwCursorPosition.Y -= yEndOfInput - yCursorPos;
SetConsoleCursorPosition(console_out, inf.dwCursorPosition);
#else
char seq[64];
int cursorRowMovement = pi.promptCursorRowOffset - pi.promptExtraLines;
if (cursorRowMovement > 0) {
snprintf(seq, sizeof seq, "\x1b[%dA", cursorRowMovement);
if (write(1, seq, strlen(seq)) == -1)
return;
}
snprintf(seq, sizeof seq, "\x1b[1G\x1b[J");
if (write(1, seq, strlen(seq)) == -1)
return;
if (write32(1, pi.promptText.get(), pi.promptChars) == -1)
return;
if (write32(1, buf32, len) == -1)
return;
if (xEndOfInput == 0 && yEndOfInput > 0)
if (write(1, "\n", 1) == -1)
return;
cursorRowMovement = yEndOfInput - yCursorPos;
if (cursorRowMovement > 0) {
snprintf(seq, sizeof seq, "\x1b[%dA", cursorRowMovement);
if (write(1, seq, strlen(seq)) == -1)
return;
}
snprintf(seq, sizeof seq, "\x1b[%dG", xCursorPos + 1);
if (write(1, seq, strlen(seq)) == -1)
return;
#endif
pi.promptCursorRowOffset = pi.promptExtraLines + yCursorPos;
},0

brcmf_cfg80211_del_station(struct wiphy *wiphy, struct net_device *ndev,
struct station_del_parameters *params)
{
struct brcmf_cfg80211_info *cfg = wiphy_to_cfg(wiphy);
struct brcmf_scb_val_le scbval;
struct brcmf_if *ifp = netdev_priv(ndev);
s32 err;
if (!params->mac)
return -EFAULT;
brcmf_dbg(TRACE, "Enter %pM\n", params->mac);
if (ifp->vif == cfg->p2p.bss_idx[P2PAPI_BSSCFG_DEVICE].vif)
ifp = cfg->p2p.bss_idx[P2PAPI_BSSCFG_PRIMARY].vif->ifp;
if (!check_vif_up(ifp->vif))
return -EIO;
memcpy(&scbval.ea, params->mac, ETH_ALEN);
scbval.val = cpu_to_le32(params->reason_code);
err = brcmf_fil_cmd_data_set(ifp, BRCMF_C_SCB_DEAUTHENTICATE_FOR_REASON,
&scbval, sizeof(scbval));
if (err)
brcmf_err("SCB_DEAUTHENTICATE_FOR_REASON failed %d\n", err);
brcmf_dbg(TRACE, "Exit\n");
return err;
},0

static int vfio_msi_enable(struct vfio_pci_device *vdev, int nvec, bool msix)
{
struct pci_dev *pdev = vdev->pdev;
unsigned int flag = msix ? PCI_IRQ_MSIX : PCI_IRQ_MSI;
int ret;
if (!is_irq_none(vdev))
return -EINVAL;
vdev->ctx = kzalloc(nvec * sizeof(struct vfio_pci_irq_ctx), GFP_KERNEL);
if (!vdev->ctx)
return -ENOMEM;
ret = pci_alloc_irq_vectors(pdev, 1, nvec, flag);
if (ret < nvec) {
if (ret > 0)
pci_free_irq_vectors(pdev);
kfree(vdev->ctx);
return ret;
}
vdev->num_ctx = nvec;
vdev->irq_type = msix ? VFIO_PCI_MSIX_IRQ_INDEX :
VFIO_PCI_MSI_IRQ_INDEX;
if (!msix) {
vdev->msi_qmax = fls(nvec * 2 - 1) - 1;
}
return 0;
},1

mz_uint tdefl_create_comp_flags_from_zip_params(int level, int window_bits,
int strategy) {
mz_uint comp_flags =
s_tdefl_num_probes[(level >= 0) ? MZ_MIN(10, level) : MZ_DEFAULT_LEVEL] |
((level <= 3) ? TDEFL_GREEDY_PARSING_FLAG : 0);
if (window_bits > 0) comp_flags |= TDEFL_WRITE_ZLIB_HEADER;
if (!level)
comp_flags |= TDEFL_FORCE_ALL_RAW_BLOCKS;
else if (strategy == MZ_FILTERED)
comp_flags |= TDEFL_FILTER_MATCHES;
else if (strategy == MZ_HUFFMAN_ONLY)
comp_flags &= ~TDEFL_MAX_PROBES_MASK;
else if (strategy == MZ_FIXED)
comp_flags |= TDEFL_FORCE_ALL_STATIC_BLOCKS;
else if (strategy == MZ_RLE)
comp_flags |= TDEFL_RLE_MATCHES;
return comp_flags;
},0

void InstanceImpl::initialize(const Options& options,
Network::Address::InstanceConstSharedPtr local_address,
ComponentFactory& component_factory, ListenerHooks& hooks) {
ENVOY_LOG(info, "initializing epoch {} (base id={}, hot restart version={})",
options.restartEpoch(), restarter_.baseId(), restarter_.version());
ENVOY_LOG(info, "statically linked extensions:");
for (const auto& ext : Envoy::Registry::FactoryCategoryRegistry::registeredFactories()) {
ENVOY_LOG(info, " {}: {}", ext.first, absl::StrJoin(ext.second->registeredNames(), ", "));
}
InstanceUtil::loadBootstrapConfig(bootstrap_, options,
messageValidationContext().staticValidationVisitor(), *api_);
bootstrap_config_update_time_ = time_source_.systemTime();
if (!bootstrap_.header_prefix().empty()) {
ThreadSafeSingleton<Http::PrefixValue>::get().setPrefix(bootstrap_.header_prefix().c_str());
}
ENVOY_LOG(info, "HTTP header map info:");
for (const auto& info : Http::HeaderMapImplUtility::getAllHeaderMapImplInfo()) {
ENVOY_LOG(info, " {}: {} bytes: {}", info.name_, info.size_,
absl::StrJoin(info.registered_headers_, ","));
}
stats_store_.setTagProducer(Config::Utility::createTagProducer(bootstrap_));
stats_store_.setStatsMatcher(Config::Utility::createStatsMatcher(bootstrap_));
const std::string server_stats_prefix = "server.";
server_stats_ = std::make_unique<ServerStats>(
ServerStats{ALL_SERVER_STATS(POOL_COUNTER_PREFIX(stats_store_, server_stats_prefix),
POOL_GAUGE_PREFIX(stats_store_, server_stats_prefix),
POOL_HISTOGRAM_PREFIX(stats_store_, server_stats_prefix))});
validation_context_.static_warning_validation_visitor().setUnknownCounter(
server_stats_->static_unknown_fields_);
validation_context_.dynamic_warning_validation_visitor().setUnknownCounter(
server_stats_->dynamic_unknown_fields_);
initialization_timer_ = std::make_unique<Stats::HistogramCompletableTimespanImpl>(
server_stats_->initialization_time_ms_, timeSource());
server_stats_->concurrency_.set(options_.concurrency());
server_stats_->hot_restart_epoch_.set(options_.restartEpoch());
assert_action_registration_ = Assert::setDebugAssertionFailureRecordAction(
[this]() { server_stats_->debug_assertion_failures_.inc(); });
envoy_bug_action_registration_ = Assert::setEnvoyBugFailureRecordAction(
[this]() { server_stats_->envoy_bug_failures_.inc(); });
InstanceImpl::failHealthcheck(false);
uint64_t version_int;
if (bootstrap_.stats_server_version_override().value() > 0) {
version_int = bootstrap_.stats_server_version_override().value();
} else {
if (!StringUtil::atoull(VersionInfo::revision().substr(0, 6).c_str(), version_int, 16)) {
throw EnvoyException("compiled GIT SHA is invalid. Invalid build.");
}
}
server_stats_->version_.set(version_int);
bootstrap_.mutable_node()->set_hidden_envoy_deprecated_build_version(VersionInfo::version());
bootstrap_.mutable_node()->set_user_agent_name("envoy");
*bootstrap_.mutable_node()->mutable_user_agent_build_version() = VersionInfo::buildVersion();
for (const auto& ext : Envoy::Registry::FactoryCategoryRegistry::registeredFactories()) {
for (const auto& name : ext.second->allRegisteredNames()) {
auto* extension = bootstrap_.mutable_node()->add_extensions();
extension->set_name(std::string(name));
extension->set_category(ext.first);
auto const version = ext.second->getFactoryVersion(name);
if (version) {
*extension->mutable_version() = version.value();
}
extension->set_disabled(ext.second->isFactoryDisabled(name));
}
}
local_info_ = std::make_unique<LocalInfo::LocalInfoImpl>(
bootstrap_.node(), local_address, options.serviceZone(), options.serviceClusterName(),
options.serviceNodeName());
Configuration::InitialImpl initial_config(bootstrap_);
restarter_.sendParentAdminShutdownRequest(original_start_time_);
