static struct binder_buffer *binder_alloc_prepare_to_free_locked(
struct binder_alloc *alloc,
uintptr_t user_ptr)
{
struct rb_node *n = alloc->allocated_buffers.rb_node;
struct binder_buffer *buffer;
void *kern_ptr;
kern_ptr = (void *)(user_ptr - alloc->user_buffer_offset);
while (n) {
buffer = rb_entry(n, struct binder_buffer, rb_node);
BUG_ON(buffer->free);
if (kern_ptr < buffer->data)
n = n->rb_left;
else if (kern_ptr > buffer->data)
n = n->rb_right;
else {
if (buffer->free_in_progress) {
binder_alloc_debug(BINDER_DEBUG_USER_ERROR,
"%d:%d FREE_BUFFER u%016llx user freed buffer twice\n",
alloc->pid, current->pid,
(u64)user_ptr);
return NULL;
}
buffer->free_in_progress = 1;
return buffer;
}
}
return NULL;
},1

std::string get_wml_location(const std::string &filename, const std::string &current_dir)
{
DBG_FS << "Looking for '" << filename << "'.\n";
std::string result;
if (filename.empty()) {
LOG_FS << " invalid filename\n";
return result;
}
if (filename.find("..") != std::string::npos) {
ERR_FS << "Illegal path '" << filename << "' (\"..\" not allowed).\n";
return result;
}
bool already_found = false;
if (filename[0] == '~')
{
result = get_user_data_dir() + "/data/" + filename.substr(1);
DBG_FS << " trying '" << result << "'\n";
already_found = file_exists(result) || is_directory(result);
}
else if (filename.size() >= 2 && filename[0] == '.' && filename[1] == '/')
{
result = current_dir + filename.substr(2);
}
else if (!game_config::path.empty())
result = game_config::path + "/data/" + filename;
DBG_FS << " trying '" << result << "'\n";
if (result.empty() ||
(!already_found && !file_exists(result) && !is_directory(result)))
{
DBG_FS << " not found\n";
result.clear();
}
else
DBG_FS << " found: '" << result << "'\n";
return result;
},1

TEST_P(DownstreamProtocolIntegrationTest, TestEncodeHeadersReturnsStopAll) {
EXCLUDE_DOWNSTREAM_HTTP3
config_helper_.addFilter(R"EOF(
name: encode-headers-return-stop-all-filter
)EOF");
config_helper_.addConfigModifier(
[&](envoy::extensions::filters::network::http_connection_manager::v3::HttpConnectionManager&
hcm) -> void { hcm.mutable_http2_protocol_options()->set_allow_metadata(true); });
initialize();
codec_client_ = makeHttpConnection(lookupPort("http"));
auto response = codec_client_->makeRequestWithBody(default_request_headers_, 10);
waitForNextUpstreamRequest();
changeHeadersForStopAllTests(default_response_headers_, false);
upstream_request_->encodeHeaders(default_response_headers_, false);
for (int i = 0; i < count_ - 1; i++) {
upstream_request_->encodeData(size_, false);
}
absl::SleepFor(absl::Seconds(1));
upstream_request_->encodeData(size_, false);
Http::TestResponseTrailerMapImpl response_trailers{{"response", "trailer"}};
upstream_request_->encodeTrailers(response_trailers);
ASSERT_TRUE(response->waitForEndStream());
ASSERT_TRUE(response->complete());
int times_added = (upstreamProtocol() == FakeHttpConnection::Type::HTTP1 ||
downstreamProtocol() == Http::CodecClient::Type::HTTP1)
? 1
: 2;
if (downstreamProtocol() == Http::CodecClient::Type::HTTP1 &&
upstreamProtocol() == FakeHttpConnection::Type::HTTP3) {
return;
}
EXPECT_EQ(count_ * size_ + added_decoded_data_size_ * times_added, response->body().size());
},0

coroutine_fn iscsi_co_pwrite_zeroes(BlockDriverState *bs, int64_t offset,
int bytes, BdrvRequestFlags flags)
{
IscsiLun *iscsilun = bs->opaque;
struct IscsiTask iTask;
uint64_t lba;
uint32_t nb_blocks;
bool use_16_for_ws = iscsilun->use_16_for_rw;
int r = 0;
if (!is_byte_request_lun_aligned(offset, bytes, iscsilun)) {
return -ENOTSUP;
}
if (flags & BDRV_REQ_MAY_UNMAP) {
if (!use_16_for_ws && !iscsilun->lbp.lbpws10) {
use_16_for_ws = true;
}
if (use_16_for_ws && !iscsilun->lbp.lbpws) {
flags &= ~BDRV_REQ_MAY_UNMAP;
use_16_for_ws = iscsilun->use_16_for_rw;
}
}
if (!(flags & BDRV_REQ_MAY_UNMAP) && !iscsilun->has_write_same) {
return -ENOTSUP;
}
lba = offset / iscsilun->block_size;
nb_blocks = bytes / iscsilun->block_size;
if (iscsilun->zeroblock == NULL) {
iscsilun->zeroblock = g_try_malloc0(iscsilun->block_size);
if (iscsilun->zeroblock == NULL) {
return -ENOMEM;
}
}
qemu_mutex_lock(&iscsilun->mutex);
iscsi_co_init_iscsitask(iscsilun, &iTask);
retry:
if (use_16_for_ws) {
iTask.task = iscsi_writesame16_task(iscsilun->iscsi, iscsilun->lun, lba,
iscsilun->zeroblock, iscsilun->block_size,
nb_blocks, 0, !!(flags & BDRV_REQ_MAY_UNMAP),
0, 0, iscsi_co_generic_cb, &iTask);
} else {
iTask.task = iscsi_writesame10_task(iscsilun->iscsi, iscsilun->lun, lba,
iscsilun->zeroblock, iscsilun->block_size,
nb_blocks, 0, !!(flags & BDRV_REQ_MAY_UNMAP),
0, 0, iscsi_co_generic_cb, &iTask);
}
if (iTask.task == NULL) {
qemu_mutex_unlock(&iscsilun->mutex);
return -ENOMEM;
}
iscsi_co_wait_for_task(&iTask, iscsilun);
if (iTask.status == SCSI_STATUS_CHECK_CONDITION &&
iTask.task->sense.key == SCSI_SENSE_ILLEGAL_REQUEST &&
(iTask.task->sense.ascq == SCSI_SENSE_ASCQ_INVALID_OPERATION_CODE ||
iTask.task->sense.ascq == SCSI_SENSE_ASCQ_INVALID_FIELD_IN_CDB)) {
iscsilun->has_write_same = false;
scsi_free_scsi_task(iTask.task);
r = -ENOTSUP;
goto out_unlock;
}
if (iTask.task != NULL) {
scsi_free_scsi_task(iTask.task);
iTask.task = NULL;
}
if (iTask.do_retry) {
iTask.complete = 0;
goto retry;
}
if (iTask.status != SCSI_STATUS_GOOD) {
iscsi_allocmap_set_invalid(iscsilun, offset, bytes);
error_report("iSCSI WRITESAME10/16 failed at lba %" PRIu64 ": %s",
lba, iTask.err_str);
r = iTask.err_code;
goto out_unlock;
}
if (flags & BDRV_REQ_MAY_UNMAP) {
iscsi_allocmap_set_invalid(iscsilun, offset, bytes);
} else {
iscsi_allocmap_set_allocated(iscsilun, offset, bytes);
}
out_unlock:
qemu_mutex_unlock(&iscsilun->mutex);
g_free(iTask.err_str);
return r;
},0

static int packet_getname_spkt(struct socket *sock, struct sockaddr *uaddr,
int peer)
{
struct net_device *dev;
struct sock *sk = sock->sk;
if (peer)
return -EOPNOTSUPP;
uaddr->sa_family = AF_PACKET;
memset(uaddr->sa_data, 0, sizeof(uaddr->sa_data));
rcu_read_lock();
dev = dev_get_by_index_rcu(sock_net(sk), READ_ONCE(pkt_sk(sk)->ifindex));
if (dev)
strlcpy(uaddr->sa_data, dev->name, sizeof(uaddr->sa_data));
rcu_read_unlock();
return sizeof(*uaddr);
},0

void ZrtpStateClass::processEvent(Event_t *ev) {
char *msg, first, middle, last;
uint8_t *pkt;
parent->synchEnter();
event = ev;
if (event->type == ZrtpPacket) {
pkt = event->packet;
msg = (char *)pkt + 4;
first = tolower(*msg);
middle = tolower(*(msg+4));
last = tolower(*(msg+7));
if (!inState(WaitErrorAck)) {
uint16_t totalLength = *(uint16_t*)(pkt+2);
totalLength = zrtpNtohs(totalLength) * ZRTP_WORD_SIZE;
totalLength += 12 + sizeof(uint32_t);
if (totalLength != ev->length) {
fprintf(stderr, "Total length does not match received length: %d - %ld\n", totalLength, ev->length);
sendErrorPacket(MalformedPacket);
parent->synchLeave();
return;
}
}
if (first == 'e' && middle =='r' && last == ' ') {
cancelTimer();
ZrtpPacketError epkt(pkt);
ZrtpPacketErrorAck* eapkt = parent->prepareErrorAck(&epkt);
parent->sendPacketZRTP(static_cast<ZrtpPacketBase *>(eapkt));
event->type = ErrorPkt;
}
else if (first == 'p' && middle == ' ' && last == ' ') {
ZrtpPacketPing ppkt(pkt);
ZrtpPacketPingAck* ppktAck = parent->preparePingAck(&ppkt);
parent->sendPacketZRTP(static_cast<ZrtpPacketBase *>(ppktAck));
parent->synchLeave();
return;
}
else if (first == 's' && last == 'y') {
uint32_t errorCode = 0;
ZrtpPacketSASrelay* srly = new ZrtpPacketSASrelay(pkt);
ZrtpPacketRelayAck* rapkt = parent->prepareRelayAck(srly, &errorCode);
parent->sendPacketZRTP(static_cast<ZrtpPacketBase *>(rapkt));
parent->synchLeave();
return;
}
}
else if (event->type == ZrtpClose) {
cancelTimer();
}
engine->processEvent(*this);
parent->synchLeave();
},1

