static GF_List *dasher_get_content_protection_desc(GF_DasherCtx *ctx, GF_DashStream *ds, GF_MPD_AdaptationSet *for_set)
{
char sCan[40];
u32 prot_scheme=0;
u32 i, count;
const GF_PropertyValue *p;
GF_List *res = NULL;
GF_BitStream *bs_r;
count = gf_list_count(ctx->current_period->streams);
bs_r = gf_bs_new((const char *) &count, 1, GF_BITSTREAM_READ);
for (i=0; i<count; i++) {
GF_MPD_Descriptor *desc;
GF_DashStream *a_ds = gf_list_get(ctx->current_period->streams, i);
if (!a_ds->is_encrypted) continue;
if (for_set) {
if (a_ds->set != for_set) continue;
if (!a_ds->owns_set) continue;
} else if ((a_ds != ds) && (a_ds->muxed_base != ds) ) {
continue;
}
p = gf_filter_pid_get_property(a_ds->ipid, GF_PROP_PID_PROTECTION_SCHEME_TYPE);
if (p) prot_scheme = p->value.uint;
if ((prot_scheme==GF_ISOM_CENC_SCHEME) || (prot_scheme==GF_ISOM_CBC_SCHEME) || (prot_scheme==GF_ISOM_CENS_SCHEME) || (prot_scheme==GF_ISOM_CBCS_SCHEME)
) {
const GF_PropertyValue *ki;
u32 j, nb_pssh;
GF_XMLAttribute *att;
char szVal[GF_MAX_PATH];
ctx->use_cenc = GF_TRUE;
ki = gf_filter_pid_get_property(a_ds->ipid, GF_PROP_PID_CENC_KEY_INFO);
if (!ki || !ki->value.data.ptr) {
continue;
}
if (!res) res = gf_list_new();
desc = gf_mpd_descriptor_new(NULL, "urn:mpeg:dash:mp4protection:2011", gf_4cc_to_str(prot_scheme));
gf_list_add(res, desc);
get_canon_urn(ki->value.data.ptr + 4, sCan);
att = gf_xml_dom_create_attribute("cenc:default_KID", sCan);
if (!desc->x_attributes) desc->x_attributes = gf_list_new();
gf_list_add(desc->x_attributes, att);
if (ctx->pssh <= GF_DASH_PSSH_MOOF) {
continue;
}
p = gf_filter_pid_get_property(a_ds->ipid, GF_PROP_PID_CENC_PSSH);
if (!p) continue;
gf_bs_reassign_buffer(bs_r, p->value.data.ptr, p->value.data.size);
nb_pssh = gf_bs_read_u32(bs_r);
for (j=0; j<nb_pssh; j++) {
u32 pssh_idx;
bin128 sysID;
GF_XMLNode *node;
u32 version, k_count;
u8 *pssh_data=NULL;
u32 pssh_len, size_64;
GF_BitStream *bs_w = gf_bs_new(NULL, 0, GF_BITSTREAM_WRITE);
gf_bs_write_u32(bs_w, 0);
gf_bs_write_u32(bs_w, GF_ISOM_BOX_TYPE_PSSH);
gf_bs_read_data(bs_r, sysID, 16);
version = gf_bs_read_u32(bs_r);
k_count = version ? gf_bs_read_u32(bs_r) : 0;
gf_bs_write_u8(bs_w, version);
gf_bs_write_u24(bs_w, 0);
gf_bs_write_data(bs_w, sysID, 16);
if (version) {
gf_bs_write_u32(bs_w, k_count);
for (j=0; j<k_count; j++) {
bin128 keyID;
gf_bs_read_data(bs_r, keyID, 16);
gf_bs_write_data(bs_w, keyID, 16);
}
}
k_count = gf_bs_read_u32(bs_r);
gf_bs_write_u32(bs_w, k_count);
for (pssh_idx=0; pssh_idx<k_count; pssh_idx++) {
gf_bs_write_u8(bs_w, gf_bs_read_u8(bs_r) );
}
pssh_len = (u32) gf_bs_get_position(bs_w);
gf_bs_seek(bs_w, 0);
gf_bs_write_u32(bs_w, pssh_len);
gf_bs_seek(bs_w, pssh_len);
gf_bs_get_content(bs_w, &pssh_data, &pssh_len);
gf_bs_del(bs_w);
get_canon_urn(sysID, sCan);
desc = gf_mpd_descriptor_new(NULL, NULL, NULL);
desc->x_children = gf_list_new();
sprintf(szVal, "urn:uuid:%s", sCan);
desc->scheme_id_uri = gf_strdup(szVal);
desc->value = gf_strdup(get_drm_kms_name(sCan));
gf_list_add(res, desc);
GF_SAFEALLOC(node, GF_XMLNode);
if (node) {
GF_XMLNode *pnode;
node->type = GF_XML_NODE_TYPE;
node->name = gf_strdup("cenc:pssh");
node->content = gf_list_new();
gf_list_add(desc->x_children, node);
GF_SAFEALLOC(pnode, GF_XMLNode);
if (pnode) {
pnode->type = GF_XML_TEXT_TYPE;
gf_list_add(node->content, pnode);
size_64 = 2*pssh_len;
pnode->name = gf_malloc(size_64);
if (pnode->name) {
size_64 = gf_base64_encode((const char *)pssh_data, pssh_len, (char *)pnode->name, size_64);
pnode->name[size_64] = 0;
}
}
}
gf_free(pssh_data);
}
} else {
if (ctx->do_mpd) {
GF_LOG(GF_LOG_WARNING, GF_LOG_DASH, ("[Dasher] Protection scheme %s has no official DASH mapping, using URI \"urn:gpac:dash:mp4protection:2018\"\n", gf_4cc_to_str(prot_scheme)));
}
if (!res) res = gf_list_new();,1

int fullSpeedBench(char** fileNamesTable, int nbFiles)
{
int fileIdx=0;
char* orig_buff;
# define NB_COMPRESSION_ALGORITHMS 13
# define MINCOMPRESSIONCHAR '0'
double totalCTime[NB_COMPRESSION_ALGORITHMS+1] = {0};
double totalCSize[NB_COMPRESSION_ALGORITHMS+1] = {0};
# define NB_DECOMPRESSION_ALGORITHMS 7
# define MINDECOMPRESSIONCHAR '0'
# define MAXDECOMPRESSIONCHAR (MINDECOMPRESSIONCHAR + NB_DECOMPRESSION_ALGORITHMS)
static char* decompressionNames[] = { "LZ4_decompress_fast", "LZ4_decompress_fast_withPrefix64k", "LZ4_decompress_fast_usingDict",
"LZ4_decompress_safe", "LZ4_decompress_safe_withPrefix64k", "LZ4_decompress_safe_usingDict", "LZ4_decompress_safe_partial" };
double totalDTime[NB_DECOMPRESSION_ALGORITHMS+1] = {0};
U64 totals = 0;
while (fileIdx<nbFiles)
{
FILE* inFile;
char* inFileName;
U64 inFileSize;
size_t benchedSize;
int nbChunks;
int maxCompressedChunkSize;
struct chunkParameters* chunkP;
size_t readSize;
char* compressed_buff; int compressedBuffSize;
U32 crcOriginal;
stateLZ4 = malloc(LZ4_sizeofState());
stateLZ4HC = malloc(LZ4_sizeofStateHC());
inFileName = fileNamesTable[fileIdx++];
inFile = fopen( inFileName, "rb" );
if (inFile==NULL)
{
DISPLAY( "Pb opening %s\n", inFileName);
return 11;
}
inFileSize = BMK_GetFileSize(inFileName);
benchedSize = (size_t) BMK_findMaxMem(inFileSize) / 2;
if ((U64)benchedSize > inFileSize) benchedSize = (size_t)inFileSize;
if (benchedSize < inFileSize)
{
DISPLAY("Not enough memory for '%s' full size; testing %i MB only...\n", inFileName, (int)(benchedSize>>20));
}
chunkP = (struct chunkParameters*) malloc(((benchedSize / (size_t)chunkSize)+1) * sizeof(struct chunkParameters));
orig_buff = (char*) malloc((size_t)benchedSize);
nbChunks = (int) ((int)benchedSize / chunkSize) + 1;
maxCompressedChunkSize = LZ4_compressBound(chunkSize);
compressedBuffSize = nbChunks * maxCompressedChunkSize;
compressed_buff = (char*)malloc((size_t)compressedBuffSize);
if(!orig_buff || !compressed_buff)
{
DISPLAY("\nError: not enough memory!\n");
free(orig_buff);
free(compressed_buff);
free(chunkP);
fclose(inFile);
return 12;
}
{
int i;
size_t remaining = benchedSize;
char* in = orig_buff;
char* out = compressed_buff;
for (i=0; i<nbChunks; i++)
{
chunkP[i].id = i;
chunkP[i].origBuffer = in; in += chunkSize;
if ((int)remaining > chunkSize) { chunkP[i].origSize = chunkSize; remaining -= chunkSize; } else { chunkP[i].origSize = (int)remaining; remaining = 0; }
chunkP[i].compressedBuffer = out; out += maxCompressedChunkSize;
chunkP[i].compressedSize = 0;
}
}
DISPLAY("Loading %s... \r", inFileName);
readSize = fread(orig_buff, 1, benchedSize, inFile);
fclose(inFile);
if(readSize != benchedSize)
{
DISPLAY("\nError: problem reading file '%s' !! \n", inFileName);
free(orig_buff);
free(compressed_buff);
free(chunkP);
return 13;
}
crcOriginal = XXH32(orig_buff, (unsigned int)benchedSize,0);
{
int loopNb, nb_loops, chunkNb, cAlgNb, dAlgNb;
size_t cSize=0;
double ratio=0.;
DISPLAY("\r%79s\r", "");
DISPLAY(" %s : \n", inFileName);
for (cAlgNb=1; (cAlgNb <= NB_COMPRESSION_ALGORITHMS) && (compressionTest); cAlgNb++)
{
char* compressorName;
int (*compressionFunction)(const char*, char*, int);
void* (*initFunction)(const char*) = NULL;
double bestTime = 100000000.;
if ((compressionAlgo != ALL_COMPRESSORS) && (compressionAlgo != cAlgNb)) continue;
switch(cAlgNb)
{
case 1 : compressionFunction = LZ4_compress; compressorName = "LZ4_compress"; break;
case 2 : compressionFunction = local_LZ4_compress_limitedOutput; compressorName = "LZ4_compress_limitedOutput"; break;
case 3 : compressionFunction = local_LZ4_compress_withState; compressorName = "LZ4_compress_withState"; break;
case 4 : compressionFunction = local_LZ4_compress_limitedOutput_withState; compressorName = "LZ4_compress_limitedOutput_withState"; break;
case 5 : compressionFunction = local_LZ4_compress_continue; initFunction = LZ4_create; compressorName = "LZ4_compress_continue"; break;
case 6 : compressionFunction = local_LZ4_compress_limitedOutput_continue; initFunction = LZ4_create; compressorName = "LZ4_compress_limitedOutput_continue"; break;
case 7 : compressionFunction = LZ4_compressHC; compressorName = "LZ4_compressHC"; break;
case 8 : compressionFunction = local_LZ4_compressHC_limitedOutput; compressorName = "LZ4_compressHC_limitedOutput"; break;
case 9 : compressionFunction = local_LZ4_compressHC_withStateHC; compressorName = "LZ4_compressHC_withStateHC"; break;
case 10: compressionFunction = local_LZ4_compressHC_limitedOutput_withStateHC; compressorName = "LZ4_compressHC_limitedOutput_withStateHC"; break;
case 11: compressionFunction = local_LZ4_compressHC_continue; initFunction = LZ4_createHC; compressorName = "LZ4_compressHC_continue"; break;
case 12: compressionFunction = local_LZ4_compressHC_limitedOutput_continue; initFunction = LZ4_createHC; compressorName = "LZ4_compressHC_limitedOutput_continue"; break;
case 13: compressionFunction = local_LZ4_compress_forceDict; initFunction = local_LZ4_resetDictT; compressorName = "LZ4_compress_forceDict"; break;
default : DISPLAY("ERROR ! Bad algorithm Id !! \n"); free(chunkP); return 1;
}
for (loopNb = 1; loopNb <= nbIterations; loopNb++)
{
double averageTime;
int milliTime;
PROGRESS("%1i-%-26.26s : %9i ->\r", loopNb, compressorName, (int)benchedSize);
{ size_t i; for (i=0; i<benchedSize; i++) compressed_buff[i]=(char)i; }
nb_loops = 0;
milliTime = BMK_GetMilliStart();
while(BMK_GetMilliStart() == milliTime);
milliTime = BMK_GetMilliStart();
while(BMK_GetMilliSpan(milliTime) < TIMELOOP)
{
if (initFunction!=NULL) ctx = initFunction(chunkP[0].origBuffer);
for (chunkNb=0; chunkNb<nbChunks; chunkNb++)
{
chunkP[chunkNb].compressedSize = compressionFunction(chunkP[chunkNb].origBuffer, chunkP[chunkNb].compressedBuffer, chunkP[chunkNb].origSize);
if (chunkP[chunkNb].compressedSize==0) DISPLAY("ERROR ! %s() = 0 !! \n", compressorName), exit(1);
}
if (initFunction!=NULL) free(ctx);
nb_loops++;
}
milliTime = BMK_GetMilliSpan(milliTime);
averageTime = (double)milliTime / nb_loops;
if (averageTime < bestTime) bestTime = averageTime;
cSize=0; for (chunkNb=0; chunkNb<nbChunks; chunkNb++) cSize += chunkP[chunkNb].compressedSize;
ratio = (double)cSize/(double)benchedSize*100.;
PROGRESS("%1i-%-26.26s : %9i -> %9i (%5.2f%%),%7.1f MB/s\r", loopNb, compressorName, (int)benchedSize, (int)cSize, ratio, (double)benchedSize / bestTime / 1000.);
}
if (ratio<100.)
DISPLAY("%-28.28s : %9i -> %9i (%5.2f%%),%7.1f MB/s\n", compressorName, (int)benchedSize, (int)cSize, ratio, (double)benchedSize / bestTime / 1000.);
else
DISPLAY("%-28.28s : %9i -> %9i (%5.1f%%),%7.1f MB/s\n", compressorName, (int)benchedSize, (int)cSize, ratio, (double)benchedSize / bestTime / 1000.);
totalCTime[cAlgNb] += bestTime;
totalCSize[cAlgNb] += cSize;
}
for (chunkNb=0; chunkNb<nbChunks; chunkNb++)
{
chunkP[chunkNb].compressedSize = LZ4_compress(chunkP[chunkNb].origBuffer, chunkP[chunkNb].compressedBuffer, chunkP[chunkNb].origSize);
if (chunkP[chunkNb].compressedSize==0) DISPLAY("ERROR ! %s() = 0 !! \n", "LZ4_compress"), exit(1);
}
{ size_t i; for (i=0; i<benchedSize; i++) orig_buff[i]=0; }
for (dAlgNb=0; (dAlgNb < NB_DECOMPRESSION_ALGORITHMS) && (decompressionTest); dAlgNb++)
{
char* dName = decompressionNames[dAlgNb];
int (*decompressionFunction)(const char*, char*, int, int);
double bestTime = 100000000.;
if ((decompressionAlgo != ALL_DECOMPRESSORS) && (decompressionAlgo != dAlgNb+1)) continue;
switch(dAlgNb)
{
case 0: decompressionFunction = local_LZ4_decompress_fast; break;
case 1: decompressionFunction = local_LZ4_decompress_fast_withPrefix64k; break;
case 2: decompressionFunction = local_LZ4_decompress_fast_usingDict; break;
case 3: decompressionFunction = LZ4_decompress_safe; break;
case 4: decompressionFunction = LZ4_decompress_safe_withPrefix64k; break;
case 5: decompressionFunction = local_LZ4_decompress_safe_usingDict; break;
case 6: decompressionFunction = local_LZ4_decompress_safe_partial; break;
default : DISPLAY("ERROR ! Bad decompression algorithm Id !! \n"); free(chunkP); return 1;
}
for (loopNb = 1; loopNb <= nbIterations; loopNb++)
{
double averageTime;
int milliTime;
U32 crcDecoded;
PROGRESS("%1i-%-29.29s :%10i ->\r", loopNb, dName, (int)benchedSize);
nb_loops = 0;
milliTime = BMK_GetMilliStart();
while(BMK_GetMilliStart() == milliTime);
milliTime = BMK_GetMilliStart();
while(BMK_GetMilliSpan(milliTime) < TIMELOOP)
{
for (chunkNb=0; chunkNb<nbChunks; chunkNb++)
{
int decodedSize = decompressionFunction(chunkP[chunkNb].compressedBuffer, chunkP[chunkNb].origBuffer, chunkP[chunkNb].compressedSize, chunkP[chunkNb].origSize);
if (chunkP[chunkNb].origSize != decodedSize) DISPLAY("ERROR ! %s() == %i != %i !! \n", dName, decodedSize, chunkP[chunkNb].origSize), exit(1);
}
nb_loops++;
}
milliTime = BMK_GetMilliSpan(milliTime);
averageTime = (double)milliTime / nb_loops;
if (averageTime < bestTime) bestTime = averageTime;
PROGRESS("%1i-%-29.29s :%10i -> %7.1f MB/s\r", loopNb, dName, (int)benchedSize, (double)benchedSize / bestTime / 1000.);
crcDecoded = XXH32(orig_buff, (int)benchedSize, 0);
if (crcOriginal!=crcDecoded) { DISPLAY("\n!!! WARNING !!! %14s : Invalid Checksum : %x != %x\n", inFileName, (unsigned)crcOriginal, (unsigned)crcDecoded); exit(1); }
}
DISPLAY("%-31.31s :%10i -> %7.1f MB/s\n", dName, (int)benchedSize, (double)benchedSize / bestTime / 1000.);
totalDTime[dAlgNb] += bestTime;
}
totals += benchedSize;
}
free(orig_buff);
free(compressed_buff);
free(chunkP);
}
if (BMK_pause) { printf("press enter...\n"); getchar(); }
return 0;
},1

MagickExport MagickBooleanType PasskeyEncipherImage(Image *image,
const StringInfo *passkey,ExceptionInfo *exception)
{
#define EncipherImageTag "Encipher/Image "
AESInfo
*aes_info;
CacheView
*image_view;
char
*signature;
const unsigned char
*digest;
MagickBooleanType
proceed;
MagickSizeType
extent;
QuantumInfo
*quantum_info;
QuantumType
quantum_type;
unsigned char
*p;
SignatureInfo
*signature_info;
size_t
length;
ssize_t
y;
StringInfo
*key,
*nonce;
unsigned char
input_block[AESBlocksize],
output_block[AESBlocksize],
*pixels;
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
if (passkey == (const StringInfo *) NULL)
return(MagickTrue);
if (SetImageStorageClass(image,DirectClass,exception) == MagickFalse)
return(MagickFalse);
aes_info=AcquireAESInfo();
key=CloneStringInfo(passkey);
if (key == (StringInfo *) NULL)
{
aes_info=DestroyAESInfo(aes_info);
ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
image->filename);
}
nonce=SplitStringInfo(key,GetStringInfoLength(key)/2);
if (nonce == (StringInfo *) NULL)
{
key=DestroyStringInfo(key);
aes_info=DestroyAESInfo(aes_info);
ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
image->filename);
}
SetAESKey(aes_info,key);
key=DestroyStringInfo(key);
signature_info=AcquireSignatureInfo();
UpdateSignature(signature_info,nonce);
extent=(MagickSizeType) image->columns*image->rows;
SetStringInfoLength(nonce,sizeof(extent));
SetStringInfoDatum(nonce,(const unsigned char *) &extent);
UpdateSignature(signature_info,nonce);
nonce=DestroyStringInfo(nonce);
FinalizeSignature(signature_info);
signature=StringInfoToHexString(GetSignatureDigest(signature_info));
(void) SetImageProperty(image,"cipher:type","AES",exception);
(void) SetImageProperty(image,"cipher:mode","CTR",exception);
(void) SetImageProperty(image,"cipher:nonce",signature,exception);
signature=DestroyString(signature);
(void) memset(input_block,0,sizeof(input_block));
digest=GetStringInfoDatum(GetSignatureDigest(signature_info));
(void) memcpy(input_block,digest,MagickMin(AESBlocksize,
GetSignatureDigestsize(signature_info))*sizeof(*input_block));
signature_info=DestroySignatureInfo(signature_info);
quantum_info=AcquireQuantumInfo((const ImageInfo *) NULL,image);
if (quantum_info == (QuantumInfo *) NULL)
{
aes_info=DestroyAESInfo(aes_info);
ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
image->filename);
}
quantum_type=GetQuantumType(image,exception);
pixels=(unsigned char *) GetQuantumPixels(quantum_info);
image_view=AcquireAuthenticCacheView(image,exception);
for (y=0; y < (ssize_t) image->rows; y++)
{
ssize_t
i,
x;
Quantum
*magick_restrict q;
q=GetCacheViewAuthenticPixels(image_view,0,y,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
length=ExportQuantumPixels(image,image_view,quantum_info,quantum_type,
pixels,exception);
p=pixels;
for (x=0; x < (ssize_t) length; x+=AESBlocksize)
{
(void) memcpy(output_block,input_block,AESBlocksize*
sizeof(*output_block));
IncrementCipherNonce(AESBlocksize,input_block);
EncipherAESBlock(aes_info,output_block,output_block);
for (i=0; i < AESBlocksize; i++)
p[i]^=output_block[i];
p+=AESBlocksize;
}
(void) memcpy(output_block,input_block,AESBlocksize*
sizeof(*output_block));
EncipherAESBlock(aes_info,output_block,output_block);
for (i=0; x < (ssize_t) length; x++)
{
p[i]^=output_block[i];
i++;
}
(void) ImportQuantumPixels(image,image_view,quantum_info,quantum_type,
pixels,exception);
if (SyncCacheViewAuthenticPixels(image_view,exception) == MagickFalse)
break;
proceed=SetImageProgress(image,EncipherImageTag,(MagickOffsetType) y,
image->rows);
if (proceed == MagickFalse)
break;
}
image_view=DestroyCacheView(image_view);
image->taint=MagickFalse;
quantum_info=DestroyQuantumInfo(quantum_info);
aes_info=DestroyAESInfo(aes_info);
(void) memset(input_block,0,sizeof(input_block));
(void) memset(output_block,0,sizeof(output_block));
return(y == (ssize_t) image->rows ? MagickTrue : MagickFalse);
},1

void do_tune(void)
{
struct VOICE_S *p_voice;
struct SYMBOL *s, *s1, *s2;
int i;
lvlarena(0);
nstaff = 0;
staves_found = -1;
for (i = 0; i < MAXVOICE; i++) {
p_voice = &voice_tb[i];
s1 = (struct SYMBOL *) getarena(sizeof *s1);
memset(s1, 0, sizeof *s1);
s1->type = CLEF;
s1->voice = i;
if (cfmt.autoclef) {
s1->u.clef.type = AUTOCLEF;
s1->sflags = S_CLEF_AUTO;
} else {
s1->u.clef.type = TREBLE;
}
s1->u.clef.line = 2;
p_voice->s_clef = s1;
p_voice->meter.wmeasure = 1;
p_voice->wmeasure = 1;
p_voice->scale = 1;
p_voice->clone = -1;
p_voice->over = -1;
p_voice->posit = cfmt.posit;
p_voice->stafflines = NULL;
}
curvoice = first_voice = voice_tb;
reset_deco();
abc2win = 0;
clip_start.bar = -1;
clip_end.bar = (short unsigned) ~0 >> 1;
parsys = NULL;
system_new();
parsys->top_voice = parsys->voice[0].range = 0;
if (!epsf) {
#if 1
use_buffer = 0;
#else
if (cfmt.oneperpage) {
use_buffer = 0;
close_page();
} else {
if (in_page)
use_buffer = cfmt.splittune != 1;
}
#endif
} else {
use_buffer = 1;
marg_init();
}
for (s = parse.first_sym; s; s = s->abc_next) {
switch (s->abc_type) {
case ABC_T_EOLN:
if (s->u.eoln.type == 2)
abc2win = 1;
break;
case ABC_T_NOTE:
case ABC_T_REST:
s1 = s;
s1->dur = s1->u.note.notes[0].len;
break;
}
}
if (voice_tb[0].id[0] == '\0') {
voice_tb[0].id[0] = '1';
voice_tb[0].id[1] = '\0';
}
for (s = parse.first_sym; s; s = s->abc_next) {
s1 = s;
if (s->flags & ABC_F_LYRIC_START)
curvoice->lyric_start = curvoice->last_sym;
switch (s->abc_type) {
case ABC_T_INFO:
s = get_info(s);
break;
case ABC_T_PSCOM:
s = process_pscomment(s);
break;
case ABC_T_NOTE:
case ABC_T_REST:
if (curvoice->space
&& !(s->flags & ABC_F_GRACE)) {
curvoice->space = 0;
s1->flags |= ABC_F_SPACE;
}
get_note(s1);
break;
case ABC_T_BAR:
if (over_bar)
get_over(s1);
get_bar(s1);
break;
case ABC_T_CLEF:
get_clef(s1);
break;
case ABC_T_EOLN:
if (cfmt.breakoneoln
|| (s->flags & ABC_F_SPACE))
curvoice->space = 1;
if (cfmt.continueall || cfmt.barsperstaff
|| s->u.eoln.type == 1)
continue;
if (s->u.eoln.type == 0
&& abc2win
&& parse.abc_vers != (2 << 16))
continue;
if (parsys->voice[curvoice - voice_tb].range == 0
&& curvoice->last_sym)
curvoice->last_sym->sflags |= S_EOLN;
if (!cfmt.alignbars)
continue;
while (s->abc_next) {
if (s->abc_next->abc_type != ABC_T_INFO)
break;
switch (s->abc_next->text[0]) {
case 'w':
s = get_info(s->abc_next);
s1 = s;
continue;
case 'd':
case 's':
s = s->abc_next;
s1 = s;
continue;
}
break;
}
i = (curvoice - voice_tb) + 1;
if (i < cfmt.alignbars) {
curvoice = &voice_tb[i];
continue;
}
generate();
buffer_eob(0);
curvoice = &voice_tb[0];
continue;
case ABC_T_MREST: {
int dur;
dur = curvoice->wmeasure * s->u.bar.len;
if (curvoice->second) {
curvoice->time += dur;
break;
}
sym_link(s1, MREST);
s->dur = dur;
curvoice->time += dur;
if (s1->text)
gch_build(s1);
if (s1->u.bar.dc.n > 0)
deco_cnv(&s1->u.bar.dc, s, NULL);
break;
}
case ABC_T_MREP: {
int n;
if (!s->abc_next || s->abc_next->abc_type != ABC_T_BAR) {
error(1, s1,
"Measure repeat not followed by a bar");
break;
}
if (curvoice->ignore)
break;
n = s->u.bar.len;
if (curvoice->second) {
curvoice->time += curvoice->wmeasure * n;
break;
}
s2 = sym_add(curvoice, NOTEREST);
s2->abc_type = ABC_T_REST;
s2->flags |= ABC_F_INVIS;
