void __init mnt_init(void)
{
unsigned u;
int err;
mnt_cache = kmem_cache_create("mnt_cache", sizeof(struct mount),
0, SLAB_HWCACHE_ALIGN | SLAB_PANIC, NULL);
mount_hashtable = alloc_large_system_hash("Mount-cache",
sizeof(struct hlist_head),
mhash_entries, 19,
0,
&m_hash_shift, &m_hash_mask, 0, 0);
mountpoint_hashtable = alloc_large_system_hash("Mountpoint-cache",
sizeof(struct hlist_head),
mphash_entries, 19,
0,
&mp_hash_shift, &mp_hash_mask, 0, 0);
if (!mount_hashtable || !mountpoint_hashtable)
panic("Failed to allocate mount hash table\n");
for (u = 0; u <= m_hash_mask; u++)
INIT_HLIST_HEAD(&mount_hashtable[u]);
for (u = 0; u <= mp_hash_mask; u++)
INIT_HLIST_HEAD(&mountpoint_hashtable[u]);
kernfs_init();
err = sysfs_init();
if (err)
printk(KERN_WARNING "%s: sysfs_init error: %d\n",
__func__, err);
fs_kobj = kobject_create_and_add("fs", NULL);
if (!fs_kobj)
printk(KERN_WARNING "%s: kobj create error\n", __func__);
init_rootfs();
init_mount_tree();
},0

tiffsep1_print_page(gx_device_printer * pdev, gp_file * file)
{
tiffsep1_device * const tfdev = (tiffsep1_device *)pdev;
int num_std_colorants = tfdev->devn_params.num_std_colorant_names;
int num_order = tfdev->devn_params.num_separation_order_names;
int num_spot = tfdev->devn_params.separations.num_separations;
int num_comp, comp_num, code = 0, code1 = 0;
short map_comp_to_sep[GX_DEVICE_COLOR_MAX_COMPONENTS];
char *name = NULL;
int save_depth = pdev->color_info.depth;
int save_numcomps = pdev->color_info.num_components;
const char *fmt;
gs_parsed_file_name_t parsed;
int non_encodable_count = 0;
if (tfdev->thresholds[0].dstart == NULL)
return_error(gs_error_rangecheck);
name = (char *)gs_alloc_bytes(pdev->memory, gp_file_name_sizeof, "tiffsep1_print_page(name)");
if (!name)
return_error(gs_error_VMerror);
build_comp_to_sep_map((tiffsep_device *)tfdev, map_comp_to_sep);
code = gx_parse_output_file_name(&parsed, &fmt, tfdev->fname,
strlen(tfdev->fname), pdev->memory);
if (code < 0 || (fmt == NULL && tfdev->PageCount > 0)) {
emprintf(tfdev->memory,
"\nUse of the %%d format is required to output more than one page to tiffsep1.\n"
"See doc/Devices.htm#TIFF for details.\n\n");
code = gs_note_error(gs_error_ioerror);
}
if (pdev->file != NULL && parsed.iodev == iodev_default(pdev->memory) && fmt) {
long count1 = pdev->PageCount;
char *compname = (char *)gs_alloc_bytes(pdev->memory, gp_file_name_sizeof, "tiffsep1_print_page(compname)");
if (!compname) {
code = gs_note_error(gs_error_VMerror);
goto done;
}
gx_device_close_output_file((gx_device *)pdev, pdev->fname, pdev->file);
pdev->file = NULL;
while (*fmt != 'l' && *fmt != '%')
--fmt;
if (*fmt == 'l')
gs_sprintf(compname, parsed.fname, count1);
else
gs_sprintf(compname, parsed.fname, (int)count1);
parsed.iodev->procs.delete_file(parsed.iodev, compname);
code = gdev_prn_open_printer((gx_device *)pdev, 1);
gs_free_object(pdev->memory, compname, "tiffsep_print_page(compname)");
if (code < 0) {
goto done;
}
}
num_comp = number_output_separations( tfdev->color_info.num_components,
num_std_colorants, num_order, num_spot);
for (comp_num = 0; comp_num < num_comp; comp_num++ ) {
int sep_num = map_comp_to_sep[comp_num];
code = create_separation_file_name((tiffsep_device *)tfdev, name,
gp_file_name_sizeof, sep_num, true);
if (code < 0) {
goto done;
}
if (tfdev->sep_file[comp_num] == NULL) {
code = gs_add_outputfile_control_path(tfdev->memory, name);
if (code < 0) {
goto done;
}
code = gx_device_open_output_file((gx_device *)pdev, name,
true, true, &(tfdev->sep_file[comp_num]));
if (code < 0) {
goto done;
}
tfdev->tiff[comp_num] = tiff_from_filep(pdev, name,
tfdev->sep_file[comp_num],
tfdev->BigEndian, tfdev->UseBigTIFF);
if (!tfdev->tiff[comp_num]) {
code = gs_note_error(gs_error_ioerror);
goto done;
}
}
pdev->color_info.depth = 8;
pdev->color_info.num_components = 1;
code = tiff_set_fields_for_printer(pdev, tfdev->tiff[comp_num], 1, 0, tfdev->write_datetime);
tiff_set_gray_fields(pdev, tfdev->tiff[comp_num], 1, tfdev->Compression, tfdev->MaxStripSize);
pdev->color_info.depth = save_depth;
pdev->color_info.num_components = save_numcomps;
if (code < 0) {
goto done;
}
}
{
byte *planes[GS_CLIENT_COLOR_MAX_COMPONENTS];
int width = tfdev->width;
int raster_plane = bitmap_raster(width * 8);
int dithered_raster = ((7 + width) / 8) + ARCH_SIZEOF_LONG;
int pixel, y;
gs_get_bits_params_t params;
gs_int_rect rect;
uint32_t *dithered_line = (uint32_t *)gs_alloc_bytes(pdev->memory, dithered_raster,
"tiffsep1_print_page");
memset(planes, 0, sizeof(*planes) * GS_CLIENT_COLOR_MAX_COMPONENTS);
params.options = (GB_RETURN_POINTER | GB_RETURN_COPY |
GB_ALIGN_STANDARD | GB_OFFSET_0 | GB_RASTER_STANDARD |
GB_PACKING_PLANAR | GB_COLORS_NATIVE | GB_ALPHA_NONE);
params.x_offset = 0;
params.raster = bitmap_raster(width * pdev->color_info.depth);
code = 0;
for (comp_num = 0; comp_num < num_comp; comp_num++) {
planes[comp_num] = gs_alloc_bytes(pdev->memory, raster_plane,
"tiffsep1_print_page");
if (planes[comp_num] == NULL) {
code = gs_error_VMerror;
break;
}
}
if (code < 0 || dithered_line == NULL) {
code = gs_note_error(gs_error_VMerror);
goto cleanup;
}
for (comp_num = 0; comp_num < num_comp; comp_num++ )
TIFFCheckpointDirectory(tfdev->tiff[comp_num]);
rect.p.x = 0;
rect.q.x = pdev->width;
for (y = 0; y < pdev->height; ++y) {
rect.p.y = y;
rect.q.y = y + 1;
for (comp_num = 0; comp_num < num_comp; comp_num++)
params.data[comp_num] = planes[comp_num];
code = (*dev_proc(pdev, get_bits_rectangle))((gx_device *)pdev, &rect, &params, NULL);
if (code < 0)
break;
for (comp_num = 0; comp_num < num_comp; comp_num++ ) {
#ifndef SKIP_HALFTONING_FOR_TIMING
#define USE_32_BIT_WRITES
byte *thresh_line_base = tfdev->thresholds[comp_num].dstart +
((y % tfdev->thresholds[comp_num].dheight) *
tfdev->thresholds[comp_num].dwidth) ;
byte *thresh_ptr = thresh_line_base;
byte *thresh_limit = thresh_ptr + tfdev->thresholds[comp_num].dwidth;
byte *src = params.data[comp_num];
#ifdef USE_32_BIT_WRITES
uint32_t *dest = dithered_line;
uint32_t val = 0;
const uint32_t *mask = &bit_order[0];
#else
byte *dest = dithered_line;
byte val = 0;
byte mask = 0x80;
#endif
for (pixel = 0; pixel < width; pixel++, src++) {
#ifdef USE_32_BIT_WRITES
if (*src < *thresh_ptr++)
val |= *mask;
if (++mask == &(bit_order[32])) {
*dest++ = val;
val = 0;
mask = &bit_order[0];
}
#else
if (*src < *thresh_ptr++)
val |= mask;
mask >>= 1;
if (mask == 0) {
*dest++ = val;
val = 0;
mask = 0x80;
}
#endif
if (thresh_ptr >= thresh_limit)
thresh_ptr = thresh_line_base;
}
#ifdef USE_32_BIT_WRITES
if (mask != &bit_order[0]) {
*dest = val;
}
#else
if (mask != 0x80) {
*dest = val;
}
#endif
#endif
TIFFWriteScanline(tfdev->tiff[comp_num], (tdata_t)dithered_line, y, 0);
}
}
for (comp_num = 0; comp_num < num_comp; comp_num++ ) {
TIFFWriteDirectory(tfdev->tiff[comp_num]);
if (fmt) {
int sep_num = map_comp_to_sep[comp_num];
code = create_separation_file_name((tiffsep_device *)tfdev, name, gp_file_name_sizeof, sep_num, false);
if (code < 0) {
code1 = code;
continue;
}
code = tiffsep_close_sep_file((tiffsep_device *)tfdev, name, comp_num);
if (code >= 0)
code = gs_remove_outputfile_control_path(tfdev->memory, name);
if (code < 0) {
code1 = code;
}
}
}
code = code1;
cleanup:
gs_free_object(pdev->memory, dithered_line, "tiffsep1_print_page");
for (comp_num = 0; comp_num < num_comp; comp_num++) {
gs_free_object(pdev->memory, planes[comp_num], "tiffsep1_print_page");
}
}
if (non_encodable_count) {
dmlprintf1(pdev->memory, "WARNING: Non encodable pixels = %d\n", non_encodable_count);
code = gs_note_error(gs_error_rangecheck);
}
done:
if (name)
gs_free_object(pdev->memory, name, "tiffsep1_print_page(name)");
return code;
},1

image_render_color_thresh(gx_image_enum *penum_orig, const byte *buffer, int data_x,
uint w, int h, gx_device * dev)
{
gx_image_enum *penum = penum_orig;
image_posture posture = penum->posture;
int vdi;
fixed xrun = 0;
byte *thresh_align;
byte *devc_contone[GX_DEVICE_COLOR_MAX_COMPONENTS];
byte *psrc_plane[GX_DEVICE_COLOR_MAX_COMPONENTS];
byte *devc_contone_gray;
const byte *psrc = buffer + data_x;
int dest_width, dest_height, data_length;
int spp_out = dev->color_info.num_components;
int position, i, j, k;
int offset_bits = penum->ht_offset_bits;
int contone_stride = 0;
fixed offset;
int src_size;
bool flush_buff = false;
byte *psrc_temp;
int offset_contone[GX_DEVICE_COLOR_MAX_COMPONENTS];
int offset_threshold;
gx_dda_fixed dda_ht;
int xn, xr;
int code = 0;
int spp_cm = 0;
byte *psrc_cm = NULL, *psrc_cm_start = NULL;
byte *bufend = NULL;
int psrc_planestride = w/penum->spp;
if (h != 0 && penum->line_size != 0) {
code = image_color_icc_prep(penum, psrc, w, dev, &spp_cm, &psrc_cm,
&psrc_cm_start, &bufend, true);
if (code < 0)
return code;
} else {
if (penum->ht_landscape.count == 0 || posture == image_portrait) {
return 0;
} else {
offset_bits = penum->ht_landscape.count;
penum->ht_offset_bits = offset_bits;
penum->ht_landscape.offset_set = true;
flush_buff = true;
}
}
src_size = penum->rect.w;
dda_ht = (posture == image_portrait) ? penum->dda.pixel0.x : penum->dda.pixel0.y;
if (penum->dxx > 0)
dda_translate(dda_ht, -fixed_epsilon);
switch (posture) {
case image_portrait:
xrun = dda_current(dda_ht);
dest_width = gxht_dda_length(&dda_ht, src_size);
if (penum->x_extent.x < 0)
xrun += penum->x_extent.x;
vdi = penum->hci;
contone_stride = penum->line_size;
offset_threshold = (- (((long)(penum->thresh_buffer)) +
penum->ht_offset_bits)) & 15;
for (k = 0; k < spp_out; k ++) {
offset_contone[k] = (- (((long)(penum->line)) +
contone_stride * k +
penum->ht_offset_bits)) & 15;
}
data_length = dest_width;
dest_height = fixed2int_var_rounded(any_abs(penum->y_extent.y));
#ifdef DEBUG
memset(penum->ht_buffer, 0x00, penum->ht_stride * vdi * spp_out);
#endif
break;
case image_landscape:
default:
vdi = penum->wci;
contone_stride = penum->line_size;
dest_width = fixed2int_var_rounded(any_abs(penum->y_extent.x));
xrun = dda_current(dda_ht);
dest_height = gxht_dda_length(&dda_ht, src_size);
data_length = dest_height;
offset_threshold = (-(long)(penum->thresh_buffer)) & 15;
for (k = 0; k < spp_out; k ++) {
offset_contone[k] = (- ((long)(penum->line) +
contone_stride * k)) & 15;
}
if (penum->ht_landscape.count == 0) {
penum->ht_landscape.offset_set = true;
if (penum->ht_landscape.index < 0) {
penum->ht_landscape.xstart = penum->xci + vdi - 1;
offset_bits = (penum->ht_landscape.xstart % 16) + 1;
if (offset_bits <= 0) offset_bits += 16;
} else {
penum->ht_landscape.xstart = penum->xci;
offset_bits = 16 - penum->xci % 16;
if (offset_bits >= 16) offset_bits -= 16;
}
if (offset_bits == 0 || offset_bits == 16) {
penum->ht_landscape.offset_set = false;
penum->ht_offset_bits = 0;
} else {
penum->ht_offset_bits = offset_bits;
}
}
break;
}
if (flush_buff)
goto flush;
for (k = 0; k < spp_out; k++) {
if (posture == image_portrait) {
devc_contone[k] = penum->line + contone_stride * k +
offset_contone[k];
} else {
devc_contone[k] = penum->line + offset_contone[k] +
LAND_BITS * k * contone_stride;
}
psrc_plane[k] = psrc_cm + psrc_planestride * k;
}
xr = fixed2int_var_rounded(dda_current(dda_ht));
switch (spp_out)
{
case 1:
devc_contone_gray = devc_contone[0];
switch (posture) {
case image_portrait:
if (penum->dst_width > 0) {
if (src_size == dest_width) {
memcpy(devc_contone_gray, psrc_cm, data_length);
} else if (src_size * 2 == dest_width) {
psrc_temp = psrc_cm;
for (k = 0; k < data_length; k+=2,
devc_contone_gray+=2, psrc_temp++) {
*devc_contone_gray =
*(devc_contone_gray+1) = *psrc_temp;
}
} else {
psrc_temp = psrc_cm;
for (k=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr < xn) {
*devc_contone_gray++ = *psrc_temp;
xr++;
}
psrc_temp++;
}
}
} else {
devc_contone_gray += (data_length - 1);
psrc_temp = psrc_cm;
for (k=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr > xn) {
*devc_contone_gray-- = *psrc_temp;
xr--;
}
psrc_temp++;
}
}
break;
case image_landscape:
if (penum->ht_landscape.flipy) {
position = penum->ht_landscape.curr_pos +
LAND_BITS * (data_length - 1);
psrc_temp = psrc_cm;
for (k=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr > xn) {
devc_contone_gray[position] = *psrc_temp;
position -= LAND_BITS;
xr--;
}
psrc_temp++;
}
} else {
position = penum->ht_landscape.curr_pos;
if (src_size == dest_height) {
for (k = 0; k < data_length; k++) {
devc_contone_gray[position] = psrc_cm[k];
position += LAND_BITS;
}
} else if (src_size*2 == dest_height) {
for (k = 0; k < data_length; k+=2) {
offset = fixed2int_var_rounded(fixed_half * k);
devc_contone_gray[position] =
devc_contone_gray[position + LAND_BITS] =
psrc_cm[offset];
position += 2*LAND_BITS;
}
} else {
psrc_temp = psrc_cm;
for (k=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr < xn) {
devc_contone_gray[position] = *psrc_temp;
position += LAND_BITS;
xr++;
}
psrc_temp++;
}
}
}
penum->ht_landscape.count += vdi;
penum->ht_landscape.widths[penum->ht_landscape.curr_pos] = vdi;
penum->ht_landscape.curr_pos += penum->ht_landscape.index;
penum->ht_landscape.num_contones++;
break;
default:
break;
}
break;
case 4:
switch (posture) {
case image_portrait:
if (penum->dst_width > 0) {
if (src_size == dest_width) {
memcpy(devc_contone[0], psrc_plane[0], data_length);
memcpy(devc_contone[1], psrc_plane[1], data_length);
memcpy(devc_contone[2], psrc_plane[2], data_length);
memcpy(devc_contone[3], psrc_plane[3], data_length);
} else if (src_size * 2 == dest_width) {
for (k = 0; k < data_length; k+=2) {
*(devc_contone[0]) = *(devc_contone[0]+1) =
*psrc_plane[0]++;
*(devc_contone[1]) = *(devc_contone[1]+1) =
*psrc_plane[1]++;
*(devc_contone[2]) = *(devc_contone[2]+1) =
*psrc_plane[2]++;
*(devc_contone[3]) = *(devc_contone[3]+1) =
*psrc_plane[3]++;
devc_contone[0] += 2;
devc_contone[1] += 2;
devc_contone[2] += 2;
devc_contone[3] += 2;
}
} else {
for (k=0, j=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr < xn) {
*(devc_contone[0])++ = (psrc_plane[0])[j];
*(devc_contone[1])++ = (psrc_plane[1])[j];
*(devc_contone[2])++ = (psrc_plane[2])[j];
*(devc_contone[3])++ = (psrc_plane[3])[j];
xr++;
}
j++;
}
}
} else {
devc_contone[0] += (data_length - 1);
devc_contone[1] += (data_length - 1);
devc_contone[2] += (data_length - 1);
devc_contone[3] += (data_length - 1);
for (k=0, j=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr > xn) {
*(devc_contone[0])-- = (psrc_plane[0])[j];
*(devc_contone[1])-- = (psrc_plane[1])[j];
*(devc_contone[2])-- = (psrc_plane[2])[j];
*(devc_contone[3])-- = (psrc_plane[3])[j];
xr--;
}
j++;
}
}
break;
case image_landscape:
if (penum->ht_landscape.flipy) {
position = penum->ht_landscape.curr_pos +
LAND_BITS * (data_length - 1);
for (k=0, i=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr > xn) {
for (j = 0; j < spp_out; j++) {
*(devc_contone[j] + position) = (psrc_plane[j])[i];
position -= LAND_BITS;
}
xr--;
}
i++;
}
} else {
position = penum->ht_landscape.curr_pos;
for (k = 0; k < spp_out; k++) {
devc_contone[k] = devc_contone[k] + position;
}
if (src_size == dest_height) {
for (k = 0; k < data_length; k++) {
for (j = 0; j < spp_out; j++) {
*(devc_contone[j]) = (psrc_plane[j])[k];
devc_contone[j] += LAND_BITS;
}
}
} else if (src_size*2 == dest_height) {
for (k = 0; k < data_length; k+=2) {
offset = fixed2int_var_rounded(fixed_half * k);
for (j = 0; j < spp_out; j++) {
*(devc_contone[j]) =
*(devc_contone[j] + LAND_BITS) =
(psrc_plane[j])[offset];
devc_contone[j] += 2 * LAND_BITS;
}
}
} else {
for (k=0, i=0; k<src_size; k++) {
dda_next(dda_ht);
xn = fixed2int_var_rounded(dda_current(dda_ht));
while (xr > xn) {
for (j = 0; j < spp_out; j++) {
*(devc_contone[j] + position) = (psrc_plane[j])[i];
position -= LAND_BITS;
}
xr--;
}
i++;
}
}
}
penum->ht_landscape.count += vdi;
penum->ht_landscape.widths[penum->ht_landscape.curr_pos] = vdi;
penum->ht_landscape.curr_pos += penum->ht_landscape.index;
penum->ht_landscape.num_contones++;
break;
default:
break;
}
break;
default:
break;
}
flush:
thresh_align = penum->thresh_buffer + offset_threshold;
code = gxht_thresh_planes(penum, xrun, dest_width, dest_height,
thresh_align, dev, offset_contone,
contone_stride);
if (psrc_cm_start != NULL) {
gs_free_object(penum->pgs->memory, (byte *)psrc_cm_start,
"image_render_color_thresh");
}
return code;
