ConnectionExists(struct SessionHandle *data,
struct connectdata *needle,
struct connectdata **usethis,
bool *force_reuse)
{
struct connectdata *check;
struct connectdata *chosen = 0;
bool canPipeline = IsPipeliningPossible(data, needle);
bool wantNTLMhttp = ((data->state.authhost.want & CURLAUTH_NTLM) ||
(data->state.authhost.want & CURLAUTH_NTLM_WB)) &&
(needle->handler->protocol & PROTO_FAMILY_HTTP) ? TRUE : FALSE;
struct connectbundle *bundle;
*force_reuse = FALSE;
if(canPipeline && Curl_pipeline_site_blacklisted(data, needle)) {
canPipeline = FALSE;
}
bundle = Curl_conncache_find_bundle(needle, data->state.conn_cache);
if(bundle) {
size_t max_pipe_len = Curl_multi_max_pipeline_length(data->multi);
size_t best_pipe_len = max_pipe_len;
struct curl_llist_element *curr;
infof(data, "Found bundle for host %s: %p\n",
needle->host.name, (void *)bundle);
if(canPipeline && !bundle->server_supports_pipelining) {
infof(data, "Server doesn't support pipelining\n");
canPipeline = FALSE;
}
curr = bundle->conn_list->head;
while(curr) {
bool match = FALSE;
#if defined(USE_NTLM)
bool credentialsMatch = FALSE;
#endif
size_t pipeLen;
check = curr->ptr;
curr = curr->next;
if(disconnect_if_dead(check, data))
continue;
pipeLen = check->send_pipe->size + check->recv_pipe->size;
if(canPipeline) {
struct SessionHandle* sh = gethandleathead(check->send_pipe);
struct SessionHandle* rh = gethandleathead(check->recv_pipe);
if(sh) {
if(!IsPipeliningPossible(sh, check))
continue;
}
else if(rh) {
if(!IsPipeliningPossible(rh, check))
continue;
}
}
else {
if(pipeLen > 0) {
continue;
}
if(Curl_resolver_asynch()) {
if(!check->ip_addr_str[0]) {
infof(data,
"Connection #%ld is still name resolving, can't reuse\n",
check->connection_id);
continue;
}
}
if((check->sock[FIRSTSOCKET] == CURL_SOCKET_BAD) ||
check->bits.close) {
infof(data, "Connection #%ld isn't open enough, can't reuse\n",
check->connection_id);
#ifdef DEBUGBUILD
if(check->recv_pipe->size > 0) {
infof(data,
"BAD! Unconnected #%ld has a non-empty recv pipeline!\n",
check->connection_id);
}
#endif
continue;
}
}
if((needle->handler->flags&PROTOPT_SSL) !=
(check->handler->flags&PROTOPT_SSL))
if(!(needle->handler->protocol & check->handler->protocol))
continue;
if(needle->handler->flags&PROTOPT_SSL) {
if((data->set.ssl.verifypeer != check->verifypeer) ||
(data->set.ssl.verifyhost != check->verifyhost))
continue;
}
if(needle->bits.proxy != check->bits.proxy)
continue;
if(!canPipeline && check->inuse)
continue;
if(needle->localdev || needle->localport) {
if((check->localport != needle->localport) ||
(check->localportrange != needle->localportrange) ||
!check->localdev ||
!needle->localdev ||
strcmp(check->localdev, needle->localdev))
continue;
}
if((!(needle->handler->flags & PROTOPT_CREDSPERREQUEST)) ||
wantNTLMhttp) {
if(!strequal(needle->user, check->user) ||
!strequal(needle->passwd, check->passwd)) {
continue;
}
#if defined(USE_NTLM)
credentialsMatch = TRUE;
#endif
}
if(!needle->bits.httpproxy || needle->handler->flags&PROTOPT_SSL ||
(needle->bits.httpproxy && check->bits.httpproxy &&
needle->bits.tunnel_proxy && check->bits.tunnel_proxy &&
Curl_raw_equal(needle->proxy.name, check->proxy.name) &&
(needle->port == check->port))) {
if((Curl_raw_equal(needle->handler->scheme, check->handler->scheme) ||
needle->handler->protocol & check->handler->protocol) &&
Curl_raw_equal(needle->host.name, check->host.name) &&
needle->remote_port == check->remote_port) {
if(needle->handler->flags & PROTOPT_SSL) {
if(!Curl_ssl_config_matches(&needle->ssl_config,
&check->ssl_config)) {
DEBUGF(infof(data,
"Connection #%ld has different SSL parameters, "
"can't reuse\n",
check->connection_id));
continue;
}
else if(check->ssl[FIRSTSOCKET].state != ssl_connection_complete) {
DEBUGF(infof(data,
"Connection #%ld has not started SSL connect, "
"can't reuse\n",
check->connection_id));
continue;
}
}
match = TRUE;
}
}
else {
if(check->bits.proxy &&
(needle->proxytype == check->proxytype) &&
(needle->bits.tunnel_proxy == check->bits.tunnel_proxy) &&
Curl_raw_equal(needle->proxy.name, check->proxy.name) &&
needle->port == check->port) {
match = TRUE;
}
}
if(match) {
#if defined(USE_NTLM)
if(wantNTLMhttp) {
if(credentialsMatch && check->ntlm.state != NTLMSTATE_NONE) {
chosen = check;
*force_reuse = TRUE;
break;
}
else if(credentialsMatch)
chosen = check;
continue;
}
#endif
if(canPipeline) {
if(pipeLen == 0) {
chosen = check;
break;
}
if(pipeLen >= max_pipe_len)
continue;
if(Curl_pipeline_penalized(data, check))
continue;
if(pipeLen < best_pipe_len) {
chosen = check;
best_pipe_len = pipeLen;
continue;
}
}
else {
chosen = check;
break;
}
}
}
}
if(chosen) {
*usethis = chosen;
return TRUE;
}
return FALSE;
},1

int service_main(int argc __attribute__((unused)),
char **argv __attribute__((unused)),
char **envp __attribute__((unused)))
{
socklen_t salen;
char localip[60], remoteip[60];
char hbuf[NI_MAXHOST];
int niflags;
sasl_security_properties_t *secprops=NULL;
int shutdown;
char unavail[1024];
signals_poll();
sync_log_init();
nntp_in = prot_new(0, 0);
nntp_out = prot_new(1, 1);
protgroup_insert(protin, nntp_in);
salen = sizeof(nntp_remoteaddr);
if (getpeername(0, (struct sockaddr *)&nntp_remoteaddr, &salen) == 0 &&
(nntp_remoteaddr.ss_family == AF_INET ||
nntp_remoteaddr.ss_family == AF_INET6)) {
if (getnameinfo((struct sockaddr *)&nntp_remoteaddr, salen,
hbuf, sizeof(hbuf), NULL, 0, NI_NAMEREQD) == 0) {
strncpy(nntp_clienthost, hbuf, sizeof(hbuf));
strlcat(nntp_clienthost, " ", sizeof(nntp_clienthost));
nntp_clienthost[sizeof(nntp_clienthost)-30] = '\0';
} else {
nntp_clienthost[0] = '\0';
}
niflags = NI_NUMERICHOST;
#ifdef NI_WITHSCOPEID
if (((struct sockaddr *)&nntp_remoteaddr)->sa_family == AF_INET6)
niflags |= NI_WITHSCOPEID;
#endif
if (getnameinfo((struct sockaddr *)&nntp_remoteaddr, salen, hbuf,
sizeof(hbuf), NULL, 0, niflags) != 0)
strlcpy(hbuf, "unknown", sizeof(hbuf));
strlcat(nntp_clienthost, "[", sizeof(nntp_clienthost));
strlcat(nntp_clienthost, hbuf, sizeof(nntp_clienthost));
strlcat(nntp_clienthost, "]", sizeof(nntp_clienthost));
salen = sizeof(nntp_localaddr);
if (getsockname(0, (struct sockaddr *)&nntp_localaddr, &salen) == 0) {
nntp_haveaddr = 1;
}
nntp_logfd = telemetry_log(hbuf, nntp_in, nntp_out, 0);
}
if (sasl_server_new("nntp", config_servername, NULL, NULL, NULL,
NULL, SASL_SUCCESS_DATA, &nntp_saslconn) != SASL_OK)
fatal("SASL failed initializing: sasl_server_new()",EC_TEMPFAIL);
secprops = mysasl_secprops(0);
sasl_setprop(nntp_saslconn, SASL_SEC_PROPS, secprops);
sasl_setprop(nntp_saslconn, SASL_SSF_EXTERNAL, &extprops_ssf);
if(iptostring((struct sockaddr *)&nntp_localaddr, salen,
localip, 60) == 0) {
sasl_setprop(nntp_saslconn, SASL_IPLOCALPORT, localip);
saslprops.iplocalport = xstrdup(localip);
}
if(iptostring((struct sockaddr *)&nntp_remoteaddr, salen,
remoteip, 60) == 0) {
sasl_setprop(nntp_saslconn, SASL_IPREMOTEPORT, remoteip);
saslprops.ipremoteport = xstrdup(remoteip);
}
proc_register("nntpd", nntp_clienthost, NULL, NULL);
nntp_timeout = config_getint(IMAPOPT_NNTPTIMEOUT);
if (nntp_timeout < 3) nntp_timeout = 3;
nntp_timeout *= 60;
prot_settimeout(nntp_in, nntp_timeout);
prot_setflushonread(nntp_in, nntp_out);
if (nntps == 1) cmd_starttls(1);
if ((shutdown = shutdown_file(unavail, sizeof(unavail)))) {
prot_printf(nntp_out, "%u", 400);
} else {
prot_printf(nntp_out, "%u", (nntp_capa & MODE_READ) ? 200 : 201);
}
if (config_serverinfo) prot_printf(nntp_out, " %s", config_servername);
if (config_serverinfo == IMAP_ENUM_SERVERINFO_ON) {
prot_printf(nntp_out, " Cyrus NNTP%s %s",
config_mupdate_server ? " Murder" : "", cyrus_version());
}
if (shutdown) {
prot_printf(nntp_out, "server unavailable, %s\r\n", unavail);
shut_down(0);
}
else {
prot_printf(nntp_out, " server ready, posting %s\r\n",
(nntp_capa & MODE_READ) ? "allowed" : "prohibited");
}
cmdloop();
nntp_reset();
return 0;
},0

static int _init_by_name_verity(struct crypt_device *cd, const char *name)
{
struct crypt_dm_active_device dmd;
struct dm_target *tgt = &dmd.segment;
int r;
r = dm_query_device(cd, name,
DM_ACTIVE_DEVICE |
DM_ACTIVE_VERITY_HASH_DEVICE |
DM_ACTIVE_VERITY_ROOT_HASH |
DM_ACTIVE_VERITY_PARAMS, &dmd);
if (r < 0)
return r;
if (!single_segment(&dmd) || tgt->type != DM_VERITY) {
log_dbg(cd, "Unsupported device table detected in %s.", name);
r = -EINVAL;
goto out;
}
if (r > 0)
r = 0;
if (isVERITY(cd->type)) {
cd->u.verity.uuid = NULL;
cd->u.verity.hdr.flags = CRYPT_VERITY_NO_HEADER;
cd->u.verity.hdr.data_size = tgt->u.verity.vp->data_size;
cd->u.verity.root_hash_size = tgt->u.verity.root_hash_size;
MOVE_REF(cd->u.verity.hdr.hash_name, tgt->u.verity.vp->hash_name);
cd->u.verity.hdr.data_device = NULL;
cd->u.verity.hdr.hash_device = NULL;
cd->u.verity.hdr.data_block_size = tgt->u.verity.vp->data_block_size;
cd->u.verity.hdr.hash_block_size = tgt->u.verity.vp->hash_block_size;
cd->u.verity.hdr.hash_area_offset = tgt->u.verity.hash_offset;
cd->u.verity.hdr.fec_area_offset = tgt->u.verity.fec_offset;
cd->u.verity.hdr.hash_type = tgt->u.verity.vp->hash_type;
cd->u.verity.hdr.flags = tgt->u.verity.vp->flags;
cd->u.verity.hdr.salt_size = tgt->u.verity.vp->salt_size;
MOVE_REF(cd->u.verity.hdr.salt, tgt->u.verity.vp->salt);
MOVE_REF(cd->u.verity.hdr.fec_device, tgt->u.verity.vp->fec_device);
cd->u.verity.hdr.fec_roots = tgt->u.verity.vp->fec_roots;
MOVE_REF(cd->u.verity.fec_device, tgt->u.verity.fec_device);
MOVE_REF(cd->metadata_device, tgt->u.verity.hash_device);
MOVE_REF(cd->u.verity.root_hash, tgt->u.verity.root_hash);
}
out:
dm_targets_free(cd, &dmd);
return r;
},0

static BROTLI_INLINE void TakeDistanceFromRingBuffer(BrotliDecoderState* s) {
int offset = s->distance_code - 3;
if (s->distance_code <= 3) {
s->distance_context = 1 >> s->distance_code;
s->distance_code = s->dist_rb[(s->dist_rb_idx - offset) & 3];
s->dist_rb_idx -= s->distance_context;
} else {
int index_delta = 3;
int delta;
int base = s->distance_code - 10;
if (s->distance_code < 10) {
base = s->distance_code - 4;
} else {
index_delta = 2;
}
delta = ((0x605142 >> (4 * base)) & 0xF) - 3;
s->distance_code = s->dist_rb[(s->dist_rb_idx + index_delta) & 0x3] + delta;
if (s->distance_code <= 0) {
s->distance_code = 0x7FFFFFFF;
}
}
