} else {
std::cout << " Compiling kernel..." << std::flush;
const std::string strKeccak = readFile("keccak.cl");
const std::string strVanity = readFile("profanity.cl");
const char * szKernels[] = { strKeccak.c_str(), strVanity.c_str() };
