retval = 0;
pkiDebug("%s: returning context at %p\n", __FUNCTION__, realm_contexts);
errout:
if (retval) {
pkinit_server_plugin_fini(context,
(krb5_kdcpreauth_moddata)realm_contexts);
}
return retval;
