assemble_mountinfo(struct parsed_mount_info *parsed_info,
const char *thisprogram, const char *mountpoint,
const char *orig_dev, char *orgoptions)
{
int rc;
char *newopts = NULL;
rc = drop_capabilities(0);
if (rc)
goto assemble_exit;
rc = drop_child_privs();
if (rc)
goto assemble_exit;
if (getuid()) {
rc = check_fstab(thisprogram, mountpoint, orig_dev,
&newopts);
if (rc)
goto assemble_exit;
orgoptions = newopts;
parsed_info->flags |= CIFS_SETUID_FLAGS;
}
rc = get_pw_from_env(parsed_info, thisprogram);
if (rc)
goto assemble_exit;
if (orgoptions) {
rc = parse_options(orgoptions, parsed_info);
if (rc)
goto assemble_exit;
}
if (getuid()) {
if (!(parsed_info->flags & (MS_USERS | MS_USER))) {
fprintf(stderr, "%s: permission denied\n", thisprogram);
rc = EX_USAGE;
goto assemble_exit;
}
}
parsed_info->flags &= ~(MS_USERS | MS_USER);
rc = parse_unc(orig_dev, parsed_info, thisprogram);
if (rc)
goto assemble_exit;
if (parsed_info->addrlist[0] == '\0')
rc = resolve_host(parsed_info->host, parsed_info->addrlist);
switch (rc) {
case EX_USAGE:
fprintf(stderr, "mount error: could not resolve address for "
"%s: %s\n", parsed_info->host,
rc == EAI_SYSTEM ? strerror(errno) : gai_strerror(rc));
goto assemble_exit;
case EX_SYSERR:
fprintf(stderr, "mount error: problem parsing address "
"list: %s\n", strerror(errno));
goto assemble_exit;
}
if (!parsed_info->got_user) {
if (getenv("USER"))
strlcpy(parsed_info->username, getenv("USER"),
sizeof(parsed_info->username));
else
strlcpy(parsed_info->username, getusername(getuid()),
sizeof(parsed_info->username));
parsed_info->got_user = 1;
}
if (!parsed_info->got_password) {
char tmp_pass[MOUNT_PASSWD_SIZE + 1];
char *prompt = NULL;
if(asprintf(&prompt, "Password for %s@%s: ", parsed_info->username, orig_dev) < 0)
prompt = NULL;
if (get_password(prompt ? prompt : "Password: ", tmp_pass, MOUNT_PASSWD_SIZE + 1)) {
rc = set_password(parsed_info, tmp_pass);
} else {
fprintf(stderr, "Error reading password, exiting\n");
rc = EX_SYSERR;
}
free(prompt);
if (rc)
goto assemble_exit;
}
if (parsed_info->got_user) {
if (*parsed_info->options)
strlcat(parsed_info->options, ",",
sizeof(parsed_info->options));
strlcat(parsed_info->options, "user=",
sizeof(parsed_info->options));
strlcat(parsed_info->options, parsed_info->username,
sizeof(parsed_info->options));
}
if (*parsed_info->domain) {
if (*parsed_info->options)
strlcat(parsed_info->options, ",",
sizeof(parsed_info->options));
strlcat(parsed_info->options, "domain=",
sizeof(parsed_info->options));
strlcat(parsed_info->options, parsed_info->domain,
sizeof(parsed_info->options));
} else if (parsed_info->got_domain) {
strlcat(parsed_info->options, ",domain=",
sizeof(parsed_info->options));
}
assemble_exit:
free(newopts);
return rc;
},0

static int i40e_reserve_msix_vectors(struct i40e_pf *pf, int vectors)
{
vectors = pci_enable_msix_range(pf->pdev, pf->msix_entries,
I40E_MIN_MSIX, vectors);
if (vectors < 0) {
dev_info(&pf->pdev->dev,
"MSI-X vector reservation failed: %d\n", vectors);
vectors = 0;
}
return vectors;
},0

void sum_init(int csum_type, int seed)
{
char s[4];
if (csum_type < 0)
csum_type = parse_csum_name(NULL, 0);
cursum_type = csum_type;
switch (csum_type) {
case CSUM_MD5:
md5_begin(&md);
break;
case CSUM_MD4:
mdfour_begin(&md);
sumresidue = 0;
break;
case CSUM_MD4_OLD:
case CSUM_MD4_BUSTED:
mdfour_begin(&md);
sumresidue = 0;
SIVAL(s, 0, seed);
sum_update(s, 4);
break;
case CSUM_NONE:
break;
}
},1

apply_enable_disable(
attr_val_fifo * fifo,
int enable
)
{
attr_val *curr_flag;
int option;
#ifdef BC_LIST_FRAMEWORK_NOT_YET_USED
bc_entry *pentry;
#endif
for (curr_flag = HEAD_PFIFO(fifo);
curr_flag != NULL;
curr_flag = curr_flag->link) {
option = curr_flag->value.i;
switch (option) {
default:
msyslog(LOG_ERR,
"can not apply enable/disable token %d, unknown",
option);
break;
case T_Auth:
proto_config(PROTO_AUTHENTICATE, enable, 0., NULL);
break;
case T_Bclient:
proto_config(PROTO_BROADCLIENT, enable, 0., NULL);
break;
case T_Calibrate:
proto_config(PROTO_CAL, enable, 0., NULL);
break;
case T_Kernel:
proto_config(PROTO_KERNEL, enable, 0., NULL);
break;
case T_Monitor:
proto_config(PROTO_MONITOR, enable, 0., NULL);
break;
case T_Ntp:
proto_config(PROTO_NTP, enable, 0., NULL);
break;
case T_Mode7:
proto_config(PROTO_MODE7, enable, 0., NULL);
break;
case T_Stats:
proto_config(PROTO_FILEGEN, enable, 0., NULL);
break;
#ifdef BC_LIST_FRAMEWORK_NOT_YET_USED
case T_Bc_bugXXXX:
pentry = bc_list;
while (pentry->token) {
if (pentry->token == option)
break;
pentry++;
}
if (!pentry->token) {
msyslog(LOG_ERR,
"compat token %d not in bc_list[]",
option);
continue;
}
pentry->enabled = enable;
break;
#endif
}
}
},1

xfs_ioc_fsgeometry_v1(
