app.checkConflict("--write-xfer-little", "--prefer-rle", opt_in_networkTransferSyntax == EXS_RLELossless);
opt_writeTransferSyntax = EXS_LittleEndianExplicit;
}
if (cmd.findOption("--write-xfer-big"))
{
