static js_Ast *equality(js_State *J, int notin)
{
js_Ast *a = relational(J, notin);
loop:
if (jsP_accept(J, TK_EQ)) { a = EXP2(EQ, a, relational(J, notin)); goto loop; }
if (jsP_accept(J, TK_NE)) { a = EXP2(NE, a, relational(J, notin)); goto loop; }
if (jsP_accept(J, TK_STRICTEQ)) { a = EXP2(STRICTEQ, a, relational(J, notin)); goto loop; }
if (jsP_accept(J, TK_STRICTNE)) { a = EXP2(STRICTNE, a, relational(J, notin)); goto loop; }
return a;
},1

static void console_putchar(QemuConsole *s, int ch)
{
int i;
int x, y;
char response[40];
switch(s->state) {
case TTY_STATE_NORM:
switch(ch) {
case '\r':
s->x = 0;
break;
case '\n':
console_put_lf(s);
break;
case '\b':
if (s->x > 0)
s->x--;
break;
case '\t':
if (s->x + (8 - (s->x % 8)) > s->width) {
s->x = 0;
console_put_lf(s);
} else {
s->x = s->x + (8 - (s->x % 8));
}
break;
case '\a':
break;
case 14:
break;
case 15:
break;
case 27:
s->state = TTY_STATE_ESC;
break;
default:
console_put_one(s, ch);
break;
}
break;
case TTY_STATE_ESC:
if (ch == '[') {
for(i=0;i<MAX_ESC_PARAMS;i++)
s->esc_params[i] = 0;
s->nb_esc_params = 0;
s->state = TTY_STATE_CSI;
} else {
s->state = TTY_STATE_NORM;
}
break;
case TTY_STATE_CSI:
if (ch >= '0' && ch <= '9') {
if (s->nb_esc_params < MAX_ESC_PARAMS) {
int *param = &s->esc_params[s->nb_esc_params];
int digit = (ch - '0');
*param = (*param <= (INT_MAX - digit) / 10) ?
*param * 10 + digit : INT_MAX;
}
} else {
if (s->nb_esc_params < MAX_ESC_PARAMS)
s->nb_esc_params++;
if (ch == ';')
break;
trace_console_putchar_csi(s->esc_params[0], s->esc_params[1],
ch, s->nb_esc_params);
s->state = TTY_STATE_NORM;
switch(ch) {
case 'A':
if (s->esc_params[0] == 0) {
s->esc_params[0] = 1;
}
set_cursor(s, s->x, s->y - s->esc_params[0]);
break;
case 'B':
if (s->esc_params[0] == 0) {
s->esc_params[0] = 1;
}
set_cursor(s, s->x, s->y + s->esc_params[0]);
break;
case 'C':
if (s->esc_params[0] == 0) {
s->esc_params[0] = 1;
}
set_cursor(s, s->x + s->esc_params[0], s->y);
break;
case 'D':
if (s->esc_params[0] == 0) {
s->esc_params[0] = 1;
}
set_cursor(s, s->x - s->esc_params[0], s->y);
break;
case 'G':
set_cursor(s, s->esc_params[0] - 1, s->y);
break;
case 'f':
case 'H':
set_cursor(s, s->esc_params[1] - 1, s->esc_params[0] - 1);
break;
case 'J':
switch (s->esc_params[0]) {
case 0:
for (y = s->y; y < s->height; y++) {
for (x = 0; x < s->width; x++) {
if (y == s->y && x < s->x) {
continue;
}
console_clear_xy(s, x, y);
}
}
break;
case 1:
for (y = 0; y <= s->y; y++) {
for (x = 0; x < s->width; x++) {
if (y == s->y && x > s->x) {
break;
}
console_clear_xy(s, x, y);
}
}
break;
case 2:
for (y = 0; y <= s->height; y++) {
for (x = 0; x < s->width; x++) {
console_clear_xy(s, x, y);
}
}
break;
}
break;
case 'K':
switch (s->esc_params[0]) {
case 0:
for(x = s->x; x < s->width; x++) {
console_clear_xy(s, x, s->y);
}
break;
case 1:
for (x = 0; x <= s->x; x++) {
console_clear_xy(s, x, s->y);
}
break;
case 2:
for(x = 0; x < s->width; x++) {
console_clear_xy(s, x, s->y);
}
break;
}
break;
case 'm':
console_handle_escape(s);
break;
case 'n':
switch (s->esc_params[0]) {
case 5:
console_respond_str(s, "\033[0n");
break;
case 6:
sprintf(response, "\033[%d;%dR",
(s->y_base + s->y) % s->total_height + 1,
s->x + 1);
console_respond_str(s, response);
break;
}
break;
case 's':
s->x_saved = s->x;
s->y_saved = s->y;
break;
case 'u':
s->x = s->x_saved;
s->y = s->y_saved;
break;
default:
trace_console_putchar_unhandled(ch);
break;
}
break;
}
}
},0

TEST_F(OwnedImplTest, AddEmptyFragment) {
char input[] = "hello world";
BufferFragmentImpl frag1(input, 11, [](const void*, size_t, const BufferFragmentImpl*) {});
BufferFragmentImpl frag2("", 0, [this](const void*, size_t, const BufferFragmentImpl*) {
release_callback_called_ = true;
});
Buffer::OwnedImpl buffer;
buffer.addBufferFragment(frag1);
EXPECT_EQ(11, buffer.length());
buffer.addBufferFragment(frag2);
EXPECT_EQ(11, buffer.length());
buffer.drain(11);
EXPECT_EQ(0, buffer.length());
EXPECT_TRUE(release_callback_called_);
},1

void ax25_dev_device_down(struct net_device *dev)
{
ax25_dev *s, *ax25_dev;
if ((ax25_dev = ax25_dev_ax25dev(dev)) == NULL)
return;
ax25_unregister_dev_sysctl(ax25_dev);
spin_lock_bh(&ax25_dev_lock);
#ifdef CONFIG_AX25_DAMA_SLAVE
ax25_ds_del_timer(ax25_dev);
#endif
for (s = ax25_dev_list; s != NULL; s = s->next)
if (s->forward == dev)
s->forward = NULL;
if ((s = ax25_dev_list) == ax25_dev) {
ax25_dev_list = s->next;
ax25_dev_put(ax25_dev);
spin_unlock_bh(&ax25_dev_lock);
dev->ax25_ptr = NULL;
dev_put_track(dev, &ax25_dev->dev_tracker);
ax25_dev_put(ax25_dev);
return;
}
while (s != NULL && s->next != NULL) {
if (s->next == ax25_dev) {
s->next = ax25_dev->next;
ax25_dev_put(ax25_dev);
spin_unlock_bh(&ax25_dev_lock);
dev->ax25_ptr = NULL;
dev_put_track(dev, &ax25_dev->dev_tracker);
ax25_dev_put(ax25_dev);
return;
}
s = s->next;
}
spin_unlock_bh(&ax25_dev_lock);
dev->ax25_ptr = NULL;
ax25_dev_put(ax25_dev);
},1

void NumberFormatTest::Test20037_ScientificIntegerOverflow() {
IcuTestErrorCode status(*this, "Test20037_ScientificIntegerOverflow");
LocalPointer<NumberFormat> nf(NumberFormat::createInstance(status));
if (U_FAILURE(status)) {
dataerrln("Unable to create NumberFormat instance.");
return;
}
Formattable result;
nf->parse(u"1E-2147483648", result, status);
StringPiece sp = result.getDecimalNumber(status);
assertEquals(u"Should snap to zero",
u"0",
{sp.data(), sp.length(), US_INV});
result = Formattable();
nf->parse(u"1E-2147483647E-1", result, status);
sp = result.getDecimalNumber(status);
assertEquals(u"Should not overflow and should parse only the first exponent",
u"1E-2147483647",
{sp.data(), sp.length(), US_INV});
},1

static void parse_path(char *p, char *q, char *id, int idsz)
{
struct SYMBOL *s;
char *buf, *r, *t, *op = NULL, *width, *scale, *trans;
int i, fill, npar = 0;
float x1, y1, x, y;
char *rmax;
r = strstr(p, "class=\"");
if (!r || r > q)
return;
r += 7;
fill = strncmp(r, "fill", 4) == 0;
width = strstr(p, "stroke-width:");
scale = strstr(p, "scale(");
if (scale && scale > q)
scale = NULL;
trans = strstr(p, "translate(");
if (trans && trans > q)
trans = NULL;
for (;;) {
p = strstr(p, "d=\"");
if (!p)
return;
if (isspace((unsigned char) p[-1]))
break;
p += 3;
}
i = (int) (q - p) * 4 + 200;
if (i > TEX_BUF_SZ)
buf = malloc(i);
else
buf = tex_buf;
rmax=buf + i;
r = buf;
*r++ = '/';
idsz -= 5;
strncpy(r, id + 4, idsz);
r += idsz;
strcpy(r, "{gsave T ");
r += strlen(r);
if (scale || trans) {
if (scale) {
scale += 6;
t = get_val(scale, &x1);
if (*t == ',')
t = get_val(t + 1, &y1);
else
y1 = x1;
}
if (trans) {
trans += 10;
t = get_val(trans, &x) + 1;
t = get_val(t, &y);
}
if (!scale)
r += sprintf(r, "%.2f %.2f T ", x, -y);
else if (!trans)
r += sprintf(r, "%.2f %.2f scale ", x1, y1);
else if (scale > trans)
r += sprintf(r, "%.2f %.2f T %.2f %.2f scale ",
x, -y, x1, y1);
else
r += sprintf(r, "%.2f %.2f scale %.2f %.2f T ",
x1, y1, x, -y);
}
strcpy(r, "0 0 M\n");
r += strlen(r);
if (width && width < q) {
*r++ = ' ';
width += 13;
while (isdigit(*width) || *width == '.')
*r++ = *width++;
*r++ = ' ';
*r++ = 'S';
*r++ = 'L';
*r++ = 'W';
}
p += 3;
for (;;) {
if (*p == '\0' || *p == '"')
break;
i = 0;
switch (*p++) {
default:
if ((isdigit((unsigned char) p[-1]))
|| p[-1] == '-' || p[-1] == '.') {
if (!npar)
continue;
p--;
break;
}
continue;
case 'M':
op = "M";
npar = 2;
break;
case 'm':
op = "RM";
npar = 2;
break;
case 'L':
op = "L";
npar = 2;
break;
case 'l':
op = "RL";
npar = 2;
break;
case 'H':
op = "H";
npar = 1;
break;
case 'h':
op = "h";
npar = 1;
break;
case 'V':
op = "V";
npar = 1;
break;
case 'v':
*r++ = ' ';
*r++ = '0';
op = "RL";
i = 1;
npar = 2;
break;
case 'z':
op = "closepath";
npar = 0;
break;
case 'C':
op = "C";
npar = 6;
break;
case 'c':
op = "RC";
npar = 6;
break;
case 'q':
op = "RC";
npar = 2;
p = get_val(p, &x1);
p = get_val(p, &y1);
t = get_val(p, &x);
t = get_val(t, &y);
r += sprintf(r, " %.2f %.2f %.2f %.2f",
x1*2/3, -y1*2/3,
x1+(x-x1)*2/3, -y1-(y-y1)*2/3);
break;
case 't':
op = "RC";
npar = 2;
x1 = x - x1;
y1 = y - y1;
t = get_val(p, &x);
t = get_val(t, &y);
r += sprintf(r, " %.2f %.2f %.2f %.2f",
x1*2/3, -y1*2/3,
x1+(x-x1)*2/3, -y1-(y-y1)*2/3);
break;
}
*r++ = ' ';
for ( ; i < npar; i++) {
while (isspace((unsigned char) *p))
p++;
if (i & 1) {
if (*p == '-')
p++;
else if (*p != '0' || p[1] != ' ')
*r++ = '-';
}
while ((isdigit((unsigned char) *p))
|| *p == '-' || *p == '.')
*r++ = *p++;
*r++ = ' ';
}
if (*op == 'h') {
*r++ = '0';
*r++ = ' ';
op = "RL";
}
strcpy(r, op);
r += strlen(r);
if (r + 30 > rmax) bug("Buffer overflow in SVG to PS", 1);
}
strcpy(r, fill ? " fill" : " stroke");
r += strlen(r);
strcpy(r, "\ngrestore}!");
r += strlen(r);
s = getarena(sizeof(struct SYMBOL));
memset(s, 0, sizeof(struct SYMBOL));
s->text = getarena(strlen(buf) + 1);
strcpy(s->text, buf);
ps_def(s, s->text, 'p');
if (buf != tex_buf)
free(buf);
},0

void vrend_link_program(struct vrend_context *ctx, uint32_t *handles)
{
if (handles[PIPE_SHADER_COMPUTE])
return;
struct vrend_shader_selector *prev_handles[PIPE_SHADER_TYPES];
memset(prev_handles, 0, sizeof(prev_handles));
uint32_t prev_shader_ids[PIPE_SHADER_TYPES];
memcpy(prev_shader_ids, ctx->sub->prog_ids, PIPE_SHADER_TYPES * sizeof(uint32_t));
struct vrend_linked_shader_program *prev_prog = ctx->sub->prog;
for (uint32_t type = 0; type < PIPE_SHADER_TYPES; ++type) {
vrend_shader_state_reference(&prev_handles[type], ctx->sub->shaders[type]);
vrend_bind_shader(ctx, handles[type], type);
}
vrend_select_program(ctx->sub, 1);
ctx->sub->shader_dirty = true;
ctx->sub->cs_shader_dirty = true;
for (uint32_t type = 0; type < PIPE_SHADER_TYPES; ++type) {
vrend_shader_state_reference(&ctx->sub->shaders[type], prev_handles[type]);
vrend_shader_state_reference(&prev_handles[type], NULL);
}
memcpy(ctx->sub->prog_ids, prev_shader_ids, PIPE_SHADER_TYPES * sizeof(uint32_t));
ctx->sub->prog = prev_prog;
},0

gpk_build_pin_apdu(sc_card_t *card, sc_apdu_t *apdu, struct sc_pin_cmd_data *data)
{
static u8 sbuf[8];
int r;
if (data->pin_type != SC_AC_CHV)
return SC_ERROR_INVALID_ARGUMENTS;
memset(apdu, 0, sizeof(*apdu));
apdu->cse = SC_APDU_CASE_3_SHORT;
data->flags |= SC_PIN_CMD_NEED_PADDING;
switch (data->cmd) {
case SC_PIN_CMD_VERIFY:
data->pin1.encoding = SC_PIN_ENCODING_ASCII;
data->pin1.pad_length = 8;
data->pin1.pad_char = 0x00;
data->pin1.offset = 5;
r = sc_build_pin(sbuf, 8, &data->pin1, 1);
if (r < 0)
return r;
apdu->cla = 0x00;
apdu->ins = 0x20;
apdu->p1 = 0x00;
break;
case SC_PIN_CMD_CHANGE:
case SC_PIN_CMD_UNBLOCK:
data->pin1.encoding = SC_PIN_ENCODING_BCD;
data->pin1.pad_length = 8;
data->pin1.pad_char = 0x00;
data->pin1.offset = 5;
data->pin2.encoding = SC_PIN_ENCODING_BCD;
data->pin2.pad_length = 8;
data->pin2.pad_char = 0x00;
data->pin2.offset = 5 + 4;
if ((r = sc_build_pin(sbuf, 4, &data->pin1, 1)) < 0
|| (r = sc_build_pin(sbuf + 4, 4, &data->pin2, 1)) < 0)
return r;
apdu->cla = 0x80;
apdu->ins = 0x24;
apdu->p1 = (data->cmd == SC_PIN_CMD_CHANGE)? 0x00 : 0x01;
break;
default:
return SC_ERROR_NOT_SUPPORTED;
}
apdu->p2 = data->pin_reference & 7;
apdu->lc = 8;
apdu->datalen = 8;
apdu->data = sbuf;
return 0;
},0

gremlin_flood_clients(struct multi_context *m)
{
const int level = GREMLIN_PACKET_FLOOD_LEVEL(m->top.options.gremlin);
if (level)
{
struct gc_arena gc = gc_new();
struct buffer buf = alloc_buf_gc(BUF_SIZE(&m->top.c2.frame), &gc);
struct packet_flood_parms parm = get_packet_flood_parms(level);
int i;
ASSERT(buf_init(&buf, FRAME_HEADROOM(&m->top.c2.frame)));
parm.packet_size = min_int(parm.packet_size, MAX_RW_SIZE_TUN(&m->top.c2.frame));
msg(D_GREMLIN, "GREMLIN_FLOOD_CLIENTS: flooding clients with %d packets of size %d",
parm.n_packets,
parm.packet_size);
for (i = 0; i < parm.packet_size; ++i)
{
ASSERT(buf_write_u8(&buf, get_random() & 0xFF));
}
for (i = 0; i < parm.n_packets; ++i)
{
multi_bcast(m, &buf, NULL, NULL, 0);
}
gc_free(&gc);
}
},0

static inline void ModulateHSI(const double percent_hue,
const double percent_saturation,const double percent_intensity,double *red,
double *green,double *blue)
{
double
intensity,
hue,
saturation;
ConvertRGBToHSI(*red,*green,*blue,&hue,&saturation,&intensity);
hue+=0.5*(0.01*percent_hue-1.0);
while (hue < 0.0)
hue+=1.0;
while (hue > 1.0)
hue-=1.0;
saturation*=0.01*percent_saturation;
intensity*=0.01*percent_intensity;
ConvertHSIToRGB(hue,saturation,intensity,red,green,blue);
},1

load_data_open (struct archive *a,
void *client_data)
{
