static int smaps_pte_range(pmd_t *pmd, unsigned long addr, unsigned long end,
struct mm_walk *walk)
{
struct mem_size_stats *mss = walk->private;
struct vm_area_struct *vma = mss->vma;
pte_t *pte;
spinlock_t *ptl;
spin_lock(&walk->mm->page_table_lock);
if (pmd_trans_huge(*pmd)) {
if (pmd_trans_splitting(*pmd)) {
spin_unlock(&walk->mm->page_table_lock);
wait_split_huge_page(vma->anon_vma, pmd);
} else {
smaps_pte_entry(*(pte_t *)pmd, addr,
HPAGE_PMD_SIZE, walk);
spin_unlock(&walk->mm->page_table_lock);
mss->anonymous_thp += HPAGE_PMD_SIZE;
return 0;
}
} else {
spin_unlock(&walk->mm->page_table_lock);
}
pte = pte_offset_map_lock(vma->vm_mm, pmd, addr, &ptl);
for (; addr != end; pte++, addr += PAGE_SIZE)
smaps_pte_entry(*pte, addr, PAGE_SIZE, walk);
pte_unmap_unlock(pte - 1, ptl);
cond_resched();
return 0;
},1

int dev_change_net_namespace(struct net_device *dev, struct net *net, const char *pat)
{
int err;
ASSERT_RTNL();
err = -EINVAL;
if (dev->features & NETIF_F_NETNS_LOCAL)
goto out;
if (dev->reg_state != NETREG_REGISTERED)
goto out;
err = 0;
if (net_eq(dev_net(dev), net))
goto out;
err = -EEXIST;
if (__dev_get_by_name(net, dev->name)) {
if (!pat)
goto out;
if (dev_get_valid_name(net, dev, pat) < 0)
goto out;
}
dev_close(dev);
err = -ENODEV;
unlist_netdevice(dev);
synchronize_net();
dev_shutdown(dev);
call_netdevice_notifiers(NETDEV_UNREGISTER, dev);
rcu_barrier();
call_netdevice_notifiers(NETDEV_UNREGISTER_FINAL, dev);
rtmsg_ifinfo(RTM_DELLINK, dev, ~0U, GFP_KERNEL);
dev_uc_flush(dev);
dev_mc_flush(dev);
kobject_uevent(&dev->dev.kobj, KOBJ_REMOVE);
netdev_adjacent_del_links(dev);
dev_net_set(dev, net);
if (__dev_get_by_index(net, dev->ifindex))
dev->ifindex = dev_new_index(net);
kobject_uevent(&dev->dev.kobj, KOBJ_ADD);
netdev_adjacent_add_links(dev);
err = device_rename(&dev->dev, dev->name);
WARN_ON(err);
list_netdevice(dev);
call_netdevice_notifiers(NETDEV_REGISTER, dev);
rtmsg_ifinfo(RTM_NEWLINK, dev, ~0U, GFP_KERNEL);
synchronize_net();
err = 0;
out:
return err;,0

static int xfrm_user_rcv_msg(struct sk_buff *skb, struct nlmsghdr *nlh,
struct netlink_ext_ack *extack)
{
struct net *net = sock_net(skb->sk);
struct nlattr *attrs[XFRMA_MAX+1];
const struct xfrm_link *link;
int type, err;
#ifdef CONFIG_COMPAT
if (in_compat_syscall())
return -EOPNOTSUPP;
#endif
type = nlh->nlmsg_type;
if (type > XFRM_MSG_MAX)
return -EINVAL;
type -= XFRM_MSG_BASE;
link = &xfrm_dispatch[type];
if (!netlink_net_capable(skb, CAP_NET_ADMIN))
return -EPERM;
if ((type == (XFRM_MSG_GETSA - XFRM_MSG_BASE) ||
type == (XFRM_MSG_GETPOLICY - XFRM_MSG_BASE)) &&
(nlh->nlmsg_flags & NLM_F_DUMP)) {
if (link->dump == NULL)
return -EINVAL;
{
struct netlink_dump_control c = {
.dump = link->dump,
.done = link->done,
};
return netlink_dump_start(net->xfrm.nlsk, skb, nlh, &c);
}
}
err = nlmsg_parse(nlh, xfrm_msg_min[type], attrs,
link->nla_max ? : XFRMA_MAX,
link->nla_pol ? : xfrma_policy, extack);
if (err < 0)
return err;
if (link->doit == NULL)
return -EINVAL;
return link->doit(skb, nlh, attrs);
},1

xz_head(xz_statep state)
{
lzma_stream *strm = &(state->strm);
lzma_stream init = LZMA_STREAM_INIT;
int flags;
unsigned len;
if (state->size == 0) {
state->in = xmlMalloc(state->want);
state->out = xmlMalloc(state->want << 1);
if (state->in == NULL || state->out == NULL) {
if (state->out != NULL)
xmlFree(state->out);
if (state->in != NULL)
xmlFree(state->in);
xz_error(state, LZMA_MEM_ERROR, "out of memory");
return -1;
}
state->size = state->want;
state->strm = init;
state->strm.avail_in = 0;
state->strm.next_in = NULL;
if (lzma_auto_decoder(&state->strm, UINT64_MAX, 0) != LZMA_OK) {
xmlFree(state->out);
xmlFree(state->in);
state->size = 0;
xz_error(state, LZMA_MEM_ERROR, "out of memory");
return -1;
}
#ifdef HAVE_ZLIB_H
state->zstrm.zalloc = Z_NULL;
state->zstrm.zfree = Z_NULL;
state->zstrm.opaque = Z_NULL;
state->zstrm.avail_in = 0;
state->zstrm.next_in = Z_NULL;
if (state->init == 0) {
if (inflateInit2(&(state->zstrm), -15) != Z_OK) {
xmlFree(state->out);
xmlFree(state->in);
state->size = 0;
xz_error(state, LZMA_MEM_ERROR, "out of memory");
return -1;
}
state->init = 1;
}
#endif
}
if (strm->avail_in == 0) {
if (xz_avail(state) == -1)
return -1;
if (strm->avail_in == 0)
return 0;
}
if (is_format_xz(state) || is_format_lzma(state)) {
state->how = LZMA;
state->direct = 0;
return 0;
}
#ifdef HAVE_ZLIB_H
if (strm->next_in[0] == 31) {
strm->avail_in--;
strm->next_in++;
if (strm->avail_in == 0 && xz_avail(state) == -1)
return -1;
if (strm->avail_in && strm->next_in[0] == 139) {
strm->avail_in--;
strm->next_in++;
if (NEXT() != 8) {
xz_error(state, LZMA_DATA_ERROR,
"unknown compression method");
return -1;
}
flags = NEXT();
if (flags & 0xe0) {
xz_error(state, LZMA_DATA_ERROR,
"unknown header flags set");
return -1;
}
NEXT();
NEXT();
NEXT();
NEXT();
NEXT();
NEXT();
if (flags & 4) {
len = (unsigned) NEXT();
len += (unsigned) NEXT() << 8;
while (len--)
if (NEXT() < 0)
break;
}
if (flags & 8)
while (NEXT() > 0) ;
if (flags & 16)
while (NEXT() > 0) ;
if (flags & 2) {
NEXT();
NEXT();
}
inflateReset(&state->zstrm);
state->zstrm.adler = crc32(0L, Z_NULL, 0);
state->how = GZIP;
state->direct = 0;
return 0;
} else {
state->out[0] = 31;
state->have = 1;
}
}
#endif
state->raw = state->pos;
state->next = state->out;
if (strm->avail_in) {
memcpy(state->next + state->have, strm->next_in, strm->avail_in);
state->have += strm->avail_in;
strm->avail_in = 0;
}
state->how = COPY;
state->direct = 1;
return 0;
},1

nv_brackets(cmdarg_T *cap)
{
pos_T prev_pos;
pos_T *pos = NULL;
pos_T old_pos;
int flag;
long n;
cap->oap->motion_type = MCHAR;
cap->oap->inclusive = FALSE;
old_pos = curwin->w_cursor;
curwin->w_cursor.coladd = 0;
#ifdef FEAT_SEARCHPATH
if (cap->nchar == 'f')
nv_gotofile(cap);
else
#endif
#ifdef FEAT_FIND_ID
if (vim_strchr((char_u *)"iI\011dD\004", cap->nchar) != NULL)
{
char_u *ptr;
int len;
if ((len = find_ident_under_cursor(&ptr, FIND_IDENT)) == 0)
clearop(cap->oap);
else
{
find_pattern_in_path(ptr, 0, len, TRUE,
cap->count0 == 0 ? !isupper(cap->nchar) : FALSE,
((cap->nchar & 0xf) == ('d' & 0xf)) ? FIND_DEFINE : FIND_ANY,
cap->count1,
isupper(cap->nchar) ? ACTION_SHOW_ALL :
islower(cap->nchar) ? ACTION_SHOW : ACTION_GOTO,
cap->cmdchar == ']' ? curwin->w_cursor.lnum + 1 : (linenr_T)1,
(linenr_T)MAXLNUM);
curwin->w_set_curswant = TRUE;
}
}
else
#endif
if ( (cap->cmdchar == '['
&& vim_strchr((char_u *)"{(*/#mM", cap->nchar) != NULL)
|| (cap->cmdchar == ']'
&& vim_strchr((char_u *)"})*/#mM", cap->nchar) != NULL))
nv_bracket_block(cap, &old_pos);
else if (cap->nchar == '[' || cap->nchar == ']')
{
if (cap->nchar == cap->cmdchar)
flag = '{';
else
flag = '}';
curwin->w_set_curswant = TRUE;
if (!findpar(&cap->oap->inclusive, cap->arg, cap->count1, flag,
(cap->oap->op_type != OP_NOP
&& cap->arg == FORWARD && flag == '{')))
clearopbeep(cap->oap);
else
{
if (cap->oap->op_type == OP_NOP)
beginline(BL_WHITE | BL_FIX);
#ifdef FEAT_FOLDING
if ((fdo_flags & FDO_BLOCK) && KeyTyped && cap->oap->op_type == OP_NOP)
foldOpenCursor();
#endif
}
}
else if (cap->nchar == 'p' || cap->nchar == 'P')
{
nv_put_opt(cap, TRUE);
}
else if (cap->nchar == '\'' || cap->nchar == '`')
{
pos = &curwin->w_cursor;
for (n = cap->count1; n > 0; --n)
{
prev_pos = *pos;
pos = getnextmark(pos, cap->cmdchar == '[' ? BACKWARD : FORWARD,
cap->nchar == '\'');
if (pos == NULL)
break;
}
if (pos == NULL)
pos = &prev_pos;
nv_cursormark(cap, cap->nchar == '\'', pos);
}
else if (cap->nchar >= K_RIGHTRELEASE && cap->nchar <= K_LEFTMOUSE)
{
(void)do_mouse(cap->oap, cap->nchar,
(cap->cmdchar == ']') ? FORWARD : BACKWARD,
cap->count1, PUT_FIXINDENT);
}
#ifdef FEAT_FOLDING
else if (cap->nchar == 'z')
{
if (foldMoveTo(FALSE, cap->cmdchar == ']' ? FORWARD : BACKWARD,
cap->count1) == FAIL)
clearopbeep(cap->oap);
}
#endif
#ifdef FEAT_DIFF
else if (cap->nchar == 'c')
{
if (diff_move_to(cap->cmdchar == ']' ? FORWARD : BACKWARD,
cap->count1) == FAIL)
clearopbeep(cap->oap);
}
#endif
#ifdef FEAT_SPELL
else if (cap->nchar == 's' || cap->nchar == 'S')
{
setpcmark();
for (n = 0; n < cap->count1; ++n)
if (spell_move_to(curwin, cap->cmdchar == ']' ? FORWARD : BACKWARD,
cap->nchar == 's' ? TRUE : FALSE, FALSE, NULL) == 0)
{
clearopbeep(cap->oap);
break;
}
else
curwin->w_set_curswant = TRUE;
# ifdef FEAT_FOLDING
if (cap->oap->op_type == OP_NOP && (fdo_flags & FDO_SEARCH) && KeyTyped)
foldOpenCursor();
# endif
}
#endif
else
clearopbeep(cap->oap);
},1

static pj_status_t init_ossl_lock()
{
pj_status_t status = PJ_SUCCESS;
pj_caching_pool_init(&cp, NULL, 0);
lock_pool = pj_pool_create(&cp.factory,
"ossl-lock",
64,
64,
NULL);
if (!lock_pool) {
status = PJ_ENOMEM;
PJ_PERROR(1, (THIS_FILE, status,"Fail creating OpenSSL lock pool"));
pj_caching_pool_destroy(&cp);
return status;
}
ossl_num_locks = CRYPTO_num_locks();
ossl_locks = (pj_lock_t **)pj_pool_calloc(lock_pool,
ossl_num_locks,
sizeof(pj_lock_t*));
if (ossl_locks) {
unsigned i = 0;
for (; (i < ossl_num_locks) && (status == PJ_SUCCESS); ++i) {
status = pj_lock_create_simple_mutex(lock_pool, "ossl_lock%p",
&ossl_locks[i]);
}
if (status != PJ_SUCCESS) {
PJ_PERROR(1, (THIS_FILE, status,
"Fail creating mutex for OpenSSL lock"));
release_thread_cb();
return status;
}
#if OPENSSL_VERSION_NUMBER >= 0x10000000
CRYPTO_THREADID_set_callback(ossl_set_thread_id);
#else
CRYPTO_set_id_callback(ossl_thread_id);
#endif
CRYPTO_set_locking_callback(ossl_lock);
status = pj_atexit(&release_thread_cb);
if (status != PJ_SUCCESS) {
PJ_PERROR(1, (THIS_FILE, status, "Warning! Unable to set OpenSSL "
"lock thread callback unrelease method."));
}
} else {
status = PJ_ENOMEM;
PJ_PERROR(1, (THIS_FILE, status,"Fail creating OpenSSL locks"));
release_thread_cb();
}
return status;
},0

static PHP_FUNCTION(session_id)
{
char *name = NULL;
int name_len, argc = ZEND_NUM_ARGS();
if (zend_parse_parameters(argc TSRMLS_CC, "|s", &name, &name_len) == FAILURE) {
return;
}
if (PS(id)) {
RETVAL_STRING(PS(id), 1);
} else {
RETVAL_EMPTY_STRING();
}
if (name) {
if (PS(use_strict_mode) && argc) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Set session ID while session.use_strict_mode is enabled");
}
if (PS(id)) {
efree(PS(id));
}
PS(id) = estrndup(name, name_len);
}
},1

void MACH0_(mach_headerfields)(RzBinFile *bf) {
PrintfCallback cb_printf = bf->rbin->cb_printf;
if (!cb_printf) {
cb_printf = printf;
}
RzBuffer *buf = bf->buf;
ut64 length = rz_buf_size(buf);
int n = 0;
struct MACH0_(mach_header) *mh = MACH0_(get_hdr)(buf);
if (!mh) {
return;
}
ut64 pvaddr = pa2va(bf, 0);
cb_printf("pf.mach0_header @ 0x%08" PFMT64x "\n", pvaddr);
cb_printf("0x%08" PFMT64x " Magic 0x%x\n", pvaddr, mh->magic);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " CpuType 0x%x\n", pvaddr, mh->cputype);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " CpuSubType 0x%x\n", pvaddr, mh->cpusubtype);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " FileType 0x%x\n", pvaddr, mh->filetype);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " nCmds %d\n", pvaddr, mh->ncmds);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " sizeOfCmds %d\n", pvaddr, mh->sizeofcmds);
pvaddr += 4;
cb_printf("0x%08" PFMT64x " Flags 0x%x\n", pvaddr, mh->flags);
pvaddr += 4;
bool is64 = mh->cputype >> 16;
ut64 addr = 0x20 - 4;
ut32 word = 0;
ut8 wordbuf[sizeof(word)];
bool isBe = false;
switch (mh->cputype) {
case CPU_TYPE_POWERPC:
case CPU_TYPE_POWERPC64:
isBe = true;
break;
}
#define READWORD() \
if (rz_buf_read_at(buf, addr, (ut8 *)wordbuf, 4) != 4) { \
eprintf("Invalid address in buffer."); \
break; \
} \
addr += 4; \
pvaddr += 4; \
word = isBe ? rz_read_be32(wordbuf) : rz_read_le32(wordbuf);
if (is64) {
addr += 4;
pvaddr += 4;
}
for (n = 0; n < mh->ncmds; n++) {
READWORD();
ut32 lcType = word;
const char *pf_definition = cmd_to_pf_definition(lcType);
if (pf_definition) {
cb_printf("pf.%s @ 0x%08" PFMT64x "\n", pf_definition, pvaddr - 4);
}
cb_printf("0x%08" PFMT64x " cmd %7d 0x%x %s\n",
pvaddr - 4, n, lcType, cmd_to_string(lcType));
READWORD();
if (addr > length) {
break;
}
int lcSize = word;
word &= 0xFFFFFF;
cb_printf("0x%08" PFMT64x " cmdsize %d\n", pvaddr - 4, word);
if (lcSize < 1) {
eprintf("Invalid size for a load command\n");
break;
}
switch (lcType) {
case LC_BUILD_VERSION: {
ut32 platform;
if (!rz_buf_read_le32_at(buf, addr, &platform)) {
break;
}
cb_printf("0x%08" PFMT64x " platform %s\n", pvaddr, build_version_platform_to_string(platform));
ut16 minos1;
if (!rz_buf_read_le16_at(buf, addr + 6, &minos1)) {
break;
}
ut8 minos2;
if (!rz_buf_read8_at(buf, addr + 5, &minos2)) {
break;
}
ut8 minos3;
if (!rz_buf_read8_at(buf, addr + 4, &minos3)) {
break;
}
cb_printf("0x%08" PFMT64x " minos %d.%d.%d\n", pvaddr + 4, minos1, minos2, minos3);
ut16 sdk1;
if (!rz_buf_read_le16_at(buf, addr + 10, &sdk1)) {
break;
}
ut8 sdk2;
if (!rz_buf_read8_at(buf, addr + 9, &sdk2)) {
break;
}
ut8 sdk3;
if (!rz_buf_read8_at(buf, addr + 8, &sdk3)) {
break;
}
cb_printf("0x%08" PFMT64x " sdk %d.%d.%d\n", pvaddr + 8, sdk1, sdk2, sdk3);
ut32 ntools;
if (!rz_buf_read_le32_at(buf, addr + 12, &ntools)) {
break;
}
cb_printf("0x%08" PFMT64x " ntools %d\n", pvaddr + 12, ntools);
ut64 off = 16;
while (off < (lcSize - 8) && ntools--) {
cb_printf("pf.mach0_build_version_tool @ 0x%08" PFMT64x "\n", pvaddr + off);
ut32 tool;
if (!rz_buf_read_le32_at(buf, addr + off, &tool)) {
break;
}
cb_printf("0x%08" PFMT64x " tool %s\n", pvaddr + off, build_version_tool_to_string(tool));
off += 4;
if (off >= (lcSize - 8)) {
break;
}
ut16 version1;
if (!rz_buf_read_le16_at(buf, addr + off + 2, &version1)) {
break;
}
ut8 version2;
if (!rz_buf_read8_at(buf, addr + off + 1, &version2)) {
break;
}
ut8 version3;
if (!rz_buf_read8_at(buf, addr + off, &version3)) {
break;
}
cb_printf("0x%08" PFMT64x " version %d.%d.%d\n", pvaddr + off, version1, version2, version3);
off += 4;
}
break;
}
case LC_MAIN: {
ut8 data[64] = { 0 };
rz_buf_read_at(buf, addr, data, sizeof(data));
#if RZ_BIN_MACH064
ut64 ep = rz_read_ble64(&data, false);
cb_printf("0x%08" PFMT64x " entry0 0x%" PFMT64x "\n", pvaddr, ep);
ut64 ss = rz_read_ble64(&data[8], false);
cb_printf("0x%08" PFMT64x " stacksize 0x%" PFMT64x "\n", pvaddr + 8, ss);
#else
ut32 ep = rz_read_ble32(&data, false);
cb_printf("0x%08" PFMT32x " entry0 0x%" PFMT32x "\n", (ut32)pvaddr, ep);
ut32 ss = rz_read_ble32(&data[4], false);
cb_printf("0x%08" PFMT32x " stacksize 0x%" PFMT32x "\n", (ut32)pvaddr + 4, ss);
#endif
} break;
case LC_SYMTAB:
#if 0
{
char *id = rz_buf_get_string (buf, addr + 20);
cb_printf ("0x%08"PFMT64x" id 0x%x\n", addr + 20, id? id: "");
cb_printf ("0x%08"PFMT64x" symooff 0x%x\n", addr + 20, id? id: "");
cb_printf ("0x%08"PFMT64x" nsyms %d\n", addr + 20, id? id: "");
cb_printf ("0x%08"PFMT64x" stroff 0x%x\n", addr + 20, id? id: "");
cb_printf ("0x%08"PFMT64x" strsize 0x%x\n", addr + 20, id? id: "");
free (id);
}
#endif
break;
case LC_ID_DYLIB: {
ut32 str_off;
if (!rz_buf_read_ble32_at(buf, addr, &str_off, isBe)) {
break;
}
char *id = rz_buf_get_string(buf, addr + str_off - 8);
ut16 current1;
if (!rz_buf_read_le16_at(buf, addr + 10, &current1)) {
free(id);
break;
}
ut8 current2;
if (!rz_buf_read8_at(buf, addr + 9, &current2)) {
free(id);
break;
}
ut8 current3;
if (!rz_buf_read8_at(buf, addr + 8, &current3)) {
free(id);
break;
}
cb_printf("0x%08" PFMT64x " current %d.%d.%d\n", pvaddr + 8, current1, current2, current3);
ut16 compat1;
if (!rz_buf_read_le16_at(buf, addr + 14, &compat1)) {
free(id);
break;
}
ut8 compat2;
if (!rz_buf_read8_at(buf, addr + 13, &compat2)) {
free(id);
break;
}
ut8 compat3;
if (!rz_buf_read8_at(buf, addr + 12, &compat3)) {
free(id);
break;
}
cb_printf("0x%08" PFMT64x " compat %d.%d.%d\n", pvaddr + 12, compat1, compat2, compat3);
cb_printf("0x%08" PFMT64x " id %s\n",
pvaddr + str_off - 8, id ? id : "");
free(id);
break;
}
case LC_UUID: {
ut8 i, uuid[16];
rz_buf_read_at(buf, addr, uuid, sizeof(uuid));
cb_printf("0x%08" PFMT64x " uuid ", pvaddr);
for (i = 0; i < sizeof(uuid); i++) {
cb_printf("%02x", uuid[i]);
}
cb_printf("\n");
} break;
case LC_SEGMENT:
case LC_SEGMENT_64: {
ut8 name[17] = { 0 };
rz_buf_read_at(buf, addr, name, sizeof(name) - 1);
cb_printf("0x%08" PFMT64x " name %s\n", pvaddr, name);
ut32 nsects;
if (!rz_buf_read_le32_at(buf, addr - 8 + (is64 ? 64 : 48), &nsects)) {
break;
}
ut64 off = is64 ? 72 : 56;
while (off < lcSize && nsects--) {
if (is64) {
cb_printf("pf.mach0_section64 @ 0x%08" PFMT64x "\n", pvaddr - 8 + off);
off += 80;
} else {
cb_printf("pf.mach0_section @ 0x%08" PFMT64x "\n", pvaddr - 8 + off);
off += 68;
}
}
} break;
case LC_LOAD_DYLIB:
case LC_LOAD_WEAK_DYLIB: {
ut32 str_off;
if (!rz_buf_read_ble32_at(buf, addr, &str_off, isBe)) {
break;
}
char *load_dylib = rz_buf_get_string(buf, addr + str_off - 8);
ut16 current1;
if (!rz_buf_read_le16_at(buf, addr + 10, &current1)) {
free(load_dylib);
break;
}
ut8 current2;
if (!rz_buf_read8_at(buf, addr + 9, &current2)) {
free(load_dylib);
break;
}
ut8 current3;
if (!rz_buf_read8_at(buf, addr + 8, &current3)) {
free(load_dylib);
break;
}
cb_printf("0x%08" PFMT64x " current %d.%d.%d\n", pvaddr + 8, current1, current2, current3);
ut16 compat1;
if (!rz_buf_read_le16_at(buf, addr + 14, &compat1)) {
free(load_dylib);
break;
}
ut8 compat2;
if (!rz_buf_read8_at(buf, addr + 13, &compat2)) {
free(load_dylib);
break;
}
ut8 compat3;
if (!rz_buf_read8_at(buf, addr + 12, &compat3)) {
free(load_dylib);
break;
}
cb_printf("0x%08" PFMT64x " compat %d.%d.%d\n", pvaddr + 12, compat1, compat2, compat3);
cb_printf("0x%08" PFMT64x " load_dylib %s\n",
pvaddr + str_off - 8, load_dylib ? load_dylib : "");
free(load_dylib);
break;
}
case LC_RPATH: {
char *rpath = rz_buf_get_string(buf, addr + 4);
cb_printf("0x%08" PFMT64x " rpath %s\n",
pvaddr + 4, rpath ? rpath : "");
free(rpath);
break;
}
case LC_ENCRYPTION_INFO:
case LC_ENCRYPTION_INFO_64: {
ut32 word;
if (!rz_buf_read_le32_at(buf, addr, &word)) {
break;
}
cb_printf("0x%08" PFMT64x " cryptoff 0x%08x\n", pvaddr, word);
if (!rz_buf_read_le32_at(buf, addr + 4, &word)) {
break;
}
cb_printf("0x%08" PFMT64x " cryptsize %d\n", pvaddr + 4, word);
if (!rz_buf_read_le32_at(buf, addr + 8, &word)) {
break;
}
cb_printf("0x%08" PFMT64x " cryptid %d\n", pvaddr + 8, word);
break;
}
case LC_CODE_SIGNATURE: {
ut32 words[2];
rz_buf_read_at(buf, addr, (ut8 *)words, sizeof(words));
cb_printf("0x%08" PFMT64x " dataoff 0x%08x\n", pvaddr, words[0]);
cb_printf("0x%08" PFMT64x " datasize %d\n", pvaddr + 4, words[1]);
cb_printf("# wtf mach0.sign %d @ 0x%x\n", words[1], words[0]);
break;
}
}
addr += word - 8;
pvaddr += word - 8;
}
free(mh);
},0

