snprintf (val, maxlen, _("%.02f EV"), d);
snprintf (b, sizeof (b), _(" (%.02f cd/m^2)"),
1. / (M_PI * 0.3048 * 0.3048) * pow (2, d));
strncat (val, b, maxlen-1 - strlen (val));
break;
case EXIF_TAG_FILE_SOURCE:
CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
CC (e, 1, val, maxlen);
v_byte = e->data[0];
if (v_byte == 3)
strncpy (val, _("DSC"), maxlen-1);
else
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_byte);
break;
case EXIF_TAG_COMPONENTS_CONFIGURATION:
CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
CC (e, 4, val, maxlen);
for (i = 0; i < 4; i++) {
switch (e->data[i]) {
case 0: c = _("-"); break;
case 1: c = _("Y"); break;
case 2: c = _("Cb"); break;
case 3: c = _("Cr"); break;
case 4: c = _("R"); break;
case 5: c = _("G"); break;
case 6: c = _("B"); break;
default: c = _("Reserved"); break;
}
strncat (val, c, maxlen-1 - strlen (val));
if (i < 3)
strncat (val, " ", maxlen-1 - strlen (val));
}
break;
case EXIF_TAG_EXPOSURE_BIAS_VALUE:
CF (e, EXIF_FORMAT_SRATIONAL, val, maxlen);
CC (e, 1, val, maxlen);
v_srat = exif_get_srational (e->data, o);
if (!v_srat.denominator) {
exif_entry_format_value(e, val, maxlen);
break;
}
d = (double) v_srat.numerator / (double) v_srat.denominator;
snprintf (val, maxlen, _("%.02f EV"), d);
break;
case EXIF_TAG_SCENE_TYPE:
CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
CC (e, 1, val, maxlen);
v_byte = e->data[0];
if (v_byte == 1)
strncpy (val, _("Directly photographed"), maxlen-1);
else
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_byte);
break;
case EXIF_TAG_YCBCR_SUB_SAMPLING:
CF (e, EXIF_FORMAT_SHORT, val, maxlen);
CC (e, 2, val, maxlen);
v_short = exif_get_short (e->data, o);
v_short2 = exif_get_short (
e->data + exif_format_get_size (e->format),
o);
if ((v_short == 2) && (v_short2 == 1))
strncpy (val, _("YCbCr4:2:2"), maxlen-1);
else if ((v_short == 2) && (v_short2 == 2))
strncpy (val, _("YCbCr4:2:0"), maxlen-1);
else
snprintf (val, maxlen, "%u, %u", v_short, v_short2);
break;
case EXIF_TAG_SUBJECT_AREA:
CF (e, EXIF_FORMAT_SHORT, val, maxlen);
switch (e->components) {
case 2:
v_short = exif_get_short (e->data, o);
v_short2 = exif_get_short (e->data + 2, o);
snprintf (val, maxlen, "(x,y) = (%i,%i)",
v_short, v_short2);
break;
case 3:
v_short = exif_get_short (e->data, o);
v_short2 = exif_get_short (e->data + 2, o);
v_short3 = exif_get_short (e->data + 4, o);
snprintf (val, maxlen, _("Within distance %i of "
"(x,y) = (%i,%i)"), v_short3, v_short,
v_short2);
break;
case 4:
v_short = exif_get_short (e->data, o);
v_short2 = exif_get_short (e->data + 2, o);
v_short3 = exif_get_short (e->data + 4, o);
v_short4 = exif_get_short (e->data + 6, o);
snprintf (val, maxlen, _("Within rectangle "
"(width %i, height %i) around "
"(x,y) = (%i,%i)"), v_short3, v_short4,
v_short, v_short2);
break;
default:
snprintf (val, maxlen, _("Unexpected number "
"of components (%li, expected 2, 3, or 4)."),
e->components);
}
break;
case EXIF_TAG_GPS_VERSION_ID:
CF (e, EXIF_FORMAT_BYTE, val, maxlen);
CC (e, 4, val, maxlen);
v_byte = e->data[0];
snprintf (val, maxlen, "%u", v_byte);
for (i = 1; i < e->components; i++) {
v_byte = e->data[i];
snprintf (b, sizeof (b), ".%u", v_byte);
strncat (val, b, maxlen-1 - strlen (val));
}
break;
case EXIF_TAG_INTEROPERABILITY_VERSION:
if (e->format == EXIF_FORMAT_UNDEFINED) {
strncpy (val, (char *) e->data, MIN (maxlen-1, e->size));
break;
}
exif_entry_format_value(e, val, maxlen);
break;
case EXIF_TAG_GPS_ALTITUDE_REF:
CF (e, EXIF_FORMAT_BYTE, val, maxlen);
CC (e, 1, val, maxlen);
v_byte = e->data[0];
if (v_byte == 0)
strncpy (val, _("Sea level"), maxlen-1);
else if (v_byte == 1)
strncpy (val, _("Sea level reference"), maxlen-1);
else
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_byte);
break;
case EXIF_TAG_GPS_TIME_STAMP:
CF (e, EXIF_FORMAT_RATIONAL, val, maxlen);
CC (e, 3, val, maxlen);
v_rat = exif_get_rational (e->data, o);
if (!v_rat.denominator) {
exif_entry_format_value(e, val, maxlen);
break;
}
i = v_rat.numerator / v_rat.denominator;
v_rat = exif_get_rational (e->data +
exif_format_get_size (e->format),
o);
if (!v_rat.denominator) {
exif_entry_format_value(e, val, maxlen);
break;
}
j = v_rat.numerator / v_rat.denominator;
v_rat = exif_get_rational (e->data +
2*exif_format_get_size (e->format),
o);
if (!v_rat.denominator) {
exif_entry_format_value(e, val, maxlen);
break;
}
d = (double) v_rat.numerator / (double) v_rat.denominator;
snprintf (val, maxlen, "%02u:%02u:%05.2f", i, j, d);
break;
case EXIF_TAG_METERING_MODE:
case EXIF_TAG_COMPRESSION:
case EXIF_TAG_LIGHT_SOURCE:
case EXIF_TAG_FOCAL_PLANE_RESOLUTION_UNIT:
case EXIF_TAG_RESOLUTION_UNIT:
case EXIF_TAG_EXPOSURE_PROGRAM:
case EXIF_TAG_FLASH:
case EXIF_TAG_SUBJECT_DISTANCE_RANGE:
case EXIF_TAG_COLOR_SPACE:
CF (e,EXIF_FORMAT_SHORT, val, maxlen);
CC (e, 1, val, maxlen);
v_short = exif_get_short (e->data, o);
for (i = 0; list2[i].tag && (list2[i].tag != e->tag); i++);
if (!list2[i].tag) {
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_short);
break;
}
for (j = 0; list2[i].elem[j].values[0] &&
(list2[i].elem[j].index < v_short); j++);
if (list2[i].elem[j].index != v_short) {
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_short);
break;
}
memset (val, 0, maxlen);
for (k = 0; list2[i].elem[j].values[k]; k++) {
size_t l = strlen (_(list2[i].elem[j].values[k]));
if ((maxlen > l) && (strlen (val) < l))
strncpy (val, _(list2[i].elem[j].values[k]), maxlen-1);
}
if (!val[0]) snprintf (val, maxlen, "%i", v_short);
break;
case EXIF_TAG_PLANAR_CONFIGURATION:
case EXIF_TAG_SENSING_METHOD:
case EXIF_TAG_ORIENTATION:
case EXIF_TAG_YCBCR_POSITIONING:
case EXIF_TAG_PHOTOMETRIC_INTERPRETATION:
case EXIF_TAG_CUSTOM_RENDERED:
case EXIF_TAG_EXPOSURE_MODE:
case EXIF_TAG_WHITE_BALANCE:
case EXIF_TAG_SCENE_CAPTURE_TYPE:
case EXIF_TAG_GAIN_CONTROL:
case EXIF_TAG_SATURATION:
case EXIF_TAG_CONTRAST:
case EXIF_TAG_SHARPNESS:
CF (e, EXIF_FORMAT_SHORT, val, maxlen);
CC (e, 1, val, maxlen);
v_short = exif_get_short (e->data, o);
for (i = 0; list[i].tag && (list[i].tag != e->tag); i++);
if (!list[i].tag) {
snprintf (val, maxlen, _("Internal error (unknown "
"value %i)"), v_short);
break;
}
for (j = 0; list[i].strings[j] && (j < v_short); j++);
if (!list[i].strings[j])
snprintf (val, maxlen, "%i", v_short);
else if (!*list[i].strings[j])
snprintf (val, maxlen, _("Unknown value %i"), v_short);
else
strncpy (val, _(list[i].strings[j]), maxlen-1);
break;
case EXIF_TAG_XP_TITLE:
case EXIF_TAG_XP_COMMENT:
case EXIF_TAG_XP_AUTHOR:
case EXIF_TAG_XP_KEYWORDS:
case EXIF_TAG_XP_SUBJECT:
{
unsigned short *utf16;
if (e->size+sizeof(unsigned short) < e->size) break;
utf16 = exif_mem_alloc (e->priv->mem, e->size+sizeof(unsigned short));
if (!utf16) break;
memcpy(utf16, e->data, e->size);
utf16[e->size/sizeof(unsigned short)] = 0;
exif_convert_utf16_to_utf8(val, utf16, maxlen);
exif_mem_free(e->priv->mem, utf16);
break;
}
default:
exif_entry_format_value(e, val, maxlen);
}
return val;
},1

void CWebServer::Cmd_UpdateMobileDevice(WebEmSession & session, const request& req, Json::Value &root)
{
if (session.rights != 2)
{
session.reply_status = reply::forbidden;
return;
}
std::string sidx = request::findValue(&req, "idx");
std::string enabled = request::findValue(&req, "enabled");
std::string name = request::findValue(&req, "name");
if (
(sidx.empty()) ||
(enabled.empty()) ||
(name.empty())
)
return;
uint64_t idx = std::strtoull(sidx.c_str(), nullptr, 10);
m_sql.safe_query("UPDATE MobileDevices SET Name='%q', Active=%d WHERE (ID==%" PRIu64 ")",
name.c_str(), (enabled == "true") ? 1 : 0, idx);
root["status"] = "OK";
root["title"] = "UpdateMobile";
},0

struct ea_list *read_nttrans_ea_list(TALLOC_CTX *ctx, const char *pdata, size_t data_size)
{
struct ea_list *ea_list_head = NULL;
size_t offset = 0;
if (data_size < 4) {
return NULL;
}
while (offset + 4 <= data_size) {
size_t next_offset = IVAL(pdata,offset);
struct ea_list *eal = read_ea_list_entry(ctx, pdata + offset + 4, data_size - offset - 4, NULL);
if (!eal) {
return NULL;
}
DLIST_ADD_END(ea_list_head, eal, struct ea_list *);
if (next_offset == 0) {
break;
}
offset += next_offset;
}
return ea_list_head;
},1

static int l2cap_sock_bind(struct socket *sock, struct sockaddr *addr, int alen)
{
struct sock *sk = sock->sk;
struct l2cap_chan *chan = l2cap_pi(sk)->chan;
struct sockaddr_l2 la;
int len, err = 0;
BT_DBG("sk %p", sk);
if (!addr || alen < offsetofend(struct sockaddr, sa_family) ||
addr->sa_family != AF_BLUETOOTH)
return -EINVAL;
memset(&la, 0, sizeof(la));
len = min_t(unsigned int, sizeof(la), alen);
memcpy(&la, addr, len);
if (la.l2_cid && la.l2_psm)
return -EINVAL;
if (!bdaddr_type_is_valid(la.l2_bdaddr_type))
return -EINVAL;
if (bdaddr_type_is_le(la.l2_bdaddr_type)) {
if (la.l2_cid &&
la.l2_cid != cpu_to_le16(L2CAP_CID_ATT))
return -EINVAL;
}
lock_sock(sk);
if (sk->sk_state != BT_OPEN) {
err = -EBADFD;
goto done;
}
if (la.l2_psm) {
__u16 psm = __le16_to_cpu(la.l2_psm);
if (la.l2_bdaddr_type == BDADDR_BREDR)
err = l2cap_validate_bredr_psm(psm);
else
err = l2cap_validate_le_psm(psm);
if (err)
goto done;
}
bacpy(&chan->src, &la.l2_bdaddr);
chan->src_type = la.l2_bdaddr_type;
if (la.l2_cid)
err = l2cap_add_scid(chan, __le16_to_cpu(la.l2_cid));
else
err = l2cap_add_psm(chan, &la.l2_bdaddr, la.l2_psm);
if (err < 0)
goto done;
switch (chan->chan_type) {
case L2CAP_CHAN_CONN_LESS:
if (__le16_to_cpu(la.l2_psm) == L2CAP_PSM_3DSP)
chan->sec_level = BT_SECURITY_SDP;
break;
case L2CAP_CHAN_CONN_ORIENTED:
if (__le16_to_cpu(la.l2_psm) == L2CAP_PSM_SDP ||
__le16_to_cpu(la.l2_psm) == L2CAP_PSM_RFCOMM)
chan->sec_level = BT_SECURITY_SDP;
break;
case L2CAP_CHAN_RAW:
chan->sec_level = BT_SECURITY_SDP;
break;
case L2CAP_CHAN_FIXED:
set_bit(FLAG_HOLD_HCI_CONN, &chan->flags);
break;
}
if (chan->psm && bdaddr_type_is_le(chan->src_type))
chan->mode = L2CAP_MODE_LE_FLOWCTL;
chan->state = BT_BOUND;
sk->sk_state = BT_BOUND;
done:
release_sock(sk);
return err;
},0

_gnutls_remove_unwanted_ciphersuites (gnutls_session_t session,
cipher_suite_st ** cipherSuites,
int numCipherSuites,
gnutls_pk_algorithm_t requested_pk_algo)
{
int ret = 0;
cipher_suite_st *newSuite, cs;
int newSuiteSize = 0, i;
gnutls_certificate_credentials_t cert_cred;
gnutls_kx_algorithm_t kx;
int server = session->security_parameters.entity == GNUTLS_SERVER ? 1 : 0;
gnutls_kx_algorithm_t *alg = NULL;
int alg_size = 0;
cert_cred =
(gnutls_certificate_credentials_t) _gnutls_get_cred (session->key,
GNUTLS_CRD_CERTIFICATE,
NULL);
if (session->security_parameters.entity == GNUTLS_SERVER
&& cert_cred != NULL)
{
ret = _gnutls_server_select_cert (session, requested_pk_algo);
if (ret < 0)
{
gnutls_assert ();
_gnutls_x509_log("Could not find an appropriate certificate: %s\n", gnutls_strerror(ret));
cert_cred = NULL;
}
}
if ((ret =
_gnutls_selected_cert_supported_kx (session, &alg, &alg_size)) < 0)
{
gnutls_assert ();
return ret;
}
newSuite = gnutls_malloc (numCipherSuites * sizeof (cipher_suite_st));
if (newSuite == NULL)
{
gnutls_assert ();
gnutls_free (alg);
return GNUTLS_E_MEMORY_ERROR;
}
for (i = 0; i < numCipherSuites; i++)
{
int delete = 0;
kx = _gnutls_cipher_suite_get_kx_algo (&(*cipherSuites)[i]);
if (_gnutls_get_kx_cred (session, kx, NULL) == NULL)
{
delete = 1;
}
else
{
delete = 0;
if (server)
delete = check_server_params (session, kx, alg, alg_size);
}
if (kx == GNUTLS_KX_SRP_RSA || kx == GNUTLS_KX_SRP_DSS)
{
if (!_gnutls_get_cred (session->key, GNUTLS_CRD_SRP, NULL))
delete = 1;
}
memcpy (&cs.suite, &(*cipherSuites)[i].suite, 2);
if (delete == 0)
{
_gnutls_handshake_log ("HSK[%x]: Keeping ciphersuite: %s\n",
session,
_gnutls_cipher_suite_get_name (&cs));
memcpy (newSuite[newSuiteSize].suite, (*cipherSuites)[i].suite, 2);
newSuiteSize++;
}
else
{
_gnutls_handshake_log ("HSK[%x]: Removing ciphersuite: %s\n",
session,
_gnutls_cipher_suite_get_name (&cs));
}
}
gnutls_free (alg);
gnutls_free (*cipherSuites);
*cipherSuites = newSuite;
ret = newSuiteSize;
return ret;
},0

nm_gconf_read_connection (GConfClient *client,
const char *dir)
{
ReadFromGConfInfo info;
GSList *list;
GError *err = NULL;
list = gconf_client_all_dirs (client, dir, &err);
if (err) {
g_warning ("Error while reading connection: %s", err->message);
g_error_free (err);
return NULL;
}
if (!list) {
g_warning ("Invalid connection (empty)");
return NULL;
}
info.connection = nm_connection_new ();
info.client = client;
info.dir = dir;
info.dir_len = strlen (dir);
g_slist_foreach (list, read_one_setting, &info);
g_slist_free (list);
return info.connection;
},1

findmatchlimit(
oparg_T *oap,
int initc,
int flags,
int maxtravel)
{
static pos_T pos;
int findc = 0;
int c;
int count = 0;
int backwards = FALSE;
int raw_string = FALSE;
int inquote = FALSE;
char_u *linep;
char_u *ptr;
int do_quotes;
int at_start;
int hash_dir = 0;
int comment_dir = 0;
pos_T match_pos;
int start_in_quotes;
int traveled = 0;
int ignore_cend = FALSE;
int cpo_match;
int cpo_bsl;
int match_escaped = 0;
int dir;
int comment_col = MAXCOL;
int lispcomm = FALSE;
int lisp = curbuf->b_p_lisp;
pos = curwin->w_cursor;
pos.coladd = 0;
linep = ml_get(pos.lnum);
cpo_match = (vim_strchr(p_cpo, CPO_MATCH) != NULL);
cpo_bsl = (vim_strchr(p_cpo, CPO_MATCHBSL) != NULL);
if (flags & FM_BACKWARD)
dir = BACKWARD;
else if (flags & FM_FORWARD)
dir = FORWARD;
else
dir = 0;
if (initc == '/' || initc == '*' || initc == 'R')
{
comment_dir = dir;
if (initc == '/')
ignore_cend = TRUE;
backwards = (dir == FORWARD) ? FALSE : TRUE;
raw_string = (initc == 'R');
initc = NUL;
}
else if (initc != '#' && initc != NUL)
{
find_mps_values(&initc, &findc, &backwards, TRUE);
if (dir)
backwards = (dir == FORWARD) ? FALSE : TRUE;
if (findc == NUL)
return NULL;
}
else
{
if (initc == '#')
{
hash_dir = dir;
}
else
{
if (!cpo_match)
{
ptr = skipwhite(linep);
if (*ptr == '#' && pos.col <= (colnr_T)(ptr - linep))
{
ptr = skipwhite(ptr + 1);
if ( STRNCMP(ptr, "if", 2) == 0
|| STRNCMP(ptr, "endif", 5) == 0
|| STRNCMP(ptr, "el", 2) == 0)
hash_dir = 1;
}
else if (linep[pos.col] == '/')
{
if (linep[pos.col + 1] == '*')
{
comment_dir = FORWARD;
backwards = FALSE;
pos.col++;
}
else if (pos.col > 0 && linep[pos.col - 1] == '*')
{
comment_dir = BACKWARD;
backwards = TRUE;
pos.col--;
}
}
else if (linep[pos.col] == '*')
{
if (linep[pos.col + 1] == '/')
{
comment_dir = BACKWARD;
backwards = TRUE;
}
else if (pos.col > 0 && linep[pos.col - 1] == '/')
{
comment_dir = FORWARD;
backwards = FALSE;
}
}
}
if (!hash_dir && !comment_dir)
{
if (linep[pos.col] == NUL && pos.col)
--pos.col;
for (;;)
{
initc = PTR2CHAR(linep + pos.col);
if (initc == NUL)
break;
find_mps_values(&initc, &findc, &backwards, FALSE);
if (findc)
break;
pos.col += mb_ptr2len(linep + pos.col);
}
if (!findc)
{
if (!cpo_match && *skipwhite(linep) == '#')
hash_dir = 1;
else
return NULL;
}
else if (!cpo_bsl)
{
int col, bslcnt = 0;
for (col = pos.col; check_prevcol(linep, col, '\\', &col);)
bslcnt++;
match_escaped = (bslcnt & 1);
}
}
}
if (hash_dir)
{
if (oap != NULL)
oap->motion_type = MLINE;
if (initc != '#')
{
ptr = skipwhite(skipwhite(linep) + 1);
if (STRNCMP(ptr, "if", 2) == 0 || STRNCMP(ptr, "el", 2) == 0)
hash_dir = 1;
else if (STRNCMP(ptr, "endif", 5) == 0)
hash_dir = -1;
else
return NULL;
}
pos.col = 0;
while (!got_int)
{
if (hash_dir > 0)
{
if (pos.lnum == curbuf->b_ml.ml_line_count)
break;
}
else if (pos.lnum == 1)
break;
pos.lnum += hash_dir;
linep = ml_get(pos.lnum);
line_breakcheck();
ptr = skipwhite(linep);
if (*ptr != '#')
continue;
pos.col = (colnr_T) (ptr - linep);
ptr = skipwhite(ptr + 1);
if (hash_dir > 0)
{
if (STRNCMP(ptr, "if", 2) == 0)
count++;
else if (STRNCMP(ptr, "el", 2) == 0)
{
if (count == 0)
return &pos;
}
else if (STRNCMP(ptr, "endif", 5) == 0)
{
if (count == 0)
return &pos;
count--;
}
}
else
{
if (STRNCMP(ptr, "if", 2) == 0)
{
if (count == 0)
return &pos;
count--;
}
else if (initc == '#' && STRNCMP(ptr, "el", 2) == 0)
{
if (count == 0)
return &pos;
}
else if (STRNCMP(ptr, "endif", 5) == 0)
count++;
}
}
return NULL;
}
}
#ifdef FEAT_RIGHTLEFT
if (curwin->w_p_rl && vim_strchr((char_u *)"()[]{}<>", initc) != NULL)
backwards = !backwards;
#endif
do_quotes = -1;
start_in_quotes = MAYBE;
CLEAR_POS(&match_pos);
if ((backwards && comment_dir) || lisp)
comment_col = check_linecomment(linep);
if (lisp && comment_col != MAXCOL && pos.col > (colnr_T)comment_col)
lispcomm = TRUE;
while (!got_int)
{
if (backwards)
{
if (lispcomm && pos.col < (colnr_T)comment_col)
break;
if (pos.col == 0)
{
if (pos.lnum == 1)
break;
--pos.lnum;
if (maxtravel > 0 && ++traveled > maxtravel)
break;
linep = ml_get(pos.lnum);
pos.col = (colnr_T)STRLEN(linep);
do_quotes = -1;
line_breakcheck();
if (comment_dir || lisp)
comment_col = check_linecomment(linep);
if (lisp && comment_col != MAXCOL)
pos.col = comment_col;
}
else
{
--pos.col;
if (has_mbyte)
pos.col -= (*mb_head_off)(linep, linep + pos.col);
}
}
else
{
if (linep[pos.col] == NUL
|| (lisp && comment_col != MAXCOL
&& pos.col == (colnr_T)comment_col))
{
if (pos.lnum == curbuf->b_ml.ml_line_count
|| lispcomm)
break;
++pos.lnum;
if (maxtravel && traveled++ > maxtravel)
break;
linep = ml_get(pos.lnum);
pos.col = 0;
do_quotes = -1;
line_breakcheck();
if (lisp)
comment_col = check_linecomment(linep);
}
else
{
if (has_mbyte)
pos.col += (*mb_ptr2len)(linep + pos.col);
else
++pos.col;
}
}
if (pos.col == 0 && (flags & FM_BLOCKSTOP)
&& (linep[0] == '{' || linep[0] == '}'))
{
if (linep[0] == findc && count == 0)
return &pos;
break;
}
if (comment_dir)
{
if (comment_dir == FORWARD)
{
if (linep[pos.col] == '*' && linep[pos.col + 1] == '/')
{
pos.col++;
return &pos;
}
}
else
{
if (pos.col == 0)
continue;
else if (raw_string)
{
if (linep[pos.col - 1] == 'R'
&& linep[pos.col] == '"'
&& vim_strchr(linep + pos.col + 1, '(') != NULL)
{
if (!find_rawstring_end(linep, &pos,
count > 0 ? &match_pos : &curwin->w_cursor))
{
count++;
match_pos = pos;
match_pos.col--;
}
linep = ml_get(pos.lnum);
}
}
else if ( linep[pos.col - 1] == '/'
&& linep[pos.col] == '*'
&& (pos.col == 1 || linep[pos.col - 2] != '*')
&& (int)pos.col < comment_col)
{
count++;
match_pos = pos;
match_pos.col--;
}
else if (linep[pos.col - 1] == '*' && linep[pos.col] == '/')
{
if (count > 0)
pos = match_pos;
else if (pos.col > 1 && linep[pos.col - 2] == '/'
&& (int)pos.col <= comment_col)
pos.col -= 2;
else if (ignore_cend)
continue;
else
return NULL;
return &pos;
}
}
continue;
}
if (cpo_match)
do_quotes = 0;
else if (do_quotes == -1)
{
at_start = do_quotes;
for (ptr = linep; *ptr; ++ptr)
{
if (ptr == linep + pos.col + backwards)
at_start = (do_quotes & 1);
if (*ptr == '"'
&& (ptr == linep || ptr[-1] != '\'' || ptr[1] != '\''))
++do_quotes;
if (*ptr == '\\' && ptr[1] != NUL)
++ptr;
}
do_quotes &= 1;
if (!do_quotes)
{
inquote = FALSE;
if (ptr[-1] == '\\')
{
do_quotes = 1;
if (start_in_quotes == MAYBE)
{
inquote = TRUE;
start_in_quotes = TRUE;
}
else if (backwards)
inquote = TRUE;
}
if (pos.lnum > 1)
{
ptr = ml_get(pos.lnum - 1);
if (*ptr && *(ptr + STRLEN(ptr) - 1) == '\\')
{
do_quotes = 1;
if (start_in_quotes == MAYBE)
{
inquote = at_start;
if (inquote)
start_in_quotes = TRUE;
}
else if (!backwards)
inquote = TRUE;
}
linep = ml_get(pos.lnum);
}
}
}
if (start_in_quotes == MAYBE)
start_in_quotes = FALSE;
c = PTR2CHAR(linep + pos.col);
switch (c)
{
case NUL:
if (pos.col == 0 || linep[pos.col - 1] != '\\')
{
inquote = FALSE;
start_in_quotes = FALSE;
}
break;
case '"':
if (do_quotes)
{
int col;
for (col = pos.col - 1; col >= 0; --col)
if (linep[col] != '\\')
break;
if ((((int)pos.col - 1 - col) & 1) == 0)
{
inquote = !inquote;
start_in_quotes = FALSE;
}
}
break;
case '\'':
if (!cpo_match && initc != '\'' && findc != '\'')
{
if (backwards)
{
if (pos.col > 1)
{
if (linep[pos.col - 2] == '\'')
{
pos.col -= 2;
break;
}
else if (linep[pos.col - 2] == '\\'
&& pos.col > 2 && linep[pos.col - 3] == '\'')
{
pos.col -= 3;
break;
}
}
}
else if (linep[pos.col + 1])
{
if (linep[pos.col + 1] == '\\'
&& linep[pos.col + 2] && linep[pos.col + 3] == '\'')
{
pos.col += 3;
break;
}
else if (linep[pos.col + 2] == '\'')
{
pos.col += 2;
break;
}
}
}
default:
if (curbuf->b_p_lisp
&& vim_strchr((char_u *)"(){}[]", c) != NULL
&& pos.col > 1
&& check_prevcol(linep, pos.col, '\\', NULL)
&& check_prevcol(linep, pos.col - 1, '#', NULL))
break;
if ((!inquote || start_in_quotes == TRUE)
&& (c == initc || c == findc))
{
int col, bslcnt = 0;
if (!cpo_bsl)
{
for (col = pos.col; check_prevcol(linep, col, '\\', &col);)
bslcnt++;
}
if (cpo_bsl || (bslcnt & 1) == match_escaped)
{
if (c == initc)
count++;
else
{
if (count == 0)
return &pos;
count--;
}
}
}
}
}
if (comment_dir == BACKWARD && count > 0)
{
pos = match_pos;
return &pos;
}
return (pos_T *)NULL;
