find_matching_request_by_fid(struct mswsp_ct *ct, packet_info *pinfo, guint32 msg, gboolean in, void *private_data)
{
guint32 fid = 0;
guint frame = 0;
GSList *iter;
int *p_smb_level = (int*)p_get_proto_data(wmem_file_scope(), pinfo, proto_mswsp, 0);
struct message_data *result = NULL;
get_fid_and_frame(pinfo, &fid, &frame, private_data);
for (iter = ct->GSL_message_data; iter; iter = iter->next) {
struct message_data* data = (struct message_data*)iter->data;
if (data->frame < frame && data->fid == fid && data->is_request == in
&& data->msg_id == msg && data->smb_level == *p_smb_level) {
result = data;
break;
}
}
return result;
},0

static RList* sections(RBinFile *bf) {
struct Elf_(r_bin_elf_obj_t)* obj = (bf && bf->o)? bf->o->bin_obj : NULL;
struct r_bin_elf_section_t *section = NULL;
int i, num, found_load = 0;
Elf_(Phdr)* phdr = NULL;
RBinSection *ptr = NULL;
RList *ret = NULL;
if (!obj || !(ret = r_list_newf (free))) {
return NULL;
}
if ((section = Elf_(r_bin_elf_get_sections) (obj))) {
for (i = 0; !section[i].last; i++) {
if (!(ptr = R_NEW0 (RBinSection))) {
break;
}
strncpy (ptr->name, (char*)section[i].name, R_BIN_SIZEOF_STRINGS);
if (strstr (ptr->name, "data") && !strstr (ptr->name, "rel")) {
ptr->is_data = true;
}
ptr->size = section[i].type != SHT_NOBITS ? section[i].size : 0;
ptr->vsize = section[i].size;
ptr->paddr = section[i].offset;
ptr->vaddr = section[i].rva;
ptr->add = !obj->phdr;
ptr->srwx = 0;
if (R_BIN_ELF_SCN_IS_EXECUTABLE (section[i].flags)) {
ptr->srwx |= R_BIN_SCN_EXECUTABLE;
}
if (R_BIN_ELF_SCN_IS_WRITABLE (section[i].flags)) {
ptr->srwx |= R_BIN_SCN_WRITABLE;
}
if (R_BIN_ELF_SCN_IS_READABLE (section[i].flags)) {
ptr->srwx |= R_BIN_SCN_READABLE;
}
r_list_append (ret, ptr);
}
}
num = obj->ehdr.e_phnum;
phdr = obj->phdr;
if (phdr) {
int n = 0;
for (i = 0; i < num; i++) {
if (!(ptr = R_NEW0 (RBinSection))) {
return ret;
}
ptr->add = false;
ptr->size = phdr[i].p_filesz;
ptr->vsize = phdr[i].p_memsz;
ptr->paddr = phdr[i].p_offset;
ptr->vaddr = phdr[i].p_vaddr;
ptr->srwx = phdr[i].p_flags;
switch (phdr[i].p_type) {
case PT_DYNAMIC:
strncpy (ptr->name, "DYNAMIC", R_BIN_SIZEOF_STRINGS);
break;
case PT_LOAD:
snprintf (ptr->name, R_BIN_SIZEOF_STRINGS, "LOAD%d", n++);
found_load = 1;
ptr->add = true;
break;
case PT_INTERP:
strncpy (ptr->name, "INTERP", R_BIN_SIZEOF_STRINGS);
break;
case PT_GNU_STACK:
strncpy (ptr->name, "GNU_STACK", R_BIN_SIZEOF_STRINGS);
break;
case PT_GNU_RELRO:
strncpy (ptr->name, "GNU_RELRO", R_BIN_SIZEOF_STRINGS);
break;
case PT_GNU_EH_FRAME:
strncpy (ptr->name, "GNU_EH_FRAME", R_BIN_SIZEOF_STRINGS);
break;
case PT_PHDR:
strncpy (ptr->name, "PHDR", R_BIN_SIZEOF_STRINGS);
break;
case PT_TLS:
strncpy (ptr->name, "TLS", R_BIN_SIZEOF_STRINGS);
break;
case PT_NOTE:
strncpy (ptr->name, "NOTE", R_BIN_SIZEOF_STRINGS);
break;
default:
strncpy (ptr->name, "UNKNOWN", R_BIN_SIZEOF_STRINGS);
break;
}
ptr->name[R_BIN_SIZEOF_STRINGS - 1] = '\0';
r_list_append (ret, ptr);
}
}
if (r_list_empty (ret)) {
if (!bf->size) {
struct Elf_(r_bin_elf_obj_t) *bin = bf->o->bin_obj;
bf->size = bin? bin->size: 0x9999;
}
if (found_load == 0) {
if (!(ptr = R_NEW0 (RBinSection))) {
return ret;
}
sprintf (ptr->name, "uphdr");
ptr->size = bf->size;
ptr->vsize = bf->size;
ptr->paddr = 0;
ptr->vaddr = 0x10000;
ptr->add = true;
ptr->srwx = R_BIN_SCN_READABLE | R_BIN_SCN_WRITABLE |
R_BIN_SCN_EXECUTABLE;
r_list_append (ret, ptr);
}
}
ptr = R_NEW0 (RBinSection);
if (ptr) {
ut64 ehdr_size = sizeof (obj->ehdr);
if (bf->size < ehdr_size) {
ehdr_size = bf->size;
}
sprintf (ptr->name, "ehdr");
ptr->paddr = 0;
ptr->vaddr = obj->baddr;
ptr->size = ehdr_size;
ptr->vsize = ehdr_size;
ptr->add = false;
if (obj->ehdr.e_type == ET_REL) {
ptr->add = true;
}
ptr->srwx = R_BIN_SCN_READABLE | R_BIN_SCN_WRITABLE;
r_list_append (ret, ptr);
}
return ret;
},0

int rad_packet_recv(int fd, struct rad_packet_t **p, struct sockaddr_in *addr)
{
struct rad_packet_t *pack;
struct rad_attr_t *attr;
struct rad_dict_attr_t *da;
struct rad_dict_vendor_t *vendor;
uint8_t *ptr;
int n, id, len, vendor_id;
socklen_t addr_len = sizeof(*addr);
*p = NULL;
pack = rad_packet_alloc(0);
if (!pack)
return 0;
ptr = mempool_alloc(buf_pool);
if (ptr == MAP_FAILED) {
log_emerg("radius:packet: out of memory\n");
goto out_err;
}
pack->buf = ptr;
clock_gettime(CLOCK_MONOTONIC, &pack->tv);
while (1) {
if (addr)
n = recvfrom(fd, pack->buf, REQ_LENGTH_MAX, 0, addr, &addr_len);
else
n = read(fd, pack->buf, REQ_LENGTH_MAX);
if (n < 0) {
rad_packet_free(pack);
if (errno == EAGAIN)
return 1;
if (errno != ECONNREFUSED)
log_ppp_error("radius:packet:read: %s\n", strerror(errno));
return -1;
}
break;
}
if (n < 20) {
log_ppp_warn("radius:packet: short packed received (%i)\n", n);
goto out_err;
}
pack->code = *ptr; ptr++;
pack->id = *ptr; ptr++;
pack->len = ntohs(*(uint16_t*)ptr); ptr += 2;
if (pack->len > n) {
log_ppp_warn("radius:packet: short packet received %i, expected %i\n", pack->len, n);
goto out_err;
}
ptr += 16;
n -= 20;
while (n>0) {
id = *ptr; ptr++;
len = *ptr - 2; ptr++;
if (len < 0) {
log_ppp_warn("radius:packet short attribute len received\n");
goto out_err;
}
if (2 + len > n) {
log_ppp_warn("radius:packet: too long attribute received (%i, %i)\n", id, len);
goto out_err;
}
if (id == 26) {
vendor_id = ntohl(*(uint32_t *)ptr);
vendor = rad_dict_find_vendor_id(vendor_id);
if (vendor) {
ptr += 4;
if (vendor->tag == 2)
id = (uint16_t)ntohs(*(uint16_t *)ptr);
else
id = *ptr;
ptr += vendor->tag;
if (vendor->len == 2)
len = (uint16_t)ntohs(*(uint16_t *)ptr);
else
len = *ptr;
ptr += vendor->len;
len -= vendor->tag + vendor->len;
n -= 4 + vendor->tag + vendor->len;
} else
log_ppp_warn("radius:packet: vendor %i not found\n", id);
} else
vendor = NULL;
da = rad_dict_find_attr_id(vendor, id);
if (da) {
attr = mempool_alloc(attr_pool);
if (!attr) {
log_emerg("radius:packet: out of memory\n");
goto out_err;
}
memset(attr, 0, sizeof(*attr));
attr->vendor = vendor;
attr->attr = da;
attr->len = len;
attr->raw = ptr;
if (!da->array) {
switch (da->type) {
case ATTR_TYPE_STRING:
attr->alloc = 1;
attr->val.string = _malloc(len + 1);
memcpy(attr->val.string, ptr, len);
attr->val.string[len] = 0;
break;
case ATTR_TYPE_OCTETS:
case ATTR_TYPE_ETHER:
case ATTR_TYPE_TLV:
attr->val.octets = ptr;
break;
case ATTR_TYPE_INTEGER:
if (len != da->size)
log_ppp_warn("radius:packet: attribute %s has invalid length %i (must be %i)\n", da->name, len, da->size);
case ATTR_TYPE_DATE:
if (len == 4)
attr->val.integer = ntohl(*(uint32_t*)ptr);
else if (len == 2)
attr->val.integer = ntohs(*(uint16_t*)ptr);
else if (len == 1)
attr->val.integer = *ptr;
break;
case ATTR_TYPE_IPADDR:
case ATTR_TYPE_IFID:
case ATTR_TYPE_IPV6ADDR:
memcpy(&attr->val.integer, ptr, len);
break;
case ATTR_TYPE_IPV6PREFIX:
attr->val.ipv6prefix.len = ptr[1];
memset(&attr->val.ipv6prefix.prefix, 0, sizeof(attr->val.ipv6prefix.prefix));
memcpy(&attr->val.ipv6prefix.prefix, ptr + 2, len - 2);
break;
}
}
list_add_tail(&attr->entry, &pack->attrs);
} else
log_ppp_warn("radius:packet: unknown attribute received (%i,%i)\n", vendor ? vendor->id : 0, id);
ptr += len;
n -= 2 + len;
}
*p = pack;
return 0;
out_err:
