}
cert_host = cinfo;
sign_digest = cinfo->digest;
sign_siglen = EVP_PKEY_size(sign_pkey);
if (cinfo->flags & CERT_PRIV)
crypto_flags |= CRYPTO_FLAG_PRIV;
if (strcmp(cinfo->subject, cinfo->issuer) != 0) {
