static ssize_t state_show(struct device *dev, struct device_attribute *attr,
char *buf)
{
struct memory_block *mem = to_memory_block(dev);
ssize_t len = 0;
switch (mem->state) {
case MEM_ONLINE:
len = sprintf(buf, "online\n");
break;
case MEM_OFFLINE:
len = sprintf(buf, "offline\n");
break;
case MEM_GOING_OFFLINE:
len = sprintf(buf, "going-offline\n");
break;
default:
len = sprintf(buf, "ERROR-UNKNOWN-%ld\n",
mem->state);
WARN_ON(1);
break;
}
return len;
},1

GF_ISMASample *gf_isom_get_ismacryp_sample(GF_ISOFile *the_file, u32 trackNumber, const GF_ISOSample *samp, u32 sampleDescriptionIndex)
{
GF_TrackBox *trak;
GF_ISMASampleFormatBox *fmt;
GF_ProtectionSchemeInfoBox *sinf;
trak = gf_isom_get_track_from_file(the_file, trackNumber);
if (!trak) return NULL;
sinf = isom_get_sinf_entry(trak, sampleDescriptionIndex, 0, NULL);
if (!sinf) return NULL;
if (sinf->scheme_type->scheme_type == GF_ISOM_ISMACRYP_SCHEME) {
fmt = sinf->info->isfm;
if (!fmt) return NULL;
return gf_isom_ismacryp_sample_from_data(samp->data, samp->dataLength, sinf->info->isfm->selective_encryption, sinf->info->isfm->key_indicator_length, sinf->info->isfm->IV_length);
}
else if (sinf->scheme_type->scheme_type == GF_ISOM_OMADRM_SCHEME ) {
if (!sinf->info->odkm) return NULL;
fmt = sinf->info->odkm->fmt;
if (fmt) {
return gf_isom_ismacryp_sample_from_data(samp->data, samp->dataLength, fmt->selective_encryption, fmt->key_indicator_length, fmt->IV_length);
}
return gf_isom_ismacryp_sample_from_data(samp->data, samp->dataLength, GF_FALSE, 0, 128);
}
return NULL;
},0

list_instructions(char *pfx, isn_T *instr, int instr_count, ufunc_T *ufunc)
{
int line_idx = 0;
int prev_current = 0;
int current;
int def_arg_idx = 0;
for (current = 0; current < instr_count; ++current)
{
isn_T *iptr = &instr[current];
char *line;
if (ufunc != NULL)
{
while (line_idx < iptr->isn_lnum
&& line_idx < ufunc->uf_lines.ga_len)
{
if (current > prev_current)
{
msg_puts("\n\n");
prev_current = current;
}
line = ((char **)ufunc->uf_lines.ga_data)[line_idx++];
if (line != NULL)
msg(line);
}
if (iptr->isn_type == ISN_JUMP_IF_ARG_SET)
{
int first_def_arg = ufunc->uf_args.ga_len
- ufunc->uf_def_args.ga_len;
if (def_arg_idx > 0)
msg_puts("\n\n");
msg_start();
msg_puts(" ");
msg_puts(((char **)(ufunc->uf_args.ga_data))[
first_def_arg + def_arg_idx]);
msg_puts(" = ");
msg_puts(((char **)(ufunc->uf_def_args.ga_data))[def_arg_idx++]);
msg_clr_eos();
msg_end();
}
}
switch (iptr->isn_type)
{
case ISN_EXEC:
smsg("%s%4d EXEC %s", pfx, current, iptr->isn_arg.string);
break;
case ISN_EXEC_SPLIT:
smsg("%s%4d EXEC_SPLIT %s", pfx, current, iptr->isn_arg.string);
break;
case ISN_EXECRANGE:
smsg("%s%4d EXECRANGE %s", pfx, current, iptr->isn_arg.string);
break;
case ISN_LEGACY_EVAL:
smsg("%s%4d EVAL legacy %s", pfx, current,
iptr->isn_arg.string);
break;
case ISN_REDIRSTART:
smsg("%s%4d REDIR", pfx, current);
break;
case ISN_REDIREND:
smsg("%s%4d REDIR END%s", pfx, current,
iptr->isn_arg.number ? " append" : "");
break;
case ISN_CEXPR_AUCMD:
#ifdef FEAT_QUICKFIX
smsg("%s%4d CEXPR pre %s", pfx, current,
cexpr_get_auname(iptr->isn_arg.number));
#endif
break;
case ISN_CEXPR_CORE:
#ifdef FEAT_QUICKFIX
{
cexprref_T *cer = iptr->isn_arg.cexpr.cexpr_ref;
smsg("%s%4d CEXPR core %s%s \"%s\"", pfx, current,
cexpr_get_auname(cer->cer_cmdidx),
cer->cer_forceit ? "!" : "",
cer->cer_cmdline);
}
#endif
break;
case ISN_INSTR:
{
smsg("%s%4d INSTR", pfx, current);
list_instructions(" ", iptr->isn_arg.instr,
INT_MAX, NULL);
msg(" -------------");
}
break;
case ISN_SUBSTITUTE:
{
subs_T *subs = &iptr->isn_arg.subs;
smsg("%s%4d SUBSTITUTE %s", pfx, current, subs->subs_cmd);
list_instructions(" ", subs->subs_instr, INT_MAX, NULL);
msg(" -------------");
}
break;
case ISN_EXECCONCAT:
smsg("%s%4d EXECCONCAT %lld", pfx, current,
(varnumber_T)iptr->isn_arg.number);
break;
case ISN_ECHO:
{
echo_T *echo = &iptr->isn_arg.echo;
smsg("%s%4d %s %d", pfx, current,
echo->echo_with_white ? "ECHO" : "ECHON",
echo->echo_count);
}
break;
case ISN_EXECUTE:
smsg("%s%4d EXECUTE %lld", pfx, current,
(varnumber_T)(iptr->isn_arg.number));
break;
case ISN_ECHOMSG:
smsg("%s%4d ECHOMSG %lld", pfx, current,
(varnumber_T)(iptr->isn_arg.number));
break;
case ISN_ECHOCONSOLE:
smsg("%s%4d ECHOCONSOLE %lld", pfx, current,
