break;
case ISN_ECHOERR:
smsg("%s%4d ECHOERR %lld", pfx, current,
(varnumber_T)(iptr->isn_arg.number));
break;
case ISN_LOAD:
{
if (iptr->isn_arg.number < 0)
smsg("%s%4d LOAD arg[%lld]", pfx, current,
