break;
case ISN_DCALL:
{
cdfunc_T *cdfunc = &iptr->isn_arg.dfunc;
dfunc_T *df = ((dfunc_T *)def_functions.ga_data)
+ cdfunc->cdf_idx;
smsg("%s%4d DCALL %s(argc %d)", pfx, current,
printable_func_name(df->df_ufunc),
cdfunc->cdf_argcount);
