static int nbd_negotiate_handle_list(NBDClient *client, uint32_t length)
{
NBDExport *exp;
if (length) {
if (nbd_negotiate_drop_sync(client->ioc, length) < 0) {
return -EIO;
}
return nbd_negotiate_send_rep_err(client->ioc,
NBD_REP_ERR_INVALID, NBD_OPT_LIST,
"OPT_LIST should not have length");
}
QTAILQ_FOREACH(exp, &exports, next) {
if (nbd_negotiate_send_rep_list(client->ioc, exp)) {
return -EINVAL;
}
}
return nbd_negotiate_send_rep(client->ioc, NBD_REP_ACK, NBD_OPT_LIST);
},1

static void php_imagepolygon(INTERNAL_FUNCTION_PARAMETERS, int filled)
{
zval *IM, *POINTS;
long NPOINTS, COL;
zval **var = NULL;
gdImagePtr im;
gdPointPtr points;
int npoints, col, nelem, i;
if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "rall", &IM, &POINTS, &NPOINTS, &COL) == FAILURE) {
return;
}
ZEND_FETCH_RESOURCE(im, gdImagePtr, &IM, -1, "Image", le_gd);
npoints = NPOINTS;
col = COL;
nelem = zend_hash_num_elements(Z_ARRVAL_P(POINTS));
if (nelem < 6) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "You must have at least 3 points in your array");
RETURN_FALSE;
}
if (npoints <= 0) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "You must give a positive number of points");
RETURN_FALSE;
}
if (nelem < npoints * 2) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Trying to use %d points in array with only %d points", npoints, nelem/2);
RETURN_FALSE;
}
points = (gdPointPtr) safe_emalloc(npoints, sizeof(gdPoint), 0);
for (i = 0; i < npoints; i++) {
if (zend_hash_index_find(Z_ARRVAL_P(POINTS), (i * 2), (void **) &var) == SUCCESS) {
SEPARATE_ZVAL((var));
convert_to_long(*var);
points[i].x = Z_LVAL_PP(var);
}
if (zend_hash_index_find(Z_ARRVAL_P(POINTS), (i * 2) + 1, (void **) &var) == SUCCESS) {
SEPARATE_ZVAL(var);
convert_to_long(*var);
points[i].y = Z_LVAL_PP(var);
}
}
if (filled) {
gdImageFilledPolygon(im, points, npoints, col);
} else {
gdImagePolygon(im, points, npoints, col);
}
efree(points);
RETURN_TRUE;
},1

static int create_name_extension_data(git_buf *name_buf, git_index_name_entry *conflict_name)
{
int error = 0;
if (conflict_name->ancestor == NULL)
error = git_buf_put(name_buf, "\0", 1);
else
error = git_buf_put(name_buf, conflict_name->ancestor, strlen(conflict_name->ancestor) + 1);
if (error != 0)
goto on_error;
if (conflict_name->ours == NULL)
error = git_buf_put(name_buf, "\0", 1);
else
error = git_buf_put(name_buf, conflict_name->ours, strlen(conflict_name->ours) + 1);
if (error != 0)
goto on_error;
if (conflict_name->theirs == NULL)
error = git_buf_put(name_buf, "\0", 1);
else
error = git_buf_put(name_buf, conflict_name->theirs, strlen(conflict_name->theirs) + 1);
on_error:
return error;
},0

open_output_stream (struct http_stat *hs, int count, FILE **fp)
{
#ifdef __VMS
# define FOPEN_OPT_ARGS "fop=sqo", "acc", acc_cb, &open_id
# define FOPEN_BIN_FLAG 3
#else
# define FOPEN_BIN_FLAG true
#endif
if (!output_stream)
{
mkalldirs (hs->local_file);
if (opt.backups)
rotate_backups (hs->local_file);
if (hs->restval)
{
#ifdef __VMS
int open_id;
open_id = 21;
*fp = fopen (hs->local_file, "ab", FOPEN_OPT_ARGS);
#else
*fp = fopen (hs->local_file, "ab");
#endif
}
else if (ALLOW_CLOBBER || count > 0)
{
if (opt.unlink && file_exists_p (hs->local_file))
{
if (unlink (hs->local_file) < 0)
{
logprintf (LOG_NOTQUIET, "%s: %s\n", hs->local_file,
strerror (errno));
return UNLINKERR;
}
}
#ifdef __VMS
int open_id;
open_id = 22;
*fp = fopen (hs->local_file, "wb", FOPEN_OPT_ARGS);
#else
*fp = fopen (hs->local_file, "wb");
#endif
}
else
{
*fp = fopen_excl (hs->local_file, FOPEN_BIN_FLAG);
if (!*fp && errno == EEXIST)
{
logprintf (LOG_NOTQUIET,
_("%s has sprung into existence.\n"),
hs->local_file);
return FOPEN_EXCL_ERR;
}
}
if (!*fp)
{
logprintf (LOG_NOTQUIET, "%s: %s\n", hs->local_file, strerror (errno));
return FOPENERR;
}
}
else
*fp = output_stream;
logprintf (LOG_VERBOSE, _("Saving to: %s\n"),
HYPHENP (hs->local_file) ? quote ("STDOUT") : quote (hs->local_file));
return RETROK;
},0

v9fs_stat2inode(struct p9_wstat *stat, struct inode *inode,
struct super_block *sb)
{
umode_t mode;
char ext[32];
char tag_name[14];
unsigned int i_nlink;
struct v9fs_session_info *v9ses = sb->s_fs_info;
struct v9fs_inode *v9inode = V9FS_I(inode);
set_nlink(inode, 1);
inode->i_atime.tv_sec = stat->atime;
inode->i_mtime.tv_sec = stat->mtime;
inode->i_ctime.tv_sec = stat->mtime;
inode->i_uid = v9ses->dfltuid;
inode->i_gid = v9ses->dfltgid;
if (v9fs_proto_dotu(v9ses)) {
inode->i_uid = stat->n_uid;
inode->i_gid = stat->n_gid;
}
if ((S_ISREG(inode->i_mode)) || (S_ISDIR(inode->i_mode))) {
if (v9fs_proto_dotu(v9ses) && (stat->extension[0] != '\0')) {
strlcpy(ext, stat->extension, sizeof(ext));
sscanf(ext, "%13s %u", tag_name, &i_nlink);
if (!strncmp(tag_name, "HARDLINKCOUNT", 13))
set_nlink(inode, i_nlink);
}
}
mode = p9mode2perm(v9ses, stat);
mode |= inode->i_mode & ~S_IALLUGO;
inode->i_mode = mode;
i_size_write(inode, stat->length);
inode->i_blocks = (i_size_read(inode) + 512 - 1) >> 9;
v9inode->cache_validity &= ~V9FS_INO_INVALID_ATTR;
},1

GF_Err stbl_box_read(GF_Box *s, GF_BitStream *bs)
{
GF_Err e;
GF_SampleTableBox *ptr = (GF_SampleTableBox *)s;
e = gf_isom_box_array_read(s, bs);
if (e) return e;
if (!ptr->SyncSample)
ptr->no_sync_found = 1;
ptr->nb_sgpd_in_stbl = gf_list_count(ptr->sampleGroupsDescription);
ptr->nb_stbl_boxes = gf_list_count(ptr->child_boxes);
if (gf_bs_get_cookie(bs) & GF_ISOM_BS_COOKIE_CLONE_TRACK)
return GF_OK;
#define CHECK_BOX(_name) \
if (!ptr->_name) {\
GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Mandatory box %s is missing\n", #_name)); \
return GF_ISOM_INVALID_FILE; \
}
CHECK_BOX(SampleToChunk)
CHECK_BOX(SampleSize)
CHECK_BOX(ChunkOffset)
CHECK_BOX(TimeToSample)
if (ptr->SampleSize->sampleCount) {
if (!ptr->TimeToSample->nb_entries || !ptr->SampleToChunk->nb_entries)
return GF_ISOM_INVALID_FILE;
}
return GF_OK;
},1

u32 gf_bs_read_ue_log_idx3(GF_BitStream *bs, const char *fname, s32 idx1, s32 idx2, s32 idx3)
{
u32 val=0, code;
s32 nb_lead = -1;
u32 bits = 0;
for (code=0; !code; nb_lead++) {
if (nb_lead>=32) {
if (!gf_bs_available(bs)) {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[Core] exp-golomb read failed, not enough bits in bitstream !\n"));
} else {
GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[Core] corrupted exp-golomb code, %d leading zeros, max 31 allowed !\n", nb_lead));
}
return 0;
}
code = gf_bs_read_int(bs, 1);
bits++;
}
if (nb_lead) {
val = gf_bs_read_int(bs, nb_lead);
val += (1 << nb_lead) - 1;
bits += nb_lead;
}
if (fname) {
gf_bs_log_idx(bs, bits, fname, val, idx1, idx2, idx3);
}
return val;
},0

bool decode_jpeg(const std::vector<std::pair<uint32_t, uint32_t> > & huff_input_offsets,
std::vector<ThreadHandoff>*luma_row_offset_return)
{
abitreader* huffr;
unsigned char type = 0x00;
unsigned int len = 0;
unsigned int hpos = 0;
int lastdc[ 4 ] = {0, 0, 0, 0};
Sirikata::Aligned256Array1d<int16_t,64> block;
int peobrun;
unsigned int eobrun;
int rstw;
int cmp, bpos, dpos;
int mcu = 0, sub, csc;
int eob, sta;
bool is_baseline = true;
max_cmp = 0;
max_bpos = 0;
memset(max_dpos, 0, sizeof(max_dpos));
max_sah = 0;
huffr = new abitreader( huffdata, hufs );
scnc = 0;
while ( true )
{
for ( type = 0x00; type != 0xDA; ) {
if ( 3 + ( uint64_t ) hpos >= hdrs ) break;
type = hdrdata[ hpos + 1 ];
len = 2 + B_SHORT( hdrdata[ hpos + 2 ], hdrdata[ hpos + 3 ] );
if ( ( type == 0xC4 ) || ( type == 0xDA ) || ( type == 0xDD ) ) {
std::vector<unsigned char> over_data;
unsigned char * hdr_seg_data = NULL;
if ((uint64_t)hpos + (uint64_t)len > (uint64_t)hdrs) {
over_data.insert(over_data.end(), &hdrdata[hpos], &hdrdata[hpos] + (hdrs - hpos));
over_data.resize(len);
hdr_seg_data = &over_data[0];
} else {
hdr_seg_data = &( hdrdata[ hpos ] );
}
if ( !parse_jfif_jpg( type, len, len, hdr_seg_data ) ) {
delete huffr;
return false;
}
}
hpos += len;
}
if ( type != 0xDA ) break;
for ( csc = 0; csc < cs_cmpc; csc++ ) {
cmp = cs_cmp[ csc ];
if ( (( jpegtype == 1 || (( cs_cmpc > 1 || cs_to == 0 ) && cs_sah == 0 )) && htset[ 0 ][ cmpnfo[cmp].huffdc ] == 0 ) ||
( jpegtype == 1 && htset[ 1 ][ cmpnfo[cmp].huffdc ] == 0 ) ||
( cs_cmpc == 1 && cs_to > 0 && cs_sah == 0 && htset[ 1 ][ cmpnfo[cmp].huffac ] == 0 ) ) {
fprintf( stderr, "huffman table missing in scan%i", scnc );
delete huffr;
errorlevel.store(2);
return false;
}
}
cmp = cs_cmp[ 0 ];
csc = 0;
mcu = 0;
sub = 0;
dpos = 0;
if (!huffr->eof) {
max_bpos = std::max(max_bpos, cs_to);
max_sah = std::max(max_sah, std::max(cs_sal,cs_sah));
for (int i = 0; i < cs_cmpc; ++i) {
max_cmp = std::max(max_cmp, cs_cmp[i]);
}
}
bool do_handoff_print = true;
while ( true )
{
lastdc[ 0 ] = 0;
lastdc[ 1 ] = 0;
lastdc[ 2 ] = 0;
lastdc[ 3 ] = 0;
sta = 0;
eobrun = 0;
peobrun = 0;
rstw = rsti;
if (cs_cmpc != colldata.get_num_components()) {
if (!g_allow_progressive) {
custom_exit(ExitCode::PROGRESSIVE_UNSUPPORTED);
} else {
is_baseline = false;
}
}
if (jpegtype != 1) {
if (!g_allow_progressive) {
custom_exit(ExitCode::PROGRESSIVE_UNSUPPORTED);
} else {
is_baseline = false;
}
}
if ( cs_cmpc > 1 )
{
if ( jpegtype == 1 ) {
while ( sta == 0 ) {
if (do_handoff_print) {
luma_row_offset_return->push_back(crystallize_thread_handoff(huffr,
huff_input_offsets,
mcu / mcuh,
lastdc,
cmpnfo[0].bcv / mcuv));
do_handoff_print = false;
}
if(!huffr->eof) {
max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
}
eob = decode_block_seq( huffr,
&(htrees[ 0 ][ cmpnfo[cmp].huffdc ]),
&(htrees[ 1 ][ cmpnfo[cmp].huffac ]),
block.begin() );
if ( eob > 1 && !block[ eob - 1 ] ) {
fprintf( stderr, "cannot encode image with eob after last 0" );
errorlevel.store(1);
}
block[ 0 ] += lastdc[ cmp ];
lastdc[ cmp ] = block[ 0 ];
AlignedBlock&aligned_block = colldata.mutable_block((BlockType)cmp, dpos);
for ( bpos = 0; bpos < eob; bpos++ ) {
aligned_block.mutable_coefficients_zigzag(bpos) = block[ bpos ];
}
int old_mcu = mcu;
if ( eob < 0 ) sta = -1;
else sta = next_mcupos( &mcu, &cmp, &csc, &sub, &dpos, &rstw, cs_cmpc);
if (mcu % mcuh == 0 && old_mcu != mcu) {
do_handoff_print = true;
}
if(huffr->eof) {
sta = 2;
break;
}
}
}
else if ( cs_sah == 0 ) {
while ( sta == 0 ) {
if (do_handoff_print) {
luma_row_offset_return->push_back(crystallize_thread_handoff(huffr,
huff_input_offsets,
mcu / mcuh,
lastdc,
cmpnfo[0].bcv / mcuv));
do_handoff_print = false;
}
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
sta = decode_dc_prg_fs( huffr,
&(htrees[ 0 ][ cmpnfo[cmp].huffdc ]),
block.begin() );
colldata.set((BlockType)cmp,0,dpos) = block[0] + lastdc[ cmp ];
uint16_t u_last_dc = lastdc[ cmp ] = colldata.set((BlockType)cmp,0,dpos);
u_last_dc <<= cs_sal;
colldata.set((BlockType)cmp,0,dpos) = u_last_dc;
int old_mcu = mcu;
if ( sta != -1 ) {
sta = next_mcupos( &mcu, &cmp, &csc, &sub, &dpos, &rstw, cs_cmpc);
}
if (mcu % mcuh == 0 && old_mcu != mcu) {
do_handoff_print = true;
}
if(huffr->eof) {
sta = 2;
break;
}
}
}
else {
while ( sta == 0 ) {
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
sta = decode_dc_prg_sa( huffr,
block.begin() );
colldata.set((BlockType)cmp,0,dpos) += block[0] << cs_sal;
if ( sta != -1 )
sta = next_mcupos( &mcu, &cmp, &csc, &sub, &dpos, &rstw, cs_cmpc);
if(huffr->eof) {
sta = 2;
break;
}
}
}
}
else
{
if ( jpegtype == 1 ) {
int vmul = cmpnfo[0].bcv / mcuv;
int hmul = cmpnfo[0].bch / mcuh;
while ( sta == 0 ) {
if (do_handoff_print) {
luma_row_offset_return->push_back(crystallize_thread_handoff(huffr,
huff_input_offsets,
(dpos/(hmul * vmul)) / mcuh,
lastdc,
cmpnfo[0].bcv / mcuv));
do_handoff_print = false;
}
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
eob = decode_block_seq( huffr,
&(htrees[ 0 ][ cmpnfo[cmp].huffdc ]),
&(htrees[ 1 ][ cmpnfo[cmp].huffac ]),
block.begin() );
if ( eob > 1 && !block[ eob - 1 ] ) {
fprintf( stderr, "cannot encode image with eob after last 0" );
errorlevel.store(1);
}
block[ 0 ] += lastdc[ cmp ];
lastdc[ cmp ] = block[ 0 ];
AlignedBlock& aligned_block = colldata.mutable_block((BlockType)cmp, dpos);
for ( bpos = 0; bpos < eob; bpos++ ) {
aligned_block.mutable_coefficients_zigzag(bpos) = block[ bpos ];
}
if ( eob < 0 ) sta = -1;
else sta = next_mcuposn( &cmp, &dpos, &rstw);
mcu = dpos / (hmul * vmul);
if (cmp == 0 && (mcu % mcuh == 0) && (dpos %(hmul *vmul) == 0)) {
do_handoff_print = true;
}
if(huffr->eof) {
sta = 2;
break;
}
}
}
else if ( cs_to == 0 ) {
if ( cs_sah == 0 ) {
while ( sta == 0 ) {
if (do_handoff_print) {
luma_row_offset_return->push_back(crystallize_thread_handoff(huffr,
huff_input_offsets,
dpos / cmpnfo[cmp].bch,
lastdc,
cmpnfo[0].bcv / mcuv));
do_handoff_print = false;
}
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
sta = decode_dc_prg_fs( huffr,
&(htrees[ 0 ][ cmpnfo[cmp].huffdc ]),
block.begin() );
colldata.set((BlockType)cmp,0,dpos) = block[0] + lastdc[ cmp ];
lastdc[ cmp ] = colldata.set((BlockType)cmp,0,dpos);
colldata.set((BlockType)cmp,0,dpos) <<= cs_sal;
if ( sta != -1 )
sta = next_mcuposn( &cmp, &dpos, &rstw );
if (cmp == 0 && dpos % cmpnfo[cmp].bch == 0) {
do_handoff_print = true;
}
if(huffr->eof) {
sta = 2;
break;
}
}
}
else {
while( sta == 0 ) {
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
sta = decode_dc_prg_sa( huffr,
block.begin() );
colldata.set((BlockType)cmp,0,dpos) += block[0] << cs_sal;
if ( sta != -1 )
sta = next_mcuposn( &cmp, &dpos, &rstw );
if(huffr->eof) {
sta = 2;
break;
}
}
}
}
else {
if ( cs_sah == 0 ) {
while ( sta == 0 ) {
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
eob = decode_ac_prg_fs( huffr,
&(htrees[ 1 ][ cmpnfo[cmp].huffac ]),
block.begin(), &eobrun, cs_from, cs_to );
if ( ( eob == cs_from ) && ( eobrun > 0 ) &&
( peobrun > 0 ) && ( peobrun <
hcodes[ 1 ][ cmpnfo[cmp].huffac ].max_eobrun - 1 ) ) {
fprintf( stderr,
"reconstruction of non optimal coding not supported" );
errorlevel.store(1);
}
AlignedBlock &aligned_block = colldata.mutable_block((BlockType)cmp, dpos);
for ( bpos = cs_from; bpos < eob; bpos++ ) {
uint16_t block_bpos = block[ bpos ];
block_bpos <<= cs_sal;
aligned_block.mutable_coefficients_zigzag(bpos) = block_bpos;
}
if ( eob < 0 ) sta = -1;
else sta = skip_eobrun( &cmp, &dpos, &rstw, &eobrun );
if ( sta == 0 )
sta = next_mcuposn( &cmp, &dpos, &rstw );
if(huffr->eof) {
sta = 2;
break;
}
}
}
else {
while ( sta == 0 ) {
AlignedBlock &aligned_block = colldata.mutable_block((BlockType)cmp, dpos);
for ( bpos = cs_from; bpos <= cs_to; bpos++ ) {
block[ bpos ] = aligned_block.coefficients_zigzag(bpos);
}
if ( eobrun == 0 ) {
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
eob = decode_ac_prg_sa( huffr,
&(htrees[ 1 ][ cmpnfo[cmp].huffac ]),
block.begin(), &eobrun, cs_from, cs_to );
if ( ( eob == cs_from ) && ( eobrun > 0 ) &&
( peobrun > 0 ) && ( peobrun <
hcodes[ 1 ][ cmpnfo[cmp].huffac ].max_eobrun - 1 ) ) {
fprintf( stderr,
"reconstruction of non optimal coding not supported" );
errorlevel.store(1);
}
}
else {
if(!huffr->eof) max_dpos[cmp] = std::max(dpos, max_dpos[cmp]);
eob = decode_eobrun_sa( huffr,
block.begin(), &eobrun, cs_from, cs_to );
if ( eob > 1 && !block[ eob - 1 ] ) {
fprintf( stderr, "cannot encode image with eob after last 0" );
errorlevel.store(1);
}
}
peobrun = eobrun;
for ( bpos = cs_from; bpos <= cs_to; bpos++ ) {
uint16_t block_bpos = block[ bpos ];
block_bpos <<= cs_sal;
aligned_block.mutable_coefficients_zigzag(bpos) += block_bpos;
}
if ( eob < 0 ) sta = -1;
else sta = next_mcuposn( &cmp, &dpos, &rstw );
if(huffr->eof) {
sta = 2;
break;
}
}
}
}
}
if ( padbit != -1 ) {
if ( padbit != huffr->unpad( padbit ) ) {
fprintf( stderr, "inconsistent use of padbits" );
padbit = 1;
errorlevel.store(1);
}
}
else {
padbit = huffr->unpad( padbit );
}
if ( sta == -1 ) {
fprintf( stderr, "decode error in scan%i / mcu%i",
scnc, ( cs_cmpc > 1 ) ? mcu : dpos );
delete huffr;
errorlevel.store(2);
return false;
}
else if ( sta == 2 ) {
scnc++;
break;
}
}
}
if (early_eof_encountered) {
colldata.set_truncation_bounds(max_cmp, max_bpos, max_dpos, max_sah);
}
luma_row_offset_return->push_back(crystallize_thread_handoff(huffr, huff_input_offsets, (uint16_t)(mcu / mcuh), lastdc, cmpnfo[0].bcv / mcuv));
for (size_t i = 1; i < luma_row_offset_return->size(); ++i) {
if ((*luma_row_offset_return)[i].luma_y_start <
(*luma_row_offset_return)[i-1].luma_y_end) {
(*luma_row_offset_return)[i].luma_y_start = (*luma_row_offset_return)[i-1].luma_y_end;
}
}
if ( !huffr->eof ) {
fprintf( stderr, "unneeded data found after coded image data" );
errorlevel.store(1);
}
delete( huffr );
if (is_baseline) {
g_allow_progressive = false;
}
return true;
},0

TEST_P(ProtocolIntegrationTest, HittingEncoderFilterLimit) {
config_helper_.addConfigModifier(
[&](envoy::extensions::filters::network::http_connection_manager::v3::HttpConnectionManager&
hcm) -> void {
auto* route_config = hcm.mutable_route_config();
auto* virtual_host = route_config->mutable_virtual_hosts(0);
auto* header = virtual_host->mutable_response_headers_to_add()->Add()->mutable_header();
header->set_key("foo");
header->set_value("bar");
});
useAccessLog();
config_helper_.prependFilter("{ name: encoder-decoder-buffer-filter, typed_config: { \"@type\": "
"type.googleapis.com/google.protobuf.Empty } }");
config_helper_.setBufferLimits(1024, 1024);
initialize();
codec_client_ = makeHttpConnection(lookupPort("http"));
auto encoder_decoder = codec_client_->startRequest(default_request_headers_);
auto downstream_request = &encoder_decoder.first;
auto response = std::move(encoder_decoder.second);
Buffer::OwnedImpl data("HTTP body content goes here");
codec_client_->sendData(*downstream_request, data, true);
waitForNextUpstreamRequest();
upstream_request_->encodeHeaders(default_response_headers_, false);
upstream_request_->encodeData(1024 * 65, false);
if (upstreamProtocol() == Http::CodecType::HTTP1) {
ASSERT_TRUE(fake_upstream_connection_->waitForDisconnect());
} else {
ASSERT_TRUE(upstream_request_->waitForReset());
ASSERT_TRUE(fake_upstream_connection_->close());
ASSERT_TRUE(fake_upstream_connection_->waitForDisconnect());
}
ASSERT_TRUE(response->waitForEndStream());
EXPECT_TRUE(response->complete());
EXPECT_EQ("500", response->headers().getStatusValue());
auto foo = Http::LowerCaseString("foo");
ASSERT_FALSE(response->headers().get(foo).empty());
EXPECT_EQ("bar", response->headers().get(foo)[0]->value().getStringView());
EXPECT_TRUE(response->headers().Date() != nullptr);
EXPECT_THAT(waitForAccessLog(access_log_name_), HasSubstr("500"));
test_server_->waitForCounterEq("http.config_test.downstream_rq_5xx", 1);
},0

njs_vmcode_try_start(njs_vm_t *vm, njs_value_t *exception_value,
njs_value_t *offset, u_char *pc)
{
njs_value_t *exit_value;
njs_frame_t *frame;
njs_exception_t *e;
njs_vmcode_try_start_t *try_start;
frame = (njs_frame_t *) vm->top_frame;
if (frame->exception.catch != NULL) {
e = njs_mp_alloc(vm->mem_pool, sizeof(njs_exception_t));
if (njs_slow_path(e == NULL)) {
njs_memory_error(vm);
return NJS_ERROR;
}
*e = frame->exception;
frame->exception.next = e;
}
frame->exception.catch = pc + (njs_jump_off_t) offset;
njs_set_invalid(exception_value);
try_start = (njs_vmcode_try_start_t *) pc;
exit_value = njs_scope_value(vm, try_start->exit_value);
njs_set_invalid(exit_value);
njs_number(exit_value) = 0;
return sizeof(njs_vmcode_try_start_t);
},0

void CascadeClassifierImpl::detectMultiScale( InputArray _image, std::vector<Rect>& objects,
std::vector<int>& numDetections, double scaleFactor,
int minNeighbors, int flags, Size minObjectSize,
Size maxObjectSize )
{
CV_INSTRUMENT_REGION();
Mat image = _image.getMat();
CV_Assert( scaleFactor > 1 && image.depth() == CV_8U );
if( empty() )
return;
std::vector<int> fakeLevels;
std::vector<double> fakeWeights;
if( isOldFormatCascade() )
{
std::vector<CvAvgComp> vecAvgComp;
detectMultiScaleOldFormat( image, oldCascade, objects, fakeLevels, fakeWeights, vecAvgComp, scaleFactor,
minNeighbors, flags, minObjectSize, maxObjectSize );
numDetections.resize(vecAvgComp.size());
std::transform(vecAvgComp.begin(), vecAvgComp.end(), numDetections.begin(), getNeighbors());
}
else
{
detectMultiScaleNoGrouping( image, objects, fakeLevels, fakeWeights, scaleFactor, minObjectSize, maxObjectSize );
const double GROUP_EPS = 0.2;
groupRectangles( objects, numDetections, minNeighbors, GROUP_EPS );
}
