QPDF::parse_xrefFirst(std::string const& line,
int& obj, int& num, int& bytes)
{
char const* p = line.c_str();
char const* start = line.c_str();
while (QUtil::is_space(*p))
{
++p;
}
if (! QUtil::is_digit(*p))
{
return false;
}
std::string obj_str;
while (QUtil::is_digit(*p))
{
obj_str.append(1, *p++);
}
if (! QUtil::is_space(*p))
{
return false;
}
while (QUtil::is_space(*p))
{
++p;
}
if (! QUtil::is_digit(*p))
{
return false;
}
std::string num_str;
while (QUtil::is_digit(*p))
{
num_str.append(1, *p++);
}
while (QUtil::is_space(*p))
{
++p;
}
bytes = p - start;
obj = QUtil::string_to_int(obj_str.c_str());
num = QUtil::string_to_int(num_str.c_str());
return true;
},1

static char *xmlrpc_write_header(int length)
{
char buf[512];
time_t ts;
char timebuf[64];
struct tm tm;
*buf = '\0';
ts = time(NULL);
tm = *localtime(&ts);
strftime(timebuf, sizeof timebuf, "%Y-%m-%d %H:%M:%S", &tm);
snprintf(buf, sizeof buf, "HTTP/1.1 200 OK\r\nConnection: close\r\n" "Content-Length: %d\r\n" "Content-Type: text/xml\r\n" "Date: %s\r\n" "Server: Atheme/%s\r\n\r\n", length, timebuf, PACKAGE_VERSION);
return sstrdup(buf);
},0

static int fts3FindFunctionMethod(
sqlite3_vtab *pVtab,
int nArg,
const char *zName,
void (**pxFunc)(sqlite3_context*,int,sqlite3_value**),
void **ppArg
){
struct Overloaded {
const char *zName;
void (*xFunc)(sqlite3_context*,int,sqlite3_value**);
} aOverload[] = {
{ "snippet", fts3SnippetFunc },
{ "offsets", fts3OffsetsFunc },
{ "optimize", fts3OptimizeFunc },
{ "matchinfo", fts3MatchinfoFunc },
};
int i;
UNUSED_PARAMETER(pVtab);
UNUSED_PARAMETER(nArg);
UNUSED_PARAMETER(ppArg);
for(i=0; i<SizeofArray(aOverload); i++){
if( strcmp(zName, aOverload[i].zName)==0 ){
*pxFunc = aOverload[i].xFunc;
return 1;
}
}
return 0;
