static void rtsx_usb_ms_poll_card(struct work_struct *work)
{
struct rtsx_usb_ms *host = container_of(work, struct rtsx_usb_ms,
poll_card.work);
struct rtsx_ucr *ucr = host->ucr;
int err;
u8 val;
if (host->eject || host->power_mode != MEMSTICK_POWER_ON)
return;
pm_runtime_get_sync(ms_dev(host));
mutex_lock(&ucr->dev_mutex);
err = rtsx_usb_read_register(ucr, CARD_INT_PEND, &val);
if (err) {
mutex_unlock(&ucr->dev_mutex);
goto poll_again;
}
rtsx_usb_write_register(ucr, CARD_INT_PEND,
XD_INT | MS_INT | SD_INT,
XD_INT | MS_INT | SD_INT);
mutex_unlock(&ucr->dev_mutex);
if (val & MS_INT) {
dev_dbg(ms_dev(host), "MS slot change detected\n");
memstick_detect_change(host->msh);
}
poll_again:
pm_runtime_put_sync(ms_dev(host));
if (!host->eject && host->power_mode == MEMSTICK_POWER_ON)
schedule_delayed_work(&host->poll_card, 100);
},0

int main(
int argc,
char **argv)
{
int ArgIndex;
int NumErrs = 0;
char *Args[MAXARGS];
int aindex = 0;
int rc;
int pid;
char tmpJobID[PBS_MAXCLTJOBID];
char JobID[PBS_MAXCLTJOBID];
char ServerName[MAXSERVERNAME];
int DoBackground = 0;
tmpJobID[0] = '\0';
#define GETOPT_ARGS "bj:"
while ((ArgIndex = getopt(argc, argv, GETOPT_ARGS)) != EOF)
{
switch (ArgIndex)
{
case 'b':
DoBackground = 1;
break;
case 'j':
strncpy(tmpJobID, optarg, sizeof(tmpJobID));
if (tmpJobID[PBS_MAXCLTJOBID-1] != '\0')
{
fprintf(stderr, "pbs_track: given job ID too large (> %d)\n",
PBS_MAXCLTJOBID);
exit(-1);
}
break;
default:
NumErrs++;
break;
}
}
if ((NumErrs > 0) ||
(optind >= argc) ||
(tmpJobID[0] == '\0'))
{
static char Usage[] = "USAGE: pbs_track [-j <JOBID>] [-b] -- a.out arg1 arg2 ... argN\n";
fprintf(stderr, "%s", Usage);
exit(2);
}
if (getenv(NO_SERVER_SUFFIX) != NULL)
{
snprintf(JobID, sizeof(JobID), "%s", tmpJobID);
}
else
{
if (get_server(tmpJobID, JobID, sizeof(JobID), ServerName, sizeof(ServerName)))
{
fprintf(stderr, "pbs_track: illegally formed job identifier: '%s'\n", JobID);
exit(1);
}
}
aindex = 0;
for (;optind < argc;optind++)
{
Args[aindex++] = strdup(argv[optind]);
printf("Got arg: %s\n",
Args[aindex-1]);
}
Args[aindex] = NULL;
pid = 1;
if (DoBackground == 1)
{
printf("FORKING!\n");
pid = fork();
}
if ((DoBackground == 0) || (pid == 0))
{
rc = tm_adopt(JobID, TM_ADOPT_JOBID, getpid());
switch (rc)
{
case TM_SUCCESS:
break;
case TM_ENOTFOUND:
fprintf(stderr, "pbs_track: MOM could not find job %s\n",
JobID);
break;
case TM_ESYSTEM:
case TM_ENOTCONNECTED:
fprintf(stderr, "pbs_track: error occurred while trying to communication with pbs_mom: %s (%d)\n",
pbse_to_txt(rc),
rc);
break;
default:
fprintf(stderr, "pbs_track: unexpected error %s (%d) occurred\n",
pbse_to_txt(rc),
rc);
break;
}
if (rc != TM_SUCCESS)
{
exit(-1);
}
if (execvp(Args[0], Args) == -1)
{
fprintf(stderr,"execvp failed with error %d, message:\n%s\n",
errno,
strerror(errno));
}
}
else if (pid > 0)
{
fclose(stdin);
fclose(stdout);
fclose(stderr);
}
else if (pid < 0)
{
fprintf(stderr, "pbs_track: could not fork (%d:%s)\n",
errno,
strerror(errno));
}
exit(0);
},1

enum nss_status _nss_mymachines_getgrnam_r(
const char *name,
struct group *gr,
char *buffer, size_t buflen,
int *errnop) {
_cleanup_bus_error_free_ sd_bus_error error = SD_BUS_ERROR_NULL;
_cleanup_bus_message_unref_ sd_bus_message* reply = NULL;
_cleanup_bus_flush_close_unref_ sd_bus *bus = NULL;
const char *p, *e, *machine;
uint32_t mapped;
uid_t gid;
size_t l;
int r;
assert(name);
assert(gr);
p = startswith(name, "vg-");
if (!p)
goto not_found;
e = strrchr(p, '-');
if (!e || e == p)
goto not_found;
r = parse_gid(e + 1, &gid);
if (r < 0)
goto not_found;
machine = strndupa(p, e - p);
if (!machine_name_is_valid(machine))
goto not_found;
r = sd_bus_open_system(&bus);
if (r < 0)
goto fail;
r = sd_bus_call_method(bus,
"org.freedesktop.machine1",
"/org/freedesktop/machine1",
"org.freedesktop.machine1.Manager",
"MapFromMachineGroup",
&error,
&reply,
"su",
machine, (uint32_t) gid);
if (r < 0) {
if (sd_bus_error_has_name(&error, BUS_ERROR_NO_SUCH_GROUP_MAPPING))
goto not_found;
goto fail;
}
r = sd_bus_message_read(reply, "u", &mapped);
if (r < 0)
goto fail;
l = sizeof(char*) + strlen(name) + 1;
if (buflen < l) {
*errnop = ENOMEM;
return NSS_STATUS_TRYAGAIN;
}
memzero(buffer, sizeof(char*));
strcpy(buffer + sizeof(char*), name);
gr->gr_name = buffer + sizeof(char*);
gr->gr_gid = gid;
gr->gr_passwd = (char*) "*";
gr->gr_mem = (char**) buffer;
*errnop = 0;
return NSS_STATUS_SUCCESS;
not_found:
*errnop = 0;
return NSS_STATUS_NOTFOUND;
fail:
*errnop = -r;
return NSS_STATUS_UNAVAIL;
},1

