FindAKA();
case '\013':
LineFeed(0);
return 1;
case '\007':
WBell(curr, visual_bell);
return 1;
case '\t':
ForwardTab();
return 1;
case '\017':
MapCharset(G0);
return 1;
case '\016':
MapCharset(G1);
return 1;
}
return 0;
