{
size_t cur_token;
int type;
struct mailimf_orig_date * orig_date;
struct mailimf_from * from;
struct mailimf_sender * sender;
struct mailimf_reply_to * reply_to;
struct mailimf_to * to;
struct mailimf_cc * cc;
struct mailimf_bcc * bcc;
