cur_token = * indx;
orig_date = NULL;
from = NULL;
sender = NULL;
reply_to = NULL;
to = NULL;
cc = NULL;
bcc = NULL;
message_id = NULL;
in_reply_to = NULL;
references = NULL;
subject = NULL;
optional_field = NULL;
guessed_type = guess_header_type(message, length, cur_token);
type = MAILIMF_FIELD_NONE;
switch (guessed_type) {
case MAILIMF_FIELD_ORIG_DATE:
r = mailimf_orig_date_parse(message, length, &cur_token,
&orig_date);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_FROM:
r = mailimf_from_parse(message, length, &cur_token,
&from);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_SENDER:
r = mailimf_sender_parse(message, length, &cur_token,
&sender);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_REPLY_TO:
r = mailimf_reply_to_parse(message, length, &cur_token,
&reply_to);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_TO:
r = mailimf_to_parse(message, length, &cur_token,
&to);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_CC:
r = mailimf_cc_parse(message, length, &cur_token,
&cc);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_BCC:
r = mailimf_bcc_parse(message, length, &cur_token,
&bcc);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_MESSAGE_ID:
r = mailimf_message_id_parse(message, length, &cur_token,
&message_id);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_IN_REPLY_TO:
r = mailimf_in_reply_to_parse(message, length, &cur_token,
&in_reply_to);
if (r == MAILIMF_NO_ERROR)
type = guessed_type;
else if (r == MAILIMF_ERROR_PARSE) {
}
else {
res = r;
goto err;
}
break;
case MAILIMF_FIELD_REFERENCES:
r = mailimf_references_parse(message, length, &cur_token,
