static void php_wddx_serialize_object(wddx_packet *packet, zval *obj)
{
zval **ent, *fname, **varname;
zval *retval = NULL;
const char *key;
ulong idx;
char tmp_buf[WDDX_BUF_LEN];
HashTable *objhash, *sleephash;
zend_class_entry *ce;
PHP_CLASS_ATTRIBUTES;
TSRMLS_FETCH();
PHP_SET_CLASS_ATTRIBUTES(obj);
ce = Z_OBJCE_P(obj);
if (!ce || ce->serialize || ce->unserialize) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Class %s can not be serialized", class_name);
PHP_CLEANUP_CLASS_ATTRIBUTES();
return;
}
MAKE_STD_ZVAL(fname);
ZVAL_STRING(fname, "__sleep", 1);
if (call_user_function_ex(CG(function_table), &obj, fname, &retval, 0, 0, 1, NULL TSRMLS_CC) == SUCCESS) {
if (retval && (sleephash = HASH_OF(retval))) {
php_wddx_add_chunk_static(packet, WDDX_STRUCT_S);
snprintf(tmp_buf, WDDX_BUF_LEN, WDDX_VAR_S, PHP_CLASS_NAME_VAR);
php_wddx_add_chunk(packet, tmp_buf);
php_wddx_add_chunk_static(packet, WDDX_STRING_S);
php_wddx_add_chunk_ex(packet, class_name, name_len);
php_wddx_add_chunk_static(packet, WDDX_STRING_E);
php_wddx_add_chunk_static(packet, WDDX_VAR_E);
objhash = HASH_OF(obj);
for (zend_hash_internal_pointer_reset(sleephash);
zend_hash_get_current_data(sleephash, (void **)&varname) == SUCCESS;
zend_hash_move_forward(sleephash)) {
if (Z_TYPE_PP(varname) != IS_STRING) {
php_error_docref(NULL TSRMLS_CC, E_NOTICE, "__sleep should return an array only containing the names of instance-variables to serialize.");
continue;
}
if (zend_hash_find(objhash, Z_STRVAL_PP(varname), Z_STRLEN_PP(varname)+1, (void **)&ent) == SUCCESS) {
php_wddx_serialize_var(packet, *ent, Z_STRVAL_PP(varname), Z_STRLEN_PP(varname) TSRMLS_CC);
}
}
php_wddx_add_chunk_static(packet, WDDX_STRUCT_E);
}
} else {
uint key_len;
php_wddx_add_chunk_static(packet, WDDX_STRUCT_S);
snprintf(tmp_buf, WDDX_BUF_LEN, WDDX_VAR_S, PHP_CLASS_NAME_VAR);
php_wddx_add_chunk(packet, tmp_buf);
php_wddx_add_chunk_static(packet, WDDX_STRING_S);
php_wddx_add_chunk_ex(packet, class_name, name_len);
php_wddx_add_chunk_static(packet, WDDX_STRING_E);
php_wddx_add_chunk_static(packet, WDDX_VAR_E);
objhash = HASH_OF(obj);
for (zend_hash_internal_pointer_reset(objhash);
zend_hash_get_current_data(objhash, (void**)&ent) == SUCCESS;
zend_hash_move_forward(objhash)) {
if (*ent == obj) {
continue;
}
if (zend_hash_get_current_key_ex(objhash, &key, &key_len, &idx, 0, NULL) == HASH_KEY_IS_STRING) {
const char *class_name, *prop_name;
zend_unmangle_property_name(key, key_len-1, &class_name, &prop_name);
php_wddx_serialize_var(packet, *ent, prop_name, strlen(prop_name)+1 TSRMLS_CC);
} else {
key_len = slprintf(tmp_buf, sizeof(tmp_buf), "%ld", idx);
php_wddx_serialize_var(packet, *ent, tmp_buf, key_len TSRMLS_CC);
}
}
php_wddx_add_chunk_static(packet, WDDX_STRUCT_E);
}
PHP_CLEANUP_CLASS_ATTRIBUTES();
zval_dtor(fname);
FREE_ZVAL(fname);
if (retval) {
zval_ptr_dtor(&retval);
},0

Mat_VarReadNumeric5(mat_t *mat, matvar_t *matvar, void *data, size_t N)
{
int nBytes = 0, data_in_tag = 0, err = MATIO_E_NO_ERROR;
enum matio_types packed_type = MAT_T_UNKNOWN;
mat_uint32_t tag[2] = {0, 0};
if ( matvar->compression == MAT_COMPRESSION_ZLIB ) {
#if HAVE_ZLIB
matvar->internal->z->avail_in = 0;
err = Inflate(mat, matvar->internal->z, tag, 4, NULL);
if ( err ) {
return err;
}
if ( mat->byteswap )
(void)Mat_uint32Swap(tag);
packed_type = TYPE_FROM_TAG(tag[0]);
if ( tag[0] & 0xffff0000 ) {
data_in_tag = 1;
nBytes = (tag[0] & 0xffff0000) >> 16;
} else {
data_in_tag = 0;
err = Inflate(mat, matvar->internal->z, tag + 1, 4, NULL);
if ( err ) {
return err;
}
if ( mat->byteswap )
(void)Mat_uint32Swap(tag + 1);
nBytes = tag[1];
}
#endif
} else {
err = Read(tag, 4, 1, (FILE *)mat->fp, NULL);
if ( err ) {
return err;
}
if ( mat->byteswap )
(void)Mat_uint32Swap(tag);
packed_type = TYPE_FROM_TAG(tag[0]);
if ( tag[0] & 0xffff0000 ) {
data_in_tag = 1;
nBytes = (tag[0] & 0xffff0000) >> 16;
} else {
data_in_tag = 0;
err = Read(tag + 1, 4, 1, (FILE *)mat->fp, NULL);
if ( err ) {
return err;
}
if ( mat->byteswap )
(void)Mat_uint32Swap(tag + 1);
nBytes = tag[1];
}
}
if ( nBytes == 0 ) {
matvar->nbytes = 0;
return err;
}
if ( matvar->compression == MAT_COMPRESSION_NONE ) {
switch ( matvar->class_type ) {
case MAT_C_DOUBLE:
nBytes = ReadDoubleData(mat, (double *)data, packed_type, N);
break;
case MAT_C_SINGLE:
nBytes = ReadSingleData(mat, (float *)data, packed_type, N);
break;
case MAT_C_INT64:
#ifdef HAVE_MAT_INT64_T
nBytes = ReadInt64Data(mat, (mat_int64_t *)data, packed_type, N);
#endif
break;
case MAT_C_UINT64:
#ifdef HAVE_MAT_UINT64_T
nBytes = ReadUInt64Data(mat, (mat_uint64_t *)data, packed_type, N);
#endif
break;
case MAT_C_INT32:
nBytes = ReadInt32Data(mat, (mat_int32_t *)data, packed_type, N);
break;
case MAT_C_UINT32:
nBytes = ReadUInt32Data(mat, (mat_uint32_t *)data, packed_type, N);
break;
case MAT_C_INT16:
nBytes = ReadInt16Data(mat, (mat_int16_t *)data, packed_type, N);
break;
case MAT_C_UINT16:
nBytes = ReadUInt16Data(mat, (mat_uint16_t *)data, packed_type, N);
break;
case MAT_C_INT8:
nBytes = ReadInt8Data(mat, (mat_int8_t *)data, packed_type, N);
break;
case MAT_C_UINT8:
nBytes = ReadUInt8Data(mat, (mat_uint8_t *)data, packed_type, N);
break;
default:
break;
}
nBytes *= Mat_SizeOf(packed_type);
if ( data_in_tag )
nBytes += 4;
if ( (nBytes % 8) != 0 )
(void)fseek((FILE *)mat->fp, 8 - (nBytes % 8), SEEK_CUR);
#if HAVE_ZLIB
} else if ( matvar->compression == MAT_COMPRESSION_ZLIB ) {
switch ( matvar->class_type ) {
case MAT_C_DOUBLE:
nBytes = ReadCompressedDoubleData(mat, matvar->internal->z, (double *)data,
packed_type, N);
break;
case MAT_C_SINGLE:
nBytes = ReadCompressedSingleData(mat, matvar->internal->z, (float *)data,
packed_type, N);
break;
case MAT_C_INT64:
#ifdef HAVE_MAT_INT64_T
nBytes = ReadCompressedInt64Data(mat, matvar->internal->z, (mat_int64_t *)data,
packed_type, N);
#endif
break;
case MAT_C_UINT64:
#ifdef HAVE_MAT_UINT64_T
nBytes = ReadCompressedUInt64Data(mat, matvar->internal->z, (mat_uint64_t *)data,
packed_type, N);
#endif
break;
case MAT_C_INT32:
nBytes = ReadCompressedInt32Data(mat, matvar->internal->z, (mat_int32_t *)data,
packed_type, N);
break;
case MAT_C_UINT32:
nBytes = ReadCompressedUInt32Data(mat, matvar->internal->z, (mat_uint32_t *)data,
packed_type, N);
break;
case MAT_C_INT16:
nBytes = ReadCompressedInt16Data(mat, matvar->internal->z, (mat_int16_t *)data,
packed_type, N);
break;
case MAT_C_UINT16:
nBytes = ReadCompressedUInt16Data(mat, matvar->internal->z, (mat_uint16_t *)data,
packed_type, N);
break;
case MAT_C_INT8:
nBytes = ReadCompressedInt8Data(mat, matvar->internal->z, (mat_int8_t *)data,
packed_type, N);
break;
case MAT_C_UINT8:
nBytes = ReadCompressedUInt8Data(mat, matvar->internal->z, (mat_uint8_t *)data,
packed_type, N);
break;
default:
break;
}
if ( data_in_tag )
nBytes += 4;
if ( (nBytes % 8) != 0 )
err = InflateSkip(mat, matvar->internal->z, 8 - (nBytes % 8), NULL);
#endif
}
return err;
