TfLiteStatus Eval(TfLiteContext* context, TfLiteNode* node) {
const TfLiteTensor* input = GetInput(context, node, kInputTensor);
const TfLiteTensor* axis_tensor = GetInput(context, node, kAxisTensor);
int axis = GetTensorData<int32_t>(axis_tensor)[0];
const int rank = NumDimensions(input);
if (axis < 0) {
axis += rank;
}
TF_LITE_ENSURE(context, axis >= 0 && axis < rank);
TfLiteTensor* output = GetOutput(context, node, kOutputTensor);
switch (output->type) {
case kTfLiteFloat32: {
reference_ops::Reverse<float>(
axis, GetTensorShape(input), GetTensorData<float>(input),
GetTensorShape(output), GetTensorData<float>(output));
break;
}
case kTfLiteUInt8: {
reference_ops::Reverse<uint8_t>(
axis, GetTensorShape(input), GetTensorData<uint8_t>(input),
GetTensorShape(output), GetTensorData<uint8_t>(output));
break;
}
case kTfLiteInt16: {
reference_ops::Reverse<int16_t>(
axis, GetTensorShape(input), GetTensorData<int16_t>(input),
GetTensorShape(output), GetTensorData<int16_t>(output));
break;
}
case kTfLiteInt32: {
reference_ops::Reverse<int32_t>(
axis, GetTensorShape(input), GetTensorData<int32_t>(input),
GetTensorShape(output), GetTensorData<int32_t>(output));
break;
}
case kTfLiteInt64: {
reference_ops::Reverse<int64_t>(
axis, GetTensorShape(input), GetTensorData<int64_t>(input),
GetTensorShape(output), GetTensorData<int64_t>(output));
break;
}
case kTfLiteBool: {
reference_ops::Reverse<bool>(
axis, GetTensorShape(input), GetTensorData<bool>(input),
GetTensorShape(output), GetTensorData<bool>(output));
break;
}
default: {
context->ReportError(context, "Type '%s' is not supported by reverse.",
TfLiteTypeGetName(output->type));
return kTfLiteError;
}
}
return kTfLiteOk;
},1

int ext4_punch_hole(struct inode *inode, loff_t offset, loff_t length)
{
struct super_block *sb = inode->i_sb;
ext4_lblk_t first_block, stop_block;
struct address_space *mapping = inode->i_mapping;
loff_t first_block_offset, last_block_offset;
handle_t *handle;
unsigned int credits;
int ret = 0;
if (!S_ISREG(inode->i_mode))
return -EOPNOTSUPP;
trace_ext4_punch_hole(inode, offset, length, 0);
if (mapping_tagged(mapping, PAGECACHE_TAG_DIRTY)) {
ret = filemap_write_and_wait_range(mapping, offset,
offset + length - 1);
if (ret)
return ret;
}
inode_lock(inode);
if (offset >= inode->i_size)
goto out_mutex;
if (offset + length > inode->i_size) {
length = inode->i_size +
PAGE_SIZE - (inode->i_size & (PAGE_SIZE - 1)) -
offset;
}
if (offset & (sb->s_blocksize - 1) ||
(offset + length) & (sb->s_blocksize - 1)) {
ret = ext4_inode_attach_jinode(inode);
if (ret < 0)
goto out_mutex;
}
inode_dio_wait(inode);
down_write(&EXT4_I(inode)->i_mmap_sem);
first_block_offset = round_up(offset, sb->s_blocksize);
last_block_offset = round_down((offset + length), sb->s_blocksize) - 1;
if (last_block_offset > first_block_offset) {
ret = ext4_update_disksize_before_punch(inode, offset, length);
if (ret)
goto out_dio;
truncate_pagecache_range(inode, first_block_offset,
last_block_offset);
}
if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS))
credits = ext4_writepage_trans_blocks(inode);
else
credits = ext4_blocks_for_truncate(inode);
handle = ext4_journal_start(inode, EXT4_HT_TRUNCATE, credits);
if (IS_ERR(handle)) {
ret = PTR_ERR(handle);
ext4_std_error(sb, ret);
goto out_dio;
}
ret = ext4_zero_partial_blocks(handle, inode, offset,
length);
if (ret)
goto out_stop;
first_block = (offset + sb->s_blocksize - 1) >>
EXT4_BLOCK_SIZE_BITS(sb);
stop_block = (offset + length) >> EXT4_BLOCK_SIZE_BITS(sb);
if (stop_block > first_block) {
down_write(&EXT4_I(inode)->i_data_sem);
ext4_discard_preallocations(inode);
ret = ext4_es_remove_extent(inode, first_block,
stop_block - first_block);
if (ret) {
up_write(&EXT4_I(inode)->i_data_sem);
goto out_stop;
}
if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS))
ret = ext4_ext_remove_space(inode, first_block,
stop_block - 1);
else
ret = ext4_ind_remove_space(handle, inode, first_block,
stop_block);
up_write(&EXT4_I(inode)->i_data_sem);
}
if (IS_SYNC(inode))
ext4_handle_sync(handle);
inode->i_mtime = inode->i_ctime = current_time(inode);
ext4_mark_inode_dirty(handle, inode);
if (ret >= 0)
ext4_update_inode_fsync_trans(handle, inode, 1);
out_stop:
ext4_journal_stop(handle);
out_dio:
up_write(&EXT4_I(inode)->i_mmap_sem);
out_mutex:
inode_unlock(inode);
return ret;
},0

void read_stats_from_file(char from_file[])
{
struct file_magic file_magic;
struct file_activity *file_actlst = NULL;
char rec_hdr_tmp[MAX_RECORD_HEADER_SIZE];
int curr = 1, i, p;
int ifd, rtype;
int rows, eosaf = TRUE, reset = FALSE;
long cnt = 1;
off_t fpos;
rows = get_win_height();
check_file_actlst(&ifd, from_file, act, &file_magic, &file_hdr,
&file_actlst, id_seq, FALSE, &endian_mismatch, &arch_64);
allocate_structures(act);
print_report_hdr(flags, &rectime, &file_hdr);
do {
do {
if (read_record_hdr(ifd, rec_hdr_tmp, &record_hdr[0], &file_hdr,
arch_64, endian_mismatch, UEOF_STOP)) {
return;
}
rtype = record_hdr[0].record_type;
if ((rtype == R_RESTART) || (rtype == R_COMMENT)) {
print_special_record(&record_hdr[0], flags + S_F_LOCAL_TIME,
&tm_start, &tm_end, rtype, ifd,
&rectime, NULL, from_file, 0, &file_magic,
&file_hdr, act, &sar_fmt, endian_mismatch, arch_64);
}
else {
read_file_stat_bunch(act, 0, ifd, file_hdr.sa_act_nr,
file_actlst, endian_mismatch, arch_64,
from_file, &file_magic, UEOF_STOP);
if (sa_get_record_timestamp_struct(flags + S_F_LOCAL_TIME,
&record_hdr[0],
&rectime, NULL))
continue;
}
}
while ((rtype == R_RESTART) || (rtype == R_COMMENT) ||
(tm_start.use && (datecmp(&rectime, &tm_start) < 0)) ||
(tm_end.use && (datecmp(&rectime, &tm_end) >=0)));
copy_structures(act, id_seq, record_hdr, 2, 0);
reset = TRUE;
if ((fpos = lseek(ifd, 0, SEEK_CUR)) < 0) {
perror("lseek");
exit(2);
}
for (i = 0; i < NR_ACT; i++) {
if (!id_seq[i])
continue;
p = get_activity_position(act, id_seq[i], EXIT_IF_NOT_FOUND);
if (!IS_SELECTED(act[p]->options))
continue;
if (!HAS_MULTIPLE_OUTPUTS(act[p]->options)) {
handle_curr_act_stats(ifd, fpos, &curr, &cnt, &eosaf, rows,
act[p]->id, &reset, file_actlst,
from_file, &file_magic, rec_hdr_tmp,
endian_mismatch, arch_64);
}
else {
unsigned int optf, msk;
optf = act[p]->opt_flags;
for (msk = 1; msk < 0x100; msk <<= 1) {
if ((act[p]->opt_flags & 0xff) & msk) {
act[p]->opt_flags &= (0xffffff00 + msk);
handle_curr_act_stats(ifd, fpos, &curr, &cnt, &eosaf,
rows, act[p]->id, &reset, file_actlst,
from_file, &file_magic, rec_hdr_tmp,
endian_mismatch, arch_64);
act[p]->opt_flags = optf;
}
}
}
}
if (!cnt) {
do {
eosaf = read_record_hdr(ifd, rec_hdr_tmp, &record_hdr[curr],
&file_hdr, arch_64, endian_mismatch, UEOF_STOP);
rtype = record_hdr[curr].record_type;
if (!eosaf && (rtype != R_RESTART) && (rtype != R_COMMENT)) {
read_file_stat_bunch(act, curr, ifd, file_hdr.sa_act_nr,
file_actlst, endian_mismatch, arch_64,
from_file, &file_magic, UEOF_STOP);
}
else if (!eosaf && (rtype == R_COMMENT)) {
print_special_record(&record_hdr[curr], flags + S_F_LOCAL_TIME,
&tm_start, &tm_end, R_COMMENT, ifd,
&rectime, NULL, from_file, 0,
&file_magic, &file_hdr, act, &sar_fmt,
endian_mismatch, arch_64);
}
}
while (!eosaf && (rtype != R_RESTART));
}
if (!eosaf && (record_hdr[curr].record_type == R_RESTART)) {
print_special_record(&record_hdr[curr], flags + S_F_LOCAL_TIME,
&tm_start, &tm_end, R_RESTART, ifd,
&rectime, NULL, from_file, 0,
&file_magic, &file_hdr, act, &sar_fmt,
endian_mismatch, arch_64);
}
}
while (!eosaf);
close(ifd);
free(file_actlst);
},1

static int rdn_rename_callback(struct ldb_request *req, struct ldb_reply *ares)
{
struct ldb_context *ldb;
struct rename_context *ac;
struct ldb_request *mod_req;
const char *rdn_name;
const struct ldb_schema_attribute *a = NULL;
const struct ldb_val *rdn_val_p;
struct ldb_val rdn_val;
struct ldb_message *msg;
int ret;
ac = talloc_get_type(req->context, struct rename_context);
ldb = ldb_module_get_ctx(ac->module);
if (!ares) {
goto error;
}
if (ares->type == LDB_REPLY_REFERRAL) {
return ldb_module_send_referral(ac->req, ares->referral);
}
if (ares->error != LDB_SUCCESS) {
return ldb_module_done(ac->req, ares->controls,
ares->response, ares->error);
}
if (ares->type != LDB_REPLY_DONE) {
goto error;
}
ac->ares = talloc_steal(ac, ares);
msg = ldb_msg_new(ac);
if (msg == NULL) {
goto error;
}
msg->dn = ldb_dn_copy(msg, ac->req->op.rename.newdn);
if (msg->dn == NULL) {
goto error;
}
rdn_name = ldb_dn_get_rdn_name(ac->req->op.rename.newdn);
if (rdn_name == NULL) {
goto error;
}
a = ldb_schema_attribute_by_name(ldb, rdn_name);
if (a == NULL) {
goto error;
}
if (a->name != NULL && strcmp(a->name, "*") != 0) {
rdn_name = a->name;
}
rdn_val_p = ldb_dn_get_rdn_val(msg->dn);
if (rdn_val_p == NULL) {
goto error;
}
if (rdn_val_p->length == 0) {
ldb_asprintf_errstring(ldb, "Empty RDN value on %s not permitted!",
ldb_dn_get_linearized(req->op.rename.olddn));
return ldb_module_done(ac->req, NULL, NULL,
LDB_ERR_NAMING_VIOLATION);
}
rdn_val = ldb_val_dup(msg, rdn_val_p);
if (ldb_msg_append_value(msg, rdn_name, &rdn_val, LDB_FLAG_MOD_REPLACE) != 0) {
goto error;
}
if (ldb_msg_append_value(msg, "name", &rdn_val, LDB_FLAG_MOD_REPLACE) != 0) {
goto error;
}
ret = ldb_build_mod_req(&mod_req, ldb,
ac, msg, NULL,
ac, rdn_modify_callback,
req);
if (ret != LDB_SUCCESS) {
return ldb_module_done(ac->req, NULL, NULL, ret);
}
talloc_steal(mod_req, msg);
return ldb_next_request(ac->module, mod_req);
error:
return ldb_module_done(ac->req, NULL, NULL, LDB_ERR_OPERATIONS_ERROR);
},0

static MagickBooleanType WritePDBImage(const ImageInfo *image_info,Image *image,
ExceptionInfo *exception)
{
const char
*comment;
int
bits;
MagickBooleanType
status;
PDBImage
pdb_image;
PDBInfo
pdb_info;
QuantumInfo
*quantum_info;
register const Quantum
*p;
register ssize_t
x;
register unsigned char
*q;
size_t
bits_per_pixel,
literal,
packets,
packet_size,
repeat;
ssize_t
y;
unsigned char
*buffer,
*runlength,
*scanline;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
if (image->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
status=OpenBlob(image_info,image,WriteBinaryBlobMode,exception);
if (status == MagickFalse)
return(status);
(void) TransformImageColorspace(image,sRGBColorspace,exception);
if (SetImageMonochrome(image,exception) != MagickFalse) {
bits_per_pixel=1;
} else if (image->colors <= 4) {
bits_per_pixel=2;
} else if (image->colors <= 8) {
bits_per_pixel=3;
} else {
bits_per_pixel=4;
}
(void) memset(&pdb_info,0,sizeof(pdb_info));
(void) memset(&pdb_image,0,sizeof(pdb_image));
(void) CopyMagickString(pdb_info.name,image_info->filename,
sizeof(pdb_info.name));
pdb_info.attributes=0;
pdb_info.version=0;
pdb_info.create_time=time(NULL);
pdb_info.modify_time=pdb_info.create_time;
pdb_info.archive_time=0;
pdb_info.modify_number=0;
pdb_info.application_info=0;
pdb_info.sort_info=0;
(void) memcpy(pdb_info.type,"vIMG",4);
(void) memcpy(pdb_info.id,"View",4);
pdb_info.seed=0;
pdb_info.next_record=0;
comment=GetImageProperty(image,"comment",exception);
pdb_info.number_records=(comment == (const char *) NULL ? 1 : 2);
(void) WriteBlob(image,sizeof(pdb_info.name),(unsigned char *) pdb_info.name);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_info.attributes);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_info.version);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.create_time);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.modify_time);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.archive_time);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.modify_number);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.application_info);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.sort_info);
(void) WriteBlob(image,4,(unsigned char *) pdb_info.type);
(void) WriteBlob(image,4,(unsigned char *) pdb_info.id);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.seed);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_info.next_record);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_info.number_records);
(void) CopyMagickString(pdb_image.name,pdb_info.name,sizeof(pdb_image.name));
pdb_image.version=1;
switch (bits_per_pixel)
{
case 1: pdb_image.type=(unsigned char) 0xff; break;
case 2: pdb_image.type=(unsigned char) 0x00; break;
default: pdb_image.type=(unsigned char) 0x02;
}
pdb_image.reserved_1=0;
pdb_image.note=0;
pdb_image.x_last=0;
pdb_image.y_last=0;
pdb_image.reserved_2=0;
pdb_image.x_anchor=(unsigned short) 0xffff;
pdb_image.y_anchor=(unsigned short) 0xffff;
pdb_image.width=(short) image->columns;
if (image->columns % 16)
pdb_image.width=(short) (16*(image->columns/16+1));
pdb_image.height=(short) image->rows;
packets=((bits_per_pixel*image->columns+7)/8);
packet_size=(size_t) (image->depth > 8 ? 2 : 1);
runlength=(unsigned char *) AcquireQuantumMemory(9UL*packets,
image->rows*sizeof(*runlength));
buffer=(unsigned char *) AcquireQuantumMemory(512,sizeof(*buffer));
scanline=(unsigned char *) AcquireQuantumMemory(image->columns,packet_size*
sizeof(*scanline));
if ((runlength == (unsigned char *) NULL) ||
(buffer == (unsigned char *) NULL) ||
(scanline == (unsigned char *) NULL))
{
if (runlength != (unsigned char *) NULL)
runlength=(unsigned char *) RelinquishMagickMemory(runlength);
if (buffer != (unsigned char *) NULL)
buffer=(unsigned char *) RelinquishMagickMemory(buffer);
if (scanline != (unsigned char *) NULL)
scanline=(unsigned char *) RelinquishMagickMemory(scanline);
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
}
(void) ResetMagickMemory(buffer,0,512*sizeof(*buffer));
if (IssRGBCompatibleColorspace(image->colorspace) == MagickFalse)
(void) TransformImageColorspace(image,sRGBColorspace,exception);
quantum_info=AcquireQuantumInfo(image_info,image);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
status=SetQuantumDepth(image,quantum_info,image->depth > 8 ? 16 : 8);
bits=8/(int) bits_per_pixel-1;
literal=0;
repeat=0;
q=runlength;
buffer[0]=0x00;
for (y=0; y < (ssize_t) image->rows; y++)
{
p=GetVirtualPixels(image,0,y,image->columns,1,exception);
if (p == (const Quantum *) NULL)
break;
(void) ExportQuantumPixels(image,(CacheView *) NULL,quantum_info,
GrayQuantum,scanline,exception);
for (x=0; x < (ssize_t) pdb_image.width; x++)
{
if (x < (ssize_t) image->columns)
buffer[literal+repeat]|=(0xff-scanline[x*packet_size]) >>
(8-bits_per_pixel) << bits*bits_per_pixel;
bits--;
if (bits < 0)
{
if (((literal+repeat) > 0) &&
(buffer[literal+repeat] == buffer[literal+repeat-1]))
{
if (repeat == 0)
{
literal--;
repeat++;
}
repeat++;
if (0x7f < repeat)
{
q=EncodeRLE(q,buffer,literal,repeat);
literal=0;
repeat=0;
}
}
else
{
if (repeat >= 2)
literal+=repeat;
else
{
q=EncodeRLE(q,buffer,literal,repeat);
buffer[0]=buffer[literal+repeat];
literal=0;
}
literal++;
repeat=0;
if (0x7f < literal)
{
q=EncodeRLE(q,buffer,(literal < 0x80 ? literal : 0x80),0);
(void) memmove(buffer,buffer+literal+repeat,0x80);
literal-=0x80;
}
}
bits=8/(int) bits_per_pixel-1;
buffer[literal+repeat]=0x00;
}
}
status=SetImageProgress(image,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
q=EncodeRLE(q,buffer,literal,repeat);
scanline=(unsigned char *) RelinquishMagickMemory(scanline);
buffer=(unsigned char *) RelinquishMagickMemory(buffer);
quantum_info=DestroyQuantumInfo(quantum_info);
(void) WriteBlobMSBLong(image,(unsigned int)
(TellBlob(image)+8*pdb_info.number_records));
(void) WriteBlobByte(image,0x40);
(void) WriteBlobByte(image,0x6f);
(void) WriteBlobByte(image,0x80);
(void) WriteBlobByte(image,0);
if (pdb_info.number_records > 1)
{
(void) WriteBlobMSBLong(image,(unsigned int) (TellBlob(image)+8+58+q-
runlength));
(void) WriteBlobByte(image,0x40);
(void) WriteBlobByte(image,0x6f);
(void) WriteBlobByte(image,0x80);
(void) WriteBlobByte(image,1);
}
(void) WriteBlob(image,sizeof(pdb_image.name),(unsigned char *)
pdb_image.name);
(void) WriteBlobByte(image,(unsigned char) pdb_image.version);
(void) WriteBlobByte(image,pdb_image.type);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.reserved_1);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.note);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.x_last);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.y_last);
(void) WriteBlobMSBLong(image,(unsigned int) pdb_image.reserved_2);
(void) WriteBlobMSBShort(image,pdb_image.x_anchor);
(void) WriteBlobMSBShort(image,pdb_image.y_anchor);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.width);
(void) WriteBlobMSBShort(image,(unsigned short) pdb_image.height);
(void) WriteBlob(image,(size_t) (q-runlength),runlength);
runlength=(unsigned char *) RelinquishMagickMemory(runlength);
if (pdb_info.number_records > 1)
(void) WriteBlobString(image,comment);
(void) CloseBlob(image);
return(MagickTrue);
},1

static bool net_tx_pkt_do_sw_fragmentation(struct NetTxPkt *pkt,
NetClientState *nc)
{
struct iovec fragment[NET_MAX_FRAG_SG_LIST];
size_t fragment_len = 0;
bool more_frags = false;
void *l2_iov_base, *l3_iov_base;
size_t l2_iov_len, l3_iov_len;
int src_idx = NET_TX_PKT_PL_START_FRAG, dst_idx;
size_t src_offset = 0;
size_t fragment_offset = 0;
l2_iov_base = pkt->vec[NET_TX_PKT_L2HDR_FRAG].iov_base;
l2_iov_len = pkt->vec[NET_TX_PKT_L2HDR_FRAG].iov_len;
l3_iov_base = pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_base;
l3_iov_len = pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len;
fragment[NET_TX_PKT_FRAGMENT_L2_HDR_POS].iov_base = l2_iov_base;
fragment[NET_TX_PKT_FRAGMENT_L2_HDR_POS].iov_len = l2_iov_len;
fragment[NET_TX_PKT_FRAGMENT_L3_HDR_POS].iov_base = l3_iov_base;
fragment[NET_TX_PKT_FRAGMENT_L3_HDR_POS].iov_len = l3_iov_len;
do {
fragment_len = net_tx_pkt_fetch_fragment(pkt, &src_idx, &src_offset,
fragment, &dst_idx);
more_frags = (fragment_offset + fragment_len < pkt->payload_len);
eth_setup_ip4_fragmentation(l2_iov_base, l2_iov_len, l3_iov_base,
l3_iov_len, fragment_len, fragment_offset, more_frags);
eth_fix_ip4_checksum(l3_iov_base, l3_iov_len);
net_tx_pkt_sendv(pkt, nc, fragment, dst_idx);
fragment_offset += fragment_len;
} while (more_frags);
return true;
},1

do_exedit(
exarg_T *eap,
win_T *old_curwin)
{
int n;
int need_hide;
int exmode_was = exmode_active;
if ((eap->cmdidx != CMD_pedit && ERROR_IF_POPUP_WINDOW)
|| ERROR_IF_TERM_POPUP_WINDOW)
return;
if (exmode_active && (eap->cmdidx == CMD_visual
|| eap->cmdidx == CMD_view))
{
exmode_active = FALSE;
ex_pressedreturn = FALSE;
if (*eap->arg == NUL)
{
if (global_busy)
{
int rd = RedrawingDisabled;
int nwr = no_wait_return;
int ms = msg_scroll;
#ifdef FEAT_GUI
int he = hold_gui_events;
#endif
if (eap->nextcmd != NULL)
{
stuffReadbuff(eap->nextcmd);
eap->nextcmd = NULL;
}
if (exmode_was != EXMODE_VIM)
settmode(TMODE_RAW);
RedrawingDisabled = 0;
no_wait_return = 0;
need_wait_return = FALSE;
msg_scroll = 0;
#ifdef FEAT_GUI
hold_gui_events = 0;
#endif
must_redraw = CLEAR;
pending_exmode_active = TRUE;
main_loop(FALSE, TRUE);
pending_exmode_active = FALSE;
RedrawingDisabled = rd;
no_wait_return = nwr;
msg_scroll = ms;
#ifdef FEAT_GUI
hold_gui_events = he;
#endif
}
return;
}
}
if ((eap->cmdidx == CMD_new
|| eap->cmdidx == CMD_tabnew
|| eap->cmdidx == CMD_tabedit
|| eap->cmdidx == CMD_vnew) && *eap->arg == NUL)
{
setpcmark();
(void)do_ecmd(0, NULL, NULL, eap, ECMD_ONE,
ECMD_HIDE + (eap->forceit ? ECMD_FORCEIT : 0),
old_curwin == NULL ? curwin : NULL);
}
else if ((eap->cmdidx != CMD_split && eap->cmdidx != CMD_vsplit)
|| *eap->arg != NUL
#ifdef FEAT_BROWSE
|| (cmdmod.cmod_flags & CMOD_BROWSE)
#endif
)
{
if (*eap->arg != NUL && curbuf_locked())
return;
n = readonlymode;
if (eap->cmdidx == CMD_view || eap->cmdidx == CMD_sview)
readonlymode = TRUE;
else if (eap->cmdidx == CMD_enew)
readonlymode = FALSE;
if (eap->cmdidx != CMD_balt && eap->cmdidx != CMD_badd)
setpcmark();
if (do_ecmd(0, (eap->cmdidx == CMD_enew ? NULL : eap->arg),
NULL, eap,
(*eap->arg == NUL && eap->do_ecmd_lnum == 0
&& vim_strchr(p_cpo, CPO_GOTO1) != NULL)
? ECMD_ONE : eap->do_ecmd_lnum,
(buf_hide(curbuf) ? ECMD_HIDE : 0)
+ (eap->forceit ? ECMD_FORCEIT : 0)
+ (old_curwin != NULL ? ECMD_OLDBUF : 0)
+ (eap->cmdidx == CMD_badd ? ECMD_ADDBUF : 0)
+ (eap->cmdidx == CMD_balt ? ECMD_ALTBUF : 0)
, old_curwin == NULL ? curwin : NULL) == FAIL)
{
if (old_curwin != NULL)
{
need_hide = (curbufIsChanged() && curbuf->b_nwindows <= 1);
if (!need_hide || buf_hide(curbuf))
{
#if defined(FEAT_EVAL)
cleanup_T cs;
enter_cleanup(&cs);
#endif
#ifdef FEAT_GUI
need_mouse_correct = TRUE;
#endif
win_close(curwin, !need_hide && !buf_hide(curbuf));
#if defined(FEAT_EVAL)
leave_cleanup(&cs);
#endif
}
}
}
else if (readonlymode && curbuf->b_nwindows == 1)
{
curbuf->b_p_ro = TRUE;
}
readonlymode = n;
}
else
{
if (eap->do_ecmd_cmd != NULL)
do_cmd_argument(eap->do_ecmd_cmd);
n = curwin->w_arg_idx_invalid;
check_arg_idx(curwin);
if (n != curwin->w_arg_idx_invalid)
maketitle();
}
if (old_curwin != NULL
&& *eap->arg != NUL
&& curwin != old_curwin
&& win_valid(old_curwin)
&& old_curwin->w_buffer != curbuf
&& (cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
old_curwin->w_alt_fnum = curbuf->b_fnum;
ex_no_reprint = TRUE;
},1

pjmedia_avi_player_create_streams(pj_pool_t *pool,
const char *filename,
unsigned options,
pjmedia_avi_streams **p_streams)
{
pjmedia_avi_hdr avi_hdr;
struct avi_reader_port *fport[PJMEDIA_AVI_MAX_NUM_STREAMS];
pj_off_t pos;
unsigned i, nstr = 0;
pj_status_t status = PJ_SUCCESS;
PJ_ASSERT_RETURN(pool && filename && p_streams, PJ_EINVAL);
if (!pj_file_exists(filename)) {
return PJ_ENOTFOUND;
}
fport[0] = create_avi_port(pool);
if (!fport[0]) {
return PJ_ENOMEM;
}
fport[0]->fsize = pj_file_size(filename);
if (fport[0]->fsize <= sizeof(riff_hdr_t) + sizeof(avih_hdr_t) +
sizeof(strl_hdr_t))
{
return PJMEDIA_EINVALIMEDIATYPE;
}
status = pj_file_open(pool, filename, PJ_O_RDONLY, &fport[0]->fd);
if (status != PJ_SUCCESS)
return status;
status = file_read(fport[0]->fd, &avi_hdr,
sizeof(riff_hdr_t) + sizeof(avih_hdr_t));
if (status != PJ_SUCCESS)
goto on_error;
if (!COMPARE_TAG(avi_hdr.riff_hdr.riff, PJMEDIA_AVI_RIFF_TAG) ||
!COMPARE_TAG(avi_hdr.riff_hdr.avi, PJMEDIA_AVI_AVI_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.list_tag, PJMEDIA_AVI_LIST_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.hdrl_tag, PJMEDIA_AVI_HDRL_TAG) ||
!COMPARE_TAG(avi_hdr.avih_hdr.avih, PJMEDIA_AVI_AVIH_TAG))
{
status = PJMEDIA_EINVALIMEDIATYPE;
goto on_error;
}
PJ_LOG(5, (THIS_FILE, "The AVI file has %d streams.",
avi_hdr.avih_hdr.num_streams));
if (avi_hdr.avih_hdr.num_streams > PJMEDIA_AVI_MAX_NUM_STREAMS) {
status = PJMEDIA_EAVIUNSUPP;
goto on_error;
}
if (avi_hdr.avih_hdr.flags & AVIF_MUSTUSEINDEX ||
avi_hdr.avih_hdr.pad > 1)
{
PJ_LOG(3, (THIS_FILE, "Warning!!! Possibly unsupported AVI format: "
"flags:%d, pad:%d", avi_hdr.avih_hdr.flags,
avi_hdr.avih_hdr.pad));
}
for (i = 0; i < avi_hdr.avih_hdr.num_streams; i++) {
pj_size_t elem = 0;
pj_ssize_t size_to_read;
status = file_read(fport[0]->fd, &avi_hdr.strl_hdr[i],
sizeof(strl_hdr_t));
if (status != PJ_SUCCESS)
goto on_error;
elem = COMPARE_TAG(avi_hdr.strl_hdr[i].data_type,
PJMEDIA_AVI_VIDS_TAG) ?
sizeof(strf_video_hdr_t) :
COMPARE_TAG(avi_hdr.strl_hdr[i].data_type,
PJMEDIA_AVI_AUDS_TAG) ?
sizeof(strf_audio_hdr_t) : 0;
status = file_read2(fport[0]->fd, &avi_hdr.strf_hdr[i],
elem, 0);
if (status != PJ_SUCCESS)
goto on_error;
if (elem == sizeof(strf_video_hdr_t))
data_to_host2(&avi_hdr.strf_hdr[i],
sizeof(strf_video_hdr_sizes)/
sizeof(strf_video_hdr_sizes[0]),
strf_video_hdr_sizes);
else if (elem == sizeof(strf_audio_hdr_t))
data_to_host2(&avi_hdr.strf_hdr[i],
sizeof(strf_audio_hdr_sizes)/
sizeof(strf_audio_hdr_sizes[0]),
strf_audio_hdr_sizes);
size_to_read = avi_hdr.strl_hdr[i].list_sz - (sizeof(strl_hdr_t) -
8) - elem;
status = pj_file_setpos(fport[0]->fd, size_to_read, PJ_SEEK_CUR);
if (status != PJ_SUCCESS) {
goto on_error;
}
}
status = pj_file_setpos(fport[0]->fd, avi_hdr.avih_hdr.list_sz +
sizeof(riff_hdr_t) + 8, PJ_SEEK_SET);
if (status != PJ_SUCCESS) {
goto on_error;
}
do {
pjmedia_avi_subchunk ch;
int read = 0;
status = file_read(fport[0]->fd, &ch, sizeof(pjmedia_avi_subchunk));
if (status != PJ_SUCCESS) {
goto on_error;
}
if (COMPARE_TAG(ch.id, PJMEDIA_AVI_LIST_TAG))
{
read = 4;
status = file_read(fport[0]->fd, &ch, read);
if (COMPARE_TAG(ch.id, PJMEDIA_AVI_MOVI_TAG))
break;
}
status = pj_file_setpos(fport[0]->fd, ch.len-read, PJ_SEEK_CUR);
if (status != PJ_SUCCESS) {
goto on_error;
}
} while(1);
status = pj_file_getpos(fport[0]->fd, &pos);
if (status != PJ_SUCCESS)
goto on_error;
for (i = 0, nstr = 0; i < avi_hdr.avih_hdr.num_streams; i++) {
pjmedia_format_id fmt_id;
if ((!COMPARE_TAG(avi_hdr.strl_hdr[i].data_type,
PJMEDIA_AVI_VIDS_TAG) &&
!COMPARE_TAG(avi_hdr.strl_hdr[i].data_type,
PJMEDIA_AVI_AUDS_TAG)) ||
avi_hdr.strl_hdr[i].flags & AVISF_DISABLED)
{
continue;
}
if (COMPARE_TAG(avi_hdr.strl_hdr[i].data_type,
PJMEDIA_AVI_VIDS_TAG))
{
int j;
if (avi_hdr.strl_hdr[i].flags & AVISF_VIDEO_PALCHANGES) {
PJ_LOG(4, (THIS_FILE, "Unsupported video stream"));
continue;
}
fmt_id = avi_hdr.strl_hdr[i].codec;
for (j = sizeof(avi_fmts)/sizeof(avi_fmts[0])-1; j >= 0; j--) {
if (fmt_id == avi_fmts[j].fmt_id) {
if (avi_fmts[j].eff_fmt_id)
fmt_id = avi_fmts[j].eff_fmt_id;
break;
}
}
if (j < 0) {
PJ_LOG(4, (THIS_FILE, "Unsupported video stream"));
continue;
}
} else {
strf_audio_hdr_t *hdr = (strf_audio_hdr_t*)
&avi_hdr.strf_hdr[i].strf_audio_hdr;
if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_PCM &&
hdr->bits_per_sample == 16)
{
fmt_id = PJMEDIA_FORMAT_PCM;
}
else if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_ALAW)
{
fmt_id = PJMEDIA_FORMAT_PCMA;
}
else if (hdr->fmt_tag == PJMEDIA_WAVE_FMT_TAG_ULAW)
{
fmt_id = PJMEDIA_FORMAT_PCMU;
}
else
{
PJ_LOG(4, (THIS_FILE, "Unsupported audio stream"));
continue;
}
}
if (nstr > 0) {
fport[nstr] = create_avi_port(pool);
if (!fport[nstr]) {
status = PJ_ENOMEM;
goto on_error;
}
status = pj_file_open(pool, filename, PJ_O_RDONLY,
&fport[nstr]->fd);
if (status != PJ_SUCCESS)
goto on_error;
status = pj_file_setpos(fport[nstr]->fd, pos, PJ_SEEK_SET);
if (status != PJ_SUCCESS) {
goto on_error;
}
}
fport[nstr]->stream_id = i;
fport[nstr]->fmt_id = fmt_id;
nstr++;
}
if (nstr == 0) {
status = PJMEDIA_EAVIUNSUPP;
goto on_error;
}
for (i = 0; i < nstr; i++) {
strl_hdr_t *strl_hdr = &avi_hdr.strl_hdr[fport[i]->stream_id];
fport[i]->options = options;
fport[i]->fsize = fport[0]->fsize;
fport[i]->start_data = pos;
if (COMPARE_TAG(strl_hdr->data_type, PJMEDIA_AVI_VIDS_TAG)) {
strf_video_hdr_t *strf_hdr =
&avi_hdr.strf_hdr[fport[i]->stream_id].strf_video_hdr;
const pjmedia_video_format_info *vfi;
vfi = pjmedia_get_video_format_info(
pjmedia_video_format_mgr_instance(),
strl_hdr->codec);
fport[i]->bits_per_sample = (vfi ? vfi->bpp : 0);
fport[i]->usec_per_frame = avi_hdr.avih_hdr.usec_per_frame;
pjmedia_format_init_video(&fport[i]->base.info.fmt,
fport[i]->fmt_id,
strf_hdr->biWidth,
strf_hdr->biHeight,
strl_hdr->rate,
strl_hdr->scale);
#if 0
bps = strf_hdr->biSizeImage * 8 * strl_hdr->rate / strl_hdr->scale;
if (bps==0) {
bps = strf_hdr->biWidth * strf_hdr->biHeight *
strf_hdr->biBitCount *
strl_hdr->rate / strl_hdr->scale;
}
fport[i]->base.info.fmt.det.vid.avg_bps = bps;
fport[i]->base.info.fmt.det.vid.max_bps = bps;
#endif
} else {
strf_audio_hdr_t *strf_hdr =
&avi_hdr.strf_hdr[fport[i]->stream_id].strf_audio_hdr;
fport[i]->bits_per_sample = strf_hdr->bits_per_sample;
fport[i]->usec_per_frame = avi_hdr.avih_hdr.usec_per_frame;
pjmedia_format_init_audio(&fport[i]->base.info.fmt,
fport[i]->fmt_id,
strf_hdr->sample_rate,
strf_hdr->nchannels,
strf_hdr->bits_per_sample,
20000 ,
strf_hdr->bytes_per_sec * 8,
strf_hdr->bytes_per_sec * 8);
if (fport[i]->fmt_id == PJMEDIA_FORMAT_PCMA ||
fport[i]->fmt_id == PJMEDIA_FORMAT_PCMU)
{
fport[i]->base.info.fmt.id = PJMEDIA_FORMAT_PCM;
fport[i]->base.info.fmt.det.aud.bits_per_sample = 16;
}
}
pj_strdup2(pool, &fport[i]->base.info.name, filename);
}
*p_streams = pj_pool_alloc(pool, sizeof(pjmedia_avi_streams));
(*p_streams)->num_streams = nstr;
(*p_streams)->streams = pj_pool_calloc(pool, (*p_streams)->num_streams,
sizeof(pjmedia_port *));
for (i = 0; i < nstr; i++)
(*p_streams)->streams[i] = &fport[i]->base;
PJ_LOG(4,(THIS_FILE,
"AVI file player '%.*s' created with "
"%d media ports",
(int)fport[0]->base.info.name.slen,
fport[0]->base.info.name.ptr,
(*p_streams)->num_streams));
return PJ_SUCCESS;
on_error:
fport[0]->base.on_destroy(&fport[0]->base);
for (i = 1; i < nstr; i++)
fport[i]->base.on_destroy(&fport[i]->base);
if (status == AVI_EOF)
return PJMEDIA_EINVALIMEDIATYPE;
return status;
},1

renderTable(struct table *t, int max_width, struct html_feed_environ *h_env)
{
int i, j, w, r, h;
Str renderbuf;
short new_tabwidth[MAXCOL] = { 0 };
#ifdef MATRIX
int itr;
VEC *newwidth;
MAT *mat, *minv;
PERM *pivot;
#endif
int width;
int rulewidth;
Str vrulea = NULL, vruleb = NULL, vrulec = NULL;
#ifdef ID_EXT
Str idtag;
#endif
t->total_height = 0;
if (t->maxcol < 0) {
make_caption(t, h_env);
return;
}
if (t->sloppy_width > max_width)
max_width = t->sloppy_width;
rulewidth = table_rule_width(t);
max_width -= table_border_width(t);
if (rulewidth > 1)
max_width = floor_at_intervals(max_width, rulewidth);
if (max_width < rulewidth)
max_width = rulewidth;
check_maximum_width(t);
#ifdef MATRIX
if (t->maxcol == 0) {
if (t->tabwidth[0] > max_width)
t->tabwidth[0] = max_width;
if (t->total_width > 0)
t->tabwidth[0] = max_width;
else if (t->fixed_width[0] > 0)
t->tabwidth[0] = t->fixed_width[0];
if (t->tabwidth[0] < t->minimum_width[0])
t->tabwidth[0] = t->minimum_width[0];
}
else {
set_table_matrix(t, max_width);
itr = 0;
mat = m_get(t->maxcol + 1, t->maxcol + 1);
pivot = px_get(t->maxcol + 1);
newwidth = v_get(t->maxcol + 1);
minv = m_get(t->maxcol + 1, t->maxcol + 1);
do {
m_copy(t->matrix, mat);
LUfactor(mat, pivot);
LUsolve(mat, pivot, t->vector, newwidth);
LUinverse(mat, pivot, minv);
#ifdef TABLE_DEBUG
set_integered_width(t, newwidth->ve, new_tabwidth);
fprintf(stderr, "itr=%d\n", itr);
fprintf(stderr, "max_width=%d\n", max_width);
fprintf(stderr, "minimum : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", t->minimum_width[i]);
fprintf(stderr, "\nfixed : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", t->fixed_width[i]);
fprintf(stderr, "\ndecided : ");
for (i = 0; i <= t->maxcol; i++)
fprintf(stderr, "%2d ", new_tabwidth[i]);
fprintf(stderr, "\n");
#endif
itr++;
} while (check_table_width(t, newwidth->ve, minv, itr));
set_integered_width(t, newwidth->ve, new_tabwidth);
check_minimum_width(t, new_tabwidth);
v_free(newwidth);
px_free(pivot);
m_free(mat);
m_free(minv);
m_free(t->matrix);
v_free(t->vector);
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = new_tabwidth[i];
}
}
#else
set_table_width(t, new_tabwidth, max_width);
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = new_tabwidth[i];
}
#endif
check_minimum_width(t, t->tabwidth);
for (i = 0; i <= t->maxcol; i++)
t->tabwidth[i] = ceil_at_intervals(t->tabwidth[i], rulewidth);
renderCoTable(t, h_env->limit);
for (i = 0; i <= t->maxcol; i++) {
for (j = 0; j <= t->maxrow; j++) {
check_row(t, j);
if (t->tabattr[j][i] & HTT_Y)
continue;
do_refill(t, j, i, h_env->limit);
}
}
check_minimum_width(t, t->tabwidth);
t->total_width = 0;
for (i = 0; i <= t->maxcol; i++) {
t->tabwidth[i] = ceil_at_intervals(t->tabwidth[i], rulewidth);
t->total_width += t->tabwidth[i];
}
t->total_width += table_border_width(t);
check_table_height(t);
for (i = 0; i <= t->maxcol; i++) {
for (j = 0; j <= t->maxrow; j++) {
TextLineList *l;
int k;
if ((t->tabattr[j][i] & HTT_Y) ||
(t->tabattr[j][i] & HTT_TOP) || (t->tabdata[j][i] == NULL))
continue;
h = t->tabheight[j];
for (k = j + 1; k <= t->maxrow; k++) {
if (!(t->tabattr[k][i] & HTT_Y))
break;
h += t->tabheight[k];
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
case BORDER_NOWIN:
h += 1;
break;
}
}
h -= t->tabdata[j][i]->nitem;
if (t->tabattr[j][i] & HTT_MIDDLE)
h /= 2;
if (h <= 0)
continue;
l = newTextLineList();
for (k = 0; k < h; k++)
pushTextLine(l, newTextLine(NULL, 0));
t->tabdata[j][i] = appendGeneralList((GeneralList *)l,
t->tabdata[j][i]);
}
}
width = t->total_width;
make_caption(t, h_env);
HTMLlineproc1("<pre for_table>", h_env);
#ifdef ID_EXT
if (t->id != NULL) {
idtag = Sprintf("<_id id=\"%s\">", html_quote((t->id)->ptr));
HTMLlineproc1(idtag->ptr, h_env);
}
#endif
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
renderbuf = Strnew();
print_sep(t, -1, T_TOP, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
t->total_height += 1;
break;
}
vruleb = Strnew();
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
vrulea = Strnew();
vrulec = Strnew();
push_symbol(vrulea, TK_VERTICALBAR(t->border_mode), symbol_width, 1);
for (i = 0; i < t->cellpadding; i++) {
Strcat_char(vrulea, ' ');
Strcat_char(vruleb, ' ');
Strcat_char(vrulec, ' ');
}
push_symbol(vrulec, TK_VERTICALBAR(t->border_mode), symbol_width, 1);
case BORDER_NOWIN:
push_symbol(vruleb, TK_VERTICALBAR(BORDER_THIN), symbol_width, 1);
for (i = 0; i < t->cellpadding; i++)
Strcat_char(vruleb, ' ');
break;
case BORDER_NONE:
for (i = 0; i < t->cellspacing; i++)
Strcat_char(vruleb, ' ');
}
for (r = 0; r <= t->maxrow; r++) {
for (h = 0; h < t->tabheight[r]; h++) {
renderbuf = Strnew();
if (t->border_mode == BORDER_THIN
|| t->border_mode == BORDER_THICK)
Strcat(renderbuf, vrulea);
#ifdef ID_EXT
if (t->tridvalue[r] != NULL && h == 0) {
idtag = Sprintf("<_id id=\"%s\">",
html_quote((t->tridvalue[r])->ptr));
Strcat(renderbuf, idtag);
}
#endif
for (i = 0; i <= t->maxcol; i++) {
check_row(t, r);
#ifdef ID_EXT
if (t->tabidvalue[r][i] != NULL && h == 0) {
idtag = Sprintf("<_id id=\"%s\">",
html_quote((t->tabidvalue[r][i])->ptr));
Strcat(renderbuf, idtag);
}
#endif
if (!(t->tabattr[r][i] & HTT_X)) {
w = t->tabwidth[i];
for (j = i + 1;
j <= t->maxcol && (t->tabattr[r][j] & HTT_X); j++)
w += t->tabwidth[j] + t->cellspacing;
if (t->tabattr[r][i] & HTT_Y) {
for (j = r - 1; j >= 0 && t->tabattr[j]
&& (t->tabattr[j][i] & HTT_Y); j--) ;
print_item(t, j, i, w, renderbuf);
}
else
print_item(t, r, i, w, renderbuf);
}
if (i < t->maxcol && !(t->tabattr[r][i + 1] & HTT_X))
Strcat(renderbuf, vruleb);
}
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
Strcat(renderbuf, vrulec);
t->total_height += 1;
break;
}
push_render_image(renderbuf, width, t->total_width, h_env);
}
if (r < t->maxrow && t->border_mode != BORDER_NONE) {
renderbuf = Strnew();
print_sep(t, r, T_MIDDLE, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
}
t->total_height += t->tabheight[r];
}
switch (t->border_mode) {
case BORDER_THIN:
case BORDER_THICK:
renderbuf = Strnew();
print_sep(t, t->maxrow, T_BOTTOM, t->maxcol, renderbuf);
push_render_image(renderbuf, width, t->total_width, h_env);
t->total_height += 1;
break;
}
if (t->total_height == 0) {
renderbuf = Strnew_charp(" ");
t->total_height++;
t->total_width = 1;
push_render_image(renderbuf, 1, t->total_width, h_env);
